		uboUi = new UBOUI();
		uboUi.initialize(UNIFORM_BLOCK_UI);

		uboLights = new UBOLights(false);
		uboLights.initialize(UNIFORM_BLOCK_LIGHTS);

		uboLightsCulling = new UBOLights(true);
		uboLightsCulling.initialize(UNIFORM_BLOCK_LIGHTS_CULLING);
