import static rs117.hd.scene.SceneContext.TILE_SKIP_FLAG;
import static rs117.hd.scene.SceneContext.TILE_WATER_FLAG;
import static rs117.hd.scene.tile_overrides.TileOverride.NONE;
import static rs117.hd.scene.tile_overrides.TileOverride.OVERLAY_FLAG;
import static rs117.hd.utils.HDUtils.HIDDEN_HSL;
import static rs117.hd.utils.HDUtils.UNDERWATER_HSL;
import static rs117.hd.utils.HDUtils.packTerrainData;
import static rs117.hd.utils.MathUtils.*;

@Slf4j
@Singleton
@SuppressWarnings("UnnecessaryLocalVariable")
public class LegacySceneUploader {
	public static final int SCENE_ID_MASK = 0xFFFF;
	public static final int EXCLUDED_FROM_SCENE_BUFFER = 0xFFFFFFFF;

	private static final short[] UP_NORMAL = { 0, -1, 0 };

	@Inject
	private Client client;

	@Inject
	private HdPlugin plugin;

	@Inject
	private HdPluginConfig config;

	@Inject
	private AreaManager areaManager;

	@Inject
	private MaterialManager materialManager;

	@Inject
	private TileOverrideManager tileOverrideManager;

	@Inject
	private ModelOverrideManager modelOverrideManager;

	@Inject
	public ProceduralGenerator proceduralGenerator;

	@Inject
	private LegacyModelPusher modelPusher;

	public void upload(LegacySceneContext sceneContext) {
		proceduralGenerator.generateSceneData(sceneContext, null);

		Stopwatch stopwatch = Stopwatch.createStarted();

		var scene = sceneContext.scene;
		sceneContext.enableAreaHiding =
			config.hideUnrelatedAreas() &&
			sceneContext.sceneBase != null &&
			!sceneContext.forceDisableAreaHiding;
		sceneContext.fillGaps = config.fillGapsInTerrain();

		if (sceneContext.enableAreaHiding) {
			sceneContext.possibleAreas = Arrays
				.stream(areaManager.areasWithAreaHiding)
				.filter(area -> sceneContext.sceneBounds.intersects(area.aabbs))
				.toArray(Area[]::new);

			if (log.isDebugEnabled() && sceneContext.possibleAreas.length > 0) {
				log.debug(
					"Hiding areas outside of {}",
					Arrays.stream(sceneContext.possibleAreas)
						.distinct()
						.map(Area::toString)
						.collect(Collectors.joining(", "))
				);
			}
		}

		// The scene can be prepared early when loaded synchronously
		if (client.isClientThread())
			prepareBeforeSwap(sceneContext);

		sceneContext.staticCustomTilesOffset = sceneContext.staticVertexCount;
		var tiles = scene.getExtendedTiles();
		for (int z = 0; z < MAX_Z; ++z) {
			for (int x = 0; x < EXTENDED_SCENE_SIZE; ++x) {
				for (int y = 0; y < EXTENDED_SCENE_SIZE; ++y) {
					Tile tile = tiles[z][x][y];
					if (tile != null)
						upload(sceneContext, tile, x, y);
				}
			}
		}
		sceneContext.staticCustomTilesVertexCount = sceneContext.staticVertexCount - sceneContext.staticCustomTilesOffset;

		stopwatch.stop();
		log.debug(
			"Scene upload time: {}, unique models: {}, size: {} MB",
			stopwatch,
			sceneContext.uniqueModels,
			String.format(
				"%.2f",
				(
					sceneContext.getVertexOffset() * 4L * (LegacyRenderer.VERTEX_SIZE + LegacyRenderer.NORMAL_SIZE) +
					sceneContext.getUvOffset() * 4L * LegacyRenderer.UV_SIZE
				) / 1e6
			)
		);

		proceduralGenerator.clearSceneData(sceneContext);
	}

	public void prepareBeforeSwap(LegacySceneContext sceneContext) {
		assert client.isClientThread();
		if (sceneContext.isPrepared)
			return;
		sceneContext.isPrepared = true;

		// At this point, the player's position & plane has been updated, so area hiding can be set up
		if (sceneContext.enableAreaHiding)
			removeTilesOutsideCurrentArea(sceneContext);

		// Gaps need to be filled right before scene swap, since map regions aren't updated earlier
		if (sceneContext.fillGaps) {
			sceneContext.staticGapFillerTilesOffset = sceneContext.staticVertexCount;
			fillGaps(sceneContext);
			sceneContext.staticGapFillerTilesVertexCount = sceneContext.staticVertexCount - sceneContext.staticGapFillerTilesOffset;
		}
	}

	public void updatePlayerArea(LegacySceneContext sceneContext) {
		if (!sceneContext.enableAreaHiding) {
			sceneContext.currentArea = null;
			return;
		}

		assert sceneContext.sceneBase != null;
		var localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
			return;
		var lp = localPlayer.getLocalLocation();
		int[] worldPos = {
			sceneContext.sceneBase[0] + lp.getSceneX(),
			sceneContext.sceneBase[1] + lp.getSceneY(),
			sceneContext.sceneBase[2] + client.getTopLevelWorldView().getPlane()
		};

		if (sceneContext.currentArea == null || !sceneContext.currentArea.containsPoint(false, worldPos)) {
			sceneContext.currentArea = null;
			for (var area : sceneContext.possibleAreas) {
				if (area.containsPoint(false, worldPos)) {
					sceneContext.currentArea = area;
					break;
				}
			}
		}
	}

	private void removeTilesOutsideCurrentArea(LegacySceneContext sceneContext) {
		assert sceneContext.sceneBase != null;
		updatePlayerArea(sceneContext);
		if (sceneContext.currentArea == null)
			return;

		var tiles = sceneContext.scene.getExtendedTiles();
		int baseExX = sceneContext.sceneBase[0] - sceneContext.sceneOffset;
		int baseExY = sceneContext.sceneBase[1] - sceneContext.sceneOffset;
		int basePlane = sceneContext.sceneBase[2];
		for (int z = 0; z < MAX_Z; ++z) {
			for (int x = 0; x < EXTENDED_SCENE_SIZE; ++x) {
				for (int y = 0; y < EXTENDED_SCENE_SIZE; ++y) {
					Tile tile = tiles[z][x][y];
					if (tile == null)
						continue;

					if (!sceneContext.currentArea.containsPoint(baseExX + x, baseExY + y, basePlane + z))
						sceneContext.scene.removeTile(tile);
				}
			}
		}
	}

	private void fillGaps(LegacySceneContext sceneContext) {
		if (sceneContext.sceneBase == null)
			return;

		var area = sceneContext.currentArea;
		if (area != null && !area.fillGaps)
			return;

//		log.warn("TODO: Check if scene.getMapRegions() is the same as client.getMapRegions()");

		int sceneMin = -sceneContext.expandedMapLoadingChunks * CHUNK_SIZE;
		int sceneMax = SCENE_SIZE + sceneContext.expandedMapLoadingChunks * CHUNK_SIZE;
		int baseExX = sceneContext.sceneBase[0];
		int baseExY = sceneContext.sceneBase[1];
		int basePlane = sceneContext.sceneBase[2];
		Material blackMaterial = materialManager.getMaterial("BLACK");

		Tile[][][] extendedTiles = sceneContext.scene.getExtendedTiles();
		for (int tileZ = 0; tileZ < MAX_Z; ++tileZ) {
			for (int tileExX = 0; tileExX < EXTENDED_SCENE_SIZE; ++tileExX) {
				for (int tileExY = 0; tileExY < EXTENDED_SCENE_SIZE; ++tileExY) {
					if (area != null && !area.containsPoint(baseExX + tileExX, baseExY + tileExY, basePlane + tileZ))
						continue;

					int tileX = tileExX - sceneContext.sceneOffset;
					int tileY = tileExY - sceneContext.sceneOffset;
					Tile tile = extendedTiles[tileZ][tileExX][tileExY];

					SceneTilePaint paint;
					SceneTileModel model = null;
					int renderLevel = tileZ;
					if (tile != null) {
						renderLevel = tile.getRenderLevel();
						paint = tile.getSceneTilePaint();
						model = tile.getSceneTileModel();

						if (model == null) {
							boolean hasTilePaint = paint != null && paint.getNeColor() != HIDDEN_HSL;
							if (!hasTilePaint) {
								tile = tile.getBridge();
								if (tile != null) {
									renderLevel = tile.getRenderLevel();
									paint = tile.getSceneTilePaint();
									model = tile.getSceneTileModel();
									hasTilePaint = paint != null && paint.getNeColor() != HIDDEN_HSL;
								}
							}

							if (hasTilePaint)
								continue;
						}
					}

					int[] worldPoint = sceneContext.sceneToWorld(tileX, tileY, tileZ);
					boolean fillGaps =
						tileZ == 0 &&
						tileX > sceneMin &&
						tileY > sceneMin &&
						tileX < sceneMax - 1 &&
						tileY < sceneMax - 1 &&
						Area.OVERWORLD.containsPoint(worldPoint);

					if (fillGaps) {
						int tileRegionID = HDUtils.worldToRegionID(worldPoint);
						int[] regions = client.getMapRegions();

						fillGaps = false;
						for (int region : regions) {
							if (region == tileRegionID) {
								fillGaps = true;
								break;
							}
						}
					}

					if (fillGaps) {
						int vertexOffset = sceneContext.getVertexOffset();
						int uvOffset = sceneContext.getUvOffset();
						int vertexCount;

						if (model == null) {
							uploadCustomTile(sceneContext, tileExX, tileExY, renderLevel, blackMaterial);
							vertexCount = 6;
						} else {
							int[] worldPos = sceneContext.sceneToWorld(tileX, tileY, tileZ);
							int[] uploadedTileModelData = uploadHDTileModelSurface(sceneContext, tile, worldPos, model, true);
							vertexCount = uploadedTileModelData[0];
						}

						if (vertexCount > 0) {
							sceneContext.staticUnorderedModelBuffer
								.ensureCapacity(8)
								.getBuffer()
								.put(vertexOffset)
								.put(uvOffset)
								.put(vertexCount / 3)
								.put(sceneContext.staticVertexCount)
								.put(0)
								.put(tileX * LOCAL_TILE_SIZE)
								.put(0)
								.put(tileY * LOCAL_TILE_SIZE);
							sceneContext.staticVertexCount += vertexCount;
						}
					}
				}
			}
		}
	}

	private void uploadModel(LegacySceneContext sceneContext, Tile tile, int uuid, Model model, int orientation) {
		// deduplicate hillskewed models
		if (model.getUnskewedModel() != null)
			model = model.getUnskewedModel();

		if (model.getSceneId() == EXCLUDED_FROM_SCENE_BUFFER)
			return;

		int[] worldPos = sceneContext.localToWorld(tile.getLocalLocation(), tile.getPlane());
		ModelOverride modelOverride = modelOverrideManager.getOverride(uuid, worldPos);
		int sceneId = modelOverride.hashCode() << 16 | sceneContext.id;

		// check if the model has already been uploaded
		if ((model.getSceneId() & SCENE_ID_MASK) == sceneContext.id) {
			// if the same model is being uploaded, but with a different model override,
			// exclude it from the scene buffer to avoid conflicts
			if (model.getSceneId() != sceneId)
				model.setSceneId(EXCLUDED_FROM_SCENE_BUFFER);
			return;
		}

		int vertexOffset = sceneContext.getVertexOffset();
		int uvOffset = sceneContext.getUvOffset();

		if (modelOverride.hide) {
			vertexOffset = -1;
		} else {
			modelPusher.pushModel(sceneContext, tile, uuid, model, modelOverride, orientation, false);
			if (sceneContext.modelPusherResults[1] == 0)
				uvOffset = -1;
		}

		model.setBufferOffset(vertexOffset);
		model.setUvBufferOffset(uvOffset);
		model.setSceneId(sceneId);
		++sceneContext.uniqueModels;
	}

	private void upload(LegacySceneContext sceneContext, @Nonnull Tile tile, int tileExX, int tileExY) {
		Tile bridge = tile.getBridge();
		if (bridge != null)
			upload(sceneContext, bridge, tileExX, tileExY);

		int[] worldPos = sceneContext.localToWorld(tile.getLocalLocation(), tile.getPlane());
		var override = tileOverrideManager.getOverride(sceneContext, tile, worldPos);

		SceneTilePaint sceneTilePaint = tile.getSceneTilePaint();
		if (sceneTilePaint != null || override.forced) {
			sceneContext.filledTiles[tileExX][tileExY] |= (byte) (1 << tile.getPlane());

			boolean depthTested = override.depthTested ||
								  override.forced && (sceneTilePaint == null || sceneTilePaint.getNeColor() == HIDDEN_HSL);

			// Set offsets before pushing new data
			int vertexOffset = sceneContext.getVertexOffset();
			int uvOffset = sceneContext.getUvOffset();
			int[] uploadedTilePaintData = upload(sceneContext, tile, worldPos, override, sceneTilePaint);

			int vertexCount = uploadedTilePaintData[0];
			int uvCount = uploadedTilePaintData[1];

			// Opening the right-click menu causes the game to stop drawing hidden tiles, which prevents us from drawing underwater tiles
			// below the boats at Pest Control, or any other custom tile. To work around this, we can instead draw all hidden tiles at once
			// at the start of the frame. This currently means they will only draw correctly if they're always behind everything else.
			if (vertexCount > 0 && depthTested) {
				int tileX = tileExX - sceneContext.sceneOffset;
				int tileY = tileExY - sceneContext.sceneOffset;

				// Draw the tile at the start of each frame
				sceneContext.staticUnorderedModelBuffer
					.ensureCapacity(8)
					.getBuffer()
					.put(vertexOffset)
					.put(uvOffset)
					.put(vertexCount / 3)
					.put(sceneContext.staticVertexCount)
					.put(0)
					.put(tileX * LOCAL_TILE_SIZE)
					.put(0)
					.put(tileY * LOCAL_TILE_SIZE);
				sceneContext.staticVertexCount += vertexCount;

				// Since we're now drawing this tile at the beginning of the frame, remove its vertices from the draw callback
				vertexCount = 0;
				uvCount = 0;
			}

			if (uvCount <= 0)
				uvOffset = -1;

			if (sceneTilePaint != null) {
				sceneTilePaint.setBufferLen(vertexCount);
				sceneTilePaint.setBufferOffset(vertexOffset);
				sceneTilePaint.setUvBufferOffset(uvOffset);
			}
		}

		var sceneTileModel = tile.getSceneTileModel();
		if (sceneTileModel != null) {
			sceneContext.filledTiles[tileExX][tileExY] |= (byte) (1 << tile.getPlane());

			// Set offsets before pushing new data
			sceneTileModel.setBufferOffset(sceneContext.getVertexOffset());
			sceneTileModel.setUvBufferOffset(sceneContext.getUvOffset());
			int[] uploadedTileModelData = upload(sceneContext, tile, worldPos, sceneTileModel);

			final int bufferLength = uploadedTileModelData[0];
			final int uvBufferLength = uploadedTileModelData[1];
			final int underwaterTerrain = uploadedTileModelData[2];
			if (uvBufferLength <= 0)
				sceneTileModel.setUvBufferOffset(-1);
			// pack a boolean into the buffer length of tiles so we can tell
			// which tiles have procedurally-generated underwater terrain
			int packedBufferLength = bufferLength << 1 | underwaterTerrain;

			sceneTileModel.setBufferLen(packedBufferLength);
		}

		WallObject wallObject = tile.getWallObject();
		if (wallObject != null) {
			Renderable renderable1 = wallObject.getRenderable1();
			if (renderable1 instanceof Model) {
				uploadModel(
					sceneContext,
					tile,
					ModelHash.packUuid(ModelHash.TYPE_WALL_OBJECT, wallObject.getId()),
					(Model) renderable1,
					HDUtils.convertWallObjectOrientation(wallObject.getOrientationA())
				);
			}

			Renderable renderable2 = wallObject.getRenderable2();
			if (renderable2 instanceof Model) {
				uploadModel(
					sceneContext,
					tile,
					ModelHash.packUuid(ModelHash.TYPE_WALL_OBJECT, wallObject.getId()),
					(Model) renderable2,
					HDUtils.convertWallObjectOrientation(wallObject.getOrientationB())
				);
			}
		}

		GroundObject groundObject = tile.getGroundObject();
		if (groundObject != null) {
			Renderable renderable = groundObject.getRenderable();
			if (renderable instanceof Model) {
				uploadModel(
					sceneContext,
					tile,
					ModelHash.packUuid(ModelHash.TYPE_GROUND_OBJECT, groundObject.getId()),
					(Model) renderable,
					HDUtils.getModelPreOrientation(groundObject.getConfig())
				);
			}
		}

		DecorativeObject decorativeObject = tile.getDecorativeObject();
		if (decorativeObject != null) {
			Renderable renderable = decorativeObject.getRenderable();
			int orientation = HDUtils.getModelPreOrientation(decorativeObject.getConfig());
			if (renderable instanceof Model) {
				uploadModel(
					sceneContext,
					tile,
					ModelHash.packUuid(ModelHash.TYPE_DECORATIVE_OBJECT, decorativeObject.getId()),
					(Model) renderable,
					orientation
				);
			}

			Renderable renderable2 = decorativeObject.getRenderable2();
			if (renderable2 instanceof Model) {
				uploadModel(
					sceneContext,
					tile,
					ModelHash.packUuid(ModelHash.TYPE_DECORATIVE_OBJECT, decorativeObject.getId()),
					(Model) renderable2,
					orientation
				);
			}
		}

		GameObject[] gameObjects = tile.getGameObjects();
		for (GameObject gameObject : gameObjects) {
			if (gameObject == null)
				continue;

			Renderable renderable = gameObject.getRenderable();
			if (renderable instanceof Model) {
				uploadModel(sceneContext,
					tile,
					ModelHash.packUuid(ModelHash.TYPE_GAME_OBJECT, gameObject.getId()),
					(Model) gameObject.getRenderable(),
					HDUtils.getModelPreOrientation(gameObject.getConfig())
				);
			}
		}
	}

	private int[] upload(
		LegacySceneContext sceneContext,
		Tile tile,
		int[] worldPos,
		TileOverride override,
		@Nullable SceneTilePaint paint
	) {
		int bufferLength = 0;
		int uvBufferLength = 0;
		int underwaterTerrain = 0;

		int[] bufferLengths;
		WaterType waterType = WaterType.NONE;
		if (paint != null)
			waterType = proceduralGenerator.seasonalWaterType(override, paint.getTexture());

		bufferLengths = uploadHDTilePaintUnderwater(sceneContext, tile, worldPos, waterType);
		bufferLength += bufferLengths[0];
		uvBufferLength += bufferLengths[1];
		underwaterTerrain += bufferLengths[2];

		bufferLengths = uploadHDTilePaintSurface(sceneContext, tile, worldPos, waterType, paint, override);
		bufferLength += bufferLengths[0];
		uvBufferLength += bufferLengths[1];
		underwaterTerrain += bufferLengths[2];

		return new int[] { bufferLength, uvBufferLength, underwaterTerrain };
	}

	private int[] uploadHDTilePaintSurface(
		LegacySceneContext sceneContext,
		Tile tile,
		int[] worldPos,
		WaterType waterType,
		@Nullable SceneTilePaint paint,
		TileOverride override
	) {
		final Scene scene = sceneContext.scene;
		final Point tilePoint = tile.getSceneLocation();
		final int tileX = tilePoint.getX();
		final int tileY = tilePoint.getY();
		final int tileExX = tileX + sceneContext.sceneOffset;
		final int tileExY = tileY + sceneContext.sceneOffset;
		final int tileZ = tile.getRenderLevel();

		final int localX = 0;
		final int localY = 0;

		final int[][][] tileHeights = scene.getTileHeights();
		int swHeight = tileHeights[tileZ][tileExX][tileExY];
		int seHeight = tileHeights[tileZ][tileExX + 1][tileExY];
		int neHeight = tileHeights[tileZ][tileExX + 1][tileExY + 1];
		int nwHeight = tileHeights[tileZ][tileExX][tileExY + 1];

		int bufferLength = 0;
		int uvBufferLength = 0;
		int underwaterTerrain = 0;

		int localSwVertexX = localX;
		int localSwVertexY = localY;
		int localSeVertexX = localX + LOCAL_TILE_SIZE;
		int localSeVertexY = localY;
		int localNwVertexX = localX;
		int localNwVertexY = localY + LOCAL_TILE_SIZE;
		int localNeVertexX = localX + LOCAL_TILE_SIZE;
		int localNeVertexY = localY + LOCAL_TILE_SIZE;

		int[] vertexKeys = ProceduralGenerator.tileVertexKeys(sceneContext, tile);
		int swVertexKey = vertexKeys[0];
		int seVertexKey = vertexKeys[1];
		int nwVertexKey = vertexKeys[2];
		int neVertexKey = vertexKeys[3];

		int uvOrientation = 0;
		float uvScale = 1;

		// Ignore certain tiles that aren't supposed to be visible,
		// but which we can still make a height-adjusted version of for underwater
		if ((paint != null && paint.getNeColor() != HIDDEN_HSL) || override.forced)
		{
			int swColor = 0;
			int seColor = 0;
			int neColor = 0;
			int nwColor = 0;
			int textureId = -1;

			if (paint != null) {
				swColor = paint.getSwColor();
				seColor = paint.getSeColor();
				neColor = paint.getNeColor();
				nwColor = paint.getNwColor();
				textureId = paint.getTexture();
			}

			boolean neVertexIsOverlay = false;
			boolean nwVertexIsOverlay = false;
			boolean seVertexIsOverlay = false;
			boolean swVertexIsOverlay = false;

			Material swMaterial = Material.NONE;
			Material seMaterial = Material.NONE;
			Material neMaterial = Material.NONE;
			Material nwMaterial = Material.NONE;

			short[] swNormals = UP_NORMAL;
			short[] seNormals = UP_NORMAL;
			short[] neNormals = UP_NORMAL;
			short[] nwNormals = UP_NORMAL;

			if (waterType == WaterType.NONE) {
				if (textureId != -1) {
					var material = materialManager.fromVanillaTexture(textureId);
					// Disable tile overrides for newly introduced vanilla textures
					if (material.isFallbackVanillaMaterial)
						override = NONE;
					swMaterial = seMaterial = neMaterial = nwMaterial = material;
				}

				swNormals = sceneContext.getVertexNormalOrDefault(swVertexKey, new short[3], UP_NORMAL);
				seNormals = sceneContext.getVertexNormalOrDefault(seVertexKey, new short[3], UP_NORMAL);
				neNormals = sceneContext.getVertexNormalOrDefault(neVertexKey, new short[3], UP_NORMAL);
				nwNormals = sceneContext.getVertexNormalOrDefault(nwVertexKey, new short[3], UP_NORMAL);

				boolean allowBlending =
					plugin.configGroundBlending &&
					textureId == -1 &&
					!proceduralGenerator.useDefaultColor(tile, override);
				boolean blendColors = plugin.configGroundBlendingColors && allowBlending;
				boolean blendTextures = plugin.configGroundBlendingTextures && allowBlending;

				GroundMaterial groundMaterial = null;
				if (override != TileOverride.NONE) {
					groundMaterial = override.groundMaterial;
					uvOrientation = override.uvOrientation;
					uvScale = override.uvScale;
					if (!blendColors) {
						swColor = override.modifyColor(swColor);
						seColor = override.modifyColor(seColor);
						nwColor = override.modifyColor(nwColor);
						neColor = override.modifyColor(neColor);
					}
				} else if (textureId == -1) {
					// Fall back to the default ground material if the tile is untextured
					groundMaterial = override.groundMaterial;
				}

				if (blendColors) {
					swColor = sceneContext.vertexTerrainColor.getOrDefault(swVertexKey, swColor);
					seColor = sceneContext.vertexTerrainColor.getOrDefault(seVertexKey, seColor);
					neColor = sceneContext.vertexTerrainColor.getOrDefault(neVertexKey, neColor);
					nwColor = sceneContext.vertexTerrainColor.getOrDefault(nwVertexKey, nwColor);
				}

				if (plugin.configGroundTextures) {
					if (blendTextures) {
						swMaterial = sceneContext.vertexTerrainTexture.getOrDefault(swVertexKey, swMaterial);
						seMaterial = sceneContext.vertexTerrainTexture.getOrDefault(seVertexKey, seMaterial);
						neMaterial = sceneContext.vertexTerrainTexture.getOrDefault(neVertexKey, neMaterial);
						nwMaterial = sceneContext.vertexTerrainTexture.getOrDefault(nwVertexKey, nwMaterial);
					} else if (groundMaterial != null) {
						swMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1], worldPos[2]);
						seMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1], worldPos[2]);
						nwMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1] + 1, worldPos[2]);
						neMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1] + 1, worldPos[2]);
					}
				}
			}
			else
			{
				// set colors for the shoreline to create a foam effect in the water shader
				swColor = seColor = nwColor = neColor = 127;

				if (sceneContext.isVertexWater(swVertexKey) && sceneContext.isVertexLand(swVertexKey))
					swColor = 0;
				if (sceneContext.isVertexWater(seVertexKey) && sceneContext.isVertexLand(seVertexKey))
					seColor = 0;
				if (sceneContext.isVertexWater(nwVertexKey) && sceneContext.isVertexLand(nwVertexKey))
					nwColor = 0;
				if (sceneContext.isVertexWater(neVertexKey) && sceneContext.isVertexLand(neVertexKey))
					neColor = 0;
			}

			if (sceneContext.isVertexOverlay(neVertexKey) && sceneContext.isVertexUnderlay(neVertexKey))
				neVertexIsOverlay = true;
			if (sceneContext.isVertexOverlay(nwVertexKey) && sceneContext.isVertexUnderlay(nwVertexKey))
				nwVertexIsOverlay = true;
			if (sceneContext.isVertexOverlay(seVertexKey) && sceneContext.isVertexUnderlay(seVertexKey))
				seVertexIsOverlay = true;
			if (sceneContext.isVertexOverlay(swVertexKey) && sceneContext.isVertexUnderlay(swVertexKey))
				swVertexIsOverlay = true;

			swHeight -= override.heightOffset;
			seHeight -= override.heightOffset;
			neHeight -= override.heightOffset;
			nwHeight -= override.heightOffset;

			float terrainData = Float.intBitsToFloat(packTerrainData(true, 0, waterType, tileZ));

			sceneContext.stagingBufferNormals.ensureCapacity(24);
			sceneContext.stagingBufferNormals.put(neNormals[0], neNormals[1], neNormals[2], terrainData);
			sceneContext.stagingBufferNormals.put(nwNormals[0], nwNormals[1], nwNormals[2], terrainData);
			sceneContext.stagingBufferNormals.put(seNormals[0], seNormals[1], seNormals[2], terrainData);

			sceneContext.stagingBufferNormals.put(swNormals[0], swNormals[1], swNormals[2], terrainData);
			sceneContext.stagingBufferNormals.put(seNormals[0], seNormals[1], seNormals[2], terrainData);
			sceneContext.stagingBufferNormals.put(nwNormals[0], nwNormals[1], nwNormals[2], terrainData);


			sceneContext.stagingBufferVertices.ensureCapacity(24);
			sceneContext.stagingBufferVertices.put((float) localNeVertexX, neHeight, localNeVertexY, neColor);
			sceneContext.stagingBufferVertices.put((float) localNwVertexX, nwHeight, localNwVertexY, nwColor);
			sceneContext.stagingBufferVertices.put((float) localSeVertexX, seHeight, localSeVertexY, seColor);

			sceneContext.stagingBufferVertices.put((float) localSwVertexX, swHeight, localSwVertexY, swColor);
			sceneContext.stagingBufferVertices.put((float) localSeVertexX, seHeight, localSeVertexY, seColor);
			sceneContext.stagingBufferVertices.put((float) localNwVertexX, nwHeight, localNwVertexY, nwColor);

			bufferLength += 6;


			int packedMaterialDataSW = swMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, swVertexIsOverlay);
			int packedMaterialDataSE = seMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, seVertexIsOverlay);
			int packedMaterialDataNW = nwMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, nwVertexIsOverlay);
			int packedMaterialDataNE = neMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, neVertexIsOverlay);

			float uvcos = -uvScale, uvsin = 0;
			if (uvOrientation % 2048 != 0) {
				float rad = -uvOrientation * JAU_TO_RAD;
				uvcos = cos(rad) * -uvScale;
				uvsin = sin(rad) * -uvScale;
			}
			float uvx = worldPos[0];
			float uvy = worldPos[1];
			float tmp = uvx;
			uvx = uvx * uvcos - uvy * uvsin;
			uvy = tmp * uvsin + uvy * uvcos;

			sceneContext.stagingBufferUvs.ensureCapacity(24);
			sceneContext.stagingBufferUvs.put(uvx, uvy, 0, packedMaterialDataNE);
			sceneContext.stagingBufferUvs.put(uvx - uvcos, uvy - uvsin, 0, packedMaterialDataNW);
			sceneContext.stagingBufferUvs.put(uvx + uvsin, uvy - uvcos, 0, packedMaterialDataSE);

			sceneContext.stagingBufferUvs.put(uvx - uvcos + uvsin, uvy - uvsin - uvcos, 0, packedMaterialDataSW);
			sceneContext.stagingBufferUvs.put(uvx + uvsin, uvy - uvcos, 0, packedMaterialDataSE);
			sceneContext.stagingBufferUvs.put(uvx - uvcos, uvy - uvsin, 0, packedMaterialDataNW);

			uvBufferLength += 6;
		}

		return new int[]{bufferLength, uvBufferLength, underwaterTerrain};
	}

	private int[] uploadHDTilePaintUnderwater(LegacySceneContext sceneContext, Tile tile, int[] worldPos, WaterType waterType) {
		final Scene scene = sceneContext.scene;
		final Point tilePoint = tile.getSceneLocation();
		final int tileX = tilePoint.getX();
		final int tileY = tilePoint.getY();
		final int tileExX = tileX + sceneContext.sceneOffset;
		final int tileExY = tileY + sceneContext.sceneOffset;
		final int tileZ = tile.getRenderLevel();

		int baseX = scene.getBaseX();
		int baseY = scene.getBaseY();

		if (baseX >= 2816 && baseX <= 2970 && baseY <= 5375 && baseY >= 5220) {
			// fix for God Wars Dungeon's water rendering over zamorak bridge
			return new int[] { 0, 0, 0 };
		}

		final int[][][] tileHeights = scene.getTileHeights();
		int swHeight = tileHeights[tileZ][tileExX][tileExY];
		int seHeight = tileHeights[tileZ][tileExX + 1][tileExY];
		int neHeight = tileHeights[tileZ][tileExX + 1][tileExY + 1];
		int nwHeight = tileHeights[tileZ][tileExX][tileExY + 1];

		int bufferLength = 0;
		int uvBufferLength = 0;
		int underwaterTerrain = 0;

		int localSwVertexX = 0;
		int localSwVertexY = 0;
		int localSeVertexX = LOCAL_TILE_SIZE;
		int localSeVertexY = 0;
		int localNwVertexX = 0;
		int localNwVertexY = LOCAL_TILE_SIZE;
		int localNeVertexX = LOCAL_TILE_SIZE;
		int localNeVertexY = LOCAL_TILE_SIZE;

		int[] vertexKeys = ProceduralGenerator.tileVertexKeys(sceneContext, tile);
		int swVertexKey = vertexKeys[0];
		int seVertexKey = vertexKeys[1];
		int nwVertexKey = vertexKeys[2];
		int neVertexKey = vertexKeys[3];

		if (sceneContext.isTileFlagSet(tileZ, tileExX, tileExY, TILE_WATER_FLAG)) {
			// underwater terrain

			underwaterTerrain = 1;

			int swColor, seColor, neColor, nwColor;
			swColor = seColor = neColor = nwColor = UNDERWATER_HSL;

			int swDepth = sceneContext.getVertexUnderwaterDepth(swVertexKey);
			int seDepth = sceneContext.getVertexUnderwaterDepth(seVertexKey);
			int nwDepth = sceneContext.getVertexUnderwaterDepth(nwVertexKey);
			int neDepth = sceneContext.getVertexUnderwaterDepth(neVertexKey);

			short[] swNormals = sceneContext.getVertexNormalOrDefault(swVertexKey, new short[3], UP_NORMAL);
			short[] seNormals = sceneContext.getVertexNormalOrDefault(seVertexKey, new short[3], UP_NORMAL);
			short[] nwNormals = sceneContext.getVertexNormalOrDefault(nwVertexKey, new short[3], UP_NORMAL);
			short[] neNormals = sceneContext.getVertexNormalOrDefault(neVertexKey, new short[3], UP_NORMAL);

			Material swMaterial = Material.NONE;
			Material seMaterial = Material.NONE;
			Material nwMaterial = Material.NONE;
			Material neMaterial = Material.NONE;

			if (plugin.configGroundTextures)
			{
				GroundMaterial groundMaterial = GroundMaterial.UNDERWATER_GENERIC;
				swMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1], worldPos[2]);
				seMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1], worldPos[2]);
				nwMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1] + 1, worldPos[2]);
				neMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1] + 1, worldPos[2]);
			}

			float swTerrainData = Float.intBitsToFloat(packTerrainData(true, max(1, swDepth), waterType, tileZ));
			float seTerrainData = Float.intBitsToFloat(packTerrainData(true, max(1, seDepth), waterType, tileZ));
			float nwTerrainData = Float.intBitsToFloat(packTerrainData(true, max(1, nwDepth), waterType, tileZ));
			float neTerrainData = Float.intBitsToFloat(packTerrainData(true, max(1, neDepth), waterType, tileZ));

			sceneContext.stagingBufferNormals.ensureCapacity(24);
			sceneContext.stagingBufferNormals.put(neNormals[0], neNormals[1], neNormals[2], neTerrainData);
			sceneContext.stagingBufferNormals.put(nwNormals[0], nwNormals[1], nwNormals[2], nwTerrainData);
			sceneContext.stagingBufferNormals.put(seNormals[0], seNormals[1], seNormals[2], seTerrainData);

			sceneContext.stagingBufferNormals.put(swNormals[0], swNormals[1], swNormals[2], swTerrainData);
			sceneContext.stagingBufferNormals.put(seNormals[0], seNormals[1], seNormals[2], seTerrainData);
			sceneContext.stagingBufferNormals.put(nwNormals[0], nwNormals[1], nwNormals[2], nwTerrainData);

			sceneContext.stagingBufferVertices.ensureCapacity(24);
			sceneContext.stagingBufferVertices.put((float) localNeVertexX, neHeight + neDepth, localNeVertexY, neColor);
			sceneContext.stagingBufferVertices.put((float) localNwVertexX, nwHeight + nwDepth, localNwVertexY, nwColor);
			sceneContext.stagingBufferVertices.put((float) localSeVertexX, seHeight + seDepth, localSeVertexY, seColor);

			sceneContext.stagingBufferVertices.put((float) localSwVertexX, swHeight + swDepth, localSwVertexY, swColor);
			sceneContext.stagingBufferVertices.put((float) localSeVertexX, seHeight + seDepth, localSeVertexY, seColor);
			sceneContext.stagingBufferVertices.put((float) localNwVertexX, nwHeight + nwDepth, localNwVertexY, nwColor);

			bufferLength += 6;

			int packedMaterialDataSW = swMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, false);
			int packedMaterialDataSE = seMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, false);
			int packedMaterialDataNW = nwMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, false);
			int packedMaterialDataNE = neMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, false);

			sceneContext.stagingBufferUvs.ensureCapacity(24);
			sceneContext.stagingBufferUvs.put(0, 0, 0, packedMaterialDataNE);
			sceneContext.stagingBufferUvs.put(1, 0, 0, packedMaterialDataNW);
			sceneContext.stagingBufferUvs.put(0, 1, 0, packedMaterialDataSE);

			sceneContext.stagingBufferUvs.put(1, 1, 0, packedMaterialDataSW);
			sceneContext.stagingBufferUvs.put(0, 1, 0, packedMaterialDataSE);
			sceneContext.stagingBufferUvs.put(1, 0, 0, packedMaterialDataNW);

			uvBufferLength += 6;
		}

		return new int[]{bufferLength, uvBufferLength, underwaterTerrain};
	}

	private int[] upload(LegacySceneContext sceneContext, Tile tile, int[] worldPos, SceneTileModel sceneTileModel)
	{
		int bufferLength = 0;
		int uvBufferLength = 0;
		int underwaterTerrain = 0;

		int[] bufferLengths;

		bufferLengths = uploadHDTileModelSurface(sceneContext, tile, worldPos, sceneTileModel, false);
		bufferLength += bufferLengths[0];
		uvBufferLength += bufferLengths[1];
		underwaterTerrain += bufferLengths[2];

		bufferLengths = uploadHDTileModelUnderwater(sceneContext, tile, worldPos, sceneTileModel);
		assert bufferLengths[0] == bufferLength || bufferLengths[0] == 0;
		bufferLength += bufferLengths[0];
		uvBufferLength += bufferLengths[1];
		underwaterTerrain += bufferLengths[2];

		return new int[]{bufferLength, uvBufferLength, underwaterTerrain};
	}

	private int[] uploadHDTileModelSurface(
		LegacySceneContext sceneContext,
		Tile tile,
		int[] worldPos,
		SceneTileModel model,
		boolean fillGaps
	) {
		final Scene scene = sceneContext.scene;
		final Point tilePoint = tile.getSceneLocation();
		final int tileX = tilePoint.getX();
		final int tileY = tilePoint.getY();
		final int tileExX = tileX + sceneContext.sceneOffset;
		final int tileExY = tileY + sceneContext.sceneOffset;
		final int tileZ = tile.getRenderLevel();

		if (!fillGaps && sceneContext.isTileFlagSet(tileZ, tileExX, tileExY, TILE_SKIP_FLAG))
			return new int[3];

		int bufferLength = 0;
		int uvBufferLength = 0;
		int underwaterTerrain = 0;

		final int[] faceColorA = model.getTriangleColorA();
		final int[] faceColorB = model.getTriangleColorB();
		final int[] faceColorC = model.getTriangleColorC();
		final int[] faceTextures = model.getTriangleTextureId();
		final int faceCount = model.getFaceX().length;

		int overlayId = OVERLAY_FLAG | scene.getOverlayIds()[tileZ][tileExX][tileExY];
		int underlayId = scene.getUnderlayIds()[tileZ][tileExX][tileExY];
		var overlayOverride = tileOverrideManager.getOverride(sceneContext, tile, worldPos, overlayId);
		var underlayOverride = tileOverrideManager.getOverride(sceneContext, tile, worldPos, underlayId);

		for (int face = 0; face < faceCount; ++face) {
			int colorA = faceColorA[face];
			int colorB = faceColorB[face];
			int colorC = faceColorC[face];

			int[][] localVertices = new int[3][3];
			ProceduralGenerator.faceLocalVertices(tile, face, localVertices);

			int[] vertexKeys = ProceduralGenerator.faceVertexKeys(tile, face);
			int vertexKeyA = vertexKeys[0];
			int vertexKeyB = vertexKeys[1];
			int vertexKeyC = vertexKeys[2];

			boolean vertexAIsOverlay = false;
			boolean vertexBIsOverlay = false;
			boolean vertexCIsOverlay = false;

			int textureId;
			Material materialA = Material.NONE;
			Material materialB = Material.NONE;
			Material materialC = Material.NONE;

			int uvOrientation = 0;
			float uvScale = 1;

			short[] normalsA = UP_NORMAL;
			short[] normalsB = UP_NORMAL;
			short[] normalsC = UP_NORMAL;

			WaterType waterType = WaterType.NONE;

			boolean isHidden = colorA == HIDDEN_HSL;
			if (fillGaps) {
				if (!isHidden)
					continue;
				colorA = colorB = colorC = 0;
			} else {
				boolean isOverlay = ProceduralGenerator.isOverlayFace(tile, face);
				var override = isOverlay ? overlayOverride : underlayOverride;
				if (isHidden && !override.forced)
					continue;

				textureId = faceTextures == null ? -1 : faceTextures[face];
				waterType = proceduralGenerator.seasonalWaterType(override, textureId);
				if (waterType == WaterType.NONE) {
					if (textureId != -1) {
						var material = materialManager.fromVanillaTexture(textureId);
						// Disable tile overrides for newly introduced vanilla textures
						if (material.isFallbackVanillaMaterial)
							override = NONE;
						materialA = materialB = materialC = material;
					}

					normalsA = sceneContext.getVertexNormalOrDefault(vertexKeyA, new short[3], UP_NORMAL);
					normalsB = sceneContext.getVertexNormalOrDefault(vertexKeyB, new short[3], UP_NORMAL);
					normalsC = sceneContext.getVertexNormalOrDefault(vertexKeyC, new short[3], UP_NORMAL);

					GroundMaterial groundMaterial = null;

					boolean allowBlending =
						plugin.configGroundBlending &&
						textureId == -1 &&
						!(isOverlay && proceduralGenerator.useDefaultColor(tile, override));
					boolean blendColors = plugin.configGroundBlendingColors && allowBlending;
					boolean blendTextures = plugin.configGroundBlendingTextures && allowBlending;

					if (override != TileOverride.NONE) {
						groundMaterial = override.groundMaterial;
						uvOrientation = override.uvOrientation;
						uvScale = override.uvScale;
						if (!blendColors) {
							colorA = override.modifyColor(colorA);
							colorB = override.modifyColor(colorB);
							colorC = override.modifyColor(colorC);
						}
					} else if (textureId == -1) {
						// Fall back to the default ground material if the tile is untextured
						groundMaterial = override.groundMaterial;
					}

					if (blendColors) {
						colorA = sceneContext.vertexTerrainColor.getOrDefault(vertexKeyA, colorA);
						colorB = sceneContext.vertexTerrainColor.getOrDefault(vertexKeyB, colorB);
						colorC = sceneContext.vertexTerrainColor.getOrDefault(vertexKeyC, colorC);
					}

					if (plugin.configGroundTextures) {
						if (blendTextures) {
							materialA = sceneContext.vertexTerrainTexture.getOrDefault(vertexKeyA, materialA);
							materialB = sceneContext.vertexTerrainTexture.getOrDefault(vertexKeyB, materialB);
							materialC = sceneContext.vertexTerrainTexture.getOrDefault(vertexKeyC, materialC);
						} else if (groundMaterial != null) {
							materialA = groundMaterial.getRandomMaterial(
								worldPos[0] + (localVertices[0][0] >> LOCAL_COORD_BITS),
								worldPos[1] + (localVertices[0][1] >> LOCAL_COORD_BITS),
								worldPos[2]
							);
							materialB = groundMaterial.getRandomMaterial(
								worldPos[0] + (localVertices[1][0] >> LOCAL_COORD_BITS),
								worldPos[1] + (localVertices[1][1] >> LOCAL_COORD_BITS),
								worldPos[2]
							);
							materialC = groundMaterial.getRandomMaterial(
								worldPos[0] + (localVertices[2][0] >> LOCAL_COORD_BITS),
								worldPos[1] + (localVertices[2][1] >> LOCAL_COORD_BITS),
								worldPos[2]
							);
						}
					}
				} else {
					// set colors for the shoreline to create a foam effect in the water shader
					colorA = colorB = colorC = 127;
					if (sceneContext.isVertexWater(vertexKeyA) && sceneContext.isVertexLand(vertexKeyA))
						colorA = 0;
					if (sceneContext.isVertexWater(vertexKeyB) && sceneContext.isVertexLand(vertexKeyB))
						colorB = 0;
					if (sceneContext.isVertexWater(vertexKeyC) && sceneContext.isVertexLand(vertexKeyC))
						colorC = 0;
				}

				if (sceneContext.isVertexOverlay(vertexKeyA) && sceneContext.isVertexUnderlay(vertexKeyA))
					vertexAIsOverlay = true;
				if (sceneContext.isVertexOverlay(vertexKeyB) && sceneContext.isVertexUnderlay(vertexKeyB))
					vertexBIsOverlay = true;
				if (sceneContext.isVertexOverlay(vertexKeyC) && sceneContext.isVertexUnderlay(vertexKeyC))
					vertexCIsOverlay = true;

				for (int i = 0; i < 3; i++)
					localVertices[i][1] -= override.heightOffset;
			}

			float terrainData = Float.intBitsToFloat(packTerrainData(true, 0, waterType, tileZ));

			sceneContext.stagingBufferNormals.ensureCapacity(12);
			sceneContext.stagingBufferNormals.put(normalsA[0], normalsA[1], normalsA[2], terrainData);
			sceneContext.stagingBufferNormals.put(normalsB[0], normalsB[1], normalsB[2], terrainData);
			sceneContext.stagingBufferNormals.put(normalsC[0], normalsC[1], normalsC[2], terrainData);

			sceneContext.stagingBufferVertices.ensureCapacity(12);
			sceneContext.stagingBufferVertices.put((float) localVertices[0][0], localVertices[0][1], localVertices[0][2], colorA);
			sceneContext.stagingBufferVertices.put((float) localVertices[1][0], localVertices[1][1], localVertices[1][2], colorB);
			sceneContext.stagingBufferVertices.put((float) localVertices[2][0], localVertices[2][1], localVertices[2][2], colorC);

			bufferLength += 3;

			int[] packedMaterialData = {
				materialA.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, vertexAIsOverlay),
				materialB.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, vertexBIsOverlay),
				materialC.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, vertexCIsOverlay)
			};

			float uvcos = -uvScale, uvsin = 0;
			if (uvOrientation % 2048 != 0) {
				float rad = -uvOrientation * JAU_TO_RAD;
				uvcos = cos(rad) * -uvScale;
				uvsin = sin(rad) * -uvScale;
			}

			sceneContext.stagingBufferUvs.ensureCapacity(12);
			for (int i = 0; i < 3; i++) {
				float uvx = worldPos[0] + localVertices[i][0] / 128f - 1;
				float uvy = worldPos[1] + localVertices[i][2] / 128f - 1;
				float tmp = uvx;
				uvx = uvx * uvcos - uvy * uvsin;
				uvy = tmp * uvsin + uvy * uvcos;

				sceneContext.stagingBufferUvs.put(uvx, uvy, 0, packedMaterialData[i]);
			}

			uvBufferLength += 3;
		}

		return new int[]{bufferLength, uvBufferLength, underwaterTerrain};
	}

	private int[] uploadHDTileModelUnderwater(LegacySceneContext sceneContext, Tile tile, int[] worldPos, SceneTileModel model) {
		final Scene scene = sceneContext.scene;
		final Point tilePoint = tile.getSceneLocation();
		final int tileX = tilePoint.getX();
		final int tileY = tilePoint.getY();
		final int tileExX = tileX + sceneContext.sceneOffset;
		final int tileExY = tileY + sceneContext.sceneOffset;
		final int tileZ = tile.getRenderLevel();

		int bufferLength = 0;
		int uvBufferLength = 0;
		int underwaterTerrain = 0;

		if (sceneContext.isTileFlagSet(tileZ, tileExX, tileExY, TILE_SKIP_FLAG))
			return new int[] { bufferLength, uvBufferLength, underwaterTerrain };

		final int[] faceColorA = model.getTriangleColorA();
		final int faceCount = model.getFaceX().length;
		final int[] faceTextures = model.getTriangleTextureId();

		int baseX = scene.getBaseX();
		int baseY = scene.getBaseY();

		if (baseX >= 2816 && baseX <= 2970 && baseY <= 5375 && baseY >= 5220) {
			// fix for God Wars Dungeon's water rendering over zamorak bridge
			return new int[] { bufferLength, uvBufferLength, underwaterTerrain };
		}

		if (sceneContext.isTileFlagSet(tileZ, tileExX, tileExY, TILE_WATER_FLAG)) {
			underwaterTerrain = 1;

			int overlayId = OVERLAY_FLAG | scene.getOverlayIds()[tileZ][tileExX][tileExY];
			int underlayId = scene.getUnderlayIds()[tileZ][tileExX][tileExY];
			var overlayOverride = tileOverrideManager.getOverride(sceneContext, tile, worldPos, overlayId);
			var underlayOverride = tileOverrideManager.getOverride(sceneContext, tile, worldPos, underlayId);

			// underwater terrain
			for (int face = 0; face < faceCount; ++face) {
				int colorA, colorB, colorC;
				colorA = colorB = colorC = UNDERWATER_HSL;

				boolean isOverlay = ProceduralGenerator.isOverlayFace(tile, face);
				var override = isOverlay ? overlayOverride : underlayOverride;
				if (faceColorA[face] == HIDDEN_HSL && !override.forced)
					continue;

				int[][] localVertices = new int[3][3];
				ProceduralGenerator.faceLocalVertices(tile, face, localVertices);

				Material materialA = Material.NONE;
				Material materialB = Material.NONE;
				Material materialC = Material.NONE;

				int[] vertexKeys = ProceduralGenerator.faceVertexKeys(tile, face);
				int vertexKeyA = vertexKeys[0];
				int vertexKeyB = vertexKeys[1];
				int vertexKeyC = vertexKeys[2];

				int depthA = sceneContext.getVertexUnderwaterDepth(vertexKeyA);
				int depthB = sceneContext.getVertexUnderwaterDepth(vertexKeyB);
				int depthC = sceneContext.getVertexUnderwaterDepth(vertexKeyC);

				if (plugin.configGroundTextures) {
					GroundMaterial groundMaterial = GroundMaterial.UNDERWATER_GENERIC;
					materialA = groundMaterial.getRandomMaterial(
						worldPos[0] + (localVertices[0][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (localVertices[0][2] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
					materialB = groundMaterial.getRandomMaterial(
						worldPos[0] + (localVertices[1][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (localVertices[1][2] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
					materialC = groundMaterial.getRandomMaterial(
						worldPos[0] + (localVertices[2][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (localVertices[2][2] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
				}

				short[] normalsA = sceneContext.getVertexNormalOrDefault(vertexKeyA, new short[3], UP_NORMAL);
				short[] normalsB = sceneContext.getVertexNormalOrDefault(vertexKeyB, new short[3], UP_NORMAL);
				short[] normalsC = sceneContext.getVertexNormalOrDefault(vertexKeyC, new short[3], UP_NORMAL);

				int textureId = faceTextures == null ? -1 : faceTextures[face];
				WaterType waterType = proceduralGenerator.seasonalWaterType(override, textureId);

				float aTerrainData = Float.intBitsToFloat(packTerrainData(true, max(1, depthA), waterType, tileZ));
				float bTerrainData = Float.intBitsToFloat(packTerrainData(true, max(1, depthB), waterType, tileZ));
				float cTerrainData = Float.intBitsToFloat(packTerrainData(true, max(1, depthC), waterType, tileZ));

				sceneContext.stagingBufferNormals.ensureCapacity(12);
				sceneContext.stagingBufferNormals.put(normalsA[0], normalsA[1], normalsA[2], aTerrainData);
				sceneContext.stagingBufferNormals.put(normalsB[0], normalsB[1], normalsB[2], bTerrainData);
				sceneContext.stagingBufferNormals.put(normalsC[0], normalsC[1], normalsC[2], cTerrainData);

				sceneContext.stagingBufferVertices.ensureCapacity(12);
				sceneContext.stagingBufferVertices.put(
					(float) localVertices[0][0],
					localVertices[0][1] + depthA,
					localVertices[0][2],
					colorA
				);
				sceneContext.stagingBufferVertices.put(
					(float) localVertices[1][0],
					localVertices[1][1] + depthB,
					localVertices[1][2],
					colorB
				);
				sceneContext.stagingBufferVertices.put(
					(float) localVertices[2][0],
					localVertices[2][1] + depthC,
					localVertices[2][2],
					colorC
				);

				bufferLength += 3;

				int packedMaterialDataA = materialA.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, false);
				int packedMaterialDataB = materialB.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, false);
				int packedMaterialDataC = materialC.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, false);

				sceneContext.stagingBufferUvs.ensureCapacity(12);
				sceneContext.stagingBufferUvs.put(1 - localVertices[0][0] / 128f, 1 - localVertices[0][2] / 128f, 0, packedMaterialDataA);
				sceneContext.stagingBufferUvs.put(1 - localVertices[1][0] / 128f, 1 - localVertices[1][2] / 128f, 0, packedMaterialDataB);
				sceneContext.stagingBufferUvs.put(1 - localVertices[2][0] / 128f, 1 - localVertices[2][2] / 128f, 0, packedMaterialDataC);

				uvBufferLength += 3;
			}
		}

		return new int[] { bufferLength, uvBufferLength, underwaterTerrain };
	}

	private void uploadCustomTile(LegacySceneContext sceneContext, int tileExX, int tileExY, int tileZ, Material material) {
		final Scene scene = sceneContext.scene;

		int color = 0;
		float fromX = 0;
		float fromY = 0;
		float toX = LOCAL_TILE_SIZE;
		float toY = LOCAL_TILE_SIZE;

		final int[][][] tileHeights = scene.getTileHeights();
		int swHeight = tileHeights[tileZ][tileExX][tileExY];
		int seHeight = tileHeights[tileZ][tileExX + 1][tileExY];
		int neHeight = tileHeights[tileZ][tileExX + 1][tileExY + 1];
		int nwHeight = tileHeights[tileZ][tileExX][tileExY + 1];

		float terrainData = Float.intBitsToFloat(packTerrainData(true, 0, WaterType.NONE, tileZ));

		sceneContext.stagingBufferNormals.ensureCapacity(24);
		sceneContext.stagingBufferNormals.put(0, -1, 0, terrainData);
		sceneContext.stagingBufferNormals.put(0, -1, 0, terrainData);
		sceneContext.stagingBufferNormals.put(0, -1, 0, terrainData);

		sceneContext.stagingBufferNormals.put(0, -1, 0, terrainData);
		sceneContext.stagingBufferNormals.put(0, -1, 0, terrainData);
		sceneContext.stagingBufferNormals.put(0, -1, 0, terrainData);

		sceneContext.stagingBufferVertices.ensureCapacity(24);
		sceneContext.stagingBufferVertices.put(toX, neHeight, toY, color);
		sceneContext.stagingBufferVertices.put(fromX, nwHeight, toY, color);
		sceneContext.stagingBufferVertices.put(toX, seHeight, fromY, color);

		sceneContext.stagingBufferVertices.put(fromX, swHeight, fromY, color);
		sceneContext.stagingBufferVertices.put(toX, seHeight, fromY, color);
		sceneContext.stagingBufferVertices.put(fromX, nwHeight, toY, color);

		int packedMaterialData = material.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, false);

		sceneContext.stagingBufferUvs.ensureCapacity(24);
		sceneContext.stagingBufferUvs.put(0, 0, 0, packedMaterialData);
		sceneContext.stagingBufferUvs.put(1, 0, 0, packedMaterialData);
		sceneContext.stagingBufferUvs.put(0, 1, 0, packedMaterialData);

		sceneContext.stagingBufferUvs.put(1, 1, 0, packedMaterialData);
		sceneContext.stagingBufferUvs.put(0, 1, 0, packedMaterialData);
		sceneContext.stagingBufferUvs.put(1, 0, 0, packedMaterialData);
	}
}

package rs117.hd.renderer.zone;

import com.google.inject.Injector;
import java.lang.reflect.Array;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.locks.LockSupport;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.experimental.Accessors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import rs117.hd.renderer.zone.Zone.AlphaModel;
import rs117.hd.scene.model_overrides.ModelOverride;
import rs117.hd.utils.collections.ConcurrentPool;
import rs117.hd.utils.collections.PooledArrayType;
import rs117.hd.utils.jobs.Job;

import static rs117.hd.utils.collections.PooledArrayType.BYTE;
import static rs117.hd.utils.collections.PooledArrayType.FLOAT;
import static rs117.hd.utils.collections.PooledArrayType.INT;
import static rs117.hd.utils.collections.PooledArrayType.SHORT;

@Slf4j
@Getter
@Setter
@Accessors(chain = false)
public final class AsyncCachedModel extends Job implements Model {
	public static final ConcurrentLinkedQueue<AsyncCachedModel> INFLIGHT = new ConcurrentLinkedQueue<>();
	public static ConcurrentPool<AsyncCachedModel> POOL;

	public static void initialize(Injector injector) {
		if (AsyncCachedModel.POOL == null)
			AsyncCachedModel.POOL = new ConcurrentPool<>(() -> injector.getInstance(AsyncCachedModel.class), 32);
	}

	public static void destroy() {
		INFLIGHT.clear();
		if (AsyncCachedModel.POOL != null)
			AsyncCachedModel.POOL.destroy();
		AsyncCachedModel.POOL = null;
	}

	private static final Runtime RUNTIME = Runtime.getRuntime();

	private int sceneId;
	private int bufferOffset;
	private int uvBufferOffset;

	private int bottomY;
	private int radius;
	private int diameter;
	private int XYZMag;
	private int renderMode;

	private int modelHeight;
	private int animationHeightOffset;

	@Accessors(fluent = true)
	private boolean useBoundingBox;

	private int verticesCount;
	private int faceCount;

	private byte transparency;
	private byte overrideAmount;
	private byte overrideHue;
	private byte overrideSaturation;
	private byte overrideLuminance;

	private long hash;

	private final CachedArrayField<?>[] cachedFields = new CachedArrayField<?>[21];

	private final CachedArrayField<float[]> verticesX = addField(FLOAT, VERTEX_TYPE);
	private final CachedArrayField<float[]> verticesY = addField(FLOAT, VERTEX_TYPE);
	private final CachedArrayField<float[]> verticesZ = addField(FLOAT, VERTEX_TYPE);

	private final CachedArrayField<int[]> faceIndices1 = addField(INT, FACE_TYPE);
	private final CachedArrayField<int[]> faceIndices2 = addField(INT, FACE_TYPE);
	private final CachedArrayField<int[]> faceIndices3 = addField(INT, FACE_TYPE);

	private final CachedArrayField<int[]> faceColors1 = addField(INT, FACE_TYPE);
	private final CachedArrayField<int[]> faceColors2 = addField(INT, FACE_TYPE);
	private final CachedArrayField<int[]> faceColors3 = addField(INT, FACE_TYPE);

	private final CachedArrayField<short[]> unlitFaceColors = addField(SHORT, FACE_TYPE);
	private final CachedArrayField<short[]> faceTextures = addField(SHORT, FACE_TYPE);

	private final CachedArrayField<byte[]> faceRenderPriorities = addField(BYTE, FACE_TYPE);
	private final CachedArrayField<byte[]> faceTransparencies = addField(BYTE, FACE_TYPE);
	private final CachedArrayField<byte[]> faceBias = addField(BYTE, FACE_TYPE);
	private final CachedArrayField<byte[]> textureFaces = addField(BYTE, FACE_TYPE);

	private final CachedArrayField<int[]> texIndices1 = addField(INT, TEX_TYPE);
	private final CachedArrayField<int[]> texIndices2 = addField(INT, TEX_TYPE);
	private final CachedArrayField<int[]> texIndices3 = addField(INT, TEX_TYPE);

	private final CachedArrayField<int[]> vertexNormalsX = addField(INT, VERTEX_TYPE);
	private final CachedArrayField<int[]> vertexNormalsY = addField(INT, VERTEX_TYPE);
	private final CachedArrayField<int[]> vertexNormalsZ = addField(INT, VERTEX_TYPE);

	private final AtomicBoolean isProcessing = new AtomicBoolean(false);
	private final AtomicBoolean isCompleted = new AtomicBoolean(false);
	private WorldViewContext ctx;
	private Projection projection;
	@Nullable
	private TileObject tileObject;
	private Renderable renderable;
	private ModelOverride modelOverride;
	private Zone zone;
	private AlphaModel alphaModel;
	private boolean isModelPartiallyVisible;
	private int drawIndex;
	private int orientation;
	private int x;
	private int y;
	private int z;
	private UploadModelFunc uploadFunc;
	private long availableMemory;

	@SuppressWarnings("unchecked")
	private <T> CachedArrayField<T> addField(PooledArrayType arrayType, int fieldType) {
		for (int i = 0; i < cachedFields.length; i++)
			if (cachedFields[i] == null)
				return (CachedArrayField<T>) (cachedFields[i] = new CachedArrayField<>(this, arrayType, fieldType));
		throw new RuntimeException("Created too many fields, only expected: " + cachedFields.length);
	}

	@Override
	public int[] getFaceColors1() { return faceColors1.getValue(); }

	@Override
	public int[] getFaceColors2() { return faceColors2.getValue(); }

	@Override
	public int[] getFaceColors3() { return faceColors3.getValue(); }

	@Override
	public short[] getUnlitFaceColors() { return unlitFaceColors.getValue(); }

	@Override
	public byte[] getFaceRenderPriorities() { return faceRenderPriorities.getValue(); }

	@Override
	public byte[] getFaceBias() { return faceBias.getValue(); }

	@Override
	public int[] getVertexNormalsX() { return vertexNormalsX.getValue(); }

	@Override
	public int[] getVertexNormalsY() { return vertexNormalsY.getValue(); }

	@Override
	public int[] getVertexNormalsZ() { return vertexNormalsZ.getValue(); }

	@Override
	public byte[] getTextureFaces() { return textureFaces.getValue(); }

	@Override
	public int[] getTexIndices1() { return texIndices1.getValue(); }

	@Override
	public int[] getTexIndices2() { return texIndices2.getValue(); }

	@Override
	public int[] getTexIndices3() { return texIndices3.getValue(); }

	@Override
	public float[] getVerticesX() { return verticesX.getValue(); }

	@Override
	public float[] getVerticesY() { return verticesY.getValue(); }

	@Override
	public float[] getVerticesZ() { return verticesZ.getValue(); }

	@Override
	public int[] getFaceIndices1() { return faceIndices1.getValue(); }

	@Override
	public int[] getFaceIndices2() { return faceIndices2.getValue(); }

	@Override
	public int[] getFaceIndices3() { return faceIndices3.getValue(); }

	@Override
	public byte[] getFaceTransparencies() { return faceTransparencies.getValue(); }

	@Override
	public short[] getFaceTextures() { return faceTextures.getValue(); }

	public synchronized boolean setup(Model model) {
		// Wait for completion so that the job has cleared the job system before clearing the isProcessing flag
		waitForCompletion(true);

		availableMemory = RUNTIME.freeMemory();
		if (processCachedFields(model, false))
			return true;

		// We've failed to obtain arrays to cache the model, return any we obtained and return false
		for (int i = 0; i < cachedFields.length; i++)
			cachedFields[i].reset();

		return false;
	}

	public synchronized void queue(
		@Nonnull WorldViewContext ctx,
		@Nonnull Projection projection,
		@Nullable TileObject tileObject,
		@Nonnull Renderable renderable,
		@Nonnull ModelOverride modelOverride,
		@Nonnull Model model,
		@Nonnull Zone zone,
		AlphaModel alphaModel,
		boolean isModelPartiallyVisible,
		int drawIndex,
		int orientation,
		int x, int y, int z,
		@Nonnull UploadModelFunc uploadFunc
	) {
		this.ctx = ctx;
		this.projection = projection;
		this.tileObject = tileObject;
		this.renderable = renderable;
		this.modelOverride = modelOverride;
		this.zone = zone;
		this.alphaModel = alphaModel;
		this.isModelPartiallyVisible = isModelPartiallyVisible;
		this.drawIndex = drawIndex;
		this.orientation = orientation;
		this.x = x;
		this.y = y;
		this.z = z;
		this.uploadFunc = uploadFunc;

		// Scalars
		sceneId = model.getSceneId();
		bufferOffset = model.getBufferOffset();
		uvBufferOffset = model.getUvBufferOffset();

		bottomY = model.getBottomY();
		radius = model.getRadius();
		diameter = model.getDiameter();
		XYZMag = model.getXYZMag();
		renderMode = model.getRenderMode();

		modelHeight = model.getModelHeight();
		animationHeightOffset = model.getAnimationHeightOffset();

		useBoundingBox = model.useBoundingBox();
		hash = model.getHash();

		transparency = model.getTransparency();
		overrideAmount = model.getOverrideAmount();
		overrideHue = model.getOverrideHue();
		overrideSaturation = model.getOverrideSaturation();
		overrideLuminance = model.getOverrideLuminance();

		// Counts
		verticesCount = model.getVerticesCount();
		faceCount = model.getFaceCount();

		if (alphaModel != null)
			zone.pendingModelJobs.add(this);

		isProcessing.set(false);
		isCompleted.set(false);

		INFLIGHT.add(this);
		queue();

		processCachedFields(model, true);
	}

	private boolean processCachedFields(Model model, boolean cache) {
		// Caching is done in order of access
		// Ideally this should be updated to reflect any changes
		boolean success = true;
		success &= verticesX.cache(model, model.getVerticesX(), cache);
		success &= verticesY.cache(model, model.getVerticesY(), cache);
		success &= verticesZ.cache(model, model.getVerticesZ(), cache);

		success &= faceColors1.cache(model, model.getFaceColors1(), cache);
		success &= faceColors3.cache(model, model.getFaceColors3(), cache);

		success &= faceIndices1.cache(model, model.getFaceIndices1(), cache);
		success &= faceIndices2.cache(model, model.getFaceIndices2(), cache);
		success &= faceIndices3.cache(model, model.getFaceIndices3(), cache);

		success &= faceTransparencies.cache(model, model.getFaceTransparencies(), cache);
		success &= faceTextures.cache(model, model.getFaceTextures(), cache);
		success &= textureFaces.cache(model, model.getTextureFaces(), cache);

		success &= faceRenderPriorities.cache(model, model.getFaceRenderPriorities(), cache);

		success &= vertexNormalsX.cache(model, model.getVertexNormalsX(), cache);
		success &= vertexNormalsY.cache(model, model.getVertexNormalsY(), cache);
		success &= vertexNormalsZ.cache(model, model.getVertexNormalsZ(), cache);

		success &= faceColors2.cache(model, model.getFaceColors2(), cache);
		success &= unlitFaceColors.cache(model, model.getUnlitFaceColors(), cache);
		success &= faceBias.cache(model, model.getFaceBias(), cache);

		success &= texIndices1.cache(model, model.getTexIndices1(), cache);
		success &= texIndices2.cache(model, model.getTexIndices2(), cache);
		success &= texIndices3.cache(model, model.getTexIndices3(), cache);

		return success;
	}

	@Override
	protected boolean canStart() {
		if (isProcessing.get()) // Work has been stolen, so pop it off the queue
			return true;

		return
			verticesX.isCached() && verticesY.isCached() && verticesZ.isCached() &&
			faceIndices1.isCached() && faceIndices2.isCached() && faceIndices3.isCached() &&
			faceColors3.isCached();
	}

	@Override
	protected void onRun() {
		processModel();
	}

	public boolean processModel() {
		if (!isProcessing.compareAndSet(false, true))
			return false;

		try {
			uploadFunc.upload(
				ctx,
				projection,
				tileObject,
				renderable,
				modelOverride,
				this,
				zone,
				alphaModel,
				isModelPartiallyVisible,
				drawIndex,
				orientation,
				x, y, z
			);
			isCompleted.set(true);
		} catch (Exception e) {
			log.error("Error drawing temp object", e);
		} finally {
			// Reset cached status before returning to the POOL
			for (int i = 0; i < cachedFields.length; i++) {
				final CachedArrayField<?> field = cachedFields[i];
				field.ensureCached();
				field.reset();
			}

			if (alphaModel != null)
				zone.pendingModelJobs.remove(this);

			ctx = null;
			projection = null;
			zone = null;
			alphaModel = null;
			tileObject = null;
			renderable = null;
			modelOverride = null;
			drawIndex = -1;

			INFLIGHT.remove(this);
			POOL.recycle(this);
		}

		return true;
	}

	@Override
	public Model getUnskewedModel() { return this; }

	@Override
	public void calculateBoundsCylinder() {}

	@Override
	public void drawFrustum(int zero, int xRotate, int yRotate, int zRotate, int xCamera, int yCamera, int zCamera) {
		throw new UnsupportedOperationException();
	}

	@Override
	public void drawOrtho(int zero, int xRotate, int yRotate, int zRotate, int xCamera, int yCamera, int zCamera, int zoom) {
		throw new UnsupportedOperationException();
	}

	@Override
	public void calculateExtreme(int orientation) {
		throw new UnsupportedOperationException();
	}

	@Nonnull
	@Override
	public AABB getAABB(int orientation) {
		throw new UnsupportedOperationException();
	}

	@Override
	public Model rotateY90Ccw() {
		throw new UnsupportedOperationException();
	}

	@Override
	public Model rotateY180Ccw() {
		throw new UnsupportedOperationException();
	}

	@Override
	public Model rotateY270Ccw() {
		throw new UnsupportedOperationException();
	}

	@Override
	public Model translate(int x, int y, int z) {
		throw new UnsupportedOperationException();
	}

	@Override
	public Model scale(int x, int y, int z) {
		throw new UnsupportedOperationException();
	}

	@Override
	public Model getModel() {
		throw new UnsupportedOperationException();
	}

	@Override
	public Node getNext() {
		throw new UnsupportedOperationException();
	}

	@Override
	public Node getPrevious() {
		throw new UnsupportedOperationException();
	}

	@FunctionalInterface
	public interface UploadModelFunc {
		void upload(
			@Nonnull WorldViewContext ctx,
			@Nonnull Projection projection,
			@Nullable TileObject tileObject,
			@Nonnull Renderable renderable,
			@Nonnull ModelOverride modelOverride,
			@Nonnull Model model,
			@Nonnull Zone zone,
			AlphaModel alphaModel,
			boolean isModelPartiallyVisible,
			int drawIndex,
			int orientation,
			int x, int y, int z
		);
	}

	private static final int VERTEX_TYPE = 0;
	private static final int FACE_TYPE = 1;
	private static final int TEX_TYPE = 2;

	@RequiredArgsConstructor
	private final class CachedArrayField<T> {
		private final AsyncCachedModel model;
		private final PooledArrayType arrayType;
		private final int fieldType;

		private T value;
		private final AtomicBoolean cached = new AtomicBoolean(false);

		public boolean isCached() {
			return cached.get();
		}

		public void ensureCached() {
			while (!cached.get())
				LockSupport.parkNanos(this, 5);
		}

		public T getValue() {
			ensureCached();
			return value;
		}

		public void reset() {
			if (value != null)
				arrayType.release(value);
			value = null;
			cached.set(false);
		}

		@SuppressWarnings("SuspiciousSystemArraycopy")
		public boolean cache(final Model m, T src, boolean cache) {
			if (src == null) {
				if (cache)
					cached.set(true);
				return true;
			}

			final int arraySize;
			switch (fieldType) {
				case VERTEX_TYPE:
					arraySize = m.getVerticesCount();
					break;
				case FACE_TYPE:
					arraySize = m.getFaceCount();
					break;
				default:
					arraySize = Array.getLength(src);
					break;
			}

			if (!cache) {
				// Attempt to get an array from the pool, if we fail check if enough memory is available before creating
				final long requested = (long) arraySize * arrayType.stride;
				value = arrayType.borrow(arraySize, false);

				if (value == null && requested < availableMemory) {
					availableMemory -= requested;
					value = arrayType.create(arraySize);
				}

				return value != null;
			}

			if (!model.isCompleted.get())
				System.arraycopy(src, 0, value, 0, arraySize);

			cached.set(true);
			return true;
		}
	}
}

package rs117.hd.renderer.zone;

import java.util.ArrayDeque;
import java.util.Arrays;
import javax.annotation.Nonnull;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import rs117.hd.utils.CommandBuffer;
import rs117.hd.utils.Destructible;
import rs117.hd.utils.buffer.GLBuffer;
import rs117.hd.utils.buffer.GLMappedBufferIntWriter;
import rs117.hd.utils.buffer.GLMappedBufferIntWriter.ReservedView;
import rs117.hd.utils.buffer.GLTextureBuffer;

import static org.lwjgl.opengl.GL33C.*;
import static rs117.hd.HdPlugin.NVIDIA_GPU;
import static rs117.hd.HdPlugin.SUPPORTS_INDIRECT_DRAW;
import static rs117.hd.HdPlugin.SUPPORTS_MULTI_INDIRECT_DRAW;
import static rs117.hd.HdPlugin.SUPPORTS_STORAGE_BUFFERS;
import static rs117.hd.renderer.zone.ZoneRenderer.TEXTURE_UNIT_TEXTURED_FACES;
import static rs117.hd.utils.MathUtils.*;
import static rs117.hd.utils.buffer.GLBuffer.STORAGE_IMMUTABLE;
import static rs117.hd.utils.buffer.GLBuffer.STORAGE_PERSISTENT;
import static rs117.hd.utils.buffer.GLBuffer.STORAGE_WRITE;

@Slf4j
public class DynamicModelVAO implements Destructible {
	private static final int INITIAL_SIZE = (int) (64 * KiB);

	// Temp vertex format
	// pos float vec3(x, y, z)
	// uvw short vec3(u, v, w)
	// normal short vec3(nx, ny, nz)
	static final int VERT_SIZE = 32;
	static final int VERT_SIZE_INTS = VERT_SIZE / 4;

	// Metadata format
	// worldViewIndex int
	// dummy sceneOffset ivec2 for macOS workaround
	static final int METADATA_SIZE = 12;

	@Getter
	private int vao;

	private final GLBuffer vboRender;
	private final GLBuffer vboStaging;
	private final GLTextureBuffer tbo;

	private final ArrayDeque<View> usedViews = new ArrayDeque<>();
	private final ArrayDeque<View> freeViews = new ArrayDeque<>();

	private final GLMappedBufferIntWriter vboWriter;
	private final GLMappedBufferIntWriter tboWriter;

	private boolean isMapped = false;
	private int[] drawOffsets = new int[16];
	private int[] drawCounts = new int[16];
	private int writtenRangeCount;
	private int drawRangeCount;

	private long[] srcCopyOffsets = new long[16];
	private long[] dstCopyOffsets = new long[16];
	private long[] copyNumBytes = new long[16];

	DynamicModelVAO(String name, boolean useStagingBuffer) {
		if (useStagingBuffer && SUPPORTS_STORAGE_BUFFERS) {
			this.vboRender = new GLBuffer("VAO::VBO::" + name, GL_ARRAY_BUFFER, GL_STATIC_DRAW, 0);
			this.vboStaging = new GLBuffer(
				"VAO::VBO_STAGING::" + name,
				GL_ARRAY_BUFFER,
				GL_STREAM_DRAW,
				STORAGE_PERSISTENT | STORAGE_IMMUTABLE | STORAGE_WRITE
			);
		} else {
			this.vboRender = this.vboStaging = new GLBuffer(
				"VAO::VBO::" + name,
				GL_ARRAY_BUFFER,
				GL_STREAM_DRAW,
				STORAGE_PERSISTENT | STORAGE_IMMUTABLE | STORAGE_WRITE
			);
		}
		this.vboWriter = new GLMappedBufferIntWriter(this.vboStaging);

		this.tbo = new GLTextureBuffer("VAO::TBO::" + name, GL_STREAM_DRAW, STORAGE_PERSISTENT | STORAGE_IMMUTABLE | STORAGE_WRITE);
		this.tboWriter = new GLMappedBufferIntWriter(this.tbo);
	}

	public boolean hasStagingBuffer() { return vboRender != vboStaging; }

	void initialize() {
		vao = glGenVertexArrays();
		tbo.initialize(INITIAL_SIZE);
		vboRender.initialize(INITIAL_SIZE);
		if (vboRender != vboStaging)
			vboStaging.initialize(INITIAL_SIZE);

		bindRenderVAO();
	}

	public void bindMetadataVAO(@Nonnull GLBuffer vboMetadata) {
		glBindVertexArray(vao);
		glBindBuffer(GL_ARRAY_BUFFER, vboMetadata.id);

		// WorldView index (not ID)
		glEnableVertexAttribArray(6);
		glVertexAttribDivisor(6, 1);
		glVertexAttribIPointer(6, 1, GL_INT, METADATA_SIZE, 0);

		if (!NVIDIA_GPU) {
			// Workaround for incorrect implementations of disabled vertex attribs, particularly on macOS
			glEnableVertexAttribArray(7);
			glVertexAttribDivisor(7, 1);
			glVertexAttribIPointer(7, 2, GL_INT, METADATA_SIZE, 4);
		}

		glBindBuffer(GL_ARRAY_BUFFER, 0);
		glBindVertexArray(0);
	}

	void bindRenderVAO() {
		glBindVertexArray(vao);
		glBindBuffer(GL_ARRAY_BUFFER, vboRender.id);

		// Position
		glEnableVertexAttribArray(0);
		glVertexAttribPointer(0, 3, GL_FLOAT, false, VERT_SIZE, 0);

		// UVs
		glEnableVertexAttribArray(1);
		glVertexAttribPointer(1, 4, GL_HALF_FLOAT, false, VERT_SIZE, 12);

		// Normals
		glEnableVertexAttribArray(2);
		glVertexAttribPointer(2, 4, GL_SHORT, false, VERT_SIZE, 20);

		// TextureFaceIdx
		glEnableVertexAttribArray(3);
		glVertexAttribIPointer(3, 1, GL_INT, VERT_SIZE, 28);

		glBindBuffer(GL_ARRAY_BUFFER, 0);
		glBindVertexArray(0);
	}

	void map() {
		vboWriter.map(false);
		tboWriter.map(false);

		reset();
		isMapped = true;
	}

	synchronized void unmap(boolean coalesce) {
		final int renderVBOId = vboRender.id;
		long vboWrittenBytes = vboWriter.flush();
		tboWriter.flush();

		if (drawRangeCount > 0) {
			mergeRanges();

			if (hasStagingBuffer()) {
				vboRender.orphan();
				if (drawRangeCount > 1 && coalesce) {
					if (srcCopyOffsets.length < drawRangeCount) {
						srcCopyOffsets = new long[drawRangeCount];
						dstCopyOffsets = new long[drawRangeCount];
						copyNumBytes = new long[drawRangeCount];
					}

					long dstOffset = 0;
					for (int i = 0; i < drawRangeCount; i++) {
						srcCopyOffsets[i] = drawOffsets[i] * (long) VERT_SIZE;
						dstCopyOffsets[i] = dstOffset;
						copyNumBytes[i] = drawCounts[i] * (long) VERT_SIZE;
						dstOffset += copyNumBytes[i];
					}
					vboStaging.copyMultiTo(vboRender, srcCopyOffsets, dstCopyOffsets, copyNumBytes, drawRangeCount);

					drawOffsets[0] = 0;
					drawCounts[0] = (int) (dstOffset / VERT_SIZE);
					drawRangeCount = 1;
				} else {
					vboStaging.copyTo(vboRender, 0, 0, vboWrittenBytes);
				}
			}
		}

		if (renderVBOId != vboRender.id)
			bindRenderVAO();
		isMapped = false;
	}

	@Override
	public void destroy() {
		vboWriter.destroy();
		tboWriter.destroy();
		vboRender.destroy();
		vboStaging.destroy();
		tbo.destroy();

		if (vao != 0)
			glDeleteVertexArrays(vao);
		vao = 0;
	}

	synchronized int obtainDrawIndex() {
		int drawIndex = drawRangeCount++;
		if (drawRangeCount >= drawOffsets.length) {
			int oldLength = drawOffsets.length;
			drawOffsets = Arrays.copyOf(drawOffsets, oldLength * 2);
			drawCounts = Arrays.copyOf(drawCounts, oldLength * 2);
		}
		return drawIndex;
	}

	View beginDraw(int faceCount) {
		return beginDraw(-1, faceCount);
	}

	public synchronized View beginDraw(int drawIdx, int faceCount) {
		if (drawIdx == -1)
			drawIdx = obtainDrawIndex();

		assert drawIdx >= 0 && drawIdx < drawRangeCount : "drawIdx " + drawIdx + " out of bounds from 0 to " + drawRangeCount;
		assert drawOffsets[drawIdx] == 0 && drawCounts[drawIdx] == 0 : String.format(
			"Provided draw index is already in use: %d %d %d",
			drawIdx, drawOffsets[drawIdx], drawCounts[drawIdx]
		);
		assert isMapped : "beginDraw called while not mapped, this is not allowed!";

		View view = freeViews.poll();
		if (view == null)
			view = new View();
		view.vbo = vboWriter.reserve(faceCount * 3 * VERT_SIZE_INTS);
		view.tbo = tboWriter.reserve(faceCount * 9);
		view.vao = vao;
		view.tboTexId = tbo.getTexId();
		view.drawIdx = drawIdx;

		return view;
	}

	private synchronized void endDraw(View view) {
		assert drawOffsets[view.drawIdx] == 0 && drawCounts[view.drawIdx] == 0 : String.format(
			"Provided draw index is already in use: %d %d %d",
			view.drawIdx, drawOffsets[view.drawIdx], drawCounts[view.drawIdx]
		);
		assert isMapped : "beginDraw called while not mapped, this is not allowed!";

		drawOffsets[view.drawIdx] = view.getStartOffset() / VERT_SIZE_INTS;
		drawCounts[view.drawIdx] = view.getVertexCount();
		writtenRangeCount = max(writtenRangeCount, view.drawIdx + 1);

		// Clear ReservedViews before returning to pool
		view.vbo = null;
		view.tbo = null;

		usedViews.add(view);
	}

	void mergeRanges() {
		drawRangeCount = 0;
		for (int i = 0; i < writtenRangeCount; i++) {
			if (drawCounts[i] <= 0)
				continue;

			if (drawRangeCount > 0 && drawOffsets[drawRangeCount - 1] + drawCounts[drawRangeCount - 1] == drawOffsets[i]) {
				drawCounts[drawRangeCount - 1] += drawCounts[i];
			} else {
				if (drawRangeCount != i) {
					drawOffsets[drawRangeCount] = drawOffsets[i];
					drawCounts[drawRangeCount] = drawCounts[i];
				}
				drawRangeCount++;
			}
		}
	}

	void draw(CommandBuffer cmd) {
		if (drawRangeCount <= 0)
			return;

		cmd.BindVertexArray(vao);
		cmd.BindTextureUnit(GL_TEXTURE_BUFFER, tbo.getTexId(), TEXTURE_UNIT_TEXTURED_FACES);

		if (drawRangeCount == 1) {
			if (SUPPORTS_INDIRECT_DRAW) {
				cmd.DrawArraysIndirect(GL_TRIANGLES, drawOffsets[0], drawCounts[0], ZoneRenderer.indirectDrawCmdsStaging);
			} else {
				cmd.DrawArrays(GL_TRIANGLES, drawOffsets[0], drawCounts[0]);
			}
		} else {
			if (SUPPORTS_MULTI_INDIRECT_DRAW) {
				cmd.MultiDrawArraysIndirect(GL_TRIANGLES, drawOffsets, drawCounts, drawRangeCount, ZoneRenderer.indirectDrawCmdsStaging);
			} else {
				cmd.MultiDrawArrays(GL_TRIANGLES, drawOffsets, drawCounts, drawRangeCount);
			}
		}
	}

	void reset() {
		Arrays.fill(drawOffsets, 0, writtenRangeCount, 0);
		Arrays.fill(drawCounts, 0, writtenRangeCount, 0);
		drawRangeCount = 0;
		freeViews.addAll(usedViews);
		usedViews.clear();
	}

	public final class View {
		public ReservedView vbo;
		public ReservedView tbo;
		public int vao;
		public int tboTexId;
		private int drawIdx;

		public int getStartOffset() {
			return vbo.getOffsetInts();
		}

		public int getEndOffset() {
			return vbo.getEndOffsetInts();
		}

		public int getVertexCount() {
			return (getEndOffset() - getStartOffset()) / VERT_SIZE_INTS;
		}

		public void end() {
			endDraw(this);
		}
	}
}

package rs117.hd.renderer.zone;

import java.nio.IntBuffer;
import java.util.ArrayDeque;
import lombok.extern.slf4j.Slf4j;
import rs117.hd.utils.buffer.GLMappedBufferIntWriter;
import rs117.hd.utils.jobs.Job;

@Slf4j
public final class EboAlphaWriterJob extends Job {
	public final ArrayDeque<Zone.AlphaModel> alphaModels = new ArrayDeque<>();
	public GLMappedBufferIntWriter.ReservedView eboAlphaView;

	@Override
	protected void onRun() {
		try {
			final IntBuffer eboAlphaBuffer = eboAlphaView.getBuffer();
			if (eboAlphaBuffer == null)
				return;

			Zone.AlphaModel m;
			while ((m = alphaModels.poll()) != null) {
				if (m.sortedFacesLen <= 0 || m.tempSortedFaces == null)
					continue;

				if (eboAlphaBuffer.remaining() < m.sortedFacesLen) {
					log.warn("Not enough space in eboAlphaBuffer for alpha faces");
					break;
				}
				eboAlphaBuffer.put(m.tempSortedFaces, 0, m.sortedFacesLen);
			}
		} finally {
			eboAlphaView = null;
		}
	}
}

