	public void estimateZoneSize(ZoneSceneContext ctx, Zone zone, int mzx, int mzz) throws InterruptedException {
		// Initialize the zone as containing only water, until a non-water tile is found
		zone.onlyWater = true;

		for (int z = 3; z >= 0; --z) {
			for (int xoff = 0; xoff < CHUNK_SIZE; ++xoff) {
				for (int zoff = 0; zoff < CHUNK_SIZE; ++zoff) {
					Tile t = tiles[z][(mzx << 3) + xoff][(mzz << 3) + zoff];
					if (t != null) {
						if (onBeforeProcessTile != null)
							onBeforeProcessTile.invoke(t, true);
						estimateZoneTileSize(ctx, zone, t);
					}
				}
			}
		}

		// Skip gap filling for any unloaded regions by checking if they are completely empty.
		// This used to be more important when XTEAs prevented extended scene loading until the area had been visited,
		// but it can still occur for scene loads while the client is initially loading the cache.
		boolean shouldFillGaps =
			ctx.fillGaps &&
			zone.sizeO > 0 &&
			ctx.sceneBase != null &&
			(ctx.currentArea == null || ctx.currentArea.fillGaps);
		if (shouldFillGaps)
			estimateZoneGapFillers(ctx, zone, mzx, mzz);
	}

	public void uploadZone(ZoneSceneContext ctx, Zone zone, int mzx, int mzz) throws InterruptedException {
		var vb = zone.vboO != null ? zoneVboO.setBuffer(zone.vboO.mapped()) : null;
		var ab = zone.vboA != null ? zoneVboA.setBuffer(zone.vboA.mapped()) : null;
		var fb = zone.tboF != null ? zoneTboF.setBuffer(zone.tboF.mapped()) : null;
		assert zone.tboF != null;

		roofIds.length = 0;
		for (int level = 0; level <= 3; ++level) {
			for (int xoff = 0; xoff < CHUNK_SIZE; ++xoff) {
				for (int zoff = 0; zoff < CHUNK_SIZE; ++zoff) {
					int rid = roofs[level][(mzx << 3) + xoff][(mzz << 3) + zoff];
					if (rid > 0) {
						roofIds
							.ensureCapacity(1)
							.putUnique(rid);
					}
				}
			}
		}

		zone.rids = new int[4][roofIds.length];
		zone.roofStart = new int[4][roofIds.length];
		zone.roofEnd = new int[4][roofIds.length];

		for (int z = 0; z <= 3; ++z) {
			renderablePlane = z;

			if (z == 0) {
				uploadZoneLevel(ctx, zone, mzx, mzz, 0, false, false, true, vb, ab, fb);
				uploadZoneLevel(ctx, zone, mzx, mzz, 0, true, false, true, vb, ab, fb);
				uploadZoneLevel(ctx, zone, mzx, mzz, 1, true, false, true, vb, ab, fb);
				uploadZoneLevel(ctx, zone, mzx, mzz, 2, true, false, true, vb, ab, fb);
				uploadZoneLevel(ctx, zone, mzx, mzz, 3, true, false, true, vb, ab, fb);
			} else {
				uploadZoneLevel(ctx, zone, mzx, mzz, z, false, false, false, vb, ab, fb);
			}

			if (vb != null)
				zone.levelOffsets[z] = vb.position();
		}

		if (vb != null) {
			uploadZoneLevel(ctx, zone, mzx, mzz, 0, false, true, false, vb, ab, fb);
			uploadZoneLevel(ctx, zone, mzx, mzz, 0, true, true, false, vb, ab, fb);
			uploadZoneLevel(ctx, zone, mzx, mzz, 1, true, true, false, vb, ab, fb);
			uploadZoneLevel(ctx, zone, mzx, mzz, 2, true, true, false, vb, ab, fb);
			uploadZoneLevel(ctx, zone, mzx, mzz, 3, true, true, false, vb, ab, fb);
			zone.levelOffsets[Zone.LEVEL_TERRAIN] = vb.position();

			// Upload water surface tiles to be drawn after everything else
			if (zone.hasWater)
				uploadZoneWater(ctx, zone, mzx, mzz, vb, fb);
			zone.levelOffsets[Zone.LEVEL_WATER_SURFACE] = vb.position();

			if (zone.hasGapFiller)
				uploadZoneGapFillers(ctx, mzx, mzz, vb, fb);
			zone.levelOffsets[Zone.LEVEL_GAP_FILLER] = vb.position();
		}
	}

	private void uploadZoneLevel(
		ZoneSceneContext ctx,
		Zone zone,
		int mzx,
		int mzz,
		int level,
		boolean visbelow,
		boolean onlyTiles,
		boolean onlyRenderables,
		GpuIntBuffer vb,
		GpuIntBuffer ab,
		GpuIntBuffer fb
	) throws InterruptedException {
		int ridx = 0;

		// upload the roofs and save their positions
		for (int i = 0; i < roofIds.length; ++i ) {
			final int id = roofIds.array[i];
			int pos = vb != null ? vb.position() : 0;

			uploadZoneLevelRoof(ctx, zone, mzx, mzz, level, id, visbelow, onlyTiles, onlyRenderables, vb, ab, fb);

			int endpos = vb != null ? vb.position() : 0;

			if (endpos > pos) {
				zone.rids[level][ridx] = id;
				zone.roofStart[level][ridx] = pos;
				zone.roofEnd[level][ridx] = endpos;
				++ridx;
			}
		}

		// upload everything else
		uploadZoneLevelRoof(ctx, zone, mzx, mzz, level, 0, visbelow, onlyTiles, onlyRenderables, vb, ab, fb);
	}

	private void uploadZoneLevelRoof(
		ZoneSceneContext ctx,
		Zone zone,
		int mzx,
		int mzz,
		int level,
		int roofId,
		boolean visbelow,
		boolean onlyTiles,
		boolean onlyRenderables,
		GpuIntBuffer vb,
		GpuIntBuffer ab,
		GpuIntBuffer fb
	) throws InterruptedException {
		this.basex = (mzx - (ctx.sceneOffset >> 3)) << 10;
		this.basez = (mzz - (ctx.sceneOffset >> 3)) << 10;

		for (int xoff = 0; xoff < CHUNK_SIZE; ++xoff) {
			for (int zoff = 0; zoff < CHUNK_SIZE; ++zoff) {
				int msx = (mzx << 3) + xoff;
				int msz = (mzz << 3) + zoff;

				boolean isbridge = (settings[1][msx][msz] & Constants.TILE_FLAG_BRIDGE) != 0;
				int maplevel = level;
				if (isbridge) {
					++maplevel;
				}

				boolean isvisbelow = maplevel <= 3 && (settings[maplevel][msx][msz] & Constants.TILE_FLAG_VIS_BELOW) != 0;
				int rid;
				if (isvisbelow || maplevel == 0) {
					rid = 0;
				} else {
					rid = roofs[maplevel - 1][msx][msz];
				}

				if (isvisbelow != visbelow) {
					continue;
				}

				if (rid == roofId) {
					Tile t = tiles[level][msx][msz];
					if (t != null) {
						this.rid = rid;
						if (onBeforeProcessTile != null)
							onBeforeProcessTile.invoke(t, false);
						uploadZoneTile(ctx, zone, t, false, onlyTiles, false, onlyRenderables, vb, ab, fb);
					}
				}
			}
		}
	}

	private void uploadZoneWater(
		ZoneSceneContext ctx,
		Zone zone,
		int mzx,
		int mzz,
		GpuIntBuffer vb,
		GpuIntBuffer fb
	) throws InterruptedException {
		this.basex = (mzx - (ctx.sceneOffset >> 3)) << 10;
		this.basez = (mzz - (ctx.sceneOffset >> 3)) << 10;

		for (int level = 0; level < MAX_Z; level++) {
			for (int xoff = 0; xoff < CHUNK_SIZE; ++xoff) {
				for (int zoff = 0; zoff < CHUNK_SIZE; ++zoff) {
					final int msx = (mzx << 3) + xoff;
					final int msz = (mzz << 3) + zoff;
					final Tile t = tiles[level][msx][msz];
					if (t == null)
						continue;

					if (onBeforeProcessTile != null)
						onBeforeProcessTile.invoke(t, false);

					uploadZoneTile(ctx, zone, t, false, true, true, false, vb, null, fb);
				}
			}
		}
	}

	private void estimateZoneTileSize(ZoneSceneContext ctx, Zone z, Tile t) {
		var tilePoint = t.getSceneLocation();
		ctx.sceneToWorld(tilePoint.getX(), tilePoint.getY(), t.getPlane(), worldPos);

		int tileExX = tilePoint.getX() + ctx.sceneOffset;
		int tileExY = tilePoint.getY() + ctx.sceneOffset;
		int tileZ = t.getRenderLevel();

		final boolean isTileVisBelow = (settings[tileZ][tileExX][tileExY] & TILE_FLAG_VIS_BELOW) != 0;

		SceneTilePaint paint = t.getSceneTilePaint();
		if (paint != null && paint.getNeColor() != HIDDEN_HSL) {
			z.sizeO += 2;
			z.sizeF += 2;

			TileOverride override = ctx.getTileOverride(tileZ, tileExX, tileExY, TILE_OVERRIDE_MAIN);
			WaterType waterType = proceduralGenerator.seasonalWaterType(override, paint.getTexture());
			if (waterType != WaterType.NONE) {
				z.hasWater = true;
				// Since these are surface tiles, they should perhaps technically be in the alpha buffer,
				// but we'll render them in the correct order without needing face sorting,
				// so we might as well use the opaque buffer for simplicity
				z.sizeO += 2;
				z.sizeF += 2;
			} else {
				z.onlyWater = false;
			}

			boolean isDoubleSided = !isTileVisBelow && tileZ != 0 || override.doubleSidedFaces;
			if (isDoubleSided)
				z.sizeO += 2;
		}

		SceneTileModel model = t.getSceneTileModel();
		if (model != null) {
			int len = model.getFaceX().length;
			z.sizeO += len;
			z.sizeF += len;

			var overlayOverride = ctx.getTileOverride(tileZ, tileExX, tileExY, TILE_OVERRIDE_OVERLAY);
			var underlayOverride = ctx.getTileOverride(tileZ, tileExX, tileExY, TILE_OVERRIDE_UNDERLAY);

			final int[] triangleTextures = model.getTriangleTextureId();
			boolean isFallbackWater = false;
			if (triangleTextures != null) {
				for (int textureId : triangleTextures) {
					if (textureId != -1 && proceduralGenerator.seasonalWaterType(TileOverride.NONE, textureId) != WaterType.NONE) {
						isFallbackWater = true;
						break;
					}
				}
			}
			WaterType overlayWaterType = proceduralGenerator.seasonalWaterType(overlayOverride, 0);
			WaterType underlayWaterType = proceduralGenerator.seasonalWaterType(underlayOverride, 0);
			boolean isOverlayWater = overlayWaterType != WaterType.NONE;
			boolean isUnderlayWater = underlayWaterType != WaterType.NONE;
			if (isFallbackWater || isOverlayWater || isUnderlayWater) {
				z.hasWater = true;
				z.sizeO += len;
				z.sizeF += len;
			} else {
				z.onlyWater = false;
			}

			boolean isDoubleSided = !isTileVisBelow && tileZ != 0 || overlayOverride.doubleSidedFaces || underlayOverride.doubleSidedFaces;
			if (isDoubleSided)
				z.sizeO += len;
		}

		WallObject wallObject = t.getWallObject();
		if (wallObject != null) {
			ModelOverride modelOverride = modelOverrideManager.getOverride(wallObject, worldPos);
			if (!modelOverride.hide) {
				estimateRenderableSize(z, wallObject.getRenderable1(), modelOverride);
				estimateRenderableSize(z, wallObject.getRenderable2(), modelOverride);
			}
		}

		DecorativeObject decorativeObject = t.getDecorativeObject();
		if (decorativeObject != null) {
			ModelOverride modelOverride = modelOverrideManager.getOverride(decorativeObject, worldPos);
			if (!modelOverride.hide) {
				estimateRenderableSize(z, decorativeObject.getRenderable(), modelOverride);
				estimateRenderableSize(z, decorativeObject.getRenderable2(), modelOverride);
			}
		}

		GroundObject groundObject = t.getGroundObject();
		if (groundObject != null) {
			ModelOverride modelOverride = modelOverrideManager.getOverride(groundObject, worldPos);
			if (!modelOverride.hide)
				estimateRenderableSize(z, groundObject.getRenderable(), modelOverride);
		}

		GameObject[] gameObjects = t.getGameObjects();
		for (int i = 0; i < gameObjects.length; i++) {
			final GameObject gameObject = gameObjects[i];
			if (gameObject == null || !gameObject.getSceneMinLocation().equals(t.getSceneLocation()))
				continue;

			if (ModelHash.isTemporaryObject(gameObject.getHash()))
				continue;

			ModelOverride modelOverride = modelOverrideManager.getOverride(gameObject, worldPos);
			if (modelOverride.hide)
				continue;

			estimateRenderableSize(z, gameObject.getRenderable(), modelOverride);
		}

		Tile bridge = t.getBridge();
		if (bridge != null)
			estimateZoneTileSize(ctx, z, bridge);
	}

	private void uploadZoneTile(
		ZoneSceneContext ctx,
		Zone zone,
		Tile t,
		boolean isBridge,
		boolean onlyTiles,
		boolean onlyWaterSurface,
		boolean onlyRenderables,
		GpuIntBuffer vertexBuffer,
		GpuIntBuffer alphaBuffer,
		GpuIntBuffer textureBuffer
	) {
		var tilePoint = t.getSceneLocation();
		int tileExX = tilePoint.getX() + ctx.sceneOffset;
		int tileExY = tilePoint.getY() + ctx.sceneOffset;
		int tileZ = t.getRenderLevel();
		ctx.sceneToWorld(tilePoint.getX(), tilePoint.getY(), t.getPlane(), worldPos);

		if (ctx.currentArea != null && !isBridge && !ctx.currentArea.containsPoint(worldPos))
			return;

		boolean drawTile = renderCallbackManager.drawTile(ctx.scene, t);

		SceneTilePaint paint = t.getSceneTilePaint();
		if (paint != null && drawTile && !onlyRenderables) {
			uploadTilePaint(
				ctx,
				t,
				paint,
				onlyWaterSurface,
				tileExX, tileExY, tileZ,
				vertexBuffer,
				textureBuffer,
				tilePoint.getX() * 128 - basex, tilePoint.getY() * 128 - basez
			);
		}

		SceneTileModel model = t.getSceneTileModel();
		if (model != null && drawTile && !onlyRenderables)
			uploadTileModel(ctx, t, model, onlyWaterSurface, tileExX, tileExY, tileZ, basex, basez, vertexBuffer, textureBuffer);

		if (!onlyWaterSurface && !onlyTiles)
			uploadZoneTileRenderables(ctx, zone, t, tileExX, tileExY, tileZ, vertexBuffer, alphaBuffer, textureBuffer);

		Tile bridge = t.getBridge();
		if (bridge != null)
			uploadZoneTile(ctx, zone, bridge, true, onlyTiles, onlyWaterSurface, onlyRenderables, vertexBuffer, alphaBuffer, textureBuffer);
	}

	private void uploadZoneTileRenderables(
		ZoneSceneContext ctx,
		Zone zone,
		Tile t,
		int tileExX, int tileExY, int tileZ,
		GpuIntBuffer vertexBuffer,
		GpuIntBuffer alphaBuffer,
		GpuIntBuffer textureBuffer
	) {
		WallObject wallObject = t.getWallObject();
		if (wallObject != null && renderCallbackManager.drawObject(ctx.scene, wallObject)) {
			int uuid = ModelHash.packUuid(ModelHash.TYPE_WALL_OBJECT, wallObject.getId());
			Renderable renderable1 = wallObject.getRenderable1();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable1,
				uuid,
				HDUtils.convertWallObjectOrientation(wallObject.getOrientationA()),
				0,
				wallObject.getX(),
				wallObject.getZ(),
				wallObject.getY(),
				-1,
				-1,
				-1,
				-1,
				wallObject.getId(),
				tileExX, tileExY, tileZ,
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);

			Renderable renderable2 = wallObject.getRenderable2();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable2,
				uuid,
				HDUtils.convertWallObjectOrientation(wallObject.getOrientationB()),
				0,
				wallObject.getX(),
				wallObject.getZ(),
				wallObject.getY(),
				-1,
				-1,
				-1,
				-1,
				wallObject.getId(),
				tileExX, tileExY, tileZ,
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);
		}

		DecorativeObject decorativeObject = t.getDecorativeObject();
		if (decorativeObject != null && renderCallbackManager.drawObject(ctx.scene, decorativeObject)) {
			int uuid = ModelHash.packUuid(ModelHash.TYPE_DECORATIVE_OBJECT, decorativeObject.getId());
			int preOrientation = HDUtils.getModelPreOrientation(decorativeObject.getConfig());
			Renderable renderable = decorativeObject.getRenderable();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable,
				uuid,
				preOrientation,
				0,
				decorativeObject.getX() + decorativeObject.getXOffset(),
				decorativeObject.getZ(),
				decorativeObject.getY() + decorativeObject.getYOffset(),
				-1,
				-1,
				-1,
				-1,
				decorativeObject.getId(),
				tileExX, tileExY, tileZ,
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);

			Renderable renderable2 = decorativeObject.getRenderable2();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable2,
				uuid,
				preOrientation,
				0,
				decorativeObject.getX(),
				decorativeObject.getZ(),
				decorativeObject.getY(),
				-1,
				-1,
				-1,
				-1,
				decorativeObject.getId(),
				tileExX, tileExY, tileZ,
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);
		}

		GroundObject groundObject = t.getGroundObject();
		if (groundObject != null && renderCallbackManager.drawObject(ctx.scene, groundObject)) {
			Renderable renderable = groundObject.getRenderable();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable,
				ModelHash.packUuid(ModelHash.TYPE_GROUND_OBJECT, groundObject.getId()),
				HDUtils.getModelPreOrientation(groundObject.getConfig()),
				0,
				groundObject.getX(), groundObject.getZ(), groundObject.getY(),
				-1,
				-1, -1,
				-1,
				groundObject.getId(),
				tileExX, tileExY, tileZ,
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);
		}

		GameObject[] gameObjects = t.getGameObjects();
		for (int i = 0; i < gameObjects.length; i++) {
			final GameObject gameObject = gameObjects[i];
			if (gameObject == null || !renderCallbackManager.drawObject(ctx.scene, gameObject))
				continue;

			if (ModelHash.isTemporaryObject(gameObject.getHash()))
				continue;

			Point min = gameObject.getSceneMinLocation();
			if (!min.equals(t.getSceneLocation()))
				continue;

			Point max = gameObject.getSceneMaxLocation();
			Renderable renderable = gameObject.getRenderable();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable,
				ModelHash.packUuid(ModelHash.TYPE_GAME_OBJECT, gameObject.getId()),
				HDUtils.getModelPreOrientation(gameObject.getConfig()),
				gameObject.getModelOrientation(),
				gameObject.getX(), gameObject.getZ(), gameObject.getY(),
				min.getX(),
				min.getY(), max.getX(),
				max.getY(),
				gameObject.getId(),
				tileExX, tileExY, tileZ,
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);
		}
	}

	private void estimateRenderableSize(Zone z, Renderable r, ModelOverride modelOverride) {
		boolean mightHaveTransparency = modelOverride.mightHaveTransparency;
		boolean mightBeDoubleSided = modelOverride.mightBeDoubleSided;
		Model m = null;
		if (r instanceof Model) {
			m = (Model) r;
		} else if (r instanceof DynamicObject) {
			var dynamic = (DynamicObject) r;
			m = dynamic.getModelZbuf();
			if (dynamic.getRecordedObjectComposition() != null) {
				mightHaveTransparency = true;
				mightBeDoubleSided = true;
			}
		}
		if (m == null)
			return;

		int faceCount = m.getFaceCount();
		byte[] transparencies = m.getFaceTransparencies();
		boolean isVanillaTextured = m.getFaceTextures() != null;
		byte modelTransparency = m.getTransparency();

		z.sizeF += faceCount;

		mightBeDoubleSided |= isVanillaTextured;
		if (mightBeDoubleSided)
			faceCount *= 2; // sizeF remains the same, since the double-sided faces will reuse the textureFaceIdx

		z.sizeO += faceCount;

		mightHaveTransparency |= transparencies != null || isVanillaTextured || modelTransparency != 0;
		if (mightHaveTransparency)
			z.sizeA += faceCount;

		z.modelCount++;
	}

	private void uploadZoneRenderable(
		ZoneSceneContext ctx,
		Zone zone,
		Tile tile,
		Renderable r,
		int uuid,
		int preOrientation,
		int orient,
		int x,
		int y,
		int z,
		int lx,
		int lz,
		int ux,
		int uz,
		int id,
		int tileExX, int tileExY, int tileZ,
		GpuIntBuffer opaqueBuffer,
		GpuIntBuffer alphaBuffer,
		GpuIntBuffer textureBuffer
	) {
		Model model;
		if (r instanceof Model) {
			model = (Model) r;
		} else if (r instanceof DynamicObject) {
			var dynamic = (DynamicObject) r;
			model = dynamic.getModelZbuf();

			if (model == null) {
				// The model will likely be drawn through drawDynamic, and may have an impostor
				zone.animatedDynamicObjectIds.add(id);
				return;
			}

			var composition = dynamic.getRecordedObjectComposition();
			if (composition != null)
				uuid = ModelHash.packUuid(ModelHash.TYPE_GAME_OBJECT, composition.getId());
		} else {
			return;
		}

		ModelOverride modelOverride = modelOverrideManager.getOverride(uuid, worldPos);
		if (modelOverride.hide)
			return;

		int alphaStart = alphaBuffer != null ? alphaBuffer.position() : 0;
		try {
			uploadStaticModel(
				ctx, tile, model, modelOverride, uuid,
				preOrientation, orient,
				x - basex, y, z - basez,
				tileExX, tileExY, tileZ,
				opaqueBuffer,
				alphaBuffer,
				textureBuffer
			);
		} catch (Throwable ex) {
			try (var gamevals = gamevalManager.obtainHandle()) {
				log.warn(
					"Error uploading {} {} {} {} (ID {}), override=\"{}\", opaque={}, alpha={}",
					r instanceof DynamicObject ? "dynamic" : "static",
					ModelHash.getTypeName(ModelHash.getUuidType(uuid)),
					ModelHash.getUuidSubType(uuid),
					gamevals.getObjectName(id),
					id,
					modelOverride.description,
					opaqueBuffer,
					alphaBuffer,
					ex
				);
			}
		}

		int alphaEnd = alphaBuffer != null ? alphaBuffer.position() : 0;
		if (alphaEnd > alphaStart) {
			if (lx > -1) {
				lx -= basex >> 7;
				lz -= basez >> 7;
				ux -= basex >> 7;
				uz -= basez >> 7;
				assert lx >= 0 : lx;
				assert lz >= 0 : lz;
				assert ux < 25 : ux; // largest object?
				assert uz < 25 : uz;
			}
			try {
				zone.addAlphaModel(
					plugin,
					materialManager,
					zone.glVaoA,
					zone.tboF.getTexId(),
					model, modelOverride, alphaStart, alphaEnd,
					x - basex, y + modelOverride.heightOffset, z - basez,
					lx, lz, ux, uz,
					rid, renderablePlane, id
				);
			} catch (Throwable ex) {
				try (var gamevals = gamevalManager.obtainHandle()) {
					log.warn(
						"Error adding alpha model for {} {} {} {} (ID {}), override=\"{}\", opaque={}, alpha={}",
						r instanceof DynamicObject ? "dynamic" : "static",
						ModelHash.getTypeName(ModelHash.getUuidType(uuid)),
						ModelHash.getUuidSubType(uuid),
						gamevals.getObjectName(id),
						id,
						modelOverride.description,
						opaqueBuffer,
						alphaBuffer,
						ex
					);
				}
			}
		}
	}

	@SuppressWarnings({ "UnnecessaryLocalVariable" })
	private void uploadTilePaint(
		ZoneSceneContext ctx,
		Tile tile,
		SceneTilePaint paint,
		boolean onlyWaterSurface,
		int tileExX, int tileExY, int tileZ,
		GpuIntBuffer opaqueBuffer,
		GpuIntBuffer textureBuffer,
		int lx,
		int lz
	) {
		if (writeCache == null)
			writeCache = new VertexWriteCache.Collection();
		writeCache.setOutputBuffers(opaqueBuffer, opaqueBuffer, textureBuffer);

		int swColor = paint.getSwColor();
		int seColor = paint.getSeColor();
		int neColor = paint.getNeColor();
		int nwColor = paint.getNwColor();

		if (neColor == HIDDEN_HSL)
			return;

		TileOverride override = ctx.getTileOverride(tileZ, tileExX, tileExY, TILE_OVERRIDE_MAIN);
		WaterType waterType = proceduralGenerator.seasonalWaterType(override, paint.getTexture());
		if (onlyWaterSurface && waterType == WaterType.NONE)
			return;

		ctx.filledTiles[tileExX][tileExY] |= (byte) (1 << tileZ);

		final boolean isTileVisBelow = (settings[tileZ][tileExX][tileExY] & TILE_FLAG_VIS_BELOW) != 0;
		int swHeight = tileHeights[tileZ][tileExX][tileExY];
		int seHeight = tileHeights[tileZ][tileExX + 1][tileExY];
		int neHeight = tileHeights[tileZ][tileExX + 1][tileExY + 1];
		int nwHeight = tileHeights[tileZ][tileExX][tileExY + 1];
		int textureId = paint.getTexture();

		// 0,0
		final int lx0 = lx;
		final int lz0 = lz;

		// 1,0
		final int lx1 = lx + LOCAL_TILE_SIZE;
		final int lz1 = lz;

		// 1,1
		final int lx2 = lx + LOCAL_TILE_SIZE;
		final int lz2 = lz + LOCAL_TILE_SIZE;

		// 0,1
		final int lx3 = lx;
		final int lz3 = lz + LOCAL_TILE_SIZE;

		ProceduralGenerator.tileVertexKeys(ctx, tile, vertices, vertexKeys);
		int swVertexKey = vertexKeys[0];
		int seVertexKey = vertexKeys[1];
		int nwVertexKey = vertexKeys[2];
		int neVertexKey = vertexKeys[3];
		boolean neVertexIsOverlay = false;
		boolean nwVertexIsOverlay = false;
		boolean seVertexIsOverlay = false;
		boolean swVertexIsOverlay = false;

		int uvOrientation = 0;
		float uvScale = 1;

		Material swMaterial = Material.NONE;
		Material seMaterial = Material.NONE;
		Material neMaterial = Material.NONE;
		Material nwMaterial = Material.NONE;

		short[] swNormals = UP_NORMAL;
		short[] seNormals = UP_NORMAL;
		short[] neNormals = UP_NORMAL;
		short[] nwNormals = UP_NORMAL;

		int swTerrainData, seTerrainData, nwTerrainData, neTerrainData;
		swTerrainData = seTerrainData = nwTerrainData = neTerrainData = HDUtils.packTerrainData(true, 0, waterType, tileZ);

		if (!onlyWaterSurface) {
			swNormals = ctx.getVertexNormalOrDefault(swVertexKey, tileNormals[0], UP_NORMAL);
			seNormals = ctx.getVertexNormalOrDefault(seVertexKey, tileNormals[1], UP_NORMAL);
			neNormals = ctx.getVertexNormalOrDefault(neVertexKey, tileNormals[2], UP_NORMAL);
			nwNormals = ctx.getVertexNormalOrDefault(nwVertexKey, tileNormals[3], UP_NORMAL);
		}

		if (waterType == WaterType.NONE) {
			if (textureId != -1) {
				var material = materialManager.fromVanillaTexture(textureId);
				// Disable tile overrides for newly introduced vanilla textures
				if (material.isFallbackVanillaMaterial)
					override = NONE;
				swMaterial = seMaterial = neMaterial = nwMaterial = material;
			}

			boolean allowBlending =
				plugin.configGroundBlending &&
				textureId == -1 &&
				!proceduralGenerator.useDefaultColor(tile, override);
			boolean blendColors = plugin.configGroundBlendingColors && allowBlending;
			boolean blendTextures = plugin.configGroundBlendingTextures && allowBlending;

			GroundMaterial groundMaterial = null;
			if (override != TileOverride.NONE) {
				groundMaterial = override.groundMaterial;
				uvOrientation = override.uvOrientation;
				uvScale = override.uvScale;
				if (!blendColors) {
					swColor = override.modifyColor(swColor);
					seColor = override.modifyColor(seColor);
					nwColor = override.modifyColor(nwColor);
					neColor = override.modifyColor(neColor);
				}
			} else if (textureId == -1) {
				// Fall back to the default ground material if the tile is untextured
				groundMaterial = override.groundMaterial;
			}

			if (blendColors) {
				swColor = ctx.vertexTerrainColor.getOrDefault(swVertexKey, swColor);
				seColor = ctx.vertexTerrainColor.getOrDefault(seVertexKey, seColor);
				neColor = ctx.vertexTerrainColor.getOrDefault(neVertexKey, neColor);
				nwColor = ctx.vertexTerrainColor.getOrDefault(nwVertexKey, nwColor);
			}

			if (plugin.configGroundTextures) {
				if (blendTextures) {
					swMaterial = ctx.vertexTerrainTexture.getOrDefault(swVertexKey, swMaterial);
					seMaterial = ctx.vertexTerrainTexture.getOrDefault(seVertexKey, seMaterial);
					neMaterial = ctx.vertexTerrainTexture.getOrDefault(neVertexKey, neMaterial);
					nwMaterial = ctx.vertexTerrainTexture.getOrDefault(nwVertexKey, nwMaterial);
				} else if (groundMaterial != null) {
					swMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1], worldPos[2]);
					seMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1], worldPos[2]);
					nwMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1] + 1, worldPos[2]);
					neMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1] + 1, worldPos[2]);
				}
			}

			if (ctx.isVertexOverlay(neVertexKey) && ctx.isVertexUnderlay(neVertexKey))
				neVertexIsOverlay = true;
			if (ctx.isVertexOverlay(nwVertexKey) && ctx.isVertexUnderlay(nwVertexKey))
				nwVertexIsOverlay = true;
			if (ctx.isVertexOverlay(seVertexKey) && ctx.isVertexUnderlay(seVertexKey))
				seVertexIsOverlay = true;
			if (ctx.isVertexOverlay(swVertexKey) && ctx.isVertexUnderlay(swVertexKey))
				swVertexIsOverlay = true;
		} else if (onlyWaterSurface) {
			// set colors for the shoreline to create a foam effect in the water shader
			swColor = seColor = nwColor = neColor = 127;

			if (ctx.isVertexWater(swVertexKey) && ctx.isVertexLand(swVertexKey))
				swColor = 0;
			if (ctx.isVertexWater(seVertexKey) && ctx.isVertexLand(seVertexKey))
				seColor = 0;
			if (ctx.isVertexWater(nwVertexKey) && ctx.isVertexLand(nwVertexKey))
				nwColor = 0;
			if (ctx.isVertexWater(neVertexKey) && ctx.isVertexLand(neVertexKey))
				neColor = 0;

			if (seColor == 0 && nwColor == 0 && (neColor == 0 || swColor == 0))
				swColor = seColor = nwColor = neColor = 1 << 16; // Bias depth a bit if it's flush with underwater geometry
		} else {
			// Underwater geometry
			swColor = seColor = neColor = nwColor = UNDERWATER_HSL;

			if (plugin.configGroundTextures) {
				GroundMaterial groundMaterial = GroundMaterial.UNDERWATER_GENERIC;
				swMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1], worldPos[2]);
				seMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1], worldPos[2]);
				nwMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1] + 1, worldPos[2]);
				neMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1] + 1, worldPos[2]);
			}

			int swDepth = ctx.getVertexUnderwaterDepth(swVertexKey);
			int seDepth = ctx.getVertexUnderwaterDepth(seVertexKey);
			int nwDepth = ctx.getVertexUnderwaterDepth(nwVertexKey);
			int neDepth = ctx.getVertexUnderwaterDepth(neVertexKey);
			swHeight += swDepth;
			seHeight += seDepth;
			nwHeight += nwDepth;
			neHeight += neDepth;

			swTerrainData = HDUtils.packTerrainData(true, max(1, swDepth), waterType, tileZ);
			seTerrainData = HDUtils.packTerrainData(true, max(1, seDepth), waterType, tileZ);
			nwTerrainData = HDUtils.packTerrainData(true, max(1, nwDepth), waterType, tileZ);
			neTerrainData = HDUtils.packTerrainData(true, max(1, neDepth), waterType, tileZ);
		}

		swHeight -= override.heightOffset;
		seHeight -= override.heightOffset;
		neHeight -= override.heightOffset;
		nwHeight -= override.heightOffset;

		int swMaterialData = swMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, swVertexIsOverlay);
		int seMaterialData = seMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, seVertexIsOverlay);
		int nwMaterialData = nwMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, nwVertexIsOverlay);
		int neMaterialData = neMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, neVertexIsOverlay);

		float uvcos = -uvScale, uvsin = 0;
		if (uvOrientation % 2048 != 0) {
			float rad = -uvOrientation * JAU_TO_RAD;
			uvcos = cos(rad) * -uvScale;
			uvsin = sin(rad) * -uvScale;
		}
		float uvx = worldPos[0];
		float uvy = worldPos[1];
		float tmp = uvx;
		uvx = fract(uvx * uvcos - uvy * uvsin);
		uvy = fract(tmp * uvsin + uvy * uvcos);

		final var vb = writeCache.getVertexBuffer();
		final var tb = writeCache.getTextureBuffer();

		int texturedFaceIdx = tb.putFace(
			neColor, nwColor, seColor,
			neMaterialData, nwMaterialData, seMaterialData,
			neTerrainData, nwTerrainData, seTerrainData
		);

		vb.putStaticVertex(
			lx2, neHeight, lz2,
			uvx, uvy, 0,
			neNormals[0], neNormals[1], neNormals[2],
			texturedFaceIdx, false
		);

		vb.putStaticVertex(
			lx3, nwHeight, lz3,
			uvx - uvcos, uvy - uvsin, 0,
			nwNormals[0], nwNormals[1], nwNormals[2],
			texturedFaceIdx, false
		);

		vb.putStaticVertex(
			lx1, seHeight, lz1,
			uvx + uvsin, uvy - uvcos, 0,
			seNormals[0], seNormals[1], seNormals[2],
			texturedFaceIdx, false
		);

		boolean isDoubleSided = !onlyWaterSurface && (!isTileVisBelow && tileZ != 0 || override.doubleSidedFaces);
		if (isDoubleSided) {
			vb.putStaticVertex(
				lx1, seHeight, lz1,
				uvx + uvsin, uvy - uvcos, 0,
				-seNormals[0], -seNormals[1], -seNormals[2],
				texturedFaceIdx, true
			);

			vb.putStaticVertex(
				lx3, nwHeight, lz3,
				uvx - uvcos, uvy - uvsin, 0,
				-nwNormals[0], -nwNormals[1], -nwNormals[2],
				texturedFaceIdx, true
			);

			vb.putStaticVertex(
				lx2, neHeight, lz2,
				uvx, uvy, 0,
				-neNormals[0], -neNormals[1], -neNormals[2],
				texturedFaceIdx, true
			);
		}

		texturedFaceIdx = tb.putFace(
			swColor, seColor, nwColor,
			swMaterialData, seMaterialData, nwMaterialData,
			swTerrainData, seTerrainData, nwTerrainData
		);

		vb.putStaticVertex(
			lx0, swHeight, lz0,
			uvx - uvcos + uvsin, uvy - uvsin - uvcos, 0,
			swNormals[0], swNormals[1], swNormals[2],
			texturedFaceIdx, false
		);

		vb.putStaticVertex(
			lx1, seHeight, lz1,
			uvx + uvsin, uvy - uvcos, 0,
			seNormals[0], seNormals[1], seNormals[2],
			texturedFaceIdx, false
		);

		vb.putStaticVertex(
			lx3, nwHeight, lz3,
			uvx - uvcos, uvy - uvsin, 0,
			nwNormals[0], nwNormals[1], nwNormals[2],
			texturedFaceIdx, false
		);

		if (isDoubleSided) {
			vb.putStaticVertex(
				lx3, nwHeight, lz3,
				uvx - uvcos, uvy - uvsin, 0,
				-nwNormals[0], -nwNormals[1], -nwNormals[2],
				texturedFaceIdx, true
			);

			vb.putStaticVertex(
				lx1, seHeight, lz1,
				uvx + uvsin, uvy - uvcos, 0,
				-seNormals[0], -seNormals[1], -seNormals[2],
				texturedFaceIdx, true
			);

			vb.putStaticVertex(
				lx0, swHeight, lz0,
				uvx - uvcos + uvsin, uvy - uvsin - uvcos, 0,
				-swNormals[0], -swNormals[1], -swNormals[2],
				texturedFaceIdx, true
			);
		}

		writeCache.release();
	}

	private void uploadTileModel(
		ZoneSceneContext ctx,
		Tile tile,
		SceneTileModel model,
		boolean onlyWaterSurface,
		int tileExX, int tileExY, int tileZ,
		int basex, int basez,
		GpuIntBuffer opaqueBuffer,
		GpuIntBuffer textureBuffer
	) {
		if (writeCache == null)
			writeCache = new VertexWriteCache.Collection();
		writeCache.setOutputBuffers(opaqueBuffer, opaqueBuffer, textureBuffer);

		final int[] triangleTextures = model.getTriangleTextureId();
		boolean isFallbackWater = false;
		if (triangleTextures != null) {
			for (int textureId : triangleTextures) {
				if (textureId != -1 && proceduralGenerator.seasonalWaterType(TileOverride.NONE, textureId) != WaterType.NONE) {
					isFallbackWater = true;
					break;
				}
			}
		}
		var overlayOverride = ctx.getTileOverride(tileZ, tileExX, tileExY, TILE_OVERRIDE_OVERLAY);
		var underlayOverride = ctx.getTileOverride(tileZ, tileExX, tileExY, TILE_OVERRIDE_UNDERLAY);
		WaterType overlayWaterType = proceduralGenerator.seasonalWaterType(overlayOverride, 0);
		WaterType underlayWaterType = proceduralGenerator.seasonalWaterType(underlayOverride, 0);
		boolean isOverlayWater = overlayWaterType != WaterType.NONE;
		boolean isUnderlayWater = underlayWaterType != WaterType.NONE;
		if (onlyWaterSurface && !isFallbackWater && !isOverlayWater && !isUnderlayWater)
			return;

		ctx.filledTiles[tileExX][tileExY] |= (byte) (1 << tileZ);

		final boolean isTileVisBelow = (settings[tileZ][tileExX][tileExY] & TILE_FLAG_VIS_BELOW) != 0;
		final int[] faceX = model.getFaceX();
		final int[] faceY = model.getFaceY();
		final int[] faceZ = model.getFaceZ();

		final int[] vertexX = model.getVertexX();
		final int[] vertexY = model.getVertexY();
		final int[] vertexZ = model.getVertexZ();

		final int[] triangleColorA = model.getTriangleColorA();
		final int[] triangleColorB = model.getTriangleColorB();
		final int[] triangleColorC = model.getTriangleColorC();

		final int faceCount = faceX.length;

		var sceneLoc = tile.getSceneLocation();
		int tileX = sceneLoc.getX();
		int tileY = sceneLoc.getY();

		for (int face = 0; face < faceCount; ++face) {
			int colorA = triangleColorA[face];
			int colorB = triangleColorB[face];
			int colorC = triangleColorC[face];
			if (colorA == HIDDEN_HSL)
				continue;

			int textureId = triangleTextures == null ? -1 : triangleTextures[face];
			boolean isOverlay = ProceduralGenerator.isOverlayFace(tile, face);
			var override = isOverlay ? overlayOverride : underlayOverride;
			WaterType waterType = proceduralGenerator.seasonalWaterType(override, textureId);
			boolean isWater = waterType != WaterType.NONE;
			if (onlyWaterSurface && !isWater)
				continue;

			final int vertex0 = faceX[face];
			final int vertex1 = faceY[face];
			final int vertex2 = faceZ[face];

			// vertexes are stored in scene local, convert to tile local
			int lx0 = vertexX[vertex0] - basex;
			int ly0 = vertexY[vertex0];
			int lz0 = vertexZ[vertex0] - basez;

			int lx1 = vertexX[vertex1] - basex;
			int ly1 = vertexY[vertex1];
			int lz1 = vertexZ[vertex1] - basez;

			int lx2 = vertexX[vertex2] - basex;
			int ly2 = vertexY[vertex2];
			int lz2 = vertexZ[vertex2] - basez;

			ProceduralGenerator.faceVertexKeys(tile, face, vertices, vertexKeys);
			ProceduralGenerator.faceLocalVertices(tile, face, vertices);

			int vertexKeyA = vertexKeys[0];
			int vertexKeyB = vertexKeys[1];
			int vertexKeyC = vertexKeys[2];

			boolean vertexAIsOverlay = false;
			boolean vertexBIsOverlay = false;
			boolean vertexCIsOverlay = false;

			Material materialA = Material.NONE;
			Material materialB = Material.NONE;
			Material materialC = Material.NONE;

			int uvOrientation = 0;
			float uvScale = 1;

			short[] normalsA = UP_NORMAL;
			short[] normalsB = UP_NORMAL;
			short[] normalsC = UP_NORMAL;

			int terrainDataA, terrainDataB, terrainDataC;
			terrainDataA = terrainDataB = terrainDataC = HDUtils.packTerrainData(true, 0, waterType, tileZ);

			if (!onlyWaterSurface) {
				normalsA = ctx.getVertexNormalOrDefault(vertexKeyA, tileNormals[0], UP_NORMAL);
				normalsB = ctx.getVertexNormalOrDefault(vertexKeyB, tileNormals[1], UP_NORMAL);
				normalsC = ctx.getVertexNormalOrDefault(vertexKeyC, tileNormals[2], UP_NORMAL);
			}

			if (!isWater) {
				if (textureId != -1) {
					var material = materialManager.fromVanillaTexture(textureId);
					// Disable tile overrides for newly introduced vanilla textures
					if (material.isFallbackVanillaMaterial)
						override = NONE;
					materialA = materialB = materialC = material;
				}

				GroundMaterial groundMaterial = null;

				boolean allowBlending =
					plugin.configGroundBlending &&
					textureId == -1 &&
					!(isOverlay && proceduralGenerator.useDefaultColor(tile, override));
				boolean blendColors = plugin.configGroundBlendingColors && allowBlending;
				boolean blendTextures = plugin.configGroundBlendingTextures && allowBlending;

				if (override != TileOverride.NONE) {
					groundMaterial = override.groundMaterial;
					uvOrientation = override.uvOrientation;
					uvScale = override.uvScale;
					if (!blendColors) {
						colorA = override.modifyColor(colorA);
						colorB = override.modifyColor(colorB);
						colorC = override.modifyColor(colorC);
					}
				} else if (textureId == -1) {
					// Fall back to the default ground material if the tile is untextured
					groundMaterial = override.groundMaterial;
				}

				if (blendColors) {
					colorA = ctx.vertexTerrainColor.getOrDefault(vertexKeyA, colorA);
					colorB = ctx.vertexTerrainColor.getOrDefault(vertexKeyB, colorB);
					colorC = ctx.vertexTerrainColor.getOrDefault(vertexKeyC, colorC);
				}

				if (plugin.configGroundTextures) {
					if (blendTextures) {
						materialA = ctx.vertexTerrainTexture.getOrDefault(vertexKeyA, materialA);
						materialB = ctx.vertexTerrainTexture.getOrDefault(vertexKeyB, materialB);
						materialC = ctx.vertexTerrainTexture.getOrDefault(vertexKeyC, materialC);
					} else if (groundMaterial != null) {
						materialA = groundMaterial.getRandomMaterial(
							worldPos[0] + (vertices[0][0] >> LOCAL_COORD_BITS),
							worldPos[1] + (vertices[0][1] >> LOCAL_COORD_BITS),
							worldPos[2]
						);
						materialB = groundMaterial.getRandomMaterial(
							worldPos[0] + (vertices[1][0] >> LOCAL_COORD_BITS),
							worldPos[1] + (vertices[1][1] >> LOCAL_COORD_BITS),
							worldPos[2]
						);
						materialC = groundMaterial.getRandomMaterial(
							worldPos[0] + (vertices[2][0] >> LOCAL_COORD_BITS),
							worldPos[1] + (vertices[2][1] >> LOCAL_COORD_BITS),
							worldPos[2]
						);
					}
				}
			} else if (onlyWaterSurface) {
				// set colors for the shoreline to create a foam effect in the water shader
				colorA = colorB = colorC = 127;
				if (ctx.isVertexWater(vertexKeyA) && ctx.isVertexLand(vertexKeyA))
					colorA = 0;
				if (ctx.isVertexWater(vertexKeyB) && ctx.isVertexLand(vertexKeyB))
					colorB = 0;
				if (ctx.isVertexWater(vertexKeyC) && ctx.isVertexLand(vertexKeyC))
					colorC = 0;
				if (colorA == 0 && colorB == 0 && colorC == 0)
					colorA = colorB = colorC = 1 << 16; // Bias depth a bit if it's flush with underwater geometry
			} else {
				// Underwater geometry
				colorA = colorB = colorC = UNDERWATER_HSL;

				if (plugin.configGroundTextures) {
					GroundMaterial groundMaterial = GroundMaterial.UNDERWATER_GENERIC;
					materialA = groundMaterial.getRandomMaterial(
						worldPos[0] + (vertices[0][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (vertices[0][2] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
					materialB = groundMaterial.getRandomMaterial(
						worldPos[0] + (vertices[1][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (vertices[1][2] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
					materialC = groundMaterial.getRandomMaterial(
						worldPos[0] + (vertices[2][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (vertices[2][2] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
				}

				int depthA = ctx.getVertexUnderwaterDepth(vertexKeyA);
				int depthB = ctx.getVertexUnderwaterDepth(vertexKeyB);
				int depthC = ctx.getVertexUnderwaterDepth(vertexKeyC);
				ly0 += depthA;
				ly1 += depthB;
				ly2 += depthC;

				terrainDataA = HDUtils.packTerrainData(true, max(1, depthA), waterType, tileZ);
				terrainDataB = HDUtils.packTerrainData(true, max(1, depthB), waterType, tileZ);
				terrainDataC = HDUtils.packTerrainData(true, max(1, depthC), waterType, tileZ);
			}

			if (ctx.isVertexOverlay(vertexKeyA) && ctx.isVertexUnderlay(vertexKeyA))
				vertexAIsOverlay = true;
			if (ctx.isVertexOverlay(vertexKeyB) && ctx.isVertexUnderlay(vertexKeyB))
				vertexBIsOverlay = true;
			if (ctx.isVertexOverlay(vertexKeyC) && ctx.isVertexUnderlay(vertexKeyC))
				vertexCIsOverlay = true;

			ly0 -= override.heightOffset;
			ly1 -= override.heightOffset;
			ly2 -= override.heightOffset;

			int materialDataA = materialA.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, vertexAIsOverlay);
			int materialDataB = materialB.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, vertexBIsOverlay);
			int materialDataC = materialC.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, vertexCIsOverlay);

			float uvcos = -uvScale, uvsin = 0;
			if (uvOrientation % 2048 != 0) {
				float rad = -uvOrientation * JAU_TO_RAD;
				uvcos = cos(rad) * -uvScale;
				uvsin = sin(rad) * -uvScale;
			}

			float uvx = fract(worldPos[0] * uvcos - worldPos[1] * uvsin);
			float uvy = fract(worldPos[0] * uvsin + worldPos[1] * uvcos);

			float dx, dz;
			dx = (float) lx0 / LOCAL_TILE_SIZE - tileX;
			dz = (float) lz0 / LOCAL_TILE_SIZE - tileY;
			float uvAx = uvx + dx * uvcos - dz * uvsin;
			float uvAy = uvy + dx * uvsin + dz * uvcos;
			dx = (float) lx1 / LOCAL_TILE_SIZE - tileX;
			dz = (float) lz1 / LOCAL_TILE_SIZE - tileY;
			float uvBx = uvx + dx * uvcos - dz * uvsin;
			float uvBy = uvy + dx * uvsin + dz * uvcos;
			dx = (float) lx2 / LOCAL_TILE_SIZE - tileX;
			dz = (float) lz2 / LOCAL_TILE_SIZE - tileY;
			float uvCx = uvx + dx * uvcos - dz * uvsin;
			float uvCy = uvy + dx * uvsin + dz * uvcos;

			final VertexWriteCache vb = writeCache.getVertexBuffer();
			final VertexWriteCache tb = writeCache.getTextureBuffer();

			int texturedFaceIdx = tb.putFace(
				colorA, colorB, colorC,
				materialDataA, materialDataB, materialDataC,
				terrainDataA, terrainDataB, terrainDataC
			);

			vb.putStaticVertex(
				lx0, ly0, lz0,
				uvAx, uvAy, 0,
				normalsA[0], normalsA[1], normalsA[2],
				texturedFaceIdx, false
			);

			vb.putStaticVertex(
				lx1, ly1, lz1,
				uvBx, uvBy, 0,
				normalsB[0], normalsB[1], normalsB[2],
				texturedFaceIdx, false
			);

			vb.putStaticVertex(
				lx2, ly2, lz2,
				uvCx, uvCy, 0,
				normalsC[0], normalsC[1], normalsC[2],
				texturedFaceIdx, false
			);

			boolean isDoubleSided = !onlyWaterSurface && (!isTileVisBelow && tileZ != 0 || override.doubleSidedFaces);
			if (isDoubleSided) {
				vb.putStaticVertex(
					lx2, ly2, lz2,
					uvCx, uvCy, 0,
					-normalsC[0], -normalsC[1], -normalsC[2],
					texturedFaceIdx, true
				);

				vb.putStaticVertex(
					lx1, ly1, lz1,
					uvBx, uvBy, 0,
					-normalsB[0], -normalsB[1], -normalsB[2],
					texturedFaceIdx, true
				);

				vb.putStaticVertex(
					lx0, ly0, lz0,
					uvAx, uvAy, 0,
					-normalsA[0], -normalsA[1], -normalsA[2],
					texturedFaceIdx, true
				);
			}
		}
		writeCache.release();
	}

	// scene upload
	private int uploadStaticModel(
		ZoneSceneContext ctx,
		Tile tile,
		Model model,
		ModelOverride modelOverride,
		int uuid,
		int preOrientation, int orientation,
		int x, int y, int z,
		int tileExX, int tileExY, int tileZ,
		GpuIntBuffer opaqueBuffer,
		GpuIntBuffer alphaBuffer,
		GpuIntBuffer textureBuffer
	) {
		if (writeCache == null)
			writeCache = new VertexWriteCache.Collection();
		writeCache.setOutputBuffers(opaqueBuffer, alphaBuffer, textureBuffer);

		final int faceCount = model.getFaceCount();
		final int vertexCount = model.getVerticesCount();

		final float[] vertexX = model.getVerticesX();
		final float[] vertexY = model.getVerticesY();
		final float[] vertexZ = model.getVerticesZ();

		final int[] indices1 = model.getFaceIndices1();
		final int[] indices2 = model.getFaceIndices2();
		final int[] indices3 = model.getFaceIndices3();

		final short[] unlitFaceColors = plugin.configUnlitFaceColors ? model.getUnlitFaceColors() : null;
		final int[] color1s = model.getFaceColors1();
		final int[] color2s = model.getFaceColors2();
		final int[] color3s = model.getFaceColors3();

		final int[] xVertexNormals = model.getVertexNormalsX();
		final int[] yVertexNormals = model.getVertexNormalsY();
		final int[] zVertexNormals = model.getVertexNormalsZ();
		final boolean modelHasNormals = xVertexNormals != null && yVertexNormals != null && zVertexNormals != null;

		final short[] faceTextures = model.getFaceTextures();
		final byte[] textureFaces = model.getTextureFaces();

		final byte[] bias = model.getFaceBias();
		final byte[] transparencies = model.getFaceTransparencies();
		final float modelHeight = model.getModelHeight();
		final byte modelTransparency = model.getTransparency();

		if (modelOverride.rotate != 0)
			orientation = (int) (modelOverride.rotate * DEG_TO_JAU);

		int orientSin = 0;
		int orientCos = 0;
		if (orientation != 0) {
			orientation = mod(orientation, 2048);
			orientSin = SINE[orientation];
			orientCos = COSINE[orientation];
		}

		ensureVerticesAllocated(vertexCount);

		y += modelOverride.heightOffset;

		for (int v = 0, vertexOffset = 0; v < vertexCount; ++v) {
			int vx = (int) vertexX[v];
			int vy = (int) vertexY[v];
			int vz = (int) vertexZ[v];
			float heightFrac = modelOverride.terrainVertexSnap ? abs(vy / modelHeight) : 0.0f;

			if (orientation != 0) {
				int x0 = vx;
				vx = vz * orientSin + x0 * orientCos >> 16;
				vz = vz * orientCos - x0 * orientSin >> 16;
			}

			vx += x;
			vy += y;
			vz += z;

			if (modelOverride.terrainVertexSnap && heightFrac <= modelOverride.terrainVertexSnapThreshold) {
				int vertexTileExX = clamp(ctx.sceneOffset + ((vx + basex) / 128), 0, EXTENDED_SCENE_SIZE - 1);
				int vertexTileExY = clamp(ctx.sceneOffset + ((vz + basez) / 128), 0, EXTENDED_SCENE_SIZE - 1);

				float h00 = tileHeights[tileZ][vertexTileExX][vertexTileExY];
				float h10 = tileHeights[tileZ][vertexTileExX + 1][vertexTileExY];
				float h01 = tileHeights[tileZ][vertexTileExX][vertexTileExY + 1];
				float h11 = tileHeights[tileZ][vertexTileExX + 1][vertexTileExY + 1];

				float hx0 = mix(h00, h10, (vx % 128.0f) / 128.0f);
				float hx1 = mix(h01, h11, (vx % 128.0f) / 128.0f);
				float h = mix(hx0, hx1, (vz % 128.0f) / 128.0f);

				float blend = divide(heightFrac, modelOverride.terrainVertexSnapThreshold);
				vy = (int) mix(h, vy, blend);
			}

			modelVertices[vertexOffset++] = vx;
			modelVertices[vertexOffset++] = vy;
			modelVertices[vertexOffset++] = vz;
		}

		boolean isVanillaTextured = faceTextures != null;

		final Material baseMaterial = modelOverride.baseMaterial;
		final Material textureMaterial = modelOverride.textureMaterial;

		int len = 0;
		for (int face = 0; face < faceCount; ++face) {
			int color1 = color1s[face];
			int color2 = color2s[face];
			int color3 = color3s[face];

			if (color3 == -1) {
				color2 = color3 = color1;
			} else if (color3 == -2) {
				continue;
			}

			if (unlitFaceColors != null)
				color1 = color2 = color3 = unlitFaceColors[face] & 0xFFFF;

			UvType uvType = UvType.GEOMETRY;
			Material material = baseMaterial;
			ModelOverride faceOverride = modelOverride;

			int transparency = readFaceTransparency(modelTransparency, transparencies, face);
			if (transparency == 255)
				continue;

			int textureId = isVanillaTextured ? faceTextures[face] : -1;
			boolean isTextured = textureId != -1;
			if (isTextured) {
				uvType = UvType.VANILLA;
				if (textureMaterial != Material.NONE) {
					material = textureMaterial;
				} else {
					material = materialManager.fromVanillaTexture(textureId);
					if (modelOverride.materialOverrides != null) {
						var override = modelOverride.materialOverrides.get(material);
						if (override != null) {
							faceOverride = override;
							material = faceOverride.textureMaterial;
						}
					}
				}
			} else if (modelOverride.colorOverrides != null) {
				final int ahsl = (0xFF - transparency) << 16 | color1;
				final var override = modelOverride.testColorOverrides(ahsl);
				if (override != null) {
					faceOverride = override;
					material = faceOverride.baseMaterial;
				}
			}

			if (faceOverride.hide)
				continue;

			final int triangleA = indices1[face];
			final int triangleB = indices2[face];
			final int triangleC = indices3[face];

			int vertexOffset = triangleA * 3;
			final int vx1 = modelVertices[vertexOffset];
			final int vy1 = modelVertices[vertexOffset + 1];
			final int vz1 = modelVertices[vertexOffset + 2];

			vertexOffset = triangleB * 3;
			final int vx2 = modelVertices[vertexOffset];
			final int vy2 = modelVertices[vertexOffset + 1];
			final int vz2 = modelVertices[vertexOffset + 2];

			vertexOffset = triangleC * 3;
			final int vx3 = modelVertices[vertexOffset];
			final int vy3 = modelVertices[vertexOffset + 1];
			final int vz3 = modelVertices[vertexOffset + 2];

			boolean keepShading = isTextured;
			if (isTextured) {
				// Without overriding the color for textured faces, vanilla shading remains pretty noticeable even after
				// the approximate reversal above. Ardougne rooftops is a good example, where vanilla shading results in a
				// weird-looking tint. The brightness clamp afterward is required to reduce the over-exposure introduced.
				color1 = color2 = color3 = 90;
			} else {
				// Hide fake shadows or lighting that is often baked into models by making the fake shadow transparent
				if (plugin.configHideFakeShadows && faceOverride.hideVanillaShadows && HDUtils.isBakedGroundShading(model, face))
					continue;

				if (faceOverride.inheritTileColorType != InheritTileColorType.NONE) {
					SceneTileModel tileModel = tile.getSceneTileModel();
					SceneTilePaint tilePaint = tile.getSceneTilePaint();

					if (tilePaint != null || tileModel != null) {
						// No point in inheriting tilepaint color if the ground tile does not have a color, for example above a cave wall
						if (
							tilePaint != null &&
							tilePaint.getTexture() == -1 &&
							tilePaint.getRBG() != 0 &&
							tilePaint.getNeColor() != HIDDEN_HSL
						) {
							// Since tile colors are guaranteed to have the same hue and saturation per face,
							// we can blend without converting from HSL to RGB
							int averageColor =
								(tilePaint.getSwColor() + tilePaint.getNwColor() + tilePaint.getNeColor() + tilePaint.getSeColor()) / 4;

							averageColor = ctx.getTileOverride(tileZ, tileExX, tileExY, TILE_OVERRIDE_MAIN).modifyColor(averageColor);
							color1 = color2 = color3 = averageColor;

							// Let the shader know vanilla shading reversal should be skipped for this face
							keepShading = true;
						} else if (tileModel != null && tileModel.getTriangleTextureId() == null) {
							int faceColorIndex = -1;
							for (int i = 0; i < tileModel.getTriangleColorA().length; i++) {
								boolean isOverlay = ProceduralGenerator.isOverlayFace(tile, i);
								// Use underlay if the tile does not have an overlay, useful for rocks in cave corners.
								if (faceOverride.inheritTileColorType == InheritTileColorType.UNDERLAY
									|| tileModel.getModelOverlay() == 0) {
									// pulling the color from UNDERLAY is more desirable for green grass tiles
									// OVERLAY pulls in path color which is not desirable for grass next to paths
									if (!isOverlay) {
										faceColorIndex = i;
										break;
									}
								} else if (faceOverride.inheritTileColorType == InheritTileColorType.OVERLAY) {
									if (isOverlay) {
										// OVERLAY used in dirt/path/house tile color blend better with rubbles/rocks
										faceColorIndex = i;
										break;
									}
								}
							}

							if (faceColorIndex != -1) {
								int color = tileModel.getTriangleColorA()[faceColorIndex];
								if (color != HIDDEN_HSL) {
									var override = ctx.getTileOverride(tileZ, tileExX, tileExY,
										faceOverride.inheritTileColorType == InheritTileColorType.OVERLAY ?
										TILE_OVERRIDE_OVERLAY : TILE_OVERRIDE_UNDERLAY);

									color = override.modifyColor(color);
									color1 = color2 = color3 = color;

									// Let the shader know vanilla shading reversal should be skipped for this face
									keepShading = true;
								}
							}
						}
					}
				}

				if (plugin.configLegacyTzHaarReskin && faceOverride.tzHaarRecolorType != TzHaarRecolorType.NONE) {
					ProceduralGenerator.recolorTzHaar(
						faceOverride,
						model,
						face,
						color1,
						color2,
						color3,
						tzHaarRecolored
					);
					color1 = tzHaarRecolored[0];
					color2 = tzHaarRecolored[1];
					color3 = tzHaarRecolored[2];
				}
			}

			if (faceOverride.modifiesColor) {
				color1 = faceOverride.modifyColor(color1);
				color2 = faceOverride.modifyColor(color2);
				color3 = faceOverride.modifyColor(color3);
			}

			int textureFace = textureFaces != null ? textureFaces[face] : -1;
			if (material != Material.NONE) {
				uvType = faceOverride.uvType;
				if (textureId != -1 && faceOverride.retainVanillaUvs)
					uvType = UvType.VANILLA;
			}
			// Fall back to geometry UVs if vanilla UVs aren't valid
			if (uvType == UvType.VANILLA && (textureId == -1 || textureFace == -1))
				uvType = UvType.GEOMETRY;

			final int materialData = material.packMaterialData(faceOverride, uvType, false);

			final float[] faceUVs;
			if (uvType == UvType.VANILLA) {
				computeFaceUvsInline(faceUVs = modelUvs, model, textureFace, triangleA, triangleB, triangleC, null);
			} else if (uvType != UvType.GEOMETRY) {
				faceOverride.fillUvsForFace(faceUVs = modelUvs, model, preOrientation, uvType, face, workingSpace);
			} else {
				faceUVs = GEOMETRY_UVS;
			}

			final boolean shouldRotateNormals;
			boolean shouldCalculateFaceNormal;
			if (!modelHasNormals || faceOverride.flatNormals || !plugin.configPreserveVanillaNormals && color3s[face] == -1) {
				shouldRotateNormals = false;
				shouldCalculateFaceNormal = true;
			} else {
				shouldRotateNormals = orientation != 0;
				shouldCalculateFaceNormal = (modelNormals[0] = xVertexNormals[triangleA]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[1] = yVertexNormals[triangleA]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[2] = zVertexNormals[triangleA]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[3] = xVertexNormals[triangleB]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[4] = yVertexNormals[triangleB]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[5] = zVertexNormals[triangleB]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[6] = xVertexNormals[triangleC]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[7] = yVertexNormals[triangleC]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[8] = zVertexNormals[triangleC]) == 0;
			}

			if (shouldCalculateFaceNormal) {
				calculateFaceNormal(
					modelNormals,
					vx1, vy1, vz1,
					vx2, vy2, vz2,
					vx3, vy3, vz3
				);
			}

			if (plugin.configUndoVanillaShading && faceOverride.undoVanillaShading && !keepShading) {
				color1 = undoVanillaShading(color1, plugin.configLegacyGreyColors, modelNormals[0], modelNormals[1], modelNormals[2]);
				color2 = undoVanillaShading(color2, plugin.configLegacyGreyColors, modelNormals[3], modelNormals[4], modelNormals[5]);
				color3 = undoVanillaShading(color3, plugin.configLegacyGreyColors, modelNormals[6], modelNormals[7], modelNormals[8]);
			}

			if (shouldRotateNormals)
				rotateNormals(modelNormals, orientSin, orientCos);

			if (faceOverride.modifiesAlpha)
				transparency = 255 - faceOverride.modifyAlpha(255 - transparency);

			int depthBias = faceOverride.depthBias != -1 ? faceOverride.depthBias :
				bias == null ? 0 : bias[face] & 0xFF;
			int packedAlphaBiasHsl = transparency << 24 | depthBias << 16;
			final VertexWriteCache vb = writeCache.getVertexBuffer(material.hasTransparency || transparency != 0);
			final VertexWriteCache tb = writeCache.opaqueTex;

			color1 |= packedAlphaBiasHsl;
			color2 |= packedAlphaBiasHsl;
			color3 |= packedAlphaBiasHsl;

			final int texturedFaceIdx = tb.putFace(
				color1, color2, color3,
				materialData, materialData, materialData,
				0, 0, 0
			);

			vb.putStaticVertex(
				vx1, vy1, vz1,
				faceUVs[0], faceUVs[1], faceUVs[2],
				modelNormals[0], modelNormals[1], modelNormals[2],
				texturedFaceIdx, false
			);

			vb.putStaticVertex(
				vx2, vy2, vz2,
				faceUVs[4], faceUVs[5], faceUVs[6],
				modelNormals[3], modelNormals[4], modelNormals[5],
				texturedFaceIdx, false
			);

			vb.putStaticVertex(
				vx3, vy3, vz3,
				faceUVs[8], faceUVs[9], faceUVs[10],
				modelNormals[6], modelNormals[7], modelNormals[8],
				texturedFaceIdx, false
			);

			if (faceOverride.doubleSidedFaces || material.doubleSidedFaces) {
				vb.putStaticVertex(
					vx3, vy3, vz3,
					faceUVs[8], faceUVs[9], faceUVs[10],
					-modelNormals[6], -modelNormals[7], -modelNormals[8],
					texturedFaceIdx, true
				);

				vb.putStaticVertex(
					vx2, vy2, vz2,
					faceUVs[4], faceUVs[5], faceUVs[6],
					-modelNormals[3], -modelNormals[4], -modelNormals[5],
					texturedFaceIdx, true
				);

				vb.putStaticVertex(
					vx1, vy1, vz1,
					faceUVs[0], faceUVs[1], faceUVs[2],
					-modelNormals[0], -modelNormals[1], -modelNormals[2],
					texturedFaceIdx, true
				);
			}
			len += 3;
		}
		writeCache.release();
		return len;
	}

	public boolean preprocessTempModel(
		Projection proj,
		float[][] sceneFrustumPlanes,
		int[] faceDistances,
		PrimitiveCharArray visibleFaces,
		PrimitiveCharArray culledFaces,
		boolean isModelPartiallyVisible,
		ModelOverride modelOverride,
		Model model,
		boolean sortAllFaces,
		int orientation,
		float x, float y, float z
	) {
		final int vertexCount = model.getVerticesCount();

		final float[] verticesX = model.getVerticesX();
		final float[] verticesY = model.getVerticesY();
		final float[] verticesZ = model.getVerticesZ();

		final boolean[] visibility = isModelPartiallyVisible ? PooledArrayType.BOOL.borrow(vertexCount) : null;
		modelProjected = PooledArrayType.FLOAT.ensureCapacity(modelProjected, vertexCount * 3);

		if (modelOverride.rotate != 0)
			orientation = (int) (modelOverride.rotate * DEG_TO_JAU);

		// Identity orient, will result in no rotation
		float orientSinf = 0;
		float orientCosf = 1;

		if (orientation != 0) {
			orientation = mod(orientation, 2048);
			orientSinf = SINE[orientation] / 65536f;
			orientCosf = COSINE[orientation] / 65536f;
		}

		ensureVerticesAllocated(vertexCount);

		y += modelOverride.heightOffset;

		boolean shouldSort = true;
		boolean allVertsVisible = true;
		for (int v = 0; v < vertexCount; ++v) {
			float vertexX = verticesX[v];
			float vertexY = verticesY[v];
			float vertexZ = verticesZ[v];

			if (orientation != 0) {
				final float x0 = vertexX;
				vertexX = vertexZ * orientSinf + x0 * orientCosf;
				vertexZ = vertexZ * orientCosf - x0 * orientSinf;
			}

			vertexX += x;
			vertexY += y;
			vertexZ += z;

			proj.project(vertexX, vertexY, vertexZ, projected);

			if (isModelPartiallyVisible) {
				// Ignore near & far plane, only test against the side planes
				if (!(visibility[v] = HDUtils.isPointWithinFrustum(vertexX, vertexY, vertexZ, sceneFrustumPlanes, 4)))
					allVertsVisible = false;
			}

			final float pX = projected[0];
			final float pY = projected[1];
			float pZ = projected[2];

			// Vertex is behind the camera and therefore isn't visible
			if (pZ <= 0.0f) {
				if (pZ == 0.0f)
					pZ = -1e-6f; // Avoid division by zero
				if (isModelPartiallyVisible)
					visibility[v] = allVertsVisible = false;
			}

			int vertexOffset = v * 3;
			modelVertices[vertexOffset] = Float.floatToRawIntBits(vertexX);
			modelProjected[vertexOffset] = pX / pZ;

			modelVertices[vertexOffset + 1] = Float.floatToRawIntBits(vertexY);
			modelProjected[vertexOffset + 1] = pY / pZ;

			modelVertices[vertexOffset + 2] = Float.floatToRawIntBits(vertexZ);
			modelProjected[vertexOffset + 2] = pZ;

			shouldSort &= pZ >= 50;
		}

		visibleFaces.reset();
		culledFaces.reset();

		final int triangleCount = model.getFaceCount();
		visibleFaces.ensureCapacity(triangleCount);
		culledFaces.ensureCapacity(triangleCount);

		final int[] color3s = model.getFaceColors3();
		final int[] indices1 = model.getFaceIndices1();
		final int[] indices2 = model.getFaceIndices2();
		final int[] indices3 = model.getFaceIndices3();
		final byte[] transparencies = model.getFaceTransparencies();
		final short[] faceTextures = model.getFaceTextures();
		final byte[] textureFaces = model.getTextureFaces();

		final Material baseMaterial = modelOverride.baseMaterial;
		final Material textureMaterial = modelOverride.textureMaterial;

		final boolean isVanillaTextured = faceTextures != null;

		final int zero = (int) proj.project(x, y, z, projected)[2];
		final int radius = model.getRadius();
		final byte modelTransparency = model.getTransparency();

		int cachedVanillaTexturedId = -1;
		ModelOverride cachedVanillaTextureOverride = null;

		int cachedAhsl = -1;
		ModelOverride cachedAhslOverride = null;

		faceOverrides.ensureCapacity(triangleCount);
		faceMaterials.ensureCapacity(triangleCount);
		faceUVTypes.ensureCapacity(triangleCount);

		tempModelAlphaFaces = 0;
		for (char f = 0; f < triangleCount; f++) {
			if (color3s[f] == -2)
				continue;

			int transparency = readFaceTransparency(modelTransparency, transparencies, f);
			if (transparency == 255)
				continue;

			// Hide fake shadows or lighting that is often baked into models by making the fake shadow transparent
			if (plugin.configHideFakeShadows && modelOverride.hideVanillaShadows && HDUtils.isBakedGroundShading(model, f))
				continue;

			UvType uvType = UvType.GEOMETRY;
			Material material = baseMaterial;
			ModelOverride faceOverride = modelOverride;

			final int textureId = isVanillaTextured ? faceTextures[f] : -1;
			if (textureId != -1) {
				uvType = UvType.VANILLA;
				if (textureMaterial != Material.NONE) {
					material = textureMaterial;
				} else {
					material = materialManager.fromVanillaTexture(textureId);
					if (modelOverride.materialOverrides != null) {
						final var override = cachedVanillaTexturedId == textureId ?
							cachedVanillaTextureOverride :
							modelOverride.materialOverrides.get(material);
						cachedVanillaTexturedId = textureId;
						cachedVanillaTextureOverride = override;

						if (override != null) {
							faceOverride = override;
							material = faceOverride.textureMaterial;
						}
					}
				}
			} else if (modelOverride.colorOverrides != null) {
				final int ahsl = (0xFF - transparency) << 16 | model.getFaceColors1()[f];
				final var override = cachedAhsl == ahsl ?
					cachedAhslOverride :
					modelOverride.testColorOverrides(ahsl);
				cachedAhsl = ahsl;
				cachedAhslOverride = override;

				if (override != null) {
					faceOverride = override;
					material = faceOverride.baseMaterial;
				}
			}

			if (faceOverride.hide)
				continue;

			if (material != Material.NONE) {
				uvType = faceOverride.uvType;
				if (textureId != -1 && faceOverride.retainVanillaUvs)
					uvType = UvType.VANILLA;
			}
			// Fall back to geometry UVs if vanilla UVs aren't valid
			if (uvType == UvType.VANILLA && (textureId == -1 || textureFaces == null || textureFaces[f] == -1))
				uvType = UvType.GEOMETRY;

			if (faceOverride.modifiesAlpha) {
				transparency = 255 - faceOverride.modifyAlpha(255 - transparency);
				if (transparency == 255)
					continue;
			}

			faceOverrides.set(f, faceOverride);
			faceMaterials.set(f, material);
			faceUVTypes.set(f, uvType);

			int offsetA = indices1[f];
			int offsetB = indices2[f];
			int offsetC = indices3[f];

			if (isModelPartiallyVisible && !allVertsVisible && !visibility[offsetA] && !visibility[offsetB] && !visibility[offsetC]) {
				// TODO: If a triangle is large enough to encompass the entire screen, this will need an additional plane test
				culledFaces.put(f);
				continue;
			}

			offsetA *= 3;
			offsetB *= 3;
			offsetC *= 3;

			// Face is completely behind the projection view
			final float aX = modelProjected[offsetA];
			final float aY = modelProjected[offsetA + 1];

			final float bX = modelProjected[offsetB];
			final float bY = modelProjected[offsetB + 1];

			final float cX = modelProjected[offsetC];
			final float cY = modelProjected[offsetC + 1];

			// back face culling
			if ((aX - bX) * (cY - bY) - (cX - bX) * (aY - bY) <= 0) {
				culledFaces.put(f);
				continue;
			}

			if (material.hasTransparency || transparency != 0)
				tempModelAlphaFaces++;

			// store distance for face sorting
			if (faceDistances != null) {
				if (shouldSort && (sortAllFaces || material.hasTransparency || transparency != 0)) {
					final float aZ = modelProjected[offsetA + 2];
					final float bZ = modelProjected[offsetB + 2];
					final float cZ = modelProjected[offsetC + 2];

					faceDistances[f] = radius + ((int) ((aZ + bZ + cZ) / 3.0f) - zero);
				} else {
					faceDistances[f] = Integer.MIN_VALUE;
				}
			}

			visibleFaces.put(f);
		}

		PooledArrayType.BOOL.release(visibility);

		return shouldSort;
	}

	// temp draw
	public void uploadTempModel(
		PrimitiveCharArray faces,
		Model model,
		ModelOverride modelOverride,
		int preOrientation,
		int orientation,
		boolean isShadow,
		DynamicModelVAO.View opaqueView,
		DynamicModelVAO.View alphaView
	) {
		if (writeCache == null)
			writeCache = new VertexWriteCache.Collection();
		writeCache.setOutputBuffers(opaqueView.vbo, alphaView.vbo, opaqueView.tbo, alphaView.tbo);

		final int[] indices1 = model.getFaceIndices1();
		final int[] indices2 = model.getFaceIndices2();
		final int[] indices3 = model.getFaceIndices3();

		final short[] unlitFaceColors = plugin.configUnlitFaceColors ? model.getUnlitFaceColors() : null;
		final int[] color1s = model.getFaceColors1();
		final int[] color2s = model.getFaceColors2();
		final int[] color3s = model.getFaceColors3();

		final int[] xVertexNormals = model.getVertexNormalsX();
		final int[] yVertexNormals = model.getVertexNormalsY();
		final int[] zVertexNormals = model.getVertexNormalsZ();

		final byte[] transparencies = model.getFaceTransparencies();
		final short[] faceTextures = model.getFaceTextures();
		final byte[] textureFaces = model.getTextureFaces();
		final byte[] bias = model.getFaceBias();
		final int[] faceNormals = isShadow ? EMPTY_NORMALS : modelNormals;

		final int faceCount = model.getFaceCount();
		final boolean hasBias = bias != null;
		final boolean modelHasNormals =
			model.getVertexNormalsX() != null &&
			model.getVertexNormalsY() != null &&
			model.getVertexNormalsZ() != null;

		final byte overrideAmount = model.getOverrideAmount();
		final byte overrideHue = model.getOverrideHue();
		final byte overrideSat = model.getOverrideSaturation();
		final byte overrideLum = model.getOverrideLuminance();
		final byte modelTransparency = model.getTransparency();

		final boolean isVanillaTextured = faceTextures != null;

		int orientSin = 0;
		int orientCos = 0;
		if (orientation != 0) {
			orientation = mod(orientation, 2048);
			orientSin = SINE[orientation];
			orientCos = COSINE[orientation];
		}

		for (int f = 0; f < faces.length; ++f) {
			final int face = faces.array[f];
			if (face >= faceCount)
				continue;

			int color1 = color1s[face];
			int color2 = color2s[face];
			int color3 = color3s[face];

			if (unlitFaceColors != null)
				color1 = color2 = color3 = unlitFaceColors[face] & 0xFFFF;
			else if (color3 == -1)
				color2 = color3 = color1;

			int transparency = readFaceTransparency(modelTransparency, transparencies, face);
			final int textureFace = textureFaces != null ? textureFaces[face] : -1;
			final int textureId = isVanillaTextured ? faceTextures[face] : -1;
			final UvType uvType = faceUVTypes.get(face);
			final Material material = faceMaterials.get(face);
			final ModelOverride faceOverride = faceOverrides.get(face);

			if (textureId != -1)
				color1 = color2 = color3 = 90;

			if (faceOverride.modifiesColor) {
				color1 = faceOverride.modifyColor(color1);
				color2 = faceOverride.modifyColor(color2);
				color3 = faceOverride.modifyColor(color3);
			}

			final int materialData = material.packMaterialData(faceOverride, uvType, false);

			final int triangleA = indices1[face];
			final int vertexOffsetA = triangleA * 3;

			final int triangleB = indices2[face];
			final int vertexOffsetB = triangleB * 3;

			final int triangleC = indices3[face];
			final int vertexOffsetC = triangleC * 3;

			final float[] faceUVs;
			if (uvType == UvType.VANILLA) {
				computeFaceUvsInline(faceUVs = modelUvs, model, textureFace, triangleA, triangleB, triangleC, modelProjected);
			} else if (uvType != UvType.GEOMETRY) {
				faceOverride.fillUvsForFace(faceUVs = modelUvs, model, preOrientation, uvType, face, workingSpace);
			} else {
				faceUVs = GEOMETRY_UVS;
			}

			if (!isShadow) {
				final boolean shouldRotateNormals;
				boolean shouldCalculateFaceNormal;
				if (!modelHasNormals || faceOverride.flatNormals || (!plugin.configPreserveVanillaNormals && color3s[face] == -1)) {
					shouldRotateNormals = false;
					shouldCalculateFaceNormal = true;
				} else {
					shouldRotateNormals = orientation != 0;
					shouldCalculateFaceNormal = (modelNormals[0] = xVertexNormals[triangleA]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[1] = yVertexNormals[triangleA]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[2] = zVertexNormals[triangleA]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[3] = xVertexNormals[triangleB]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[4] = yVertexNormals[triangleB]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[5] = zVertexNormals[triangleB]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[6] = xVertexNormals[triangleC]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[7] = yVertexNormals[triangleC]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[8] = zVertexNormals[triangleC]) == 0;
				}

				if (shouldCalculateFaceNormal) {
					calculateFaceNormalInt(
						faceNormals,
						modelVertices[vertexOffsetA], modelVertices[vertexOffsetA + 1], modelVertices[vertexOffsetA + 2],
						modelVertices[vertexOffsetB], modelVertices[vertexOffsetB + 1], modelVertices[vertexOffsetB + 2],
						modelVertices[vertexOffsetC], modelVertices[vertexOffsetC + 1], modelVertices[vertexOffsetC + 2]
					);
				}

				if (plugin.configUndoVanillaShading && modelOverride.undoVanillaShading) {
					color1 = undoVanillaShading(color1, plugin.configLegacyGreyColors, faceNormals[0], faceNormals[1], faceNormals[2]);
					color2 = undoVanillaShading(color2, plugin.configLegacyGreyColors, faceNormals[3], faceNormals[4], faceNormals[5]);
					color3 = undoVanillaShading(color3, plugin.configLegacyGreyColors, faceNormals[6], faceNormals[7], faceNormals[8]);
				}

				if (shouldRotateNormals && !shouldCalculateFaceNormal)
					rotateNormals(faceNormals, orientSin, orientCos);
			}

			// HSL override is not applied to textured faces
			if (overrideAmount > 0 && (!isVanillaTextured || faceTextures[face] == -1)) {
				color1 = interpolateHSL(color1, overrideHue, overrideSat, overrideLum, overrideAmount);
				color2 = interpolateHSL(color2, overrideHue, overrideSat, overrideLum, overrideAmount);
				color3 = interpolateHSL(color3, overrideHue, overrideSat, overrideLum, overrideAmount);
			}

			if (faceOverride.modifiesAlpha)
				transparency = 255 - faceOverride.modifyAlpha(255 - transparency);

			final int depthBias = faceOverride.depthBias != -1 ? faceOverride.depthBias :
				hasBias ? bias[face] & 0xFF : 0;
			final int packedAlphaBiasHsl = transparency << 24 | depthBias << 16;
			final boolean hasAlpha = material.hasTransparency || transparency != 0;

			color1 |= packedAlphaBiasHsl;
			color2 |= packedAlphaBiasHsl;
			color3 |= packedAlphaBiasHsl;

			final VertexWriteCache vb = writeCache.getVertexBuffer(hasAlpha);
			final VertexWriteCache tb = writeCache.getTextureBuffer(hasAlpha);

			final int texturedFaceIdx = tb.putFace(
				color1, color2, color3,
				materialData, materialData, materialData,
				0, 0, 0
			);

			vb.putDynamicVertex(
				modelVertices[vertexOffsetA], modelVertices[vertexOffsetA + 1], modelVertices[vertexOffsetA + 2],
				faceUVs[0], faceUVs[1], faceUVs[2],
				faceNormals[0], faceNormals[1], faceNormals[2],
				texturedFaceIdx
			);
			vb.putDynamicVertex(
				modelVertices[vertexOffsetB], modelVertices[vertexOffsetB + 1], modelVertices[vertexOffsetB + 2],
				faceUVs[4], faceUVs[5], faceUVs[6],
				faceNormals[3], faceNormals[4], faceNormals[5],
				texturedFaceIdx
			);
			vb.putDynamicVertex(
				modelVertices[vertexOffsetC], modelVertices[vertexOffsetC + 1], modelVertices[vertexOffsetC + 2],
				faceUVs[8], faceUVs[9], faceUVs[10],
				faceNormals[6], faceNormals[7], faceNormals[8],
				texturedFaceIdx
			);
		}

		writeCache.release();
	}

	public void estimateZoneGapFillers(ZoneSceneContext ctx, Zone zone, int mzx, int mzz) {
		int basex = (mzx - (ctx.sceneOffset >> 3)) << 10;
		int basez = (mzz - (ctx.sceneOffset >> 3)) << 10;

		for (int xoff = 0; xoff < CHUNK_SIZE; ++xoff) {
			for (int zoff = 0; zoff < CHUNK_SIZE; ++zoff) {
				int tileExX = (mzx << 3) + xoff;
				int tileExY = (mzz << 3) + zoff;
				int faces = processGapTile(ctx, tileExX, tileExY, null, basex, basez, false);
				if (faces > 0) {
					zone.hasGapFiller = true;
					zone.sizeO += faces;
					zone.sizeF += faces;
				}
			}
		}
	}

	public void uploadZoneGapFillers(
		ZoneSceneContext ctx,
		int mzx,
		int mzz,
		GpuIntBuffer vb,
		GpuIntBuffer fb
	) {
		assert vb != null && fb != null;
		if (writeCache == null)
			writeCache = new VertexWriteCache.Collection();
		writeCache.setOutputBuffers(vb, vb, fb);

		int basex = (mzx - (ctx.sceneOffset >> 3)) << 10;
		int basez = (mzz - (ctx.sceneOffset >> 3)) << 10;
		Material blackMaterial = materialManager.getMaterial("BLACK");

		for (int xoff = 0; xoff < CHUNK_SIZE; ++xoff) {
			for (int zoff = 0; zoff < CHUNK_SIZE; ++zoff) {
				int tileExX = (mzx << 3) + xoff;
				int tileExY = (mzz << 3) + zoff;
				processGapTile(ctx, tileExX, tileExY, blackMaterial, basex, basez, true);
			}
		}
		writeCache.release();
	}

	/**
	 * @return face count if the tile should be gap-filled, otherwise 0
	 */
	private int processGapTile(
		ZoneSceneContext ctx,
		int tileExX,
		int tileExY,
		@Nullable Material blackMaterial,
		int basex,
		int basez,
		boolean shouldUpload
	) {
		assert tileExX >= 0 && tileExY >= 0 && tileExX < EXTENDED_SCENE_SIZE && tileExY < EXTENDED_SCENE_SIZE;
		assert ctx.sceneBase != null;

		// Skip tiles along the scene boundary, which are always empty
		if (tileExX == 0 || tileExX == EXTENDED_SCENE_SIZE - 1 ||
			tileExY == 0 || tileExY == EXTENDED_SCENE_SIZE - 1)
			return 0;

		if (ctx.currentArea != null) {
			ctx.extendedSceneToWorld(tileExX, tileExY, 0, worldPos);
			if (!ctx.currentArea.containsPoint(worldPos))
				return 0;
		}

		Tile tile = tiles[0][tileExX][tileExY];

		SceneTilePaint paint;
		SceneTileModel model = null;
		int renderLevel = 0;
		if (tile != null) {
			renderLevel = tile.getRenderLevel();
			paint = tile.getSceneTilePaint();
			model = tile.getSceneTileModel();

			if (model == null) {
				boolean hasTilePaint = paint != null && paint.getNeColor() != HIDDEN_HSL;
				if (!hasTilePaint) {
					tile = tile.getBridge();
					if (tile != null) {
						renderLevel = tile.getRenderLevel();
						paint = tile.getSceneTilePaint();
						model = tile.getSceneTileModel();
						hasTilePaint = paint != null && paint.getNeColor() != HIDDEN_HSL;
					}
				}

				if (hasTilePaint)
					return 0;
			}
		}

		if (shouldUpload) {
			assert tileHeights != null && blackMaterial != null;
			if (model != null) {
				uploadCustomTileModel(tile, model, blackMaterial, basex, basez);
			} else {
				uploadCustomTilePaint(ctx, tileExX, tileExY, renderLevel, blackMaterial, basex, basez);
			}
		}

		return model == null ? 2 : model.getFaceX().length;
	}

	private void uploadCustomTileModel(Tile tile, SceneTileModel model, Material material, int basex, int basez) {
		int tileZ = tile.getRenderLevel();
		int packedMaterial = material.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, false);
		int terrainData = HDUtils.packTerrainData(true, 0, WaterType.NONE, tileZ);

		final int[] faceX = model.getFaceX();
		final int[] faceY = model.getFaceY();
		final int[] faceZ = model.getFaceZ();
		final int[] vertexX = model.getVertexX();
		final int[] vertexY = model.getVertexY();
		final int[] vertexZ = model.getVertexZ();
		final int[] triangleColorA = model.getTriangleColorA();

		for (int face = 0; face < faceX.length; ++face) {
			if (triangleColorA[face] != HIDDEN_HSL)
				continue;

			int v0 = faceX[face];
			int v1 = faceY[face];
			int v2 = faceZ[face];

			putTerrainTriangle(
				0, 0, 0,
				packedMaterial, terrainData,
				vertexX[v0] - basex, vertexY[v0], vertexZ[v0] - basez, 0, 0,
				vertexX[v1] - basex, vertexY[v1], vertexZ[v1] - basez, 0, 0,
				vertexX[v2] - basex, vertexY[v2], vertexZ[v2] - basez, 0, 0
			);
		}
	}

	private void uploadCustomTilePaint(
		SceneContext ctx,
		int tileExX,
		int tileExY,
		int tileZ,
		Material material,
		int zoneBasex,
		int zoneBasez
	) {
		int swHeight = tileHeights[tileZ][tileExX][tileExY];
		int seHeight = tileHeights[tileZ][tileExX + 1][tileExY];
		int neHeight = tileHeights[tileZ][tileExX + 1][tileExY + 1];
		int nwHeight = tileHeights[tileZ][tileExX][tileExY + 1];
		int terrainData = HDUtils.packTerrainData(true, 0, WaterType.NONE, tileZ);
		int packedMaterial = material.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, false);

		int x = (tileExX - ctx.sceneOffset) * LOCAL_TILE_SIZE - zoneBasex;
		int z = (tileExY - ctx.sceneOffset) * LOCAL_TILE_SIZE - zoneBasez;
		putTerrainTriangle(
			0, 0, 0,
			packedMaterial, terrainData,
			x + LOCAL_TILE_SIZE, neHeight, z + LOCAL_TILE_SIZE, 0, 0,
			x, nwHeight, z + LOCAL_TILE_SIZE, 1, 0,
			x + LOCAL_TILE_SIZE, seHeight, z, 0, 1
		);
		putTerrainTriangle(
			0, 0, 0,
			packedMaterial, terrainData,
			x, swHeight, z, 1, 1,
			x + LOCAL_TILE_SIZE, seHeight, z, 0, 1,
			x, nwHeight, z + LOCAL_TILE_SIZE, 1, 0
		);
	}

	private void putTerrainTriangle(
		int colorA,
		int colorB,
		int colorC,
		int packedMaterial,
		int terrainData,
		int x0, int y0, int z0, float u0, float v0,
		int x1, int y1, int z1, float u1, float v1,
		int x2, int y2, int z2, float u2, float v2
	) {
		final var vb = writeCache.getVertexBuffer();
		final var tb = writeCache.getTextureBuffer();
		int faceIdx = tb.putFace(
			colorA, colorB, colorC,
			packedMaterial, packedMaterial, packedMaterial,
			terrainData, terrainData, terrainData
		);
		vb.putStaticVertex(x0, y0, z0, u0, v0, 0, 0, -1, 0, faceIdx, false);
		vb.putStaticVertex(x1, y1, z1, u1, v1, 0, 0, -1, 0, faceIdx, false);
		vb.putStaticVertex(x2, y2, z2, u2, v2, 0, 0, -1, 0, faceIdx, false);
	}

	public static void calculateFaceNormalInt(
		int[] out,
		int vx1, int vy1, int vz1,
		int vx2, int vy2, int vz2,
		int vx3, int vy3, int vz3
	) {
		calculateFaceNormal(out,
			Float.intBitsToFloat(vx1), Float.intBitsToFloat(vy1), Float.intBitsToFloat(vz1),
			Float.intBitsToFloat(vx2), Float.intBitsToFloat(vy2), Float.intBitsToFloat(vz2),
			Float.intBitsToFloat(vx3), Float.intBitsToFloat(vy3), Float.intBitsToFloat(vz3)
		);
	}

	public static void calculateFaceNormal(
		int[] out,
		float vx1, float vy1, float vz1,
		float vx2, float vy2, float vz2,
		float vx3, float vy3, float vz3
	) {
		float e0_x = vx2 - vx1;
		float e0_y = vy2 - vy1;
		float e0_z = vz2 - vz1;

		float e1_x = vx3 - vx1;
		float e1_y = vy3 - vy1;
		float e1_z = vz3 - vz1;

		float nx = e0_y * e1_z - e0_z * e1_y;
		float ny = e0_z * e1_x - e0_x * e1_z;
		float nz = e0_x * e1_y - e0_y * e1_x;

		float length = (float) Math.sqrt(nx * nx + ny * ny + nz * nz);
		nx /= length;
		ny /= length;
		nz /= length;

		out[0] = out[3] = out[6] = (int) (nx * 2048);
		out[1] = out[4] = out[7] = (int) (ny * 2048);
		out[2] = out[5] = out[8] = (int) (nz * 2048);
	}

	public static int interpolateHSL(int hsl, byte hue2, byte sat2, byte lum2, byte lerp) {
		int hue = hsl >> 10 & 63;
		int sat = hsl >> 7 & 7;
		int lum = hsl & 127;
		int lerpInt = lerp & 255;
		if (hue2 != -1)
			hue += lerpInt * (hue2 - hue) >> 7;
		if (sat2 != -1)
			sat += lerpInt * (sat2 - sat) >> 7;
		if (lum2 != -1)
			lum += lerpInt * (lum2 - lum) >> 7;
		return (hue << 10 | sat << 7 | lum) & 65535;
	}

	private static void computeFaceUvsInline(
		float[] out,
		Model model,
		int textureFace,
		int a,
		int b,
		int c,
		@Nullable float[] projected
	) {
		assert textureFace != -1;
		int tf = textureFace & 0xFF;
		int o = model.getTexIndices1()[tf];
		int u = model.getTexIndices2()[tf];
		int v = model.getTexIndices3()[tf];
		// Only different triangles may actually require texture projection
		if (a == o && b == u && c == v) {
			copyTo(out, GEOMETRY_UVS);
			return;
		}

		float[] xs = model.getVerticesX(), ys = model.getVerticesY(), zs = model.getVerticesZ();
		float ox = xs[o], oy = ys[o], oz = zs[o];
		float ux = xs[u], uy = ys[u], uz = zs[u];
		float vx = xs[v], vy = ys[v], vz = zs[v];
		if (projected != null) {
			// Reconstruct the texture plane prior to the perspective divide
			oz = projected[o * 3 + 2];
			ox = projected[o * 3] * oz;
			oy = projected[o * 3 + 1] * oz;
			uz = projected[u * 3 + 2];
			ux = projected[u * 3] * uz;
			uy = projected[u * 3 + 1] * uz;
			vz = projected[v * 3 + 2];
			vx = projected[v * 3] * vz;
			vy = projected[v * 3 + 1] * vz;
		}
		ux -= ox;
		uy -= oy;
		uz -= oz;
		vx -= ox;
		vy -= oy;
		vz -= oz;
		float nx = uy * vz - uz * vy;
		float ny = uz * vx - ux * vz;
		float nz = ux * vy - uy * vx;
		float normalSquared = nx * nx + ny * ny + nz * nz;
		if (normalSquared == 0) {
			copyTo(out, GEOMETRY_UVS);
			return;
		}

		float uX, uY, uZ, vX, vY, vZ;
		if (projected == null) {
			uX = vy * nz - vz * ny;
			uY = vz * nx - vx * nz;
			uZ = vx * ny - vy * nx;
			vX = ny * uz - nz * uy;
			vY = nz * ux - nx * uz;
			vZ = nx * uy - ny * ux;
		} else {
			// For texture vertices A, B, C and camera ray r:
			// U = dot(C * A, r) / dot(normal, r)
			// V = dot(A * B, r) / dot(normal, r)
			uX = vy * oz - vz * oy;
			uY = vz * ox - vx * oz;
			uZ = vx * oy - vy * ox;
			vX = oy * uz - oz * uy;
			vY = oz * ux - ox * uz;
			vZ = ox * uy - oy * ux;
		}
		for (int i = 0; i < 3; i++) {
			int vertex = i == 0 ? a : i == 1 ? b : c;
			float x, y, z, denominator;
			if (projected == null) {
				x = xs[vertex] - ox;
				y = ys[vertex] - oy;
				z = zs[vertex] - oz;
				denominator = normalSquared;
			} else {
				x = projected[vertex * 3];
				y = projected[vertex * 3 + 1];
				z = 1;
				denominator = nx * x + ny * y + nz;
				// Nearly parallel rays have no stable texture projection
				if (denominator * denominator <= 1e-12f * normalSquared * (x * x + y * y + 1)) {
					copyTo(out, GEOMETRY_UVS);
					return;
				}
			}
			float uvU = (uX * x + uY * y + uZ * z) / denominator;
			float uvV = (vX * x + vY * y + vZ * z) / denominator;
			if (projected != null && (abs(uvU) > MAX_FLOAT16 || abs(uvV) > MAX_FLOAT16)) {
				copyTo(out, GEOMETRY_UVS);
				return;
			}
			out[i * 4] = uvU;
			out[i * 4 + 1] = uvV;
			out[i * 4 + 2] = 0;
		}
	}

	public static int undoVanillaShading(
		int color, boolean legacyGreyColors,
		int nx, int ny, int nz
	) {
		return undoVanillaShading(color, legacyGreyColors, nx * nx + ny * ny + nz * nz, nx + ny + nz);
	}

	public static int undoVanillaShading(
		int color, boolean legacyGreyColors,
		float nx, float ny, float nz
	) {
		return undoVanillaShading(color, legacyGreyColors, nx * nx + ny * ny + nz * nz, nx + ny + nz);
	}

	private static int undoVanillaShading(
		int color, boolean legacyGreyColors,
		float len, float norm
	) {
		//int h = color >> 10 & 0x3F; Unused only S & L need unpacking
		int s = (color >> 7) & 0x7;
		int l = color & 0x7F;

		// Approximately invert vanilla shading by brightening vertices that were likely darkened by vanilla based on
		// vertex normals. This process is error-prone, as not all models are lit by vanilla with the same light
		// direction, and some models even have baked lighting built into the model itself. In some cases, increasing
		// brightness in this way leads to overly bright colors, so we are forced to cap brightness at a relatively
		// low value for it to look acceptable in most cases.
		final float colorAdjust = BASE_LIGHTEN - l + (l < IGNORE_LOW_LIGHTNESS ? 0f : (l - IGNORE_LOW_LIGHTNESS) * LIGHTNESS_MULTIPLIER);

		// Normals are currently unrotated, so we don't need to do any rotation for this
		if (len > 0f) {
			final float invLen = rcp(sqrt(len));
			final float lightDotNormal = norm * 0.57735026f * invLen;
			if (lightDotNormal > 0f)
				l += (int) (lightDotNormal * colorAdjust);
		}

		// Clamp brightness as detailed above
		l = min(l, legacyGreyColors ? 55 : getMaxBrightness(s));

		// Preserve H, replace S & L
		return (color & 0xFC00) | (s << 7) | l;
	}

	private static int getMaxBrightness(int s) {
		// MAX_BRIGHTNESS_LOOKUP_TABLE
		// [127, 61, 59, 57, 56, 56, 55, 55]
		switch (s) {
			case 0:
				return 127;
			case 1:
				return 61;
			case 2:
				return 59;
			case 3:
				return 57;
			case 4:
			case 5:
				return 56;
			default:
				return 55;
		}
	}

	public static int readFaceTransparency(byte modelTransparency, byte[] transparencies, int f) {
		// Based on https://github.com/runelite/runelite/commit/a88ac64d5a154020cdc21612fc0f1eb32aa8d0f8#diff-2495d11499767f573d041baf080ee6b50dddd325e37b34a402f4c23efc3c2324R464-R478
		if (modelTransparency == -1)
			return 255;

		int faceTransparency = transparencies != null ? transparencies[f] & 0xFF : 0;
		if (faceTransparency >= 253) {
			// 253 & 254 are special faces like clickboxes which we don't want to render,
			// so force them to be 255 so that they are completely skipped
			return 255;
		}

		if (modelTransparency != 0) {
			assert (faceTransparency & 255) == faceTransparency;
			int t = modelTransparency & 255;
			int a = (253 - faceTransparency) * t >> 8;
			return faceTransparency + a;
		}

		return faceTransparency;
	}

	public static void rotateNormals(int[] normals, int orientSin, int orientCos) {
		int nx = normals[0], nz = normals[2];
		normals[0] = (nz * orientSin + nx * orientCos) >> 16;
		normals[2] = (nz * orientCos - nx * orientSin) >> 16;

		nx = normals[3];
		nz = normals[5];
		normals[3] = (nz * orientSin + nx * orientCos) >> 16;
		normals[5] = (nz * orientCos - nx * orientSin) >> 16;

		nx = normals[6];
		nz = normals[8];
		normals[6] = (nz * orientSin + nx * orientCos) >> 16;
		normals[8] = (nz * orientCos - nx * orientSin) >> 16;
	}

	@Override
	public void close() {
		clear();
		POOL.recycle(this);
	}
}

package rs117.hd.renderer.zone;

import java.util.Arrays;
import java.util.concurrent.atomic.AtomicIntegerArray;
import lombok.RequiredArgsConstructor;
import rs117.hd.overlays.FrameTimer;
import rs117.hd.overlays.Timer;
import rs117.hd.renderer.zone.Zone.AlphaModel;
import rs117.hd.utils.Camera;
import rs117.hd.utils.jobs.Job;

import static net.runelite.api.Perspective.*;
import static rs117.hd.utils.MathUtils.*;

@RequiredArgsConstructor
public final class StaticAlphaSortingJob extends Job {
	private FrameTimer frameTimer;

	private AlphaModel[] models = new AlphaModel[16];
	private AtomicIntegerArray states = new AtomicIntegerArray(16);
	private int size = 0;

	private int yaw;
	private int yawSin;
	private int yawCos;
	private int pitch;
	private int pitchSin;
	private int pitchCos;

	public void addAlphaModel(AlphaModel m) {
		if (size == models.length) {
			final int newCapacity = ceilPow2(models.length * 2);
			models = Arrays.copyOf(models, newCapacity);
			states = new AtomicIntegerArray(newCapacity);
		}

		m.asyncSortIdx = size;
		states.set(size, 0);
		models[size] = m;
		size++;
	}

	public void queue(Camera camera) {
		if (frameTimer == null)
			frameTimer = getInjector().getInstance(FrameTimer.class);
		yaw = camera.getFixedYaw();
		yawSin = SINE14[yaw];
		yawCos = COSINE14[yaw];
		pitch = camera.getFixedPitch();
		pitchSin = SINE14[pitch];
		pitchCos = COSINE14[pitch];
		queue();
	}

	public void reset() {
		Arrays.fill(models, 0, size, null);
		size = 0;
	}

	@Override
	protected void onRun() {
		long start = System.nanoTime();
		try (FacePrioritySorter sorter = FacePrioritySorter.POOL.acquire()) {
			for (int i = 0; i < size; i++) {
				if (!states.compareAndSet(i, 0, 1))
					continue;
				processModel(sorter, models[i]);
			}
		}
		frameTimer.add(Timer.STATIC_ALPHA_SORT, System.nanoTime() - start);
	}

	private void processModel(FacePrioritySorter sorter, AlphaModel m) {
		m.sortedFacesLen = 0;
		sorter.sortStaticModelFacesByDistance(m, yawCos, yawSin, pitchCos, pitchSin);
		m.setSorted();
	}

	public boolean forceProcessModelClient(AlphaModel m) {
		if (m.asyncSortIdx < 0 || m.asyncSortIdx >= size) return false;
		if (states.compareAndSet(m.asyncSortIdx, 0, 1)) {
			try (FacePrioritySorter sorter = FacePrioritySorter.POOL.acquire()) {
				processModel(sorter, models[m.asyncSortIdx]);
			}
			return true;
		}
		return false;
	}
}

package rs117.hd.renderer.zone;

import java.nio.IntBuffer;
import lombok.extern.slf4j.Slf4j;
import rs117.hd.utils.buffer.GLMappedBufferIntWriter.ReservedView;
import rs117.hd.utils.buffer.GpuIntBuffer;
import rs117.hd.utils.collections.PooledArrayType;

import static rs117.hd.utils.MathUtils.*;

@Slf4j
public final class VertexWriteCache {
	private IntBuffer outputBuffer;
	private int outputOffset;

	private final String name;
	private final int initialCapacity;
	private final int maxCapacity;
	private int[] stagingBuffer;
	private int stagingPosition;

	public VertexWriteCache(String name, int initialCapacity) {
		this(name, initialCapacity, initialCapacity);
	}

	public VertexWriteCache(String name, int initialCapacity, int maxCapacity) {
		this.name = name;
		this.initialCapacity = initialCapacity;
		this.maxCapacity = maxCapacity;
	}

	public void setOutputBuffer(IntBuffer outputBuffer) {
		this.outputBuffer = outputBuffer;
		outputOffset = 0;
		stagingPosition = 0;
		stagingBuffer = PooledArrayType.INT.ensureCapacity(stagingBuffer, initialCapacity);
	}

	private void setOutputView(ReservedView view) {
		setOutputBuffer(view.getBuffer());
		outputOffset = view.getPositionOffsetInts();
	}

	private void release(){
		flush();

		if (stagingBuffer != null)
			PooledArrayType.INT.release(stagingBuffer);
		stagingBuffer = null;
	}

	private void flushAndGrow() {
		// Flush buffer and then resize to avoid flushing mid put
		flush();

		if (stagingBuffer.length < maxCapacity)
			stagingBuffer = PooledArrayType.INT.ensureCapacity(stagingBuffer, min(stagingBuffer.length * 2, maxCapacity));
	}

	public int putFace(
		int alphaBiasHslA, int alphaBiasHslB, int alphaBiasHslC,
		int materialDataA, int materialDataB, int materialDataC,
		int terrainDataA, int terrainDataB, int terrainDataC
	) {
		if (stagingPosition + 9 > stagingBuffer.length)
			flushAndGrow();

		final int textureFaceIdx = (outputOffset + outputBuffer.position() + stagingPosition) / 3;
		final int[] stagingBuffer = this.stagingBuffer;
		final int stagingPosition = this.stagingPosition;

		stagingBuffer[stagingPosition] = alphaBiasHslA;
		stagingBuffer[stagingPosition + 1] = alphaBiasHslB;
		stagingBuffer[stagingPosition + 2] = alphaBiasHslC;

		stagingBuffer[stagingPosition + 3] = materialDataA;
		stagingBuffer[stagingPosition + 4] = materialDataB;
		stagingBuffer[stagingPosition + 5] = materialDataC;

		stagingBuffer[stagingPosition + 6] = terrainDataA; // TODO: Remove?
		stagingBuffer[stagingPosition + 7] = terrainDataB;
		stagingBuffer[stagingPosition + 8] = terrainDataC;

		this.stagingPosition += 9;

		return textureFaceIdx;
	}

	public void putDynamicVertex(
		int x, int y, int z,
		float u, float v, float w,
		int nx, int ny, int nz,
		int textureFaceIdx
	) {
		if (stagingPosition + 8 > stagingBuffer.length)
			flushAndGrow();

		final int[] stagingBuffer = this.stagingBuffer;
		final int stagingPosition = this.stagingPosition;

		stagingBuffer[stagingPosition] = x;
		stagingBuffer[stagingPosition + 1] = y;
		stagingBuffer[stagingPosition + 2] = z;
		stagingBuffer[stagingPosition + 3] = float16(v) << 16 | float16(u);
		stagingBuffer[stagingPosition + 4] = float16(w);
		stagingBuffer[stagingPosition + 5] = (ny & 0xFFFF) << 16 | nx & 0xFFFF;
		stagingBuffer[stagingPosition + 6] = nz & 0xFFFF;
		stagingBuffer[stagingPosition + 7] = textureFaceIdx;

		this.stagingPosition += 8;
	}

	public void putStaticVertex(
		int x, int y, int z,
		float u, float v, float w,
		int nx, int ny, int nz,
		int textureFaceIdx, boolean windingReversed
	) {
		if (stagingPosition + 7 > stagingBuffer.length)
			flushAndGrow();

		final int[] stagingBuffer = this.stagingBuffer;
		final int stagingPosition = this.stagingPosition;

		stagingBuffer[stagingPosition] = (y & 0xFFFF) << 16 | x & 0xFFFF;
		stagingBuffer[stagingPosition + 1] = z & 0xFFFF;
		stagingBuffer[stagingPosition + 2] = float16(v) << 16 | float16(u);
		stagingBuffer[stagingPosition + 3] = float16(w);
		// Unnormalized normals, assumed to be within short max
		stagingBuffer[stagingPosition + 4] = (ny & 0xFFFF) << 16 | nx & 0xFFFF;
		stagingBuffer[stagingPosition + 5] = nz & 0xFFFF;
		stagingBuffer[stagingPosition + 6] = (windingReversed ? 1 << 31 : 0) | textureFaceIdx;

		this.stagingPosition += 7;
	}

	public void flush() {
		if (stagingPosition == 0 || outputBuffer == null)
			return;

		try {
			outputBuffer.put(stagingBuffer, 0, stagingPosition);
		} catch (Exception e) {
			log.error("Failed to flush vertex write cache {} written: {} remaining: {}", name, stagingPosition, outputBuffer.remaining(), e);
		} finally {
			stagingPosition = 0;
		}
	}

	public static class Collection {
		private static final int CAPACITY = (int) (32 * KiB / Integer.BYTES);

		public final VertexWriteCache opaque = new VertexWriteCache("OPAQUE", CAPACITY);
		public final VertexWriteCache alpha = new VertexWriteCache("ALPHA", CAPACITY);
		public final VertexWriteCache opaqueTex = new VertexWriteCache("OPAQUE_TEX", CAPACITY);
		public final VertexWriteCache alphaTex = new VertexWriteCache("ALPHA_TEX", CAPACITY);
		public boolean useAlphaBuffer;

		public void setOutputBuffers(ReservedView opaque, ReservedView alpha, ReservedView opaqueTex, ReservedView alphaTex) {
			this.opaque.setOutputView(opaque);
			this.opaqueTex.setOutputView(opaqueTex);
			useAlphaBuffer = alpha != opaque && alphaTex != opaqueTex;
			if (useAlphaBuffer) {
				this.alpha.setOutputView(alpha);
				this.alphaTex.setOutputView(alphaTex);
			} else {
				this.alpha.setOutputBuffer(null);
				this.alphaTex.setOutputBuffer(null);
			}
		}

		public void setOutputBuffers(GpuIntBuffer opaque, GpuIntBuffer alpha, GpuIntBuffer tex) {
			this.opaque.setOutputBuffer(opaque.getBuffer());
			this.opaqueTex.setOutputBuffer(tex.getBuffer());
			useAlphaBuffer = alpha != null && opaque != alpha;
			if (useAlphaBuffer) {
				this.alpha.setOutputBuffer(alpha.getBuffer());
				this.alphaTex.setOutputBuffer(null);
			} else {
				this.alpha.setOutputBuffer(null);
				this.alphaTex.setOutputBuffer(null);
			}
		}

		public VertexWriteCache getVertexBuffer() { return opaque; }

		public VertexWriteCache getTextureBuffer() { return opaqueTex; }

		public VertexWriteCache getVertexBuffer(boolean hasAlpha) {
			return useAlphaBuffer && hasAlpha ? alpha : opaque;
		}

		public VertexWriteCache getTextureBuffer(boolean hasAlpha) {
			return useAlphaBuffer && hasAlpha ? alphaTex : opaqueTex;
		}

		public void release() {
			opaque.release();
			alpha.release();
			opaqueTex.release();
			alphaTex.release();
		}
	}
}

package rs117.hd.renderer.zone;

import com.google.inject.Injector;
import java.nio.IntBuffer;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.client.callback.ClientThread;
import org.lwjgl.system.MemoryStack;
import rs117.hd.HdPlugin;
import rs117.hd.opengl.uniforms.UBOWorldViews;
import rs117.hd.opengl.uniforms.UBOWorldViews.WorldViewStruct;
import rs117.hd.utils.Camera;
import rs117.hd.utils.CommandBuffer;
import rs117.hd.utils.DestructibleHandler;
import rs117.hd.utils.Mat4;
import rs117.hd.utils.buffer.GLBuffer;
import rs117.hd.utils.collections.ConcurrentPool;
import rs117.hd.utils.jobs.JobGroup;

import static org.lwjgl.opengl.GL33C.*;
import static rs117.hd.renderer.zone.DynamicModelVAO.METADATA_SIZE;
import static rs117.hd.renderer.zone.SceneManager.NUM_ZONES;
import static rs117.hd.renderer.zone.ZoneRenderer.FRAMES_IN_FLIGHT;
import static rs117.hd.utils.MathUtils.*;
import static rs117.hd.utils.collections.Util.quickSort;

@Slf4j
public class WorldViewContext {
	public static final int VAO_OPAQUE = 0;
	public static final int VAO_ALPHA = 1;
	public static final int VAO_PLAYER = 2;
	public static final int VAO_SHADOW = 3;
	public static final int VAO_PRESCENE = 4;
	public static final int VAO_COUNT = 5;

	public static final ConcurrentPool<DynamicModelVAO> DYNAMIC_MODEL_VAO_STAGING_POOL =
		new ConcurrentPool<>(() -> new DynamicModelVAO("DynamicModelVAO::Staging", true));
	public static final ConcurrentPool<DynamicModelVAO> DYNAMIC_MODEL_VAO_POOL =
		new ConcurrentPool<>(() -> new DynamicModelVAO("DynamicModelVAO", false));

	@Inject
	private Injector injector;

	@Inject
	private ClientThread clientThread;

	@Inject
	private HdPlugin plugin;

	@Inject
	private SceneManager sceneManager;

	public ZoneSceneContext sceneContext;
	public boolean isLoading = true;
	public boolean isSquashed;
	@Nullable
	public float[] projection;

	final int worldViewId;
	final int sizeX, sizeZ;
	@Nullable
	WorldViewStruct uboWorldViewStruct;

	private final float[] lastProjection = Mat4.zero();
	private final int[] lastOrigin = new int[3];
	private int lastOrientation;

	Zone[][] zones;
	GLBuffer vboM;

	int minLevel, level, maxLevel;
	Set<Integer> hideRoofIds;

	private final Comparator<Zone> alphaSortComparator = Comparator.comparingInt((Zone z) -> z.dist).reversed();
	private final List<Zone> alphaZones = new ArrayList<>();

	CommandBuffer vaoSceneCmd;
	CommandBuffer vaoDirectionalCmd;
	final DynamicModelVAO[][] dynamicModelVaos = new DynamicModelVAO[FRAMES_IN_FLIGHT][VAO_COUNT];

	public long loadTime;
	public long uploadTime;
	public long sceneSwapTime;

	final JobGroup<ZoneUploadJob> sceneLoadGroup = new JobGroup<>(true, true);
	final JobGroup<ZoneUploadJob> streamingGroup = new JobGroup<>(false, false);
	final JobGroup<ZoneUploadJob> invalidationGroup = new JobGroup<>(true, false);

	WorldViewContext(
		@Nullable WorldView worldView,
		@Nullable ZoneSceneContext sceneContext,
		UBOWorldViews uboWorldViews
	) {
		this.worldViewId = worldView == null ? WorldView.TOPLEVEL : worldView.getId();
		this.sceneContext = sceneContext;
		if (sceneContext != null)
			sceneContext.worldViewContext = this;
		this.sizeX = worldView == null ? NUM_ZONES : worldView.getSizeX() >> 3;
		this.sizeZ = worldView == null ? NUM_ZONES : worldView.getSizeY() >> 3;
		if (worldView != null)
			uboWorldViewStruct = uboWorldViews.acquire();
		zones = new Zone[sizeX][sizeZ];
	}

	public void initialize(Injector injector) {
		injector.injectMembers(this);

		vaoSceneCmd = new CommandBuffer("WorldViewScene");
		vaoDirectionalCmd = new CommandBuffer("WorldViewDirectional");

		for (int x = 0; x < sizeX; ++x)
			for (int z = 0; z < sizeZ; ++z)
				zones[x][z] = injector.getInstance(Zone.class);
	}

	void updateProjection(WorldView topLevel) {
		// Update WorldView projection, or estimate its trajectory when off-screen, if possible
		if (worldViewId == WorldView.TOPLEVEL)
			return;

		var worldEntity = topLevel.worldEntities().byIndex(worldViewId);
		isSquashed = worldEntity != null && worldEntity.isHiddenForOverlap();
		if (worldEntity == null) {
			projection = null;
			return;
		}

		var worldView = worldEntity.getWorldView();
		if (worldView.getMainWorldProjection() instanceof FloatProjection) {
			if (projection == null)
				projection = new float[16];
			copyTo(projection, ((FloatProjection) worldView.getMainWorldProjection()).getProjection());
			copyTo(lastProjection, projection);
			var origin = worldEntity.getLocalLocation();
			lastOrigin[0] = origin.getX();
			lastOrigin[1] = topLevel.getTileHeight(origin.getX(), origin.getY(), topLevel.getPlane());
			lastOrigin[2] = origin.getY();
			lastOrientation = worldEntity.getOrientation();
		} else if (projection != null) {
			// Approximate the WorldView's projection based on the WorldEntity's position & orientation
			var origin = worldEntity.getLocalLocation();
			float angle = (worldEntity.getOrientation() - lastOrientation) * JAU_TO_RAD;
			float sin = sin(angle);
			float cos = cos(angle);
			copyTo(projection, lastProjection);
			for (int i = 0; i < 16; i += 4) {
				float x = lastProjection[i];
				float z = lastProjection[i + 2];
				if (i == 12) {
					x -= lastOrigin[0];
					z -= lastOrigin[2];
				}
				projection[i] = cos * x + sin * z;
				projection[i + 2] = -sin * x + cos * z;
			}
			projection[12] += origin.getX();
			projection[13] += topLevel.getTileHeight(origin.getX(), origin.getY(), topLevel.getPlane()) - lastOrigin[1];
			projection[14] += origin.getY();
		}

		if (uboWorldViewStruct != null) {
			if (projection != null)
				uboWorldViewStruct.projection.set(projection);

			Scene scene = worldView.getScene();
			if (scene != null) {
				uboWorldViewStruct.tint.set(
					scene.getOverrideHue(), scene.getOverrideSaturation(),
					scene.getOverrideLuminance(), scene.getOverrideAmount()
				);
			} else {
				uboWorldViewStruct.tint.set(0, 0, 0, 0);
			}
		}
	}

	private static ConcurrentPool<DynamicModelVAO> getDynamicModelVaoPool(int type) {
		// Choose a pool to both acquire from and release back into, irrespective of the storage buffers setting.
		// Without this, buffers allocated during acquisition from the staging pool may be erroneously released
		// back into the non-staging pool, leading to buffers accumulating with unnecessary allocations.
		return type == VAO_OPAQUE || type == VAO_PLAYER || type == VAO_SHADOW ?
			DYNAMIC_MODEL_VAO_STAGING_POOL : DYNAMIC_MODEL_VAO_POOL;
	}

	void initBuffers() {
		if (vboM != null)
			return;

		vboM = new GLBuffer("WorldViewMetadata", GL_ARRAY_BUFFER, GL_DYNAMIC_DRAW, 0);
		vboM.initialize(METADATA_SIZE);
		try (MemoryStack stack = MemoryStack.stackPush()) {
			IntBuffer buf = stack.mallocInt(3);
			buf.put(uboWorldViewStruct == null ? 0 : uboWorldViewStruct.worldViewIdx + 1);
			buf.put(0).put(0);
			buf.flip();
			vboM.upload(buf);
		}

		long start = System.nanoTime();
		for (int i = 0; i < VAO_COUNT; i++) {
			var pool = getDynamicModelVaoPool(i);
			for (int k = 0; k < FRAMES_IN_FLIGHT; k++) {
				DynamicModelVAO dynamicModelVao = dynamicModelVaos[k][i] = pool.acquire();
				if (dynamicModelVao.getVao() == 0)
					dynamicModelVao.initialize();
				dynamicModelVao.bindMetadataVAO(vboM);
			}
		}
		log.trace("WorldViewContext - WorldViewId: {} initBuffers took {}ms", worldViewId, (System.nanoTime() - start) / 1000000);
	}

	void map() {
		for (int i = 0; i < VAO_COUNT; i++)
			dynamicModelVaos[plugin.frame % FRAMES_IN_FLIGHT][i].map();
	}

	DynamicModelVAO.View beginDraw(int type, int faces) {
		return dynamicModelVaos[plugin.frame % FRAMES_IN_FLIGHT][type].beginDraw(faces);
	}

	DynamicModelVAO.View beginDraw(int type, int playerDrawIndex, int faces) {
		return dynamicModelVaos[plugin.frame % FRAMES_IN_FLIGHT][type].beginDraw(playerDrawIndex, faces);
	}

	int obtainDrawIndex(int type) {
		return dynamicModelVaos[plugin.frame % FRAMES_IN_FLIGHT][type].obtainDrawIndex();
	}

	void drawAll(int type, CommandBuffer cmd) {
		dynamicModelVaos[plugin.frame % FRAMES_IN_FLIGHT][type].draw(cmd);
	}

	void unmap() {
		for (int i = 0; i < VAO_COUNT; i++) {
			final boolean shouldCoalesce = i == VAO_OPAQUE || i == VAO_PLAYER || i == VAO_SHADOW;
			dynamicModelVaos[plugin.frame % FRAMES_IN_FLIGHT][i].unmap(shouldCoalesce);
		}
	}

	void sortStaticAlphaModels(Camera camera) {
		alphaZones.clear();

		final int offset = sceneContext.sceneOffset >> 3;
		final int camPosX = (int) camera.getPositionX();
		final int camPosZ = (int) camera.getPositionZ();
		for (int zx = 0; zx < sizeX; zx++) {
			for (int zz = 0; zz < sizeZ; zz++) {
				final Zone z = zones[zx][zz];
				if (z.alphaModels.isEmpty() || (worldViewId == WorldView.TOPLEVEL && !z.inSceneFrustum))
					continue;

				final int dx = camPosX - ((zx - offset) << 10);
				final int dz = camPosZ - ((zz - offset) << 10);
				z.dist = dx * dx + dz * dz;
				alphaZones.add(z);
			}
		}

		if (!alphaZones.isEmpty()) {
			quickSort(alphaZones, alphaSortComparator);
			for (int i = 0; i < alphaZones.size(); i++)
				alphaZones.get(i).alphaStaticModelSort(camera);
		}
	}

	// Synchronize creation of delayed upload jobs with zone swaps and invalidation
	synchronized void handleZoneSwap(int zx, int zz, boolean queue) {
		Zone curZone = zones[zx][zz];
		ZoneUploadJob uploadTask = curZone.uploadJob;
		if (uploadTask == null)
			return;

		if (!uploadTask.isQueued()) {
			if (queue && uploadTask.revealAfterTimestampMs < System.currentTimeMillis()) {
				log.trace("queueing zone({}): [{}-{},{}]", uploadTask.zoneBeingUploaded.hashCode(), worldViewId, zx, zz);
				uploadTask.revealAfterTimestampMs = 0;
				uploadTask.queue(streamingGroup, sceneManager.getGenerateSceneDataTask());
			}
			return;
		}

		if (uploadTask.isDone()) {
			curZone.uploadJob = null;
			if (uploadTask.ranToCompletion() && !uploadTask.wasCancelled()) {
				Zone uploadedZone = uploadTask.zoneBeingUploaded;
				if (uploadedZone == null) {
					log.error(
						"Completed zone upload job [{}] has already been released: [{}-{},{}]",
						uploadTask.hashCode(),
						worldViewId,
						zx,
						zz
					);
					curZone.rebuild = true;
					return;
				}
				log.trace("swapping zone({}): [{}-{},{}]", uploadedZone.hashCode(), worldViewId, zx, zz);

				Zone prevZone = curZone;
				// Swap the zone out with the one we just uploaded
				zones[zx][zz] = curZone = uploadedZone;
				clientThread.invoke(curZone::unmap);

				if (prevZone != curZone) {
					curZone.inSceneFrustum = prevZone.inSceneFrustum;
					curZone.inShadowFrustum = prevZone.inShadowFrustum;
					DestructibleHandler.queueDestruction(prevZone);
				}

				sceneContext.animatedDynamicObjectIds.addAll(curZone.animatedDynamicObjectIds);
			} else if (uploadTask.wasCancelled() && !curZone.cull) {
				boolean shouldRetry = uploadTask.encounteredError() && curZone.isFirstLoadingAttempt;
				if (shouldRetry) {
					// Cache if the previous upload task encountered an error,
					// if it encounters another one the zone will be dropped to avoid constantly rebuilding
					curZone.rebuild = true;
					curZone.isFirstLoadingAttempt = false;
				} else if (uploadTask.encounteredError()) {
					log.debug(
						"Zone({}) [{}-{},{}] was cancelled due to an error, dropping to avoid constantly rebuilding",
						curZone.hashCode(),
						worldViewId,
						zx,
						zz
					);
				}
			}
			uploadTask.release();
		}
	}

	void processZoneSwaps() {
		for (int x = 0; x < sizeX; x++)
			for (int z = 0; z < sizeZ; z++)
				handleZoneSwap(x, z, true);
	}

	void processZoneRebuilds() {
		for (int x = 0; x < sizeX; x++) {
			for (int z = 0; z < sizeZ; z++) {
				if (zones[x][z].rebuild) {
					zones[x][z].rebuild = false;
					invalidateZone(x, z);
				}
			}
		}
	}

	void completeInvalidation() {
		if (invalidationGroup.getPendingCount() <= 0)
			return;

		invalidationGroup.complete();

		for (int x = 0; x < sizeX; x++)
			for (int z = 0; z < sizeZ; z++)
				handleZoneSwap(x, z, false);
	}

	void free() {
		sceneLoadGroup.cancel();
		streamingGroup.cancel();

		if (sceneContext != null) {
			sceneContext.worldViewContext = null;
			sceneContext.destroy();
		}
		sceneContext = null;

		if (uboWorldViewStruct != null)
			uboWorldViewStruct.free();
		uboWorldViewStruct = null;
		projection = null;
		isSquashed = false;

		for (int i = 0; i < VAO_COUNT; i++) {
			var pool = getDynamicModelVaoPool(i);
			for (int k = 0; k < FRAMES_IN_FLIGHT; k++) {
				if (dynamicModelVaos[k][i] == null)
					continue;
				pool.recycle(dynamicModelVaos[k][i]);
				dynamicModelVaos[k][i] = null;
			}
		}

		for (int x = 0; x < sizeX; ++x)
			for (int z = 0; z < sizeZ; ++z)
				zones[x][z].destroy();

		if (vboM != null)
			vboM.destroy();
		vboM = null;

		isLoading = true;
	}

	void invalidate() {
		log.debug("invalidate all zones for worldViewId: [{}]", worldViewId);
		for (int x = 0; x < sizeX; ++x)
			for (int z = 0; z < sizeZ; ++z)
				invalidateZone(x, z);
	}

	// Synchronize creation of delayed upload jobs with zone swaps and invalidation
	synchronized void invalidateZone(int zx, int zz) {
		Zone curZone = zones[zx][zz];
		long revealAfterTimestampMs = 0;
		ZoneUploadJob previousUpload = curZone.uploadJob;
		if (previousUpload != null) {
			curZone.uploadJob = null;
			Zone pendingZone = previousUpload.zoneBeingUploaded;
			log.trace(
				"Invalidate Zone({}) - Cancelled upload task: [{}-{},{}] task zone({})",
				curZone.hashCode(),
				worldViewId,
				zx,
				zz,
				pendingZone.hashCode()
			);
			revealAfterTimestampMs = previousUpload.revealAfterTimestampMs;
			previousUpload.cancel();
			previousUpload.release();

			if (pendingZone != curZone)
				DestructibleHandler.destroy(pendingZone);
		}

		Zone newZone = injector.getInstance(Zone.class);
		newZone.dirty = zones[zx][zz].dirty;

		curZone.setUploadJob(ZoneUploadJob.build(this, sceneContext, newZone, false, zx, zz));
		curZone.uploadJob.revealAfterTimestampMs = revealAfterTimestampMs;

		// Queue right away, so we can wait for it while in the POH in order to hide building mode placeholders
		if (sceneContext.isInHouse || revealAfterTimestampMs <= 0)
			curZone.uploadJob.queue(invalidationGroup, sceneManager.getGenerateSceneDataTask());
	}
}

package rs117.hd.renderer.zone;

import java.nio.IntBuffer;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import org.lwjgl.system.MemoryStack;
import rs117.hd.HdPlugin;
import rs117.hd.scene.MaterialManager;
import rs117.hd.scene.SceneContext;
import rs117.hd.scene.materials.Material;
import rs117.hd.scene.model_overrides.ModelOverride;
import rs117.hd.utils.Camera;
import rs117.hd.utils.CommandBuffer;
import rs117.hd.utils.Destructible;
import rs117.hd.utils.DestructibleHandler;
import rs117.hd.utils.HDUtils;
import rs117.hd.utils.buffer.GLBuffer;
import rs117.hd.utils.buffer.GLTextureBuffer;
import rs117.hd.utils.collections.ConcurrentPool;
import rs117.hd.utils.collections.Int2IntHashMap;
import rs117.hd.utils.collections.IntHashSet;
import rs117.hd.utils.collections.PooledArrayType;

import static net.runelite.api.Constants.*;
import static org.lwjgl.opengl.GL33C.*;
import static rs117.hd.HdPlugin.SUPPORTS_INDIRECT_DRAW;
import static rs117.hd.HdPlugin.SUPPORTS_MULTI_INDIRECT_DRAW;
import static rs117.hd.HdPlugin.checkGLErrors;
import static rs117.hd.renderer.zone.ZoneRenderer.TEXTURE_UNIT_TEXTURED_FACES;
import static rs117.hd.renderer.zone.ZoneRenderer.eboAlpha;
import static rs117.hd.utils.MathUtils.*;
import static rs117.hd.utils.collections.Util.quickSort;

@Slf4j
public class Zone implements Destructible {
	private static final ConcurrentPool<AlphaModel> ALPHA_MODEL_POOL = new ConcurrentPool<>(AlphaModel::new);

	@Inject
	private Client client;

	// Zone vertex format
	// pos short vec3(x, y, z)
	// uvw short vec3(u, v, w)
	// normal short vec3(nx, ny, nz)
	// texturedFaceIdx int
	public static final int VERT_SIZE = 28;

	// alphaBiasHsl ivec3
	// materialData ivec3
	// terrainData ivec3
	public static final int TEXTURE_SIZE = 36;

	// Metadata format
	// worldViewIndex int int
	// sceneOffset int vec2(x, y)
	public static final int METADATA_SIZE = 12;

	public static int LEVEL_COUNT = MAX_Z;
	public static final int LEVEL_TERRAIN = LEVEL_COUNT++;
	public static final int LEVEL_WATER_SURFACE = LEVEL_COUNT++;
	public static final int LEVEL_GAP_FILLER = LEVEL_COUNT++;

	public int glVao;
	int modelCount;
	int bufLen;
	int dist;

	public int glVaoA;
	public int bufLenA;

	public int sizeO, sizeA, sizeF;
	@Nullable
	public GLBuffer vboO, vboA, vboM;
	public GLTextureBuffer tboF;

	public boolean initialized; // whether the zone vao and vbos are ready
	public boolean cull; // whether the zone is queued for deletion
	public boolean needsRoofUpdate; // whether the zone needs to have its roofs updated during scene swap
	public boolean rebuild; // whether the zone is queued for rebuild
	public boolean dirty; // whether the zone has temporary modifications
	public boolean hasWater; // whether the zone has any water tiles
	public boolean onlyWater; // whether the zone only contains water tiles
	public boolean hasGapFiller; // whether the zone has any gap filler geometry
	public boolean inSceneFrustum = true; // whether the zone is visible to the scene camera
	public boolean inShadowFrustum; // whether the zone casts shadows into the visible scene
	public boolean isFirstLoadingAttempt = true;

	public IntHashSet animatedDynamicObjectIds = new IntHashSet();

	final StaticAlphaSortingJob alphaSortingJob = new StaticAlphaSortingJob();
	ZoneUploadJob uploadJob;

	void setUploadJob(ZoneUploadJob uploadJob) {
		this.uploadJob = uploadJob;
		if (uploadJob != null)
			uploadJob.zoneToBeReplaced = this;
	}

	int[] levelOffsets = new int[LEVEL_COUNT]; // buffer pos in ints for the end of the level

	int[][] rids;
	int[][] roofStart;
	int[][] roofEnd;

	final List<AlphaModel> alphaModels = new ArrayList<>(0);
	final ConcurrentLinkedQueue<AsyncCachedModel> pendingModelJobs = new ConcurrentLinkedQueue<>();

	public void initialize(GLBuffer o, GLBuffer a, GLTextureBuffer f) {
		assert glVao == 0;
		assert glVaoA == 0;
		if (o == null && a == null || f == null)
			return;

		vboM = new GLBuffer("ZoneMetadata", GL_ARRAY_BUFFER, GL_DYNAMIC_DRAW);
		vboM.initialize(METADATA_SIZE);

		if (o != null) {
			vboO = o;
			glVao = glGenVertexArrays();
			setupVao(glVao, o.id, vboM.id);
		}

		if (a != null) {
			vboA = a;
			glVaoA = glGenVertexArrays();
			setupVao(glVaoA, a.id, vboM.id);
		}

		tboF = f;
	}

	public static void freeZones(@Nullable Zone[][] zones) {
		if (zones == null)
			return;

		for (Zone[] column : zones)
			for (Zone zone : column)
				if (zone != null)
					zone.destroy();
	}

	@Override
	@SuppressWarnings("deprecation")
	protected void finalize() {
		if (glVao != 0 || glVaoA != 0)
			DestructibleHandler.queueLeakedDestruction(this);
	}

	@Override
	public void destroy() {
		if (vboO != null) {
			vboO.destroy();
			vboO = null;
		}

		if (vboA != null) {
			vboA.destroy();
			vboA = null;
		}

		if (vboM != null) {
			vboM.destroy();
			vboM = null;
		}

		if (tboF != null) {
			tboF.destroy();
			tboF = null;
		}

		if (glVao != 0) {
			glDeleteVertexArrays(glVao);
			glVao = 0;
		}

		if (glVaoA != 0) {
			glDeleteVertexArrays(glVaoA);
			glVaoA = 0;
		}

		if (uploadJob != null) {
			uploadJob.cancel();
			DestructibleHandler.destroy(uploadJob.zoneBeingUploaded);
			uploadJob = null;
		}

		sortedAlphaFacesUpload.release();

		sizeO = 0;
		sizeA = 0;
		sizeF = 0;
		bufLen = 0;
		bufLenA = 0;

		initialized = false;
		cull = false;
		hasWater = false;
		onlyWater = false;
		hasGapFiller = false;
		inSceneFrustum = false;
		inShadowFrustum = false;

		Arrays.fill(levelOffsets, 0);
		rids = null;
		roofStart = null;
		roofEnd = null;

		// don't add permanent alphamodels to the cache as permanent alphamodels are always allocated
		// to avoid having to synchronize the cache
		alphaModels.clear();
	}

	@Override
	public String toString() {
		return String.format(
			"Zone Initialized: %b, culled: %b hasUploadJob: %b opaqueSize: %d alphaSize: %d",
			initialized, cull, uploadJob != null, sizeO, sizeA
		);
	}

	public void unmap() {
		assert client.isClientThread();

		if (vboO != null)
			vboO.unmap();
		if (vboA != null)
			vboA.unmap();
		if (tboF != null)
			tboF.unmap();

		if (vboO != null) {
			this.bufLen = vboO.mapped().byteView().position() / VERT_SIZE;
		}

		if (vboA != null) {
			this.bufLenA = vboA.mapped().byteView().position() / VERT_SIZE;
		}
	}

	private void setupVao(int vao, int buffer, int metadata) {
		glBindVertexArray(vao);
		glBindBuffer(GL_ARRAY_BUFFER, buffer);

		// Position
		glEnableVertexAttribArray(0);
		glVertexAttribPointer(0, 4, GL_SHORT, false, VERT_SIZE, 0);

		// UVs
		glEnableVertexAttribArray(1);
		glVertexAttribPointer(1, 4, GL_HALF_FLOAT, false, VERT_SIZE, 8);

		// Normals
		glEnableVertexAttribArray(2);
		glVertexAttribPointer(2, 4, GL_SHORT, false, VERT_SIZE, 16);

		// TextureFaceIdx
		glEnableVertexAttribArray(3);
		glVertexAttribIPointer(3, 1, GL_INT, VERT_SIZE, 24);

		glBindBuffer(GL_ARRAY_BUFFER, metadata);

		// WorldView index (not ID)
		glEnableVertexAttribArray(6);
		glVertexAttribDivisor(6, 1);
		glVertexAttribIPointer(6, 1, GL_INT, METADATA_SIZE, 0);

		// Scene offset
		glEnableVertexAttribArray(7);
		glVertexAttribDivisor(7, 1);
		glVertexAttribIPointer(7, 2, GL_INT, METADATA_SIZE, 4);

		checkGLErrors();

		glBindVertexArray(0);
		glBindBuffer(GL_ARRAY_BUFFER, 0);
	}

	public void setMetadata(WorldViewContext viewContext, SceneContext sceneContext, int mx, int mz) {
		if (vboM == null)
			return;

		int baseX = (mx - (sceneContext.sceneOffset >> 3)) << 10;
		int baseZ = (mz - (sceneContext.sceneOffset >> 3)) << 10;

		try (MemoryStack stack = MemoryStack.stackPush()) {
			IntBuffer buf = stack.mallocInt(3)
				.put(viewContext.uboWorldViewStruct != null ? viewContext.uboWorldViewStruct.worldViewIdx + 1 : 0)
				.put(baseX)
				.put(baseZ);
			buf.flip();
			vboM.upload(buf);
		}
	}

	void updateRoofs(Int2IntHashMap updates) {
		for (int level = 0; level < 4; ++level) {
			for (int i = 0; i < rids[level].length; ++i) {
				rids[level][i] = updates.getOrDefault(rids[level][i], rids[level][i]);
			}
		}

		for (AlphaModel m : alphaModels)
			m.rid = (short) updates.getOrDefault(m.rid, m.rid);
	}

	private static final int NUM_DRAW_RANGES = 512;
	private static final int[] drawOff = new int[NUM_DRAW_RANGES];
	private static final int[] drawEnd = new int[NUM_DRAW_RANGES];

	private static final int[] glDrawOffset = new int[NUM_DRAW_RANGES];
	private static final int[] glDrawLength = new int[NUM_DRAW_RANGES];
	private static int drawIdx = 0;

	private void convertForDraw(int vertSize) {
		for (int i = 0; i < drawIdx; ++i) {
			assert drawEnd[i] >= drawOff[i];

			// convert from bytes to verts
			drawOff[i] /= vertSize >> 2;
			drawEnd[i] /= vertSize >> 2;

			drawEnd[i] -= drawOff[i]; // convert from end pos to length
		}

		copyTo(glDrawOffset, drawOff, 0, drawIdx);
		copyTo(glDrawLength, drawEnd, 0, drawIdx);
	}

	void renderOpaque(CommandBuffer cmd, WorldViewContext ctx, boolean roofShadows) {
		drawIdx = 0;

		int currentLevel = ctx.level;
		int maxLevel = ctx.maxLevel;
		var hiddenRoofIds = ctx.hideRoofIds;
		if (roofShadows) {
			maxLevel = 3;
			hiddenRoofIds = Collections.emptySet();
		}

		for (int level = ctx.minLevel; level <= maxLevel; ++level) {
			int[] rids = this.rids[level];
			int[] roofStart = this.roofStart[level];
			int[] roofEnd = this.roofEnd[level];

			if (rids.length == 0 || hiddenRoofIds.isEmpty() || level <= currentLevel) {
				// draw the whole level
				int start = level == 0 ? 0 : this.levelOffsets[level - 1];
				int end = this.levelOffsets[level];
				pushRange(start, end);
				continue;
			}

			for (int roofIdx = 0; roofIdx < rids.length; ++roofIdx) {
				int rid = rids[roofIdx];
				if (rid > 0 && !hiddenRoofIds.contains(rid)) {
					// draw the roof
					assert roofEnd[roofIdx] >= roofStart[roofIdx];
					if (roofEnd[roofIdx] > roofStart[roofIdx]) {
						pushRange(roofStart[roofIdx], roofEnd[roofIdx]);
					}
				}
			}

			// push from the end of the last roof to the end of the level
			int endpos = level == 0 ? 0 : this.levelOffsets[level - 1];
			for (int roofIdx = rids.length - 1; roofIdx >= 0; --roofIdx) {
				int rid = rids[roofIdx];
				if (rid > 0) {
					endpos = roofEnd[roofIdx];
					break;
				}
			}
			// draw the non roofs
			pushRange(endpos, this.levelOffsets[level]);
		}

		if (drawIdx == 0)
			return;

		lastDrawMode = STATIC_UNSORTED;
		lastVao = glVao;
		lastTboF = tboF.getTexId();
		flush(cmd);
	}

	void renderOpaqueLevel(CommandBuffer cmd, int level) {
		drawIdx = 0;

		pushRange(level > 0 ? this.levelOffsets[level - 1] : 0, this.levelOffsets[level]);

		if (drawIdx == 0)
			return;

		lastDrawMode = STATIC_UNSORTED;
		lastVao = glVao;
		lastTboF = tboF.getTexId();
		flush(cmd);
	}

	private static void pushRange(int start, int end) {
		assert end >= start;
		if (end <= start)
			return;

		if (drawIdx > 0 && drawEnd[drawIdx - 1] == start) {
			drawEnd[drawIdx - 1] = end;
		} else if (drawIdx >= NUM_DRAW_RANGES) {
			log.debug("draw ranges exhausted");
		} else {
			drawOff[drawIdx] = start;
			drawEnd[drawIdx] = end;
			drawIdx++;
		}
	}

	public static final class AlphaModel {
		int id;
		ModelOverride modelOverride;
		int startpos, endpos;
		short x, y, z; // local position
		short rid;
		int vao;
		int tboF;
		byte level;
		byte lx, lz, ux, uz; // lower/upper zone coords
		byte zofx, zofz; // for temp alpha models, offset of source zone from target zone
		byte flags;

		// only set for static geometry as they require sorting
		int radius;
		int[] packedFaces;
		int[] doubleSidedBitSet;
		char doubleSidedCount;

		int dist;
		int asyncSortIdx = -1;
		int sortedFacesLen;
		int[] tempSortedFaces;

		static final int SKIP = 1; // temporary model is in a closer zone
		static final int TEMP = 2; // temporary model added to a closer zone
		static final int SORT_COMPLETED = 4;

		void setSorted() {
			flags |= SORT_COMPLETED;
		}

		boolean needsSorting() {
			return (flags & SORT_COMPLETED) == 0;
		}

		boolean isTemp() {
			return packedFaces == null;
		}

		int calculateDepth(int cx, int cy, int cz, int zx, int zz) {
			final int mx = (x + ((zx - zofx) << 10));
			final int mz = (z + ((zz - zofz) << 10));
			return (mx - cx) * (mx - cx) + (y - cy) * (y - cy) + (mz - cz) * (mz - cz);
		}

		void setView(DynamicModelVAO.View view) {
			vao = view.vao;
			tboF = view.tboTexId;
			startpos = view.getStartOffset();
			endpos = view.getEndOffset();
		}
	}

	void addAlphaModel(
		HdPlugin plugin,
		MaterialManager materialManager,
		int vao,
		int tboF,
		Model model,
		ModelOverride modelOverride,
		int startpos,
		int endpos,
		int x,
		int y,
		int z,
		int lx,
		int lz,
		int ux,
		int uz,
		int rid,
		int level,
		int id
	) {
		AlphaModel m = new AlphaModel();
		m.id = id;
		m.modelOverride = modelOverride;
		m.startpos = startpos;
		m.endpos = endpos;
		m.x = (short) x;
		m.y = (short) y;
		m.z = (short) z;
		m.vao = vao;
		m.tboF = tboF;
		m.rid = (short) rid;
		m.level = (byte) level;
		if (lx > -1) {
			m.lx = (byte) lx;
			m.lz = (byte) lz;
			m.ux = (byte) ux;
			m.uz = (byte) uz;
		} else {
			m.lx = m.lz = m.ux = m.uz = -1;
		}

		int faceCount = model.getFaceCount();
		short[] unlitColor = plugin.configUnlitFaceColors ? model.getUnlitFaceColors() : null;
		int[] color1 = model.getFaceColors1();
		int[] color3 = model.getFaceColors3();
		byte[] transparencies = model.getFaceTransparencies();
		short[] faceTextures = model.getFaceTextures();
		float[] vertexX = model.getVerticesX();
		float[] vertexY = model.getVerticesY();
		float[] vertexZ = model.getVerticesZ();
		int[] indices1 = model.getFaceIndices1();
		int[] indices2 = model.getFaceIndices2();
		int[] indices3 = model.getFaceIndices3();

		int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, minZ = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE, maxZ = Integer.MIN_VALUE;

		for (int f = 0; f < faceCount; ++f) {
			if (color3[f] == -2)
				continue;

			boolean hasAlpha = modelOverride.mightHaveTransparency || transparencies != null && transparencies[f] != 0;
			if (!hasAlpha)
				continue;

			int fx = (int) (vertexX[indices1[f]] + vertexX[indices2[f]] + vertexX[indices3[f]]);
			int fy = (int) (vertexY[indices1[f]] + vertexY[indices2[f]] + vertexY[indices3[f]]);
			int fz = (int) (vertexZ[indices1[f]] + vertexZ[indices2[f]] + vertexZ[indices3[f]]);

			minX = Math.min(minX, fx);
			maxX = Math.max(maxX, fx);
			minY = Math.min(minY, fy);
			maxY = Math.max(maxY, fy);
			minZ = Math.min(minZ, fz);
			maxZ = Math.max(maxZ, fz);
		}

		int cx = (minX + maxX) / 6;
		int cy = (minY + maxY) / 6;
		int cz = (minZ + maxZ) / 6;

		int size = Math.max(
			Math.max(
				Math.max(maxX / 3 - cx, minX / -3 - cx),
				Math.max(maxY / 3 - cy, minY / -3 - cy) * 2
			),
			Math.max(maxZ / 3 - cz, minZ / -3 - cz)
		);

		int shift = 0;
		// 10 bits because we need a sign bit
		for (int v = size >> 10; v > 0; v >>= 1) {
			shift++;
		}

		final int intsPerVertex = VERT_SIZE / Integer.BYTES;
		final int writtenAlphaFaceCount = (endpos - startpos) / (3 * intsPerVertex);
		final int bucketCapacity = ceil(writtenAlphaFaceCount / 32.0f);

		final int[] packedFaces = PooledArrayType.INT.borrow(writtenAlphaFaceCount);
		final int[] doubleSidedBitSet = PooledArrayType.INT.borrow(bucketCapacity);

		Arrays.fill(doubleSidedBitSet, 0, bucketCapacity, 0);

		final Material baseMaterial = modelOverride.baseMaterial;
		final Material textureMaterial = modelOverride.textureMaterial;

		int radius = 0;
		char bufferIdx = 0;
		char doubleSidedCount = 0;
		for (int f = 0; f < faceCount; ++f) {
			if (color3[f] == -2)
				continue;

			// Hide fake shadows or lighting that is often baked into models by making the fake shadow transparent
			if (plugin.configHideFakeShadows && modelOverride.hideVanillaShadows && HDUtils.isBakedGroundShading(model, f))
				continue;

			Material material = baseMaterial;
			ModelOverride faceOverride = modelOverride;

			int transparency = SceneUploader.readFaceTransparency(model.getTransparency(), transparencies, f);
			if (transparency == 255)
				continue;

			int textureId = faceTextures != null ? faceTextures[f] : -1;
			if (textureId != -1) {
				if (modelOverride.textureMaterial != Material.NONE) {
					material = textureMaterial;
				} else {
					material = materialManager.fromVanillaTexture(textureId);
					if (modelOverride.materialOverrides != null) {
						var override = modelOverride.materialOverrides.get(material);
						if (override != null) {
							faceOverride = override;
							material = override.textureMaterial;
						}
					}
				}
			} else if (modelOverride.colorOverrides != null) {
				final int ahsl = (0xFF - transparency) << 16 | (unlitColor != null ? unlitColor[f] & 0xFFFF : color1[f]);
				final var override = modelOverride.testColorOverrides(ahsl);
				if (override != null) {
					faceOverride = override;
					material = override.baseMaterial;
				}
			}

			if (faceOverride.hide)
				continue;

			if (faceOverride.modifiesAlpha)
				transparency = 255 - faceOverride.modifyAlpha(255 - transparency);

			boolean hasAlpha = material.hasTransparency || transparency != 0;
			if (!hasAlpha)
				continue;

			final int fx = (((int) (vertexX[indices1[f]] + vertexX[indices2[f]] + vertexX[indices3[f]]) / 3) - cx) >> shift;
			final int fy = (((int) (vertexY[indices1[f]] + vertexY[indices2[f]] + vertexY[indices3[f]]) / 3) - cy) >> shift;
			final int fz = (((int) (vertexZ[indices1[f]] + vertexZ[indices2[f]] + vertexZ[indices3[f]]) / 3) - cz) >> shift;

			radius = Math.max(radius, fx * fx + fy * fy + fz * fz);
			packedFaces[bufferIdx] = ((fx & ((1 << 11) - 1)) << 21)
			                         | ((fy & ((1 << 10) - 1)) << 11)
			                         | (fz & ((1 << 11) - 1));

			if (faceOverride.doubleSidedFaces || material.doubleSidedFaces) {
				doubleSidedBitSet[bufferIdx >> 5] |= 1 << (bufferIdx & 31);
				doubleSidedCount++;
			}

			bufferIdx++;
		}

		assert packedFaces.length > 0;
		// Normally these will be equal, but transparency is used to hide faces in the TzHaar reskin
		assert bufferIdx <= packedFaces.length : String.format("%d > %d", (int) bufferIdx, packedFaces.length);

		m.radius = 2 + (int) Math.sqrt(radius);
		m.packedFaces = Arrays.copyOf(packedFaces, bufferIdx);
		m.doubleSidedBitSet = doubleSidedCount > 0 ? Arrays.copyOf(doubleSidedBitSet, ceil(bufferIdx / 32.0f)) : null;
		m.doubleSidedCount = doubleSidedCount;

		alphaModels.add(m);

		PooledArrayType.INT.release(packedFaces);
		PooledArrayType.INT.release(doubleSidedBitSet);
	}

	synchronized AlphaModel requestTempAlphaModel(ModelOverride modelOverride, int level, int x, int y, int z) {
		AlphaModel m = ALPHA_MODEL_POOL.acquire();
		m.id = -1;
		m.modelOverride = modelOverride;
		m.x = (short) x;
		m.y = (short) y;
		m.z = (short) z;
		m.level = (byte) level;
		m.vao = m.tboF = m.rid = m.lx = m.lz = m.ux = m.uz = -1;
		m.flags = 0;
		m.zofx = m.zofz = 0;
		alphaModels.add(m);
		return m;
	}

	synchronized void postAlphaPass() {
		sortedAlphaFacesUpload.waitForCompletion();
		alphaSortingJob.waitForCompletion();
		alphaSortingJob.reset();

		for (int i = alphaModels.size() - 1; i >= 0; --i) {
			AlphaModel m = alphaModels.get(i);
			m.asyncSortIdx = -1;
			m.flags &= ~(AlphaModel.SKIP | AlphaModel.SORT_COMPLETED);

			if (m.isTemp() || (m.flags & AlphaModel.TEMP) != 0) {
				alphaModels.remove(i);
				m.packedFaces = null;
				m.doubleSidedBitSet = null;
				ALPHA_MODEL_POOL.recycle(m);
			}

			if (m.tempSortedFaces != null)
				PooledArrayType.INT.release(m.tempSortedFaces);
			m.tempSortedFaces = null;
		}
	}

	private static final int STATIC = 1;
	private static final int TEMP = 2;
	private static final int STATIC_UNSORTED = 3;

	private static int alphaFaceCount;
	private static int eboAlphaOffset;
	private static int lastDrawMode;
	private static int lastVao;
	private static int lastTboF;
	private static int lastzx, lastzz;

	static class AlphaModelComparator implements Comparator<AlphaModel> {
		int zx, zz;
		int cx, cy, cz;

		@Override
		public int compare(AlphaModel modelA, AlphaModel modelB) {
			return Integer.compare(
				modelB.calculateDepth(cx, cy, cz, zx, zz),
				modelA.calculateDepth(cx, cy, cz, zx, zz)
			);
		}
	}

	private static final AlphaModelComparator alphaModelComparator = new AlphaModelComparator();
	private final EboAlphaWriterJob sortedAlphaFacesUpload = new EboAlphaWriterJob();

	synchronized void alphaSort(int zx, int zz, Camera camera) {
		final int alphaModelCount = alphaModels.size();
		if (alphaModelCount <= 1)
			return;

		alphaModelComparator.cx = (int) camera.getPositionX();
		alphaModelComparator.cy = (int) camera.getPositionY();
		alphaModelComparator.cz = (int) camera.getPositionZ();
		alphaModelComparator.zx = zx;
		alphaModelComparator.zz = zz;

		quickSort(alphaModels, alphaModelComparator);
	}

	void alphaStaticModelSort(Camera camera) {
		alphaSortingJob.reset();
		for (AlphaModel m : alphaModels) {
			if ((m.flags & AlphaModel.SKIP) != 0 || m.isTemp())
				continue;

			m.dist = dist;
			m.tempSortedFaces = PooledArrayType.INT.borrow((m.packedFaces.length + m.doubleSidedCount) * 3);
			alphaSortingJob.addAlphaModel(m);
		}
		alphaSortingJob.queue(camera);
	}

	void renderAlpha(
		CommandBuffer cmd,
		int zx,
		int zz,
		int level,
		WorldViewContext ctx,
		boolean depthOnly,
		boolean includeRoof
	) {
		if (alphaModels.isEmpty())
			return;

		int minLevel = ctx.minLevel;
		int currentLevel = ctx.level;
		int maxLevel = ctx.maxLevel;
		var hiddenRoofIds = ctx.hideRoofIds;
		if (includeRoof) {
			maxLevel = 3;
			hiddenRoofIds = Collections.emptySet();
		}

		drawIdx = 0;

		if (!depthOnly)
			sortedAlphaFacesUpload.waitForCompletion();

		int eboAlphaStart = eboAlphaOffset = ZoneRenderer.eboAlphaWriter.getWrittenInts();
		for (int i = 0; i < alphaModels.size(); i++) {
			final AlphaModel m = alphaModels.get(i);
			if ((m.flags & AlphaModel.SKIP) != 0 || m.level != level || m.vao == -1)
				continue;

			if (level < minLevel || level > maxLevel ||
				level > currentLevel && !hiddenRoofIds.isEmpty() && hiddenRoofIds.contains((int) m.rid))
				continue;

			int drawMode = STATIC;
			if (m.isTemp()) {
				// these are already sorted and so just requires a glMultiDrawArrays() from the active vao
				drawMode = TEMP;
			} else if (depthOnly || m.asyncSortIdx < 0) {
				drawMode = STATIC_UNSORTED;
			}

			if (lastDrawMode != drawMode ||
				lastVao != m.vao ||
				lastTboF != m.tboF ||
				lastzx != (zx - m.zofx) ||
				lastzz != (zz - m.zofz)
			) {
				flush(cmd);
				lastDrawMode = drawMode;
				lastVao = m.vao;
				lastTboF = m.tboF;
				lastzx = zx - m.zofx;
				lastzz = zz - m.zofz;
			}

			if (drawMode != STATIC) {
				pushRange(m.startpos, m.endpos);
				continue;
			}

			// Check if we the faces have already been sorted, if not then the client will steal the work,
			// if the model is already being processed then we'll have to wait for the result to finish
			if (m.needsSorting() && !alphaSortingJob.forceProcessModelClient(m)) {
				while (m.needsSorting() && !alphaSortingJob.isDone())
					alphaSortingJob.waitForCompletion(10);
			}

			if (m.tempSortedFaces == null || m.sortedFacesLen <= 0)
				continue;

			sortedAlphaFacesUpload.alphaModels.add(m);

			eboAlphaOffset += m.sortedFacesLen;
			alphaFaceCount += m.sortedFacesLen / 3;
			lastDrawMode = STATIC;
		}

		if (eboAlphaOffset > eboAlphaStart && !sortedAlphaFacesUpload.alphaModels.isEmpty()) {
			sortedAlphaFacesUpload.eboAlphaView = ZoneRenderer.eboAlphaWriter.reserve(eboAlphaOffset - eboAlphaStart);
			sortedAlphaFacesUpload.queue();
		}

		flush(cmd);
	}

	private void flush(CommandBuffer cmd) {
		if (lastDrawMode == STATIC) {
			if (alphaFaceCount > 0 && lastVao != 0) {
				int vertexCount = alphaFaceCount * 3;
				long byteOffset = 4L * (eboAlphaOffset - vertexCount);
				cmd.BindVertexArray(lastVao, eboAlpha);
				cmd.BindTextureUnit(GL_TEXTURE_BUFFER, lastTboF, TEXTURE_UNIT_TEXTURED_FACES);
				// The EBO & IDO is bound by in ZoneRenderer
				if (SUPPORTS_INDIRECT_DRAW) {
					cmd.DrawElementsIndirect(GL_TRIANGLES, vertexCount, (int) (byteOffset / 4L), ZoneRenderer.indirectDrawCmdsStaging);
				} else {
					cmd.DrawElements(GL_TRIANGLES, vertexCount, byteOffset);
				}
			}
			alphaFaceCount = 0;
		} else if (drawIdx != 0) {
			convertForDraw(lastDrawMode == STATIC_UNSORTED ? VERT_SIZE : DynamicModelVAO.VERT_SIZE);
			cmd.BindVertexArray(lastVao);
			cmd.BindTextureUnit(GL_TEXTURE_BUFFER, lastTboF, TEXTURE_UNIT_TEXTURED_FACES);
			if (drawIdx == 1) {
				if (SUPPORTS_INDIRECT_DRAW) {
					cmd.DrawArraysIndirect(GL_TRIANGLES, drawOff[0], drawEnd[0], ZoneRenderer.indirectDrawCmdsStaging);
				} else {
					cmd.DrawArrays(GL_TRIANGLES, drawOff[0], drawEnd[0]);
				}
			} else {
				if (SUPPORTS_MULTI_INDIRECT_DRAW) {
					cmd.MultiDrawArraysIndirect(GL_TRIANGLES, glDrawOffset, glDrawLength, drawIdx, ZoneRenderer.indirectDrawCmdsStaging);
				} else {
					cmd.MultiDrawArrays(GL_TRIANGLES, glDrawOffset, glDrawLength, drawIdx);
				}
			}
			drawIdx = 0;
		}
	}

	synchronized void multizoneLocs(SceneContext ctx, int zx, int zz, Camera camera, Zone[][] zones) {
		int offset = ctx.sceneOffset >> 3;
		int cx = (int) camera.getPositionX();
		int cz = (int) camera.getPositionZ();
		for (int i = 0; i < alphaModels.size(); i++) {
			final AlphaModel m = alphaModels.get(i);
			if (m.lx == -1)
				continue;

			// calculate which zone this model should be drawn from
			// TODO fix for boats
			int max = Integer.MAX_VALUE;
			int closestZoneX = -50, closestZoneZ = -50;
			for (int x = m.lx >> 3; x <= m.ux >> 3; ++x) {
				for (int z = m.lz >> 3; z <= m.uz >> 3; ++z) {
					int centerX = (zx - m.zofx + x) * 8 + 4 << 7;
					int centerZ = (zz - m.zofz + z) * 8 + 4 << 7;
					int distance = (centerX - cx) * (centerX - cx) +
								   (centerZ - cz) * (centerZ - cz);
					if (distance < max) {
						int zx2 = (centerX >> 10) + offset;
						int zz2 = (centerZ >> 10) + offset;
						if (zx2 >= 0 && zx2 < zones.length && zz2 >= 0 && zz2 < zones[0].length) {
							if (zones[zx2][zz2].inSceneFrustum && zones[zx2][zz2].initialized) {
								max = distance;
								closestZoneX = centerX >> 10;
								closestZoneZ = centerZ >> 10;
							}
						}
					}
				}
			}
			if (closestZoneX != -50 && (closestZoneX != zx || closestZoneZ != zz)) {
				assert closestZoneX + offset >= 0 : closestZoneX;
				assert closestZoneX + offset < zones.length : closestZoneX;
				assert closestZoneZ + offset >= 0 : closestZoneZ;
				assert closestZoneZ + offset < zones[0].length : closestZoneZ;

				Zone z = zones[closestZoneX + offset][closestZoneZ + offset];
				assert z != null;
				assert z != this;

				AlphaModel m2 = ALPHA_MODEL_POOL.acquire();
				m2.id = m.id;
				m2.modelOverride = m.modelOverride;
				m2.startpos = m.startpos;
				m2.endpos = m.endpos;
				m2.x = m.x;
				m2.y = m.y;
				m2.z = m.z;
				m2.vao = m.vao;
				m2.tboF = m.tboF;
				m2.rid = m.rid;
				m2.level = m.level;
				m2.lx = m.lx;
				m2.lz = m.lz;
				m2.ux = m.ux;
				m2.uz = m.uz;
				m2.zofx = (byte) (closestZoneX - zx);
				m2.zofz = (byte) (closestZoneZ - zz);

				m2.packedFaces = m.packedFaces;
				m2.doubleSidedBitSet = m.doubleSidedBitSet;
				m2.radius = m.radius;
				m2.doubleSidedCount = m.doubleSidedCount;
				m2.asyncSortIdx = m.asyncSortIdx;
				m2.tempSortedFaces = m.tempSortedFaces;
				m2.sortedFacesLen = m.sortedFacesLen;

				m2.flags = AlphaModel.TEMP;
				m.flags |= AlphaModel.SKIP;

				z.alphaModels.add(m2);
			}
		}
	}
}

