import rs117.hd.utils.VariableSupplier;

import static rs117.hd.utils.MathUtils.*;
import static rs117.hd.utils.ResourcePath.path;

@Slf4j
@Singleton
public class EnvironmentManager {
	private static final ResourcePath ENVIRONMENTS_PATH = Props
		.getFile("rlhd.environments-path", () -> path(EnvironmentManager.class, "environments.json"));

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private HdPlugin plugin;

	@Inject
	private HdPluginConfig config;

	@Inject
	private GamevalManager gamevalManager;

	private final Map<String, Integer> varbitConditionVars = new HashMap<>();
	private final Map<String, Integer> varpConditionVars = new HashMap<>();
	private final VariableSupplier varbitVariableSupplier = name -> {
		Integer id = varbitConditionVars.get(name);
		return id == null ? null : client.getVarbitValue(id);
	};
	private final VariableSupplier varpVariableSupplier = name -> {
		Integer id = varpConditionVars.get(name);
		return id == null ? null : client.getVarpValue(id);
	};

	private static final float TRANSITION_DURATION = 3; // seconds
	// distance in tiles to skip transition (e.g. entering cave, teleporting)
	// walking across a loading line causes a movement of 40-41 tiles
	private static final int SKIP_TRANSITION_DISTANCE = 41;

	// when the current transition began, relative to plugin startup
	private boolean transitionComplete = true;
	@Getter
	private float transitionProgress = 1;
	private double transitionStartTime = 0;
	@Getter
	private long transitionId;
	private int[] previousPosition = new int[3];

	private static final class State {
		// Mutable result consumed by renderers.
		final Environment current = Environment.DEFAULT.copy();
		// Snapshots at either end of the active transition.
		final Environment from = Environment.DEFAULT.copy();
		final Environment to = Environment.DEFAULT.copy();
		// Area-selected definition, before lighting fallbacks are applied to {@code to}.
		Environment target = Environment.NONE;
	}

	private final State state = new State();

	private boolean lightningEnabled = false;
	private boolean forceNextTransition = false;
	private boolean forceNextTransitionInstant;

	private Environment[] environments = {};
	private FileWatcher.UnregisterCallback fileWatcher;

	public void startUp() {
		fileWatcher = ENVIRONMENTS_PATH.watch((path, first) -> {
			try {
				var newEnvironments = loadEnvironments(path);
				clientThread.invoke(() -> {
					environments = newEnvironments;

					try (var gamevals = gamevalManager.obtainHandle()) {
						bindConditionVars(gamevals);
					}

					Environment.OVERWORLD = Environment.AUTUMN = Environment.WINTER = Environment.DEFAULT;
					for (var env : environments) {
						if (env.key == null)
							continue;
						switch (env.key) {
							case "OVERWORLD":
								Environment.OVERWORLD = env;
								break;
							case "AUTUMN":
								Environment.AUTUMN = env;
								break;
							case "WINTER":
								Environment.WINTER = env;
								break;
						}
					}

					// Force instant transition during development
					if (!first)
						reset();

					var ctx = plugin.getSceneContext();
					if (ctx != null && client.getGameState().getState() >= GameState.LOGGED_IN.getState())
						loadSceneEnvironments(ctx);
				});
			} catch (Exception ex) {
				log.error("Failed to load environments:", ex);
			}
		});
	}

	private Environment[] loadEnvironments(ResourcePath path) throws IOException {
		Environment[] loaded = path.loadJson(plugin.getGson(), Environment[].class);
		if (loaded == null)
			throw new IOException("Empty or invalid: " + path);

		boolean skipLegacyTob = !config.legacyTobEnvironment();
		boolean skipPohThemes = !config.pohThemeEnvironments();
		int count = 0;
		for (int i = 0; i < loaded.length; i++) {
			Environment env = loaded[i];
			try {
				if (env == null)
					throw new IllegalStateException("Expected an environment object");
				if (skipLegacyTob && env.isLegacyTob ||
					skipPohThemes && env.isPohTheme)
					continue;

				env.normalize();
				loaded[count++] = env;
			} catch (RuntimeException ex) {
				log.error("Ignoring invalid environment '{}' at {} index {}: {}", env, path, i, ex.getMessage());
			}
		}
		log.debug("Loaded {} environments", count);
		return Arrays.copyOf(loaded, count);
	}

	public void shutDown() {
		if (fileWatcher != null)
			fileWatcher.unregister();
		fileWatcher = null;
		environments = new Environment[0];
		reset();
	}

	public void reset() {
		state.target = Environment.NONE;
		forceNextTransition = false;
		forceNextTransitionInstant = false;
	}

	public void reload() {
		reload(true);
	}

	public void reloadAndSmoothlyTransition() {
		reload(false);
	}

	private void reload(boolean instantTransition) {
		var previous = state.target;
		shutDown();
		startUp();
		forceNextTransition = true;
		forceNextTransitionInstant = instantTransition;
		state.target = previous;
	}

	private void bindConditionVars(GamevalManager.Handle gamevals) {
		varbitConditionVars.clear();
		varpConditionVars.clear();
		int count = 0;
		for (int i = 0; i < environments.length; i++) {
			Environment env = environments[i];
			boolean valid = bindConditionVars(env.varbitCondition, gamevals.getVarbits(), varbitConditionVars, "varbit");
			valid &= bindConditionVars(env.varpCondition, gamevals.getVarps(), varpConditionVars, "varp");
			if (!valid) {
				log.error("Ignoring environment '{}' with unknown condition variable(s)", env);
				continue;
			}
			environments[count++] = env;
		}
		environments = Arrays.copyOf(environments, count);
	}

	private boolean bindConditionVars(
		ExpressionPredicate condition,
		Map<String, Integer> gamevals,
		Map<String, Integer> bindings,
		String kind
	) {
		if (!(condition instanceof ExpressionParser.SerializableExpressionPredicate))
			return true;
		var expr = ((ExpressionParser.SerializableExpressionPredicate) condition).expression;
		boolean valid = true;
		for (String name : expr.variables) {
			if (bindings.containsKey(name))
				continue;
			Integer id = gamevals.get(name.toUpperCase());
			if (id == null) {
				log.error("Unknown {} condition variable '{}'", kind, name, new Throwable());
				valid = false;
				continue;
			}
			bindings.put(name, id);
		}
		return valid;
	}

	private boolean isConditionSatisfied(Environment environment) {
		return
			environment.varbitCondition.test(varbitVariableSupplier) &&
			environment.varpCondition.test(varpVariableSupplier);
	}

	public void update(SceneContext sceneContext) {
		assert client.isClientThread();

		int[] focalPoint = sceneContext.localToWorld(
			plugin.cameraFocalPoint[0],
			plugin.cameraFocalPoint[1],
			client.getTopLevelWorldView().getPlane()
		);

		// skip the transitional fade if the player has moved too far
		// since the previous frame. results in an instant transition when
		// teleporting, entering dungeons, etc.
		int tileChange = (int) max(abs(subtract(vec(focalPoint), vec(previousPosition))));
		previousPosition = focalPoint;

		boolean skipTransition = tileChange >= SKIP_TRANSITION_DISTANCE;
		for (int i = 0; i < sceneContext.environments.size(); i++) {
			Environment environment = sceneContext.environments.get(i);
			if (!environment.area.containsPoint(focalPoint))
				continue;
			if (!isConditionSatisfied(environment))
				continue;
			changeEnvironment(environment, skipTransition);
			break;
		}

		// Update every frame, since other plugins may control it.
		updateTargetSkyColor(getResolvedTargetEnvironment());

		if (transitionComplete) {
			// Always write fog and water color, since they're affected by lightning
			copyTo(state.current.getFogColor(), state.to.getFogColor());
			copyTo(state.current.getWaterColor(), state.to.getWaterColor());
		} else {
			transitionProgress = smoothstep(0, 1, (float) (plugin.elapsedTime - transitionStartTime) / TRANSITION_DURATION);
			state.current.interpolate(state.from, state.to, transitionProgress);
			if (transitionProgress == 1)
				transitionComplete = true;
		}

		updateLightning();
	}

	private void changeEnvironment(Environment newEnvironment, boolean skipTransition) {
		// Skip changing the environment unless the transition is forced, since reapplying
		// the overworld environment is required when switching between seasonal themes
		if (state.target == newEnvironment && !forceNextTransition)
			return;

		if (state.target == Environment.NONE) {
			skipTransition = true;
		} else if (forceNextTransition) {
			skipTransition = forceNextTransitionInstant;
		}

		if (state.target.instantTransition || newEnvironment.instantTransition)
			skipTransition = true;

		// A fixed sky uses Default's clock rather than the configured cycle, so blending
		// between fixed and moving skies would also blend unrelated celestial motion.
		boolean oldHasFixedSun = state.target.getSky().sunAngles != null;
		boolean newHasFixedSun = newEnvironment.getSky().sunAngles != null;
		if (config.daylightCycle() != DaylightCycle.OFF && state.target != Environment.NONE &&
			oldHasFixedSun != newHasFixedSun)
			skipTransition = true;

		forceNextTransition = false;
		forceNextTransitionInstant = false;

		log.debug("changing environment from {} to {} (instant: {})", state.target, newEnvironment, skipTransition);
		state.target = newEnvironment;
		transitionId++;
		transitionComplete = false;
		transitionProgress = 0;
		transitionStartTime = plugin.elapsedTime - (skipTransition ? TRANSITION_DURATION : 0);

		state.current.copyTo(state.from);
		mod(state.from.getShadowAngles(), state.current.getShadowAngles(), TWO_PI);

		Environment areaEnvironment = getResolvedTargetEnvironment();
		Environment lightingEnvironment = areaEnvironment;
		if (config.disableEnvironmentalLighting() && !lightingEnvironment.force)
			lightingEnvironment = getOverworldEnvironment();
		lightingEnvironment.copyTo(state.to);
		state.to.fogDepth = areaEnvironment.fogDepth;
		state.to.groundFogStart = areaEnvironment.groundFogStart;
		state.to.groundFogEnd = areaEnvironment.groundFogEnd;
		state.to.groundFogOpacity = areaEnvironment.groundFogOpacity;
		lightningEnabled = areaEnvironment.lightningEffects;

		copyTo(state.to.getShadowAngles(), areaEnvironment.getShadowAngles());
		updateTargetSkyColor(areaEnvironment);

		// Prevent transitions from taking the long way around
		for (int i = 0; i < 2; i++) {
			float diff = state.from.getShadowAngles()[i] - state.to.getShadowAngles()[i];
			if (abs(diff) > PI)
				state.to.getShadowAngles()[i] += TWO_PI * sign(diff);
		}
	}

	private void updateTargetSkyColor(Environment env) {
		copyTo(state.to.getFogColor(), getFogColor(env));
		if (usesDefaultSkyColor(env)) {
			DefaultSkyColor sky = plugin.configDefaultSkyColor;
			if (sky == DefaultSkyColor.OSRS)
				sky = DefaultSkyColor.DEFAULT;
			copyTo(state.to.getWaterColor(), sky.getRgb(client));
		} else {
			copyTo(state.to.getWaterColor(), env.getFogColor());
		}

		// Override with decoupled water/sky color if present
		if (env.hasWaterColorOverride) {
			copyTo(state.to.getWaterColor(), env.getWaterColor());
		} else if (config.decoupleSkyAndWaterColor()) {
			copyTo(state.to.getWaterColor(), DefaultSkyColor.DEFAULT.getRgb(client));
		}
	}

	private boolean usesDefaultSkyColor(Environment env) {
		return !env.hasFogColorOverride || env.allowSkyOverride && plugin.configOverrideSky;
	}

	public float[] getFogColor(Environment env) {
		return usesDefaultSkyColor(env) ? plugin.configDefaultSkyColor.getRgb(client) : env.getFogColor();
	}

	public void loadSceneEnvironments(SceneContext sceneContext) {
		log.debug("Loading environments for scene: {}", sceneContext.sceneBounds);

		sceneContext.environments.clear();
		for (int i = 0; i < environments.length; i++) {
			Environment environment = environments[i];
			if (sceneContext.sceneBounds.intersects(environment.area.aabbs)) {
				log.debug("Added environment: {}", environment);
				sceneContext.environments.add(environment);
			}
		}

		// Fall back to the default environment
		sceneContext.environments.add(Environment.DEFAULT);
	}

	/* lightning */
	private static final float[] LIGHTNING_COLOR = { .25f, .25f, .25f };
	private static final float NEW_LIGHTNING_BRIGHTNESS = 7f;
	private static final float LIGHTNING_FADE_SPEED = 80f; // brightness units per second
	private static final float MIN_LIGHTNING_INTERVAL = 5.5f;
	private static final float MAX_LIGHTNING_INTERVAL = 17f;
	private static final float QUICK_LIGHTNING_CHANCE = .5f;
	private static final float MIN_QUICK_LIGHTNING_INTERVAL = .04f;
	private static final float MAX_QUICK_LIGHTNING_INTERVAL = .15f;

	@Getter
	private float lightningBrightness = 0f;
	private double nextLightningTime = -1;

	/**
	 * Updates lightning variables and sets water reflection and sky
	 * colors during lightning flashes.
	 */
	void updateLightning() {
		if (lightningBrightness > 0) {
			float brightnessChange = plugin.deltaTime * LIGHTNING_FADE_SPEED;
			lightningBrightness = max(lightningBrightness - brightnessChange, 0);
		}

		if (nextLightningTime == -1) {
			generateNextLightningTime();
			return;
		}
		if (plugin.elapsedTime > nextLightningTime) {
			lightningBrightness = NEW_LIGHTNING_BRIGHTNESS;
			generateNextLightningTime();
		}

		if (lightningEnabled && config.legacyLightning()) {
			applyLightning(state.current.getFogColor());
			applyLightning(state.current.getWaterColor());
		} else {
			lightningBrightness = 0f;
		}
	}

	public void applyLightning(float[] color) {
		if (lightningEnabled && config.legacyLightning())
			mix(color, color, LIGHTNING_COLOR, clamp(lightningBrightness, 0, 1));
	}

	/**
	 * Determines when the next lighting strike will occur.
	 * Produces a short interval for a quick successive strike
	 * or a longer interval at the end of a cluster.
	 */
	void generateNextLightningTime() {
		nextLightningTime = plugin.elapsedTime;
		if (Math.random() <= QUICK_LIGHTNING_CHANCE) {
			// chain together lighting strikes in quick succession
			nextLightningTime += mix(MIN_QUICK_LIGHTNING_INTERVAL, MAX_QUICK_LIGHTNING_INTERVAL, RAND.nextFloat());
		} else {
			// cool-down period before a new lightning cluster
			nextLightningTime += mix(MIN_LIGHTNING_INTERVAL, MAX_LIGHTNING_INTERVAL, RAND.nextFloat());
		}
	}

	private Environment getResolvedTargetEnvironment() {
		return state.target == Environment.OVERWORLD ? getOverworldEnvironment() : state.target;
	}

	/**
	 * Mutable, interpolated environment used for the current frame.
	 */
	public Environment getCurrentEnvironment() {
		return state.current;
	}

	/**
	 * Environment at the beginning of the current transition.
	 */
	Environment getFromEnvironment() {
		return state.from;
	}

	/**
	 * Resolved environment at the end of the current transition.
	 */
	Environment getToEnvironment() {
		return state.to;
	}

	/**
	 * Area-selected environment definition, before atmospheric-lighting fallbacks.
	 */
	public Environment getTargetEnvironment() {
		return state.target;
	}

	public Environment getOverworldEnvironment() {
		switch (plugin.configSeasonalTheme) {
			case AUTUMN:
				return Environment.AUTUMN;
			case WINTER:
				return Environment.WINTER;
			default:
				return Environment.OVERWORLD;
		}
	}

	@Nullable
	public Environment getEnvironmentAt(int[] worldPos) {
		for (int i = 0; i < environments.length; i++) {
			Environment env = environments[i];
			if (env.area.containsPoint(worldPos) && isConditionSatisfied(env))
				return env;
		}
		return null;
	}
}

package rs117.hd.scene;

import com.google.common.collect.Sets;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import rs117.hd.HdPlugin;
import rs117.hd.HdPluginConfig;
import rs117.hd.overlays.FrameTimer;
import rs117.hd.overlays.Timer;
import rs117.hd.scene.model_overrides.ModelOverride;

import static rs117.hd.utils.ColorUtils.hsl;
import static rs117.hd.utils.MathUtils.*;

public class FishingSpotReplacer {
	private static final int FISHING_SPOT_MODEL_ID = 41238;
	private static final int FISHING_SPOT_ANIMATION_ID = 10793;
	private static final int LAVA_SPOT_MODEL_ID = 2331;
	private static final int LAVA_SPOT_ANIMATION_ID = 525;
	private static final int LAVA_SPOT_COLOR = hsl("#837574");

	// @formatter:off
	private static final Set<Integer> FISHING_SPOT_IDS = Set.of(394, 635, 1506, 1507, 1508, 1509, 1510, 1511, 1512, 1513, 1514, 1515, 1516, 1517, 1518, 1519, 1520, 1521, 1522, 1523, 1524, 1525, 1526, 1527, 1528, 1529, 1530, 1531, 1532, 1533, 1534, 1535, 1536, 1542, 1544, 2146, 2653, 2654, 2655, 3317, 3417, 3418, 3419, 3657, 3913, 3914, 3915, 4079, 4080, 4081, 4082, 4316, 4476, 4477, 4710, 4711, 4712, 4713, 4714, 5233, 5234, 5820, 5821, 6731, 6825, 7155, 7199, 7200, 7323, 7459, 7460, 7461, 7462, 7463, 7464, 7465, 7466, 7467, 7468, 7469, 7470, 7946, 7947, 8524, 8525, 8526, 8527, 9171, 9172, 9173, 9174, 9478, 12267);
	private static final Set<Integer> LAVA_FISHING_SPOT_IDS = Set.of(4928);
	// @formatter:on
	private static final Set<Integer> NPC_IDS = Sets.union(FISHING_SPOT_IDS, LAVA_FISHING_SPOT_IDS).immutableCopy();

	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	@Inject
	private HdPlugin plugin;

	@Inject
	private HdPluginConfig config;

	@Inject
	private TileOverrideManager tileOverrideManager;

	@Inject
	private FrameTimer frameTimer;

	private final Map<Integer, RuneLiteObject> npcIndexToModel = new HashMap<>();

	public void startUp() {
		eventBus.register(this);
	}

	public void shutDown() {
		eventBus.unregister(this);
		despawnRuneLiteObjects();
	}

	public void despawnRuneLiteObjects() {
		for (var obj : npcIndexToModel.values())
			obj.setActive(false);
		npcIndexToModel.clear();
	}

	public ModelOverride getModelOverride() {
		ModelOverride override = new ModelOverride();
		override.hide = true;
		override.npcIds = NPC_IDS;
		return override;
	}

	public void update() {
		var sceneContext = plugin.getSceneContext();
		if (sceneContext == null)
			return;

		frameTimer.begin(Timer.REPLACE_FISHING_SPOTS);

		var worldView = client.getTopLevelWorldView();
		var npcs = worldView.npcs();
		var modelsToDespawn = new HashMap<>(npcIndexToModel);
		for (NPC npc : npcs) {
			if (!NPC_IDS.contains(npc.getId()))
				continue;

			var model = modelsToDespawn.remove(npc.getIndex());
			if (model == null) {
				// No fishing spot replacement associated with the NPC yet, so spawn one
				spawnFishingSpot(sceneContext, npc);
			} else {
				// Already associated with a fishing spot replacement, so let's update its position
				model.setLocation(npc.getLocalLocation(), worldView.getPlane());
			}
		}

		for (var entry : modelsToDespawn.entrySet()) {
			// Despawn the RuneLiteObject and stop tracking the index
			entry.getValue().setActive(false);
			npcIndexToModel.remove(entry.getKey());
		}

		frameTimer.end(Timer.REPLACE_FISHING_SPOTS);
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned npcSpawned) {
		var sceneContext = plugin.getSceneContext();
		var npc = npcSpawned.getNpc();
		if (sceneContext != null && NPC_IDS.contains(npc.getId()))
			spawnFishingSpot(sceneContext, npc);
	}

	public void spawnFishingSpot(SceneContext sceneContext, NPC npc) {
		if (npcIndexToModel.containsKey(npc.getIndex()))
			return;

		AnimationController animController;
		int modelId;
		int recolor = -1;
		if (LAVA_FISHING_SPOT_IDS.contains(npc.getId())) {
			animController = new AnimationController(client, LAVA_SPOT_ANIMATION_ID);
			modelId = LAVA_SPOT_MODEL_ID;
			recolor = LAVA_SPOT_COLOR;
		} else {
			animController = new AnimationController(client, FISHING_SPOT_ANIMATION_ID);
			modelId = FISHING_SPOT_MODEL_ID;
			var lp = npc.getLocalLocation();
			if (lp.isInScene()) {
				var worldView = client.getTopLevelWorldView();
				int plane = worldView.getPlane();
				Tile tile = worldView.getScene().getTiles()[plane][lp.getSceneX()][lp.getSceneY()];
				recolor = tileOverrideManager.getOverride(sceneContext, tile).waterType.fishingSpotRecolor;
			}
		}

		ModelData modelData = client.loadModelData(modelId);
		if (modelData == null)
			return;

		if (recolor != -1) {
			modelData = modelData.cloneColors();
			Arrays.fill(modelData.getFaceColors(), (short) recolor);
		}

		var anim = animController.getAnimation();
		if (anim != null)
			animController.setFrame(RAND.nextInt(anim.getDuration()));

		RuneLiteObject fishingSpot = client.createRuneLiteObject();
		fishingSpot.setAnimationController(animController);
		fishingSpot.setOrientation(RAND.nextInt(4) * 512);
		fishingSpot.setDrawFrontTilesFirst(false);
		fishingSpot.setActive(true);
		fishingSpot.setModel(modelData.light());
		npcIndexToModel.put(npc.getIndex(), fishingSpot);
	}
}

package rs117.hd.scene;

import com.google.gson.TypeAdapter;
import com.google.gson.reflect.TypeToken;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import rs117.hd.HdPlugin;
import rs117.hd.utils.FileWatcher;
import rs117.hd.utils.GsonUtils;
import rs117.hd.utils.Props;
import rs117.hd.utils.ResourcePath;

import static rs117.hd.utils.ResourcePath.path;

@Slf4j
@Singleton
public class GamevalManager {
	private static final ResourcePath GAMEVAL_PATH = Props
		.getFile("rlhd.gameval-path", () -> path(GamevalManager.class, "gamevals.json"));

	private static final String NPC_KEY = "npcs";
	private static final String OBJECT_KEY = "objects";
	private static final String ANIM_KEY = "anims";
	private static final String SPOTANIM_KEY = "spotanims";
	private static final String VARBIT_KEY = "varbits";
	private static final String VARP_KEY = "varps";

	@Inject
	private HdPlugin plugin;

	private FileWatcher.UnregisterCallback fileWatcher;

	private final HashSet<Handle> handles = new HashSet<>();
	private long clearTime = 0;

	private static boolean loaded = false;
	private static final Map<String, Map<String, Integer>> GAMEVALS = new HashMap<>();

	static {
		clearGamevals();
	}

	private static void clearGamevals() {
		GAMEVALS.put(NPC_KEY, Collections.emptyMap());
		GAMEVALS.put(OBJECT_KEY, Collections.emptyMap());
		GAMEVALS.put(ANIM_KEY, Collections.emptyMap());
		GAMEVALS.put(SPOTANIM_KEY, Collections.emptyMap());
		GAMEVALS.put(VARBIT_KEY, Collections.emptyMap());
		GAMEVALS.put(VARP_KEY, Collections.emptyMap());
		loaded = false;
	}

	public void startUp() throws IOException {
		fileWatcher = GAMEVAL_PATH.watch((path, first) -> loadGamevals());
	}

	public void update() {
		if (!loaded || clearTime == 0 || System.currentTimeMillis() < clearTime)
			return;

		log.debug("Clearing gameval mappings");
		clearGamevals();
		clearTime = 0;
	}

	private void loadGamevals() {
		try {
			Map<String, Map<String, Integer>> gamevals = plugin.getGson()
				.fromJson(GAMEVAL_PATH.toReader(), new TypeToken<Map<String, Map<String, Integer>>>() {}.getType());
			GAMEVALS.replaceAll((k, v) -> gamevals.getOrDefault(k, Collections.emptyMap()));
			loaded = true;
			log.debug("Loaded gameval mappings");
		} catch (IOException ex) {
			log.error("Failed to load gamevals:", ex);
		}
	}

	public Handle obtainHandle() {
		if (!loaded)
			loadGamevals();
		Handle handle = new Handle();
		handles.add(handle);
		clearTime = 0; // Clear the clearTime since we've requeued the handle
		return handle;
	}

	public void shutDown() {
		if (fileWatcher != null)
			fileWatcher.unregister();
		fileWatcher = null;
		clearGamevals();
	}

	private String getName(String key, int id) {
		if (!loaded)
			log.warn("Gamevals not loaded yet, will fail to resolve name.");

		return GAMEVALS
			.get(key)
			.entrySet()
			.stream()
			.filter(e -> e.getValue() == id)
			.map(Map.Entry::getKey)
			.findFirst()
			.orElse(null);
	}

	@Slf4j
	@RequiredArgsConstructor
	private abstract static class GamevalAdapter extends TypeAdapter<HashSet<Integer>> {
		private final String key;

		@Override
		public HashSet<Integer> read(JsonReader in) throws IOException {
			var map = GAMEVALS.get(key);
			HashSet<Integer> result = new HashSet<>();

			in.beginArray();
			while (in.hasNext()) {
				var type = in.peek();
				switch (type) {
					case NUMBER: {
						int id = in.nextInt();
						if (id != -1)
							log.debug("Adding raw {} ID: {} at {}. Should be replaced with a gameval.", key, id, GsonUtils.location(in));
						result.add(id);
						break;
					}
					case STRING:
						String name = in.nextString();
						Integer id = map.get(name);
						if (id == null) {
							String suggestion = "";
							for (var gamevalMapEntry : GAMEVALS.entrySet()) {
								if (gamevalMapEntry.getValue().get(name) != null) {
									suggestion = String.format(", did you mean to match %s?", gamevalMapEntry.getKey());
									break;
								}
							}
							log.error("Missing {} gameval: {}{} at {}", key, name, suggestion, GsonUtils.location(in), new Throwable());
						} else {
							result.add(id);
						}
						break;
					default:
						log.error("Unexpected {} gameval type: {} at {}", key, type, GsonUtils.location(in), new Throwable());
						break;
				}
			}
			in.endArray();

			return result;
		}

		@Override
		public void write(JsonWriter out, HashSet<Integer> ids) throws IOException {
			var remainingIds = new ArrayList<>(ids);
			var map = GAMEVALS.get(key);
			var names = map.entrySet().stream()
				.filter(e -> remainingIds.remove(e.getValue()))
				.map(Map.Entry::getKey)
				.sorted()
				.toArray(String[]::new);

			if (!remainingIds.isEmpty()) {
				remainingIds.sort(Integer::compareTo);
				log.warn(
					"Exporting IDs with no corresponding gamevals: {}", remainingIds.stream()
						.filter(i -> i != -1)
						.map(Object::toString)
						.collect(Collectors.joining(", "))
				);
			}

			out.beginArray();
			for (var id : remainingIds)
				out.value(id);
			for (var name : names)
				out.value(name);
			out.endArray();
