@Slf4j
@Singleton
public class ProceduralGenerator {
	public static final int[] DEPTH_LEVEL_SLOPE = new int[] { 150, 300, 470, 610, 700, 750, 820, 920, 1080, 1300, 1350, 1380 };
	public static final int MAX_DEPTH = DEPTH_LEVEL_SLOPE[DEPTH_LEVEL_SLOPE.length - 1];

	public static final int VERTICES_PER_FACE = 3;
	public static final boolean[][] TILE_OVERLAY_TRIS = new boolean[][]
		{
			/*  0 */ { true, true, true, true }, // Used by tile models of varying tri counts?
			/*  1 */ { false, true },
			/*  2 */ { false, false, true },
			/*  3 */ { false, false, true },
			/*  4 */ { false, true, true },
			/*  5 */ { false, true, true },
			/*  6 */ { false, false, true, true },
			/*  7 */ { false, false, false, true },
			/*  8 */ { false, true, true, true },
			/*  9 */ { false, false, false, true, true, true },
			/* 10 */ { true, true, true, false, false, false },
			/* 11 */ { true, true, false, false, false, false },
		};

	@Inject
	private TileOverrideManager tileOverrideManager;

	@Inject
	private WaterTypeManager waterTypeManager;

	private final ConcurrentPool<GeneratorContext> GENERATOR_POOL = new ConcurrentPool<>(GeneratorContext::new);

	final class GeneratorContext implements AutoCloseable {
		final MainTileOverridesGenerator mainTileOverridesGenerator = new MainTileOverridesGenerator();
		final TerrainDataGenerator terrainDataGenerator = new TerrainDataGenerator();
		final UnderwaterTerrainGenerator underwaterTerrainGenerator = new UnderwaterTerrainGenerator();
		final TerrainNormalGenerator terrainNormalGenerator = new TerrainNormalGenerator();

		@Override
		public void close() {
			GENERATOR_POOL.recycle(this);
		}
	}

	/**
	 * Gets the vertex keys of a Tile Paint tile for use in retrieving data from hashmaps.
	 * Writes the vertex keys in following order: SW, SE, NW, NE
	 *
	 * @param ctx that the tile is from
	 * @param tile to get the vertex keys of
	 */
	public static void tileVertexKeys(SceneContext ctx, Tile tile, int[][] tileVertices, int[] vertexHashes) {
		tileVertices(ctx, tile, tileVertices);

		vertexHashes[0] = tileVertexHash(tileVertices[0]);
		vertexHashes[1] = tileVertexHash(tileVertices[1]);
		vertexHashes[2] = tileVertexHash(tileVertices[2]);
		vertexHashes[3] = tileVertexHash(tileVertices[3]);
	}

	public void clearSceneData(SceneContext sceneContext) {
		sceneContext.tileFlags = null;
		sceneContext.vertexTerrainData = null;
		sceneContext.tileOverrideIndices = null;
		sceneContext.vertexTerrainTexture = null;
		sceneContext.vertexTerrainNormals = null;
	}

	public static void faceVertexKeys(Tile tile, int face, int[][] vertices, int[] vertexHashes) {
		faceVertices(tile, face, vertices);

		vertexHashes[0] = tileVertexHash(vertices[0]);
		vertexHashes[1] = tileVertexHash(vertices[1]);
		vertexHashes[2] = tileVertexHash(vertices[2]);
	}

	public static int[] faceVertexKeys(Tile tile, int face) {
		int[][] vertices = new int[3][3];
		int[] vertexHashes = new int[3];
		faceVertexKeys(tile, face, vertices, vertexHashes);
		return vertexHashes;
	}

	public void generateSceneData(SceneContext sceneCtx, SceneContext prevSceneCtx) {
		try (GeneratorContext ctx = GENERATOR_POOL.acquire()) {
			long timerTotal = System.currentTimeMillis();
			long timerCalculateMainOverrides, timerCalculateTerrainNormals, timerGenerateTerrainData, timerGenerateUnderwaterTerrain;

			long startTime = System.currentTimeMillis();
			ctx.mainTileOverridesGenerator.generate(sceneCtx, prevSceneCtx);
			timerCalculateMainOverrides = (int) (System.currentTimeMillis() - startTime);
			startTime = System.currentTimeMillis();
			ctx.underwaterTerrainGenerator.generate(sceneCtx, prevSceneCtx);
			timerGenerateUnderwaterTerrain = (int) (System.currentTimeMillis() - startTime);
			startTime = System.currentTimeMillis();
			ctx.terrainNormalGenerator.generate(sceneCtx, prevSceneCtx);
			timerCalculateTerrainNormals = (int) (System.currentTimeMillis() - startTime);
			startTime = System.currentTimeMillis();
			ctx.terrainDataGenerator.generate(sceneCtx, prevSceneCtx);
			timerGenerateTerrainData = (int) (System.currentTimeMillis() - startTime);

			log.debug("procedural data generation took {}ms to complete", (System.currentTimeMillis() - timerTotal));
			log.debug("-- calculateMainTileOverrides: {}ms", timerCalculateMainOverrides);
			log.debug("-- calculateTerrainNormals: {}ms", timerCalculateTerrainNormals);
			log.debug("-- generateTerrainData: {}ms", timerGenerateTerrainData);
			log.debug("-- generateUnderwaterTerrain: {}ms", timerGenerateUnderwaterTerrain);
		}
	}

	static class TerrainNormalGenerator {
		private final int[][] vertices = new int[4][3];
		private final int[] hashes = new int[4];

		private final int[] surfaceNormal = new int[3];

		private int[][][] faceVertices = new int[2][VERTICES_PER_FACE][3];
		private int[][] faceVertexKeys = new int[VERTICES_PER_FACE][3];
		private int[] vertexNormals;
		private int vertexNormalsPos = 0;

		/**
		 * Iterates through all Tiles in a given Scene, calculating vertex normals
		 * for each one, then stores resulting normal data in a HashMap.
		 */
		private void generate(SceneContext sceneContext, SceneContext prevSceneContext) {
			final Tile[][][] tiles = sceneContext.scene.getExtendedTiles();

			sceneContext.vertexTerrainNormalIndices = new Int2IntHashMap(
				prevSceneContext != null && prevSceneContext.vertexTerrainNormalIndices != null ?
					prevSceneContext.vertexTerrainNormalIndices.capacity() : 0);

			vertexNormals = PooledArrayType.INT.borrow(
				prevSceneContext != null && prevSceneContext.vertexTerrainNormals != null ?
					prevSceneContext.vertexTerrainNormals.length : 3000);
			vertexNormalsPos = 0;

			for (int z = 0; z < MAX_Z; z++) {
				final Tile[][] zTiles = tiles[z];
				for (int x = 0; x < sceneContext.sizeX; x++) {
					final Tile[] xTiles = zTiles[x];
					for (int y = 0; y < sceneContext.sizeZ; y++) {
						final Tile tile = xTiles[y];
						if (tile == null)
							continue;

						final boolean isBridge = tile.getBridge() != null;
						if (isBridge)
							calculateNormalsForTile(sceneContext, tile.getBridge(), false);
						calculateNormalsForTile(sceneContext, tile, isBridge);
					}
				}
			}

			sceneContext.vertexTerrainNormals = new short[vertexNormalsPos];
			for (int offset = 0; offset < vertexNormalsPos; offset += 3) {
				final float x = vertexNormals[offset];
				final float y = vertexNormals[offset + 1];
				final float z = vertexNormals[offset + 2];

				final float len = x * x + y * y + z * z;
				if (len == 0)
					continue;

				final float invLen = rcp(sqrt(len));
				sceneContext.vertexTerrainNormals[offset] = normShort(x * invLen);
				sceneContext.vertexTerrainNormals[offset + 1] = normShort(y * invLen);
				sceneContext.vertexTerrainNormals[offset + 2] = normShort(z * invLen);
			}

			PooledArrayType.INT.release(vertexNormals);
			vertexNormals = null;
		}

		/**
		 * Calculates vertex normals for a given Tile,
		 * then stores resulting normal data in a HashMap.
		 *
		 * @param sceneContext that the tile is associated with
		 * @param tile         to calculate normals for
		 * @param isBridge     whether the tile is a bridge tile, i.e. tile above
		 */
		private void calculateNormalsForTile(SceneContext sceneContext, Tile tile, boolean isBridge) {
			int faceCount = 2;
			final SceneTileModel tileModel = tile.getSceneTileModel();
			if (tileModel != null) {
				// Tile model
				faceCount = tileModel.getFaceX().length;
				if (faceVertices.length < faceCount) {
					faceVertices = new int[faceCount][VERTICES_PER_FACE][3];
					faceVertexKeys = new int[faceCount][VERTICES_PER_FACE];
				}

				for (int face = 0; face < faceCount; face++) {
					faceVertexKeys(tile, face, vertices, hashes);

					// Winding order: 0, 1, 2
					ivec3(faceVertices[face][0], vertices[0][0], vertices[0][1], vertices[0][2]);
					ivec3(faceVertices[face][1], vertices[1][0], vertices[1][1], vertices[1][2]);
					ivec3(faceVertices[face][2], vertices[2][0], vertices[2][1], vertices[2][2]);

					ivec3(faceVertexKeys[face], hashes[0], hashes[1], hashes[2]);
				}
			} else {
				tileVertexKeys(sceneContext, tile, vertices, hashes);

				// Winding order: ne, nw, se => 3, 2, 1
				ivec3(faceVertices[0][0], vertices[3][0], vertices[3][1], vertices[3][2]);
				ivec3(faceVertices[0][1], vertices[2][0], vertices[2][1], vertices[2][2]);
				ivec3(faceVertices[0][2], vertices[1][0], vertices[1][1], vertices[1][2]);

				// Winding order: sw, se, nw => 0, 1, 2
				ivec3(faceVertices[1][0], vertices[0][0], vertices[0][1], vertices[0][2]);
				ivec3(faceVertices[1][1], vertices[1][0], vertices[1][1], vertices[1][2]);
				ivec3(faceVertices[1][2], vertices[2][0], vertices[2][1], vertices[2][2]);

				ivec3(faceVertexKeys[0], hashes[3], hashes[1], hashes[2]);
				ivec3(faceVertexKeys[1], hashes[0], hashes[2], hashes[1]);
			}

			// Loop through tris to calculate and accumulate normals
			for (int face = 0; face < faceCount; face++) {
				// XYZ
				if (!isBridge) {
					faceVertices[face][0][1] += sceneContext.getVertexUnderwaterDepth(faceVertexKeys[face][0]);
					faceVertices[face][1][1] += sceneContext.getVertexUnderwaterDepth(faceVertexKeys[face][1]);
					faceVertices[face][2][1] += sceneContext.getVertexUnderwaterDepth(faceVertexKeys[face][2]);
				}

				calculateSurfaceNormals(surfaceNormal, faceVertices[face][0], faceVertices[face][1], faceVertices[face][2]);

				for (int vertex = 0; vertex < VERTICES_PER_FACE; vertex++) {
					final int vertexKey = faceVertexKeys[face][vertex];
					final int terrainNormalIdx = sceneContext.vertexTerrainNormalIndices.getOrDefault(vertexKey, -1);
					if (terrainNormalIdx == -1) {
						sceneContext.vertexTerrainNormalIndices.put(vertexKey, vertexNormalsPos / 3);

						if (vertexNormalsPos + 3 >= vertexNormals.length) {
							int[] newVertexNormals = PooledArrayType.INT.borrow(vertexNormalsPos * 2);
							System.arraycopy(vertexNormals, 0, newVertexNormals, 0, vertexNormalsPos);

							PooledArrayType.INT.release(vertexNormals);
							vertexNormals = newVertexNormals;
						}

						vertexNormals[vertexNormalsPos++] = surfaceNormal[0];
						vertexNormals[vertexNormalsPos++] = surfaceNormal[1];
						vertexNormals[vertexNormalsPos++] = surfaceNormal[2];
					} else {
						final int offset = terrainNormalIdx * 3;
						vertexNormals[offset] += surfaceNormal[0];
						vertexNormals[offset + 1] += surfaceNormal[1];
						vertexNormals[offset + 2] += surfaceNormal[2];
					}
				}
			}
		}
	}

	public boolean useDefaultColor(Tile tile, TileOverride override) {
		if ((tile.getSceneTilePaint() != null && tile.getSceneTilePaint().getTexture() >= 0) ||
			(tile.getSceneTileModel() != null && tile.getSceneTileModel().getTriangleTextureId() != null))
			return true; // skip tiles with textures provided by default

		if (override == TileOverride.NONE)
			return false;

		return !override.blended;
	}

	public WaterType seasonalWaterType(TileOverride override, int textureId) {
		var waterType = override.waterType;

		// As a fallback, always consider vanilla textured water tiles as water
		// We purposefully ignore material replacements here such as ice from the winter theme
		if (waterType == WaterType.NONE) {
			if (130 <= textureId && textureId <= 189 || textureId == 208) {
				// New sailing water textures
				waterType = waterTypeManager.getFallback(textureId);
			} else {
				switch (textureId) {
					case 1:
					case 24:
						waterType = WaterType.WATER; // This used to be WATER_FLAT, but for sailing we want translucent water
						break;
					case 25:
						waterType = WaterType.SWAMP_WATER_FLAT;
						break;
				}
			}
		}

		// Disable the winter theme ice
//		if (waterType == WaterType.WATER && plugin.configSeasonalTheme == SeasonalTheme.WINTER)
//			return WaterType.ICE;

		return waterType;
	}

	private static boolean[] getTileOverlayTris(int tileShapeIndex) {
		if (tileShapeIndex >= TILE_OVERLAY_TRIS.length) {
			log.debug("getTileOverlayTris(): unknown tileShapeIndex ({})", tileShapeIndex);
			return new boolean[10]; // false
		}

		return TILE_OVERLAY_TRIS[tileShapeIndex];
	}

	public static boolean isOverlayFace(Tile tile, int face) {
		int tileShapeIndex = tile.getSceneTileModel().getShape() - 1;
		if (face >= getTileOverlayTris(tileShapeIndex).length)
			return false;
		return getTileOverlayTris(tileShapeIndex)[face];
	}

	private static void tileVertices(SceneContext ctx, Tile tile, int[][] vertices) {
		final Point tileLocation = tile.getSceneLocation();
		final int tileX = tileLocation.getX();
		final int tileY = tileLocation.getY();
		final int tileExX = tileX + ctx.sceneOffset;
		final int tileExY = tileY + ctx.sceneOffset;
		final int[][] tileHeights = ctx.scene.getTileHeights()[tile.getRenderLevel()];

		// Winding order:
		// ne, nw, se => 3, 2, 1
		// sw, se, nw => 0, 1, 2

		// South-west
		ivec3(
			vertices[0],
			tileX * LOCAL_TILE_SIZE,
			tileHeights[tileExX][tileExY],
			tileY * LOCAL_TILE_SIZE
		);

		// South-east
		ivec3(
			vertices[1],
			(tileX + 1) * LOCAL_TILE_SIZE,
			tileHeights[tileExX + 1][tileExY],
			tileY * LOCAL_TILE_SIZE
		);

		// North-west
		ivec3(
			vertices[2],
			tileX * LOCAL_TILE_SIZE,
			tileHeights[tileExX][tileExY + 1],
			(tileY + 1) * LOCAL_TILE_SIZE
		);

		// North-east
		ivec3(
			vertices[3],
			(tileX + 1) * LOCAL_TILE_SIZE,
			tileHeights[tileExX + 1][tileExY + 1],
			(tileY + 1) * LOCAL_TILE_SIZE
		);
	}

	private static void faceVertices(Tile tile, int face, int[][] vertices) {
		SceneTileModel sceneTileModel = tile.getSceneTileModel();

		final int[] vertexX = sceneTileModel.getVertexX();
		final int[] vertexY = sceneTileModel.getVertexY();
		final int[] vertexZ = sceneTileModel.getVertexZ();

		final int vertexFacesA = sceneTileModel.getFaceX()[face];
		final int vertexFacesB = sceneTileModel.getFaceY()[face];
		final int vertexFacesC = sceneTileModel.getFaceZ()[face];

		ivec3(
			vertices[0],
			vertexX[vertexFacesA],
			vertexY[vertexFacesA],
			vertexZ[vertexFacesA]
		);

		ivec3(
			vertices[1],
			vertexX[vertexFacesB],
			vertexY[vertexFacesB],
			vertexZ[vertexFacesB]
		);

		ivec3(
			vertices[2],
			vertexX[vertexFacesC],
			vertexY[vertexFacesC],
			vertexZ[vertexFacesC]
		);
	}

	/**
	 * Returns vertex positions in local coordinates, between 0 and 128, inclusive.
	 */
	public static void faceLocalVertices(Tile tile, int face, int[][] vertices) {
		if (tile.getSceneTileModel() == null) {
			for (int i = 0; i < vertices.length; i++)
				Arrays.fill(vertices[i], 0);
			return;
		}

		int x = tile.getSceneLocation().getX();
		int y = tile.getSceneLocation().getY();
		int baseX = x * LOCAL_TILE_SIZE;
		int baseY = y * LOCAL_TILE_SIZE;

		faceVertices(tile, face, vertices);
		for (int i = 0; i < vertices.length; i++) {
			vertices[i][0] -= baseX;
			vertices[i][2] -= baseY;
		}
	}

	public static void tileVertexKeys(SceneContext ctx, Tile tile, int[] vertexHashes) {
		int[][] vertices = new int[4][3];
		tileVertexKeys(ctx, tile, vertices, vertexHashes);
	}

	public static int[] tileVertexKeys(SceneContext ctx, Tile tile) {
		int[] vertexHashes = new int[4];
		tileVertexKeys(ctx, tile, vertexHashes);
		return vertexHashes;
	}

	final class MainTileOverridesGenerator {
		private static final int SCENE_EDGE_PADDING = 1;

		private final TileOverride[] overrides = new TileOverride[TILE_OVERRIDE_COUNT];
		private final int[] worldPos = new int[3];
		private final int[] ids = new int[2];

		private void generate(SceneContext sceneContext, SceneContext preSceneCtx) {
			final boolean canReuseScene =
				preSceneCtx != null &&
				sceneContext.scene.isInstance() == preSceneCtx.scene.isInstance() &&
				sceneContext.currentArea == preSceneCtx.currentArea;
			final Tile[][][] prevTiles = canReuseScene ? preSceneCtx.scene.getExtendedTiles() : null;

			final Tile[][][] tiles = sceneContext.scene.getExtendedTiles();
			final short[][][] overlayIds = sceneContext.scene.getOverlayIds();
			final short[][][] underlayIds = sceneContext.scene.getUnderlayIds();

			final int dX = canReuseScene ? (sceneContext.scene.getBaseX() - preSceneCtx.scene.getBaseX() >> 3) << 3 : 0;
			final int dY = canReuseScene ? (sceneContext.scene.getBaseY() - preSceneCtx.scene.getBaseY() >> 3) << 3 : 0;

			sceneContext.tileOverrideIndices = new char[MAX_Z * sceneContext.sizeX * sceneContext.sizeZ * 3];

			for (int z = 0; z < MAX_Z; ++z) {
				final Tile[][] prevZTiles = canReuseScene ? prevTiles[z] : null;
				final Tile[][] zTiles = tiles[z];
				for (int x = 0; x < sceneContext.sizeX; ++x) {
					final Tile[] prevXTiles = canReuseScene ? prevZTiles[z] : null;
					final Tile[] xTiles = zTiles[x];
					for (int y = 0; y < sceneContext.sizeZ; ++y) {
						final Tile tile = xTiles[y];
						if (tile == null)
							continue;

						final int oX = x + dX;
						final int oY = y + dY;
						final boolean canReuseTile =
							canReuseScene &&
							oX >= SCENE_EDGE_PADDING && oX < sceneContext.sizeX - SCENE_EDGE_PADDING &&
							oY >= SCENE_EDGE_PADDING && oY < sceneContext.sizeZ - SCENE_EDGE_PADDING &&
							prevXTiles[oY] != null;

						int tileZ = tile.getRenderLevel();
						ids[0] = OVERLAY_FLAG | overlayIds[tileZ][x][y];
						ids[1] = underlayIds[tileZ][x][y];
						calculateTileOverride(sceneContext, canReuseTile ? preSceneCtx : null, tile, tileZ, x, y, oX, oY);

						final Tile bridge = tile.getBridge();
						if (bridge != null) {
							tileZ = bridge.getRenderLevel();
							ids[0] = OVERLAY_FLAG | overlayIds[tileZ][x][y];
							ids[1] = underlayIds[tileZ][x][y];
							calculateTileOverride(sceneContext, canReuseTile ? preSceneCtx : null, bridge, tileZ, x, y, oX, oY);
						}
					}
				}
			}
		}

		private void calculateTileOverride(
			SceneContext sceneContext,
			SceneContext prevSceneContext,
			Tile tile,
			int tileZ,
			int tileExX,
			int tileExY,
			int prevTileExX,
			int prevTileExY
		) {
			if (prevSceneContext != null && prevSceneContext.getTileOverrides(tileZ, prevTileExX, prevTileExY, overrides)) {
				sceneContext.setTileOverride(tileZ, tileExX, tileExY, overrides);
				return;
			}

			sceneContext.extendedSceneToWorld(tileExX, tileExY, tileZ, worldPos);

			overrides[0] = tileOverrideManager.getOverride(sceneContext, tile, worldPos, ids);
			overrides[1] = tileOverrideManager.getOverride(sceneContext, tile, worldPos, ids[1]);
			overrides[2] = tileOverrideManager.getOverride(sceneContext, tile, worldPos, ids[0]);

			sceneContext.setTileOverride(tileZ, tileExX, tileExY, overrides);
		}
	}

	final class TerrainDataGenerator {
		private final int[][] vertices = new int[4][3];
		private final int[] hashes = new int[4];
		private final int[] worldPos = new int[3];
		private final short[] vNormals = new short[3];

		private int[] vertexHashes;
		private int[] vertexColors;
		private TileOverride[] vertexOverrides;
		private boolean[] vertexIsOverlay;
		private boolean[] vertexDefaultColor;

		/**
		 * Iterates through all Tiles in a given Scene, producing color and
		 * material data for each vertex of each Tile. Then adds the resulting
		 * data to appropriate HashMaps.
		 */
		private void generate(SceneContext sceneContext, SceneContext prevSceneCtx) {
			sceneContext.vertexTerrainColor = new Int2IntHashMap(prevSceneCtx != null && prevSceneCtx.vertexTerrainColor != null ? prevSceneCtx.vertexTerrainColor.capacity() : 0);
			sceneContext.vertexTerrainTexture = new Int2ObjectHashMap<>(prevSceneCtx != null && prevSceneCtx.vertexTerrainTexture != null ? prevSceneCtx.vertexTerrainTexture.capacity() : 0);

			final Tile[][][] tiles = sceneContext.scene.getExtendedTiles();
			for (int z = 0; z < MAX_Z; ++z) {
				final Tile[][] zTiles = tiles[z];
				for (int x = 0; x < sceneContext.sizeX; ++x) {
					final Tile[] xTiles = zTiles[x];
					for (int y = 0; y < sceneContext.sizeZ; ++y) {
						final var tile = xTiles[y];
						if (tile == null)
							continue;

						generateDataForTile(sceneContext, tile, x, y, z);

						final var bridge = tile.getBridge();
						if (bridge != null)
							generateDataForTile(sceneContext, bridge, x, y, z);
					}
				}
			}
		}

		/**
		 * Produces color and material data for the vertices of the provided Tile.
		 * Then adds the resulting data to appropriate HashMaps.
		 *
		 * @param sceneContext that the tile is associated with
		 * @param tile         to generate terrain data for
		 */
		private void generateDataForTile(SceneContext sceneContext, Tile tile, int tileExX, int tileExY, int plane) {
			int faceCount;
			final SceneTilePaint tilePaint = tile.getSceneTilePaint();
			final SceneTileModel tileModel = tilePaint == null ? tile.getSceneTileModel() : null;
			if (tilePaint != null) {
				faceCount = 2;
			} else if (tileModel != null) {
				faceCount = tileModel.getFaceX().length;
			} else {
				return;
			}

			final int tileX = tileExX - sceneContext.sceneOffset;
			final int tileY = tileExY - sceneContext.sceneOffset;
			final int tileZ = tile.getRenderLevel();
			sceneContext.sceneToWorld(tileX, tileY, tileZ, worldPos);

			vertexHashes = ensureCapacity(vertexHashes, faceCount * VERTICES_PER_FACE);
			vertexColors = ensureCapacity(vertexColors, faceCount * VERTICES_PER_FACE);
			vertexOverrides = ensureCapacity(vertexOverrides, faceCount * VERTICES_PER_FACE, TileOverride[]::new);
			vertexIsOverlay = ensureCapacity(vertexIsOverlay, faceCount * VERTICES_PER_FACE);
			vertexDefaultColor = ensureCapacity(vertexDefaultColor, faceCount * VERTICES_PER_FACE);

			Arrays.fill(vertexHashes, 0, faceCount * VERTICES_PER_FACE, 0);
			Arrays.fill(vertexColors, 0, faceCount * VERTICES_PER_FACE, 0);
			Arrays.fill(vertexOverrides, 0, faceCount * VERTICES_PER_FACE, null);
			Arrays.fill(vertexIsOverlay, 0, faceCount * VERTICES_PER_FACE, false);
			Arrays.fill(vertexDefaultColor, 0, faceCount * VERTICES_PER_FACE, false);

			if (tilePaint != null) {
				var override = sceneContext.getTileOverride(tileZ, tileExX, tileExY, TILE_OVERRIDE_MAIN);
				if (override.waterType != WaterType.NONE) {
					// skip water tiles
					return;
				}

				int swColor = tilePaint.getSwColor();
				int seColor = tilePaint.getSeColor();
				int nwColor = tilePaint.getNwColor();
				int neColor = tilePaint.getNeColor();

				tileVertexKeys(sceneContext, tile, vertices, vertexHashes);

				if (tileExX >= EXTENDED_SCENE_SIZE - 2 && tileExY >= EXTENDED_SCENE_SIZE - 2) {
					// reduce the black scene edges by assigning surrounding colors
					neColor = swColor;
					nwColor = swColor;
					seColor = swColor;
				} else if (tileExY >= EXTENDED_SCENE_SIZE - 2) {
					nwColor = swColor;
					neColor = seColor;
				} else if (tileExX >= EXTENDED_SCENE_SIZE - 2) {
					neColor = nwColor;
					seColor = swColor;
				}

				vertexColors[0] = swColor;
				vertexColors[1] = seColor;
				vertexColors[2] = nwColor;
				vertexColors[3] = neColor;

				final boolean useDefaultColor = useDefaultColor(tile, override);
				for (int i = 0; i < 4; i++) {
					vertexOverrides[i] = override;
					vertexIsOverlay[i] = override.queriedAsOverlay;
					if (useDefaultColor)
						vertexDefaultColor[i] = true;
				}
			} else {
				final int[] faceColorsA = tileModel.getTriangleColorA();
				final int[] faceColorsB = tileModel.getTriangleColorB();
				final int[] faceColorsC = tileModel.getTriangleColorC();

				var overlayOverride = sceneContext.getTileOverride(tileZ, tileExX, tileExY, TILE_OVERRIDE_OVERLAY);
				var underlayOverride = sceneContext.getTileOverride(tileZ, tileExX, tileExY, TILE_OVERRIDE_UNDERLAY);

				for (int face = 0; face < faceCount; face++) {
					faceVertexKeys(tile, face, vertices, hashes);

					for (int vertex = 0; vertex < VERTICES_PER_FACE; vertex++) {
						final boolean isOverlay = isOverlayFace(tile, face);
						final var override = isOverlay ? overlayOverride : underlayOverride;
						if (override.waterType != WaterType.NONE)
							continue; // skip water faces

						final int base = face * VERTICES_PER_FACE + vertex;

						vertexHashes[base] = hashes[vertex];
						vertexColors[base] = (vertex == 0 ? faceColorsA : vertex == 1 ? faceColorsB : faceColorsC)[face];

						vertexOverrides[base] = override;
						vertexIsOverlay[base] = isOverlay;

						if (isOverlay && useDefaultColor(tile, override))
							vertexDefaultColor[base] = true;
					}
				}
			}

			final int vertexCount = faceCount * VERTICES_PER_FACE;
			for (int vertex = 0; vertex < vertexCount; vertex++) {
				if (vertexHashes[vertex] == 0)
					continue;

				int color = vertexColors[vertex];
				var override = vertexOverrides[vertex];
				if (color < 0 || color == HIDDEN_HSL && !override.forced)
					continue;

				// if this vertex already has a 'high priority' color assigned,
				// skip assigning a 'low priority' color unless there is no color assigned.
				// Near-solid-black tiles that are used in some places under wall objects
				boolean lowPriorityColor = vertexColors[vertex] <= 2;

				float lightenMultiplier = 1.5f;
				int lightenBase = 15;
				int lightenAdd = 3;
				float darkenMultiplier = 0.5f;

				float dot = 0;
				final int key = vertexHashes[vertex];
				if (sceneContext.getVertexNormal(key, vNormals) == null) {
					vNormals[0] = vNormals[1] = vNormals[2] = 0;
				} else {
					dot = dot(vNormals);
					if (dot >= EPSILON) {
						// Approximately reverse vanilla tile lighting
						dot = (vNormals[0] + vNormals[2]) / sqrt(2 * dot);
					}
				}

				int lightness = color & 0x7F;

				float lightFactor = Math.max(dot, 0f);
				int adjustedLight = (int) (Math.max(lightness - lightenAdd, 0) * lightenMultiplier + lightenBase);
				lightness = (int) mix(lightness, adjustedLight, lightFactor);

				float darkFactor = -Math.min(dot, 0f);
				int darkened = (int) (lightness * darkenMultiplier);
				lightness = (int) (1.25f * mix(lightness, darkened, darkFactor));

				lightness = Math.min(lightness, 55); // reduces overexposure
				color = (color & ~0x7F) | lightness;

				color = override.modifyColor(color);

				final Material material = override.groundMaterial.getRandomMaterial(worldPos);
				final boolean isOverlay = vertexIsOverlay[vertex] != override.blendedAsOpposite;

				// mark the vertex as either an overlay or underlay.
				// this is used to determine how to blend between vertex colors
				sceneContext.setVertexIsOverlay(key, isOverlay);

				// add color and texture to hashmap
				if ((!lowPriorityColor || !sceneContext.isVertexHighPriorityColor(key)) && !vertexDefaultColor[vertex]) {
					boolean shouldWrite = isOverlay || !sceneContext.vertexTerrainColor.containsKey(key);

					if (shouldWrite) {
						sceneContext.vertexTerrainColor.put(key, color);
						sceneContext.vertexTerrainTexture.put(key, material);
					} else {
						sceneContext.vertexTerrainColor.putIfAbsent(key, color);
						sceneContext.vertexTerrainTexture.putIfAbsent(key, material);
					}

					if (!lowPriorityColor)
						sceneContext.setVertexHighPriorityColor(key);
				}
			}
		}
	}

	final class UnderwaterTerrainGenerator {
		private final int[][] vertices = new int[4][3];
		private final int[] hashes = new int[4];

		private final byte[][][] underwaterDepthLevels = new byte[MAX_Z][EXTENDED_SCENE_SIZE + 1][EXTENDED_SCENE_SIZE + 1];

		// Defines ranges of water tiles
		private final int[] minX = new int[MAX_Z];
		private final int[] maxX = new int[MAX_Z];
		private final int[] minY = new int[MAX_Z];
		private final int[] maxY = new int[MAX_Z];

		/**
		 * Generates underwater terrain data by iterating through all Tiles in a given
		 * Scene, increasing the depth of each tile based on its distance from the shore.
		 * Then stores the resulting data in a HashMap.
		 */
		private void generate(SceneContext sceneContext, SceneContext prevSceneCtx) {
			final Tile[][][] tiles = sceneContext.scene.getExtendedTiles();
			final int sizeX = sceneContext.sizeX;
			final int sizeY = sceneContext.sizeZ;
			// bit 1 set if a tile contains at least 1 face which qualifies as water
			// bit 2 set if a tile will be skipped when the scene is drawn,
			// 	this is due to certain edge cases with water on the same X/Y on different planes
			sceneContext.tileFlags = new byte[MAX_Z * sizeX * sizeY];
			sceneContext.vertexTerrainData = new Int2IntHashMap(
				prevSceneCtx != null && prevSceneCtx.vertexTerrainData != null ?
					prevSceneCtx.vertexTerrainData.capacity() : 0);
			// the world-space height offsets of each vertex on the tile grid
			// these offsets are interpolated to calculate offsets for vertices not on the grid (tile models)

			for (int z = 0; z < MAX_Z; ++z) {
				for (int x = 0; x < sizeX; ++x) {
					// set the array to 1 initially
					// this assumes that all vertices are water;
					// we will set non-water vertices to 0 in the next loop
					Arrays.fill(underwaterDepthLevels[z][x], (byte) 1);
				}
			}

			int minZ = MAX_Z, maxZ = 0;
			Arrays.fill(minX, sizeX);
			Arrays.fill(minY, sizeY);
			Arrays.fill(maxX, 0);
			Arrays.fill(maxY, 0);

			// figure out which vertices are water and assign some data
			for (int z = 0; z < MAX_Z; ++z) {
				final Tile[][] zTiles = tiles[z];
				final byte[][] zUnderwaterDepthLevels = underwaterDepthLevels[z];
				for (int x = 0; x < sizeX; ++x) {
					final Tile[] xTiles = zTiles[x];
					for (int y = 0; y < sizeY; ++y) {
						Tile tile = xTiles[y];
						if (tile == null) {
							zUnderwaterDepthLevels[x][y] = 0;
							zUnderwaterDepthLevels[x + 1][y] = 0;
							zUnderwaterDepthLevels[x][y + 1] = 0;
							zUnderwaterDepthLevels[x + 1][y + 1] = 0;
							continue;
						}

						if (tile.getBridge() != null)
							tile = tile.getBridge();

						final int tileZ = tile.getRenderLevel();
						final SceneTilePaint tilePaint = tile.getSceneTilePaint();
						final SceneTileModel tileModel = tilePaint == null ? tile.getSceneTileModel() : null;

						if (tilePaint != null) {
							tileVertexKeys(sceneContext, tile, vertices, hashes);

							var override = sceneContext.getTileOverride(tileZ, x, y, TILE_OVERRIDE_MAIN);
							if (seasonalWaterType(override, tilePaint.getTexture()) == WaterType.NONE) {
								for (int i = 0; i < hashes.length; i++)
									if (tilePaint.getNeColor() != HIDDEN_HSL || override.forced)
										sceneContext.setVertexIsLand(hashes[i]);

								zUnderwaterDepthLevels[x][y] = 0;
								zUnderwaterDepthLevels[x + 1][y] = 0;
								zUnderwaterDepthLevels[x][y + 1] = 0;
								zUnderwaterDepthLevels[x + 1][y + 1] = 0;
							} else {
								// Stop tiles on the same X,Y coordinates on different planes from
								// each generating water. Prevents undesirable results in certain places.
								if (z > 0) {
									boolean continueLoop = false;

									for (int checkZ = 0; checkZ < z; ++checkZ) {
										if (sceneContext.isTileFlagSet(checkZ, x, y, TILE_WATER_FLAG)) {
											zUnderwaterDepthLevels[x][y] = 0;
											zUnderwaterDepthLevels[x + 1][y] = 0;
											zUnderwaterDepthLevels[x][y + 1] = 0;
											zUnderwaterDepthLevels[x + 1][y + 1] = 0;

											sceneContext.setTileFlag(z, x, y, TILE_SKIP_FLAG);

											continueLoop = true;

											break;
										}
									}

									if (continueLoop)
										continue;
								}

								sceneContext.setTileFlag(z, x, y, TILE_WATER_FLAG);
								maxZ = max(maxZ, z);
								minZ = min(minZ, z);
								minX[z] = min(minX[z], x);
								maxX[z] = max(maxX[z], x);
								minY[z] = min(minY[z], y);
								maxY[z] = max(maxY[z], y);

								for (int i = 0; i < hashes.length; i++)
									sceneContext.setVertexIsWater(hashes[i]);
							}
						} else if (tileModel != null) {
							int faceCount = tileModel.getFaceX().length;

							var overlayOverride = sceneContext.getTileOverride(tileZ, x, y, TILE_OVERRIDE_OVERLAY);
							var underlayOverride = sceneContext.getTileOverride(tileZ, x, y, TILE_OVERRIDE_UNDERLAY);

							// Stop tiles on the same X,Y coordinates on different planes from
							// each generating water. Prevents undesirable results in certain places.
							if (z > 0) {
								boolean tileIncludesWater = false;
								for (int face = 0; face < faceCount; face++) {
									var override = ProceduralGenerator.isOverlayFace(tile, face) ? overlayOverride : underlayOverride;
									int textureId = tileModel.getTriangleTextureId() == null ? -1 :
										tileModel.getTriangleTextureId()[face];
									if (seasonalWaterType(override, textureId) != WaterType.NONE) {
										tileIncludesWater = true;
										break;
									}
								}

								if (tileIncludesWater) {
									boolean continueLoop = false;

									for (int checkZ = 0; checkZ < z; ++checkZ) {
										if (sceneContext.isTileFlagSet(checkZ, x, y, TILE_WATER_FLAG)) {
											zUnderwaterDepthLevels[x][y] = 0;
											zUnderwaterDepthLevels[x + 1][y] = 0;
											zUnderwaterDepthLevels[x][y + 1] = 0;
											zUnderwaterDepthLevels[x + 1][y + 1] = 0;

											sceneContext.setTileFlag(z, x, y, TILE_SKIP_FLAG);

											continueLoop = true;

											break;
										}
									}

									if (continueLoop)
										continue;
								}
							}

							for (int face = 0; face < faceCount; face++) {
								faceVertexKeys(tile, face, vertices, hashes);

								var override = ProceduralGenerator.isOverlayFace(tile, face) ? overlayOverride : underlayOverride;
								int textureId = tileModel.getTriangleTextureId() == null ? -1 :
									tileModel.getTriangleTextureId()[face];
								if (seasonalWaterType(override, textureId) == WaterType.NONE) {
									for (int vertex = 0; vertex < VERTICES_PER_FACE; vertex++) {
										if (tileModel.getTriangleColorA()[face] != HIDDEN_HSL || override.forced)
											sceneContext.setVertexIsLand(hashes[vertex]);

										if (vertices[vertex][0] % LOCAL_TILE_SIZE == 0 && vertices[vertex][2] % LOCAL_TILE_SIZE == 0) {
											int vX = (vertices[vertex][0] >> LOCAL_COORD_BITS) + sceneContext.sceneOffset;
											int vY = (vertices[vertex][2] >> LOCAL_COORD_BITS) + sceneContext.sceneOffset;

											zUnderwaterDepthLevels[vX][vY] = 0;
										}
									}
								} else {
									sceneContext.setTileFlag(z, x, y, TILE_WATER_FLAG);
									minZ = min(minZ, z);
									maxZ = max(maxZ, z);
									minX[z] = min(minX[z], x);
									maxX[z] = max(maxX[z], x);
									minY[z] = min(minY[z], y);
									maxY[z] = max(maxY[z], y);

									for (int vertex = 0; vertex < VERTICES_PER_FACE; vertex++)
										sceneContext.setVertexIsWater(hashes[vertex]);
								}
							}
						} else {
							zUnderwaterDepthLevels[x][y] = 0;
							zUnderwaterDepthLevels[x + 1][y] = 0;
							zUnderwaterDepthLevels[x][y + 1] = 0;
							zUnderwaterDepthLevels[x + 1][y + 1] = 0;
						}
					}
				}
			}

			// Sink terrain further from shore by desired levels.
			// noinspection ConstantValue
			assert DEPTH_LEVEL_SLOPE.length <= Byte.MAX_VALUE;
			for (int level = 0; level < DEPTH_LEVEL_SLOPE.length - 1; level++) {
				for (int z = minZ; z <= maxZ; ++z) {
					final byte[][] zUnderwaterDepthLevels = underwaterDepthLevels[z];
					for (int x = minX[z]; x <= maxX[z]; x++) {
						for (int y = minY[z]; y <= maxY[z]; y++) {
							int tileHeight = zUnderwaterDepthLevels[x][y];
							if (tileHeight == 0)
								continue; // Skip the tile if it isn't water.

							// If it's on the edge of the scene, reset the depth so
							// it creates a 'wall' to prevent fog from passing through.
							// Not incredibly effective, but better than nothing.
							if (x == 0 || y == 0 || x == EXTENDED_SCENE_SIZE || y == EXTENDED_SCENE_SIZE) {
								zUnderwaterDepthLevels[x][y] = 0;
								continue;
							}

							if (zUnderwaterDepthLevels[x - 1][y] < tileHeight ||
								zUnderwaterDepthLevels[x][y - 1] < tileHeight ||
								x < zUnderwaterDepthLevels.length - 1 && zUnderwaterDepthLevels[x + 1][y] < tileHeight ||
								y < zUnderwaterDepthLevels.length - 1 && zUnderwaterDepthLevels[x][y + 1] < tileHeight)
								continue;

							// At this point, it's surrounded only by other depth-adjusted vertices.
							zUnderwaterDepthLevels[x][y]++;
						}
					}
				}
			}

			// Store the height offsets in a hashmap and calculate interpolated
			// height offsets for non-corner vertices.
			for (int z = minZ; z <= maxZ; ++z) {
				final Tile[][] zTiles = tiles[z];
				for (int x = minX[z]; x <= maxX[z]; x++) {
					final Tile[] xTiles = zTiles[x];
					for (int y = minY[z]; y <= maxY[z]; y++) {
						Tile tile = xTiles[y];
						if (tile == null)
							continue;

						if (!sceneContext.isTileFlagSet(z, x, y, TILE_WATER_FLAG))
							continue;

						if (tile.getBridge() != null)
							tile = tile.getBridge();

						if (tile.getSceneTilePaint() != null) {
							tileVertexKeys(sceneContext, tile, vertices, hashes);

							final int swVertex = getHeightOffset(z, x, y);
							final int seVertex = getHeightOffset(z, x + 1, y);
							final int nwVertex = getHeightOffset(z, x, y + 1);
							final int neVertex = getHeightOffset(z, x + 1, y + 1);

							sceneContext.setVertexUnderwaterDepth(hashes[0], swVertex);
							sceneContext.setVertexUnderwaterDepth(hashes[1], seVertex);
							sceneContext.setVertexUnderwaterDepth(hashes[2], nwVertex);
							sceneContext.setVertexUnderwaterDepth(hashes[3], neVertex);
						} else if (tile.getSceneTileModel() != null) {
							SceneTileModel sceneTileModel = tile.getSceneTileModel();

							int faceCount = sceneTileModel.getFaceX().length;

							for (int face = 0; face < faceCount; face++) {
								faceVertexKeys(tile, face, vertices, hashes);

								for (int vertex = 0; vertex < VERTICES_PER_FACE; vertex++) {
									if (vertices[vertex][0] % LOCAL_TILE_SIZE == 0 && vertices[vertex][2] % LOCAL_TILE_SIZE == 0) {
										// The vertex is at the corner of the tile;
										// simply use the offset in the tile grid array.

										int vX = (vertices[vertex][0] >> LOCAL_COORD_BITS) + sceneContext.sceneOffset;
										int vY = (vertices[vertex][2] >> LOCAL_COORD_BITS) + sceneContext.sceneOffset;

										int height = getHeightOffset(z, vX, vY);
										sceneContext.setVertexUnderwaterDepth(hashes[vertex], height);
									} else {
										// If the tile is a tile model and this vertex is shared only by faces that are water,
										// interpolate between the height offsets at each corner to get the height offset
										// of the vertex.

										float lerpX = fract(vertices[vertex][0] / (float) LOCAL_TILE_SIZE);
										float lerpY = fract(vertices[vertex][2] / (float) LOCAL_TILE_SIZE);
										float northHeightOffset = mix(
											getHeightOffset(z, x, y + 1),
											getHeightOffset(z, x + 1, y + 1),
											lerpX
										);
										float southHeightOffset = mix(
											getHeightOffset(z, x, y),
											getHeightOffset(z, x + 1, y),
											lerpX);
										int heightOffset = (int) mix(southHeightOffset, northHeightOffset, lerpY);

										if (!sceneContext.isVertexLand(hashes[vertex]))
											sceneContext.setVertexUnderwaterDepth(hashes[vertex], heightOffset);
									}
								}
							}
						}
					}
				}
			}

			if (sceneContext instanceof LegacySceneContext) {
				byte[][][] sceneUnderwaterDepthLevels = ((LegacySceneContext) sceneContext).underwaterDepthLevels;
				for (int z = 0; z < MAX_Z; ++z)
					for (int x = 0; x < sizeX; ++x)
						System.arraycopy(this.underwaterDepthLevels[z][x], 0, sceneUnderwaterDepthLevels[z][x], 0, sizeY);
			}
		}

		private int getHeightOffset(int z, int x, int y) {
			int depthLevel = underwaterDepthLevels[z][x][y];
			if (depthLevel == 0)
				return 0;

			int depth = DEPTH_LEVEL_SLOPE[depthLevel - 1];
			return (int) (depth * .55f); // legacy weirdness
		}
	}

	// used when calculating the gradient to apply to the walls of TzHaar
	// to emulate the style from 2008 HD rework
	private static final float[] gradientBaseColor = vec(3, 4, 26);
	private static final float[] gradientDarkColor = vec(3, 4, 10);
	private static final int gradientBottom = 200;
	private static final int gradientTop = -200;

	public static int[] recolorTzHaar(
		ModelOverride modelOverride,
		Model model,
		int face,
		int color1,
		int color2,
		int color3,
		int[] out
	) {
		int[] hsl1 = ColorUtils.unpackRawHsl(color1);
		int[] hsl2 = ColorUtils.unpackRawHsl(color2);
		int[] hsl3 = ColorUtils.unpackRawHsl(color3);

		// shift model hues from red->yellow
		hsl1[0] = hsl2[0] = hsl3[0] = 7;

		if (modelOverride.tzHaarRecolorType == TzHaarRecolorType.GRADIENT) {
			final int triA = model.getFaceIndices1()[face];
			final int triB = model.getFaceIndices2()[face];
			final int triC = model.getFaceIndices3()[face];
			final float[] yVertices = model.getVerticesY();
			float height = (yVertices[triA] + yVertices[triB] + yVertices[triC]) / 3;
			float pos = clamp((height - gradientTop) / (float) gradientBottom, 0.0f, 1.0f);

			// apply coloring to the rocky walls
			if (hsl1[2] < 20 || hsl2[2] < 20 || hsl3[2] < 20) {
				round(hsl1, mix(gradientDarkColor, gradientBaseColor, pos));
				round(hsl2, mix(gradientDarkColor, gradientBaseColor, pos));
				round(hsl3, mix(gradientDarkColor, gradientBaseColor, pos));
			}
		} else if (modelOverride.tzHaarRecolorType == TzHaarRecolorType.HUE_SHIFT) {
			// objects around the entrance to The Inferno only need a hue-shift
			// and very slight lightening to match the lightened terrain
			hsl1[2] += 1;
			hsl2[2] += 1;
			hsl3[2] += 1;
		}

		out[0] = ColorUtils.packRawHsl(hsl1);
		out[1] = ColorUtils.packRawHsl(hsl2);
		out[2] = ColorUtils.packRawHsl(hsl3);

		return out;
	}
}

package rs117.hd.scene;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import rs117.hd.renderer.zone.WorldViewContext;
import rs117.hd.scene.areas.AABB;
import rs117.hd.scene.areas.Area;
import rs117.hd.scene.environments.Environment;
import rs117.hd.scene.lights.Light;
import rs117.hd.scene.materials.Material;
import rs117.hd.scene.tile_overrides.TileOverride;
import rs117.hd.scene.tile_overrides.TileOverrideVariables;
import rs117.hd.utils.HDUtils;
import rs117.hd.utils.collections.Int2IntHashMap;
import rs117.hd.utils.collections.Int2ObjectHashMap;

import static net.runelite.api.Constants.*;
import static net.runelite.api.Constants.SCENE_SIZE;
import static net.runelite.api.Perspective.*;
import static rs117.hd.utils.MathUtils.*;

public class SceneContext {
	public static final byte TILE_WATER_FLAG = 1;
	public static final byte TILE_SKIP_FLAG = 1 << 1;

	public static final int TILE_OVERRIDE_MAIN = 0;
	public static final int TILE_OVERRIDE_UNDERLAY = 1;
	public static final int TILE_OVERRIDE_OVERLAY = 2;
	public static final int TILE_OVERRIDE_COUNT = 3;

	public static final int VERTEX_IS_LAND = 1;
	public static final int VERTEX_IS_WATER = 1 << 1;
	public static final int VERTEX_IS_OVERLAY = 1 << 2;
	public static final int VERTEX_IS_UNDERLAY = 1 << 3;
	public static final int VERTEX_IS_HIGH_PRIORITY_COLOR = 1 << 4;
	public static final int VERTEX_UNDER_WATER_DEPTH_SHIFT = 5;
	// This only needs 10 bits, since depth slope 1380 * .55 = 9.6 bits, but reserve 16 to be safe
	public static final int VERTEX_UNDER_WATER_DEPTH_MASK = 0xFFFF;

	// Thread safe tile override variables
	public final static ThreadLocal<TileOverrideVariables> TILE_OVERRIDE_VARIABLES = ThreadLocal.withInitial(TileOverrideVariables::new);
	public final Client client;
	public final Scene scene;
	@Nullable
	public WorldViewContext worldViewContext;
	public final int expandedMapLoadingChunks;

	@Nullable
	public final int[] sceneBase;
	@Nonnull
	public final AABB sceneBounds;
	public final ArrayList<Environment> environments = new ArrayList<>();
	public final ArrayList<Light> pendingLights = new ArrayList<>();
	public final HashSet<Projectile> knownProjectiles = new HashSet<>();
	public final ArrayList<TileObject> lightSpawnsToHandleOnClientThread = new ArrayList<>();
	public int sizeX, sizeZ;
	public int sceneOffset;
	public boolean enableAreaHiding;
	public boolean fillGaps;
	public boolean isInChambersOfXeric;
	public boolean isInHouse;

	@Nullable
	public Area currentArea;
	public Area[] possibleAreas = new Area[0];
	public byte[][] filledTiles = new byte[EXTENDED_SCENE_SIZE][EXTENDED_SCENE_SIZE];
	public byte[] tileFlags;
	public char[] tileOverrideIndices;

	// Terrain data
	public Int2ObjectHashMap<Material> vertexTerrainTexture;
	public Int2IntHashMap vertexTerrainColor;
	public Int2IntHashMap vertexTerrainData;
	public Int2IntHashMap vertexTerrainNormalIndices;
	public short[] vertexTerrainNormals;

	public SceneContext(Client client, Scene scene, int expandedMapLoadingChunks) {
		this.client = client;
		this.scene = scene;
		this.expandedMapLoadingChunks = scene.isInstance() ? 0 : expandedMapLoadingChunks;
		sizeX = sizeZ = EXTENDED_SCENE_SIZE;
		sceneOffset = (EXTENDED_SCENE_SIZE - SCENE_SIZE) / 2;
		sceneBase = findSceneBase();
		sceneBounds = findSceneBounds(sceneBase);
	}

	public synchronized void destroy() {}

	public void setVertexIsLand(int hash) {
		vertexTerrainData.or(hash, VERTEX_IS_LAND, 0);
	}

	public void setVertexIsWater(int hash) {
		vertexTerrainData.or(hash, VERTEX_IS_WATER, 0);
	}

	public void setVertexHighPriorityColor(int hash) {
		vertexTerrainData.or(hash, VERTEX_IS_HIGH_PRIORITY_COLOR, 0);
	}

	public void setVertexIsOverlay(int hash, boolean isOverlay) {
		vertexTerrainData.or(hash, isOverlay ? VERTEX_IS_OVERLAY : VERTEX_IS_UNDERLAY, 0);
	}

	public void setVertexUnderwaterDepth(int hash, int depth) {
		int value = (depth << VERTEX_UNDER_WATER_DEPTH_SHIFT);
		int mask = VERTEX_UNDER_WATER_DEPTH_MASK << VERTEX_UNDER_WATER_DEPTH_SHIFT;
		vertexTerrainData.setBits(hash, value, mask, 0);
	}

	public boolean isVertexHighPriorityColor(int hash) {
		return vertexTerrainData.test(hash, VERTEX_IS_HIGH_PRIORITY_COLOR);
	}

	public boolean isVertexLand(int hash) {
		return vertexTerrainData.test(hash, VERTEX_IS_LAND);
	}

	public boolean isVertexWater(int hash) {
		return vertexTerrainData.test(hash, VERTEX_IS_WATER);
	}

	public boolean isVertexOverlay(int hash) {
		return vertexTerrainData.test(hash, VERTEX_IS_OVERLAY);
	}

	public boolean isVertexUnderlay(int hash) {
		return vertexTerrainData.test(hash, VERTEX_IS_UNDERLAY);
	}

	public short[] getVertexNormalOrDefault(int hash, short[] result, short[] defaultNormal) {
		if (getVertexNormal(hash, result) != null)
			return result;

		result[0] = defaultNormal[0];
		result[1] = defaultNormal[1];
		result[2] = defaultNormal[2];

		return result;
	}

	public short[] getVertexNormal(int hash, short[] result) {
		int index = vertexTerrainNormalIndices.getOrDefault(hash, -1);
		if (index == -1)
			return null;

		final int offset = index * 3;
		result[0] = vertexTerrainNormals[offset];
		result[1] = vertexTerrainNormals[offset + 1];
		result[2] = vertexTerrainNormals[offset + 2];
		return result;
	}

	public int getVertexUnderwaterDepth(int hash) {
		return vertexTerrainData.getBits(
			hash,
			VERTEX_UNDER_WATER_DEPTH_MASK,
			VERTEX_UNDER_WATER_DEPTH_SHIFT,
			0
		);
	}

	public void setTileFlag(int plane, int x, int y, byte flag) {
		tileFlags[getTileIdx(plane, x, y)] |= flag;
	}

	public boolean isTileFlagSet(int plane, int x, int y, byte flag) {
		return (tileFlags[getTileIdx(plane, x, y)] & flag) != 0;
	}

	public void setTileOverride(int plane, int x, int y, TileOverride[] overrides) {
		setTileOverride(plane, x, y, overrides[0], overrides[1], overrides[2]);
	}

	public void setTileOverride(
		int plane,
		int x,
		int y,
		TileOverride mainOverride,
		TileOverride underlayOverride,
		TileOverride overlayOverride
	) {
		final int offset = getTileIdx(plane, x, y) * TILE_OVERRIDE_COUNT;

		if (mainOverride != null && mainOverride != TileOverride.NONE)
			tileOverrideIndices[offset + TILE_OVERRIDE_MAIN] = (char) (mainOverride.index + 1);

		if (underlayOverride != null && underlayOverride != TileOverride.NONE)
			tileOverrideIndices[offset + TILE_OVERRIDE_UNDERLAY] = (char) (underlayOverride.index + 1);

		if (overlayOverride != null && overlayOverride != TileOverride.NONE)
			tileOverrideIndices[offset + TILE_OVERRIDE_OVERLAY] = (char) (overlayOverride.index + 1);
	}

	public boolean getTileOverrides(int plane, int x, int y, TileOverride[] result) {
		final int offset = getTileIdx(plane, x, y) * TILE_OVERRIDE_COUNT;

		boolean hasOverrides = false;
		for (int i = 0; i < TILE_OVERRIDE_COUNT; i++) {
			final int idx = tileOverrideIndices[offset + i];
			result[i] = idx > 0 ? TileOverrideManager.OVERRIDES[idx - 1] : TileOverride.NONE;
			if (idx > 0)
				hasOverrides = true;
		}

		return hasOverrides;
	}

	public TileOverride getTileOverride(int plane, int x, int y, int type) {
		final int offset = getTileIdx(plane, x, y) * TILE_OVERRIDE_COUNT;
		final int idx = tileOverrideIndices[offset + type];
		return idx > 0 ? TileOverrideManager.OVERRIDES[idx - 1] : TileOverride.NONE;
	}

	public int[] getTileIndices(int tileIdx, int[] indices) {
		indices[0] = tileIdx % sizeX;
		indices[1] = (tileIdx / sizeX) % sizeZ;
		indices[2] = tileIdx / (sizeX * sizeZ);
		return indices;
	}

	public int getTileIdx(int plane, int x, int y) {
		return x + y * sizeX + plane * sizeX * sizeZ;
	}

	/**
	 * Transform local coordinates into world coordinates.
	 * If the {@link LocalPoint} is not in the scene, this returns untranslated coordinates when in instances.
	 *
	 * @param localPoint to transform
	 * @param plane      which the local coordinate is on
	 * @return world coordinate
	 */
	public int[] localToWorld(LocalPoint localPoint, int plane) {
		return localToWorld(localPoint.getX(), localPoint.getY(), plane);
	}

	public int[] localToWorld(LocalPoint localPoint, int plane, int[] result) {
		return localToWorld(localPoint.getX(), localPoint.getY(), plane, result);
	}

	public int[] localToWorld(LocalPoint localPoint) {
		return localToWorld(localPoint, client.getPlane());
	}

	public int[] localToWorld(int localX, int localY) {
		return localToWorld(localX, localY, client.getPlane());
	}

	public int[] localToWorld(int localX, int localY, int plane) {
		return sceneToWorld(localX >> LOCAL_COORD_BITS, localY >> LOCAL_COORD_BITS, plane);
	}

	public int[] localToWorld(int localX, int localY, int plane, int[] result) {
		sceneToWorld(localX >> LOCAL_COORD_BITS, localY >> LOCAL_COORD_BITS, plane, result);
		return result;
	}

	public void sceneToWorld(int sceneX, int sceneY, int plane, int[] result) {
		if (sceneBase == null) {
			HDUtils.sceneToWorld(scene, sceneX, sceneY, plane, result);
			return;
		}

		result[0] = sceneBase[0] + sceneX;
		result[1] = sceneBase[1] + sceneY;
		result[2] = sceneBase[2] + plane;
	}

	public int[] sceneToWorld(int sceneX, int sceneY, int plane) {
		int[] result = new int[3];
		sceneToWorld(sceneX, sceneY, plane, result);
		return result;
	}

	public void extendedSceneToWorld(int sceneExX, int sceneExY, int plane, int[] result) {
		sceneToWorld(sceneExX - sceneOffset, sceneExY - sceneOffset, plane, result);
	}

	public int[] extendedSceneToWorld(int sceneExX, int sceneExY, int plane) {
		return sceneToWorld(sceneExX - sceneOffset, sceneExY - sceneOffset, plane);
	}

	public List<int[]> worldToScene(int[] worldPoint) {
		if (sceneBase != null)
			return List.of(ivec(
				worldPoint[0] - sceneBase[0],
				worldPoint[1] - sceneBase[1],
				worldPoint[2]
			));

		// If the scene is not contiguous, convert the world point to world points within the instance, then to local coords
		var instanceTemplateChunks = scene.getInstanceTemplateChunks();
		ArrayList<int[]> sceneCoords = new ArrayList<>();
		for (int z = 0; z < instanceTemplateChunks.length; z++) {
			for (int x = 0; x < instanceTemplateChunks[z].length; ++x) {
				for (int y = 0; y < instanceTemplateChunks[z][x].length; ++y) {
					int chunkData = instanceTemplateChunks[z][x][y];
					int rotation = chunkData >> 1 & 0x3;
					int templateChunkY = (chunkData >> 3 & 0x7FF) * CHUNK_SIZE;
					int templateChunkX = (chunkData >> 14 & 0x3FF) * CHUNK_SIZE;
					int plane = chunkData >> 24 & 0x3;
					if (worldPoint[0] >= templateChunkX && worldPoint[0] < templateChunkX + CHUNK_SIZE &&
						worldPoint[1] >= templateChunkY && worldPoint[1] < templateChunkY + CHUNK_SIZE &&
						plane == worldPoint[2]
					) {
						var p = ivec(
							x * CHUNK_SIZE + (worldPoint[0] & (CHUNK_SIZE - 1)),
							y * CHUNK_SIZE + (worldPoint[1] & (CHUNK_SIZE - 1)),
							z
						);
						rotate(p, p, rotation);
						sceneCoords.add(p);
					}
				}
			}
		}
		return sceneCoords;
	}

	public List<int[]> worldToLocal(int[] worldPoint) {
		var points = worldToScene(worldPoint);
		for (int i = 0; i < points.size(); i++) {
			var p = points.get(i);
			multiply(p, p, LOCAL_TILE_SIZE);
		}
		return points;
	}

	/**
	 * Rotate the coordinates in the chunk according to chunk rotation
	 *
	 * @param out      output, can be the same instance as point
	 * @param point    point
	 * @param rotation rotation
	 * @return world point
	 */
	private static int[] rotate(int[] out, int[] point, int rotation) {
		int mask = CHUNK_SIZE - 1;
		int chunkX = point[0] & ~mask;
		int chunkY = point[1] & ~mask;
		int x = point[0] & mask;
		int y = point[1] & mask;
		switch (rotation) {
			case 1:
				out[0] = chunkX + y;
				out[1] = chunkY + mask - x;
				break;
			case 2:
				out[0] = chunkX + mask - x;
				out[1] = chunkY + mask - y;
				break;
			case 3:
				out[0] = chunkX + mask - y;
				out[1] = chunkY + x;
				break;
		}
		out[2] = point[2];
		return out;
	}

	public boolean intersects(Area area) {
		return intersects(area.aabbs);
	}

	public boolean intersects(AABB... aabbs) {
		return HDUtils.sceneIntersects(scene, expandedMapLoadingChunks, aabbs);
	}

	public AABB getNonInstancedSceneBounds() {
		return HDUtils.getNonInstancedSceneBounds(scene, expandedMapLoadingChunks);
	}

	/**
	 * Returns the south-west coordinate of the scene in world coordinates, after resolving instance template chunks
	 * to their original world coordinates. If the scene is instanced, this returns null when the chunks aren't contiguous.
	 */
	@Nullable
	private int[] findSceneBase() {
		int baseX = scene.getBaseX();
		int baseY = scene.getBaseY();
		int basePlane = 0;

		if (scene.isInstance()) {
			boolean foundChunk = false;

			int[][][] chunks = scene.getInstanceTemplateChunks();
			for (int plane = 0; plane < chunks.length; plane++) {
				for (int x = 0; x < chunks[plane].length; x++) {
					for (int y = 0; y < chunks[plane][x].length; y++) {
						int chunk = chunks[plane][x][y];
						if (chunk == -1)
							continue; // Ignore unfilled chunks

						// Ensure the chunk isn't rotated (although we technically could handle consistent rotation)
						int rotation = chunk >> 1 & 0x3;
						if (rotation != 0)
							return null;

						int chunkX = chunk >> 14 & 0x3FF;
						int chunkY = chunk >> 3 & 0x7FF;
						int chunkPlane = chunk >> 24 & 0x3;

						if (foundChunk) {
							int expectedX = baseX + x;
							int expectedY = baseY + y;
							int expectedPlane = basePlane + plane;
							if (chunkX != expectedX || chunkY != expectedY || chunkPlane != expectedPlane)
								return null; // Not contiguous
						} else {
							// Calculate the expected unextended scene base chunk
							baseX = chunkX - x;
							baseY = chunkY - y;
							basePlane = chunkPlane - plane;
							foundChunk = true;
						}
					}
				}
			}

			if (!foundChunk)
				return null;

			// Transform chunk to world coordinates
			baseX <<= 3;
			baseY <<= 3;
		}

		return ivec(baseX, baseY, basePlane);
	}

	/**
	 * Works for non-instanced scenes & contiguous instanced scenes.
	 * Returns a best attempt for non-contiguous instanced scenes, which may be
	 * significantly larger than necessary, but will always include all tiles.
	 */
	private AABB findSceneBounds(@Nullable int[] sceneBase) {
		if (sceneBase != null) {
			int x = sceneBase[0] - sceneOffset;
			int y = sceneBase[1] - sceneOffset;
			return new AABB(x, y, x + EXTENDED_SCENE_SIZE - 1, y + EXTENDED_SCENE_SIZE - 1);
		}

		// Assume instances are assembled from approximately adjacent chunks on the map
		int minX = Integer.MAX_VALUE;
		int minY = Integer.MAX_VALUE;
		int minZ = MAX_Z;
		int maxX = Integer.MIN_VALUE;
		int maxY = Integer.MIN_VALUE;
		int maxZ = 0;

		int[][][] chunks = scene.getInstanceTemplateChunks();
		for (int[][] plane : chunks) {
			for (int[] column : plane) {
				for (int chunk : column) {
					if (chunk == -1)
						continue;

					// Extract chunk coordinates
					int x = chunk >> 14 & 0x3FF;
					int y = chunk >> 3 & 0x7FF;
					int z = chunk >> 24 & 0x3;
					minX = min(minX, x);
					minY = min(minY, y);
					minZ = min(minZ, z);
					maxX = max(maxX, x);
					maxY = max(maxY, y);
					maxZ = max(maxZ, z);
				}
			}
		}

		// Return an AABB representing no match, if there are no chunks
		if (maxX < minX)
			return new AABB(-1, -1);

		// Transform from chunk to world coordinates
		return new AABB(minX << 3, minY << 3, minZ, (maxX << 3) + CHUNK_SIZE - 1, (maxY << 3) + CHUNK_SIZE - 1, maxZ);
	}
}

