package rs117.hd.scene.areas;

import com.google.gson.TypeAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.*;
import rs117.hd.scene.AreaManager;
import rs117.hd.utils.GsonUtils;

import static net.runelite.api.Constants.*;
import static rs117.hd.utils.MathUtils.*;

public class AABB {
	public final int minX;
	public final int minY;
	public final int minZ;
	public final int maxX;
	public final int maxY;
	public final int maxZ;

	public AABB(int x, int y) {
		minX = maxX = x;
		minY = maxY = y;
		minZ = Integer.MIN_VALUE;
		maxZ = Integer.MAX_VALUE;
	}

	public AABB(int x, int y, int z) {
		minX = maxX = x;
		minY = maxY = y;
		minZ = maxZ = z;
	}

	public AABB(int x1, int y1, int x2, int y2) {
		minX = min(x1, x2);
		minY = min(y1, y2);
		minZ = Integer.MIN_VALUE;
		maxX = max(x1, x2);
		maxY = max(y1, y2);
		maxZ = Integer.MAX_VALUE;
	}

	public AABB(int x1, int y1, int x2, int y2, int z1) {
		minX = min(x1, x2);
		minY = min(y1, y2);
		maxX = max(x1, x2);
		maxY = max(y1, y2);
		minZ = maxZ = z1;
	}

	public AABB(int x1, int y1, int z1, int x2, int y2, int z2) {
		minX = min(x1, x2);
		minY = min(y1, y2);
		minZ = min(z1, z2);
		maxX = max(x1, x2);
		maxY = max(y1, y2);
		maxZ = max(z1, z2);
	}

	public AABB(int[] point) {
		this(point[0], point[1], point[2]);
	}

	public AABB(int[] from, int[] to) {
		this(from[0], from[1], from[2], to[0], to[1], to[2]);
	}

	public static AABB fromRegionId(int regionId) {
		int minX = (regionId >>> 8) << 6;
		int minY = (regionId & 0xFF) << 6;
		int maxX = minX + REGION_SIZE - 1;
		int maxY = minY + REGION_SIZE - 1;
		return new AABB(minX, minY, maxX, maxY);
	}

	public AABB onPlane(int plane) {
		return new AABB(minX, minY, plane, maxX, maxY, plane);
	}

	public AABB expandTo(int[] point) {
		return new AABB(
			min(minX, point[0]),
			min(minY, point[1]),
			min(minZ, point[2]),
			max(maxX, point[0]),
			max(maxY, point[1]),
			max(maxZ, point[2])
		);
	}

	public boolean hasZ() {
		return minZ != Integer.MIN_VALUE || maxZ != Integer.MAX_VALUE;
	}

	public boolean isPoint() {
		return
			minX == maxX &&
			minY == maxY &&
			(!hasZ() || minZ == maxZ);
	}

	public boolean isVolume() {
		return !isPoint();
	}

	public boolean contains(int... worldPos) {
		final int length = worldPos.length;
		assert length >= 2 : "Expected X, Y & possibly a plane, got: " + Arrays.toString(worldPos);
		final int x = worldPos[0];
		final int y = worldPos[1];
		final int z = length > 2 ? worldPos[2] : 0;
		return
			minX <= x && x <= maxX &&
			minY <= y && y <= maxY &&
			(length < 3 || minZ <= z && z <= maxZ);
	}

	public boolean contains(WorldPoint location) {
		return contains(location.getX(), location.getY(), location.getPlane());
	}

	public boolean contains(AABB other) {
		return
			contains(other.minX, other.minY, other.minZ) &&
			contains(other.maxX, other.maxY, other.maxZ);
	}

	public boolean intersects(int minX, int minY, int maxX, int maxY) {
		return
			minX <= this.maxX && maxX >= this.minX &&
			minY <= this.maxY && maxY >= this.minY;
	}

	public boolean intersects(int minX, int minY, int minZ, int maxX, int maxY, int maxZ) {
		return
			minX <= this.maxX && maxX >= this.minX &&
			minY <= this.maxY && maxY >= this.minY &&
			minZ <= this.maxZ && maxZ >= this.minZ;
	}

	public boolean intersects(AABB other) {
		return intersects(
			other.minX,
			other.minY,
			other.minZ,
			other.maxX,
			other.maxY,
			other.maxZ
		);
	}

	public boolean intersects(AABB... aabbs) {
		for (var aabb : aabbs)
			if (intersects(aabb))
				return true;
		return false;
	}

	public float[] getCenter() {
		return new float[] {
			(minX + maxX) / 2.f,
			(minY + maxY) / 2.f,
			(minZ + maxZ) / 2.f
		};
	}

	public int distanceToPoint(int x, int y) {
		int dx = Math.max(Math.max(minX - x, 0), x - maxX);
		int dy = Math.max(Math.max(minY - y, 0), y - maxY);
		return dx * dx + dy * dy;
	}

	@Override
	public String toString() {
		if (hasZ())
			return String.format("AABB{min=(%d,%d,%d), max=(%d,%d,%d)}", minX, minY, minZ, maxX, maxY, maxZ);
		return String.format("AABB{min=(%d,%d), max=(%d,%d)}", minX, minY, maxX, maxY);
	}

	public String toArgs() {
		if (hasZ()) {
			if (isPoint())
				return String.format("[ %d, %d, %d ]", minX, minY, minZ);
			if (minZ == maxZ)
				return String.format("[ %d, %d, %d, %d, %d ]", minX, minY, maxX, maxY, minZ);
			return String.format("[ %d, %d, %d, %d, %d, %d ]", minX, minY, minZ, maxX, maxY, maxZ);
		}
		if (isPoint())
			return String.format("[ %d, %d ]", minX, minY);
		return String.format("[ %d, %d, %d, %d ]", minX, minY, maxX, maxY);
	}

	@Override
	public int hashCode() {
		int h = minX;
		h = h * 31 + maxX;
		h = h * 31 + minY;
		h = h * 31 + maxY;
		h = h * 31 + minZ;
		h = h * 31 + maxZ;
		return h;
	}

	@Override
	public boolean equals(Object obj) {
		if (!(obj instanceof AABB))
			return false;

		AABB other = (AABB) obj;
		return
			other.minX == minX && other.maxX == maxX &&
			other.minY == minY && other.maxY == maxY &&
			other.minZ == minZ && other.maxZ == maxZ;
	}

	@Slf4j
	public static class ArrayAdapter extends TypeAdapter<AABB[]> {
		@Override
		public AABB[] read(JsonReader in) throws IOException {
			in.beginArray();
			ArrayList<AABB> list = new ArrayList<>();
			outer:
			while (in.hasNext() && in.peek() != JsonToken.END_ARRAY) {
				if (in.peek() == JsonToken.NULL) {
					in.skipValue();
					continue;
				}

				if (in.peek() == JsonToken.NUMBER) {
					log.warn("AABBs are specified by two or more numbers. Did you forget to add an array at {}?", GsonUtils.location(in));
					continue;
				}

				if (in.peek() == JsonToken.STRING) {
					String name = in.nextString();
					for (var area : AreaManager.AREAS) {
						if (name.equals(area.name)) {
							Collections.addAll(list, area.aabbs);
							continue outer;
						}
					}

					log.warn("No area exists with the name '{}' at {}", name, GsonUtils.location(in), new Throwable());
				}

				in.beginArray();
				int[] ints = new int[6];
				int i = 0;
				while (in.hasNext()) {
					switch (in.peek()) {
						case NUMBER:
							if (i >= ints.length)
								throw new IOException(
									"Too many numbers in AABB entry (> " + ints.length + ") at " + GsonUtils.location(in));
							ints[i++] = in.nextInt();
						case END_ARRAY:
							break;
						case NULL:
							in.skipValue();
							continue;
						default:
							throw new IOException("Malformed AABB entry. Unexpected token: " + in.peek() + " at " + GsonUtils.location(in));
					}
				}
				in.endArray();

				switch (i) {
					case 1:
						log.warn("AABBs are specified by two or more numbers, only one was provided at {}", GsonUtils.location(in));
						break;
					case 2:
						list.add(new AABB(ints[0], ints[1]));
						break;
					case 3:
						list.add(new AABB(ints[0], ints[1], ints[2]));
						break;
					case 4:
						list.add(new AABB(ints[0], ints[1], ints[2], ints[3]));
						break;
					case 5:
						list.add(new AABB(ints[0], ints[1], ints[2], ints[3], ints[4]));
						break;
					case 6:
						list.add(new AABB(ints[0], ints[1], ints[2], ints[3], ints[4], ints[5]));
						break;
				}
			}
			in.endArray();
			return list.toArray(AABB[]::new);
		}

		@Override
		public void write(JsonWriter out, AABB[] aabbs) throws IOException {
			if (aabbs == null || aabbs.length == 0) {
				out.nullValue();
				return;
			}

			out.beginArray();
			for (AABB aabb : aabbs) {
				// Compact JSON array
				StringBuilder sb = new StringBuilder();
				sb.append("[ ").append(aabb.minX);
				sb.append(", ").append(aabb.minY);
				if (aabb.hasZ())
					sb.append(", ").append(aabb.minZ);
				if (aabb.isVolume()) {
					sb.append(", ").append(aabb.maxX);
					sb.append(", ").append(aabb.maxY);
					if (aabb.hasZ())
						sb.append(", ").append(aabb.maxZ);
				}
				sb.append(" ]");
				out.jsonValue(sb.toString());
			}
			out.endArray();
		}
	}
}

package rs117.hd.scene.areas;

import com.google.gson.annotations.JsonAdapter;
import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.Collections;
import lombok.NoArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import rs117.hd.scene.AreaManager;
import rs117.hd.utils.Props;

import static rs117.hd.utils.collections.Util.quickSort;

@Slf4j
@NoArgsConstructor // Required to make Gson respect initializers
public class Area {
	public static final Area NONE = new Area("NONE", 0, 0, 0, 0);
	public static final Area ALL = new Area("ALL", Integer.MIN_VALUE, Integer.MIN_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE);
	public static Area OVERWORLD = NONE;

	public String name;
	public boolean hideOtherAreas;
	public boolean fillGaps;

	public String[] areas;
	public int[] regions;

	@JsonAdapter(RegionBox.Adapter.class)
	public RegionBox[] regionBoxes;

	@JsonAdapter(AABB.ArrayAdapter.class)
	@SerializedName("aabbs")
	public AABB[] rawAabbs;

	@JsonAdapter(AABB.ArrayAdapter.class)
	public AABB[] unhideAreas = {};

	public transient AABB[] aabbs;
	public transient AABB areaBounds;

	private transient AABB[] sortedAabbs;
	private transient boolean normalized;

	public Area(String name) {
		this.name = name;
	}

	public Area(String name, int x1, int y1, int x2, int y2) {
		this(name);
		aabbs = new AABB[] { new AABB(x1, y1, x2, y2) };
	}

	public void normalize() {
		if (normalized)
			return;
		normalized = true;

		ArrayList<AABB> list = new ArrayList<>();

		if (rawAabbs != null)
			Collections.addAll(list, rawAabbs);

		if (regions != null)
			for (int regionId : regions)
				list.add(AABB.fromRegionId(regionId));

		if (regionBoxes != null)
			for (var box : regionBoxes)
				list.add(box.toAabb());

		if (areas != null) {
			for (String areaName : areas) {
				for (Area other : AreaManager.AREAS) {
					if (areaName.equals(other.name)) {
						other.normalize();
						Collections.addAll(list, other.aabbs);
						break;
					}
				}
			}
		}

		this.aabbs = list.toArray(AABB[]::new);

		if (Props.DEVELOPMENT) {
			// Check for any out of bounds areas
			for (int i = 0; i < aabbs.length; i++) {
				AABB aabb = aabbs[i];
				if (aabb.minX < -128 || aabb.minY < 1000 || aabb.maxX > 5000 || aabb.maxY > 13000) {
					throw new IllegalArgumentException(String.format(
						"Your definition for the area \"%s\" has an incorrect AABB at index %d: %s",
						name, i, aabb
					));
				}
			}
		}

		// Compute bounds
		if (aabbs.length > 0) {
			int minX = Integer.MAX_VALUE;
			int minY = Integer.MAX_VALUE;
			int minZ = Integer.MAX_VALUE;

			int maxX = Integer.MIN_VALUE;
			int maxY = Integer.MIN_VALUE;
			int maxZ = Integer.MIN_VALUE;

			for (AABB aabb : aabbs) {
				minX = Math.min(minX, aabb.minX);
				minY = Math.min(minY, aabb.minY);
				minZ = Math.min(minZ, aabb.minZ);
				maxX = Math.max(maxX, aabb.maxX);
				maxY = Math.max(maxY, aabb.maxY);
				maxZ = Math.max(maxZ, aabb.maxZ);
			}

			if (unhideAreas != null) {
				for (AABB aabb : unhideAreas) {
					minX = Math.min(minX, aabb.minX);
					minY = Math.min(minY, aabb.minY);
					minZ = Math.min(minZ, aabb.minZ);
					maxX = Math.max(maxX, aabb.maxX);
					maxY = Math.max(maxY, aabb.maxY);
					maxZ = Math.max(maxZ, aabb.maxZ);
				}
			}

			areaBounds = new AABB(minX, minY, minZ, maxX, maxY, maxZ);

			if (aabbs.length > 4) {
				sortedAabbs = new AABB[4 * aabbs.length];

				buildCorner(0, areaBounds.minX, areaBounds.minY);
				buildCorner(1, areaBounds.minX, areaBounds.maxY);
				buildCorner(2, areaBounds.maxX, areaBounds.minY);
				buildCorner(3, areaBounds.maxX, areaBounds.maxY);
			}
		}

		if (unhideAreas == null)
			unhideAreas = new AABB[0];
	}

	private void buildCorner(int c, int cx, int cy) {
		final int left = c * aabbs.length;
		final int right = left + aabbs.length;

		// Copy AABS to destination ready for sorting
		System.arraycopy(aabbs, 0, sortedAabbs, left, right - left);

		// Sort AABS in place for this corner
		quickSort(sortedAabbs, left, right - 1, (a1, a2) -> {
			final float s1 = score(a1, cx, cy);
			final float s2 = score(a2, cx, cy);
			return Float.compare(s1, s2);
		});

		if (Props.DEVELOPMENT)
			validateCorner(c, cx, cy);
	}

	private void validateCorner(int c, int cx, int cy) {
		final int left = c * aabbs.length;
		final int right = left + aabbs.length;

		for (int i = left; i < right - 1; i++) {
			final float current = score(sortedAabbs[i], cx, cy);
			final float next = score(sortedAabbs[i + 1], cx, cy);

			if (current > next) {
				log.error("Area {}: Corner {} not sorted at index {}: {} > {}", name, c, i - left, current, next);
				return;
			}
		}
	}

	private static float score(AABB aabb, int cx, int cy) {
		float distance = aabb.distanceToPoint(cx, cy);

		int w = aabb.maxX - aabb.minX;
		int h = aabb.maxY - aabb.minY;
		int area = w * h;

		final float SIZE_WEIGHT = 1e-6F;
		return distance - (area * SIZE_WEIGHT);
	}

	private int getClosestCorner(int x, int y) {
		int dx = x - areaBounds.minX;
		int dy = y - areaBounds.minY;
		int best = dx * dx + dy * dy;
		int corner = 0;

		dx = x - areaBounds.minX;
		dy = y - areaBounds.maxY;
		int d = dx * dx + dy * dy;
		if (d < best) {
			best = d;
			corner = 1;
		}

		dx = x - areaBounds.maxX;
		dy = y - areaBounds.minY;
		d = dx * dx + dy * dy;
		if (d < best) {
			best = d;
			corner = 2;
		}

		dx = x - areaBounds.maxX;
		dy = y - areaBounds.maxY;
		d = dx * dx + dy * dy;
		if (d < best)
			corner = 3;

		return corner;
	}

	public boolean containsPoint(boolean includeUnhiding, int... worldPoint) {
		if (areaBounds != null && !areaBounds.contains(worldPoint))
			return false;

		final int length = aabbs.length;
		if (sortedAabbs != null && areaBounds != null) {
			final int corner = getClosestCorner(worldPoint[0], worldPoint[1]);
			final int start = corner * length;
			final int end = start + length;

			for (int i = start; i < end; i++) {
				if (sortedAabbs[i].contains(worldPoint))
					return true;
			}
		} else {
			for (int i = 0; i < length; i++) {
				if (aabbs[i].contains(worldPoint))
					return true;
			}
		}

		if (includeUnhiding)
			for (AABB aabb : unhideAreas)
				if (aabb.contains(worldPoint))
					return true;

		return false;
	}

	public boolean containsPoint(int... worldPoint) {
		return containsPoint(true, worldPoint);
	}

	public boolean intersects(boolean includeUnhiding, int minX, int minY, int maxX, int maxY) {
		for (AABB aabb : aabbs)
			if (aabb.intersects(minX, minY, maxX, maxY))
				return true;

		if (includeUnhiding)
			for (AABB aabb : unhideAreas)
				if (aabb.intersects(minX, minY, maxX, maxY))
					return true;

		return false;
	}

	public boolean intersects(Area otherArea) {
		if (otherArea == null)
			return false;
		return intersects(otherArea.aabbs);
	}

	public boolean intersects(AABB... otherAabbs) {
		for (AABB aabb : aabbs)
			if (aabb.intersects(otherAabbs))
				return true;
		return false;
	}

	@Override
	public String toString() {
		return name;
	}
}

package rs117.hd.scene.areas;

import com.google.gson.TypeAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.util.ArrayList;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import rs117.hd.utils.GsonUtils;

import static net.runelite.api.Constants.*;

@RequiredArgsConstructor
public class RegionBox {
	public final int from, to;
	public final int fromPlane, toPlane;

	public RegionBox(int regionId) {
		this(regionId, regionId);
	}

	public RegionBox(int from, int to) {
		this(from, to, 0, MAX_Z - 1);
	}

	public RegionBox(int from, int to, int plane) {
		this(from, to, plane, plane);
	}

	public AABB toAabb() {
		int x1 = from >>> 8;
		int y1 = from & 0xFF;
		int x2 = to >>> 8;
		int y2 = to & 0xFF;
		if (x1 > x2) {
			int temp = x1;
			x1 = x2;
			x2 = temp;
		}
		if (y1 > y2) {
			int temp = y1;
			y1 = y2;
			y2 = temp;
		}
		return new AABB(
			(x1) << 6,
			(y1) << 6,
			fromPlane,
			((x2) + 1 << 6) - 1,
			((y2) + 1 << 6) - 1,
			toPlane
		);
	}

	@Slf4j
	public static class Adapter extends TypeAdapter<RegionBox[]> {
		@Override
		public RegionBox[] read(JsonReader in) throws IOException {
			in.beginArray();
			ArrayList<RegionBox> list = new ArrayList<>();
			while (in.hasNext() && in.peek() != JsonToken.END_ARRAY) {
				if (in.peek() == JsonToken.NULL) {
					in.skipValue();
					continue;
				}

				in.beginArray();
				int[] ints = new int[4];
				int i = 0;
				while (in.hasNext()) {
					switch (in.peek()) {
						case NUMBER:
							if (i >= ints.length)
								throw new IOException(
									"Too many numbers in RegionBox entry (> " + ints.length + ") at " + GsonUtils.location(in));
							ints[i++] = in.nextInt();
						case END_ARRAY:
							break;
						case NULL:
							in.skipValue();
							continue;
						default:
							throw new IOException(
								"Malformed RegionBox entry. Unexpected token: " + in.peek() + " at " + GsonUtils.location(in));
					}
				}
				in.endArray();

				switch (i) {
					case 1:
						list.add(new RegionBox(ints[0]));
						break;
					case 2:
						list.add(new RegionBox(ints[0], ints[1]));
						break;
					case 3:
						list.add(new RegionBox(ints[0], ints[1], ints[2]));
						break;
					case 4:
						list.add(new RegionBox(ints[0], ints[1], ints[2], ints[3]));
						break;
				}
			}
			in.endArray();
			return list.toArray(new RegionBox[0]);
		}

		@Override
		public void write(JsonWriter out, RegionBox[] aabbs) throws IOException {
			if (aabbs == null || aabbs.length == 0) {
				out.nullValue();
				return;
			}

			out.beginArray();
			for (RegionBox box : aabbs) {
				// Compact JSON array
				if (box.fromPlane == 0 && box.toPlane == MAX_Z - 1) {
					if (box.from == box.to) {
						out.jsonValue(String.format("[ %d ]", box.from));
					} else {
						out.jsonValue(String.format("[ %d, %d ]", box.from, box.to));
					}
				} else if (box.fromPlane == box.toPlane) {
					out.jsonValue(String.format("[ %d, %d, %d ]", box.from, box.to, box.fromPlane));
				} else {
					out.jsonValue(String.format("[ %d, %d, %d, %d ]", box.from, box.to, box.fromPlane, box.toPlane));
				}
			}
			out.endArray();
		}
	}
}

package rs117.hd.scene.daylight_cycle;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.TypeAdapter;
import com.google.gson.TypeAdapterFactory;
import com.google.gson.annotations.JsonAdapter;
import com.google.gson.reflect.TypeToken;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import rs117.hd.config.MoonPhase;
import rs117.hd.scene.SkyManager;
import rs117.hd.scene.daylight_cycle.SkyState.GradientSample;
import rs117.hd.utils.ColorUtils;
import rs117.hd.utils.ColorUtils.SrgbToLinearAdapter;
import rs117.hd.utils.GsonUtils;
import rs117.hd.utils.GsonUtils.DegreesToRadians;
import rs117.hd.utils.HDUtils;

import static rs117.hd.utils.MathUtils.*;

@SuppressWarnings({ "FieldCanBeLocal", "FieldMayBeFinal" })
public class SkyConfiguration {
	public static SkyConfiguration DEFAULT_PRESET;

	@Nullable
	public String name;
	@Nullable
	public String parent;
	public SkyProfile profile;
	public boolean customGradient;
	public float horizonWidth = 15;
	@Nullable
	@JsonAdapter(DegreesToRadians.class)
	public float[] sunAngles;
	@Nullable
	@JsonAdapter(DegreesToRadians.class)
	public float[] moonAngles;
	public boolean hideMoon;
	@Nullable
	public MoonPhase forceMoonPhase;
	public float moonDirectionalStrength = -1;
	public float moonAmbientStrength = -1;
	public float minMoonIllumination;
	@JsonAdapter(SrgbToLinearAdapter.class)
	public float[] moonDiskColor;
	@JsonAdapter(SrgbToLinearAdapter.class)
	public float[] moonDirectionalColor;
	@JsonAdapter(SrgbToLinearAdapter.class)
	public float[] moonAmbientColor;
	@JsonAdapter(SrgbToLinearAdapter.class)
	public float[] nightAmbientColor;
	public float nightAmbientStrength = 1;
	@JsonAdapter(SrgbToLinearAdapter.class)
	public float[] nightHorizonColor;
	public float nightHorizonStrength = 1;
	public float moonDiskStrength = 1;
	@JsonAdapter(SrgbToLinearAdapter.class)
	@Nullable
	public float[] skyFogColor;
	public float skyFogDensity = -1;
	public float skyFogHorizonAltitude;
	public float skyVisibility = 1;
	/** Negative means automatic; an explicit value can retain moonlight with hideMoon. */
	public float moonLightVisibility = -1;
	public float moonVisibility = 1;
	public float starVisibility = 1;
	public float nebulaVisibility = 1;
	public float auroraVisibility = 1;
	public float moonSizeMult = 1;
	public float starHorizonHeight = 1;
	private float sunStrength = 1;
	private float sunriseSunsetStrength = 1;
	private float skyColorTakeoverAngle = 40;

	private transient boolean derivedMoonDirectionalColor;
	private transient boolean derivedMoonAmbientColor;
	private transient boolean derivedMoonDirectionalStrength;
	private transient boolean derivedMoonAmbientStrength;

	public void normalize() {
		if (nightHorizonColor == null)
			throw new IllegalStateException("Missing night sky color");
		nightHorizonColor = HDUtils.ensureArrayLength(nightHorizonColor, 3);
		nightHorizonStrength = max(0, nightHorizonStrength);

		if (nightAmbientColor == null)
			nightAmbientColor = new float[3];
		nightAmbientColor = HDUtils.ensureArrayLength(nightAmbientColor, 3);
		nightAmbientStrength = max(0, nightAmbientStrength);

		if (moonDiskColor == null)
			moonDiskColor = ColorUtils.colorTemperatureToLinearRgb(8000);
		moonDiskColor = HDUtils.ensureArrayLength(moonDiskColor, 3);

		boolean deriveDirectional = moonDirectionalColor == null;
		if (deriveDirectional) {
			derivedMoonDirectionalColor = true;
			moonDirectionalColor = copy(moonDiskColor);
		} else {
			moonDirectionalColor = HDUtils.ensureArrayLength(moonDirectionalColor, 3);
		}
		if (moonDirectionalStrength < 0) {
			derivedMoonDirectionalStrength = true;
			moonDirectionalStrength = 0.0008f * moonDiskStrength * pow2(moonSizeMult);
		}

		boolean deriveAmbient = moonAmbientColor == null;
		if (deriveAmbient) {
			derivedMoonAmbientColor = true;
			moonAmbientColor = copy(moonDirectionalColor);
			if (!deriveDirectional) {
				// We assume that authored directional colors already include the mesopic shift.
				// Undo this before deriving ambient lighting from it
				ColorUtils.invertMesopicShift(moonAmbientColor);
			}
			ColorUtils.deriveAmbientLight(moonAmbientColor, moonAmbientColor);
		} else {
			moonAmbientColor = HDUtils.ensureArrayLength(moonAmbientColor, 3);
		}
		if (moonAmbientStrength < 0) {
			derivedMoonAmbientStrength = true;
			moonAmbientStrength = moonDirectionalStrength;
		}

		// Apply mesopic shifts to derived night colors, since our renderer does not account for this in later stages
		if (deriveDirectional)
			ColorUtils.applyMesopicShift(moonDirectionalColor);
		if (deriveAmbient)
			ColorUtils.applyMesopicShift(moonAmbientColor);

		if (sunAngles != null)
			sunAngles = HDUtils.ensureArrayLength(sunAngles, 2);
		if (moonAngles != null)
			moonAngles = HDUtils.ensureArrayLength(moonAngles, 2);
		if (skyFogColor != null)
			skyFogColor = HDUtils.ensureArrayLength(skyFogColor, 3);
		if (profile == null)
			throw new IllegalStateException("Invalid sky profile");
		profile.normalize();
	}

	public boolean hasExplicitMoonlight() {
		return !derivedMoonDirectionalStrength || !derivedMoonAmbientStrength;
	}

	@SuppressWarnings("unused")
	public static class SkyProfile {
		private Keyframe[] zenith;
		private Keyframe[] horizon;
		private Keyframe[] sunGlow;

		private static class Keyframe {
			private float altitude;
			@JsonAdapter(SrgbToLinearAdapter.class)
			private float[] color;
		}

		public void normalize() {
			normalizeKeyframes(zenith);
			normalizeKeyframes(horizon);
			normalizeKeyframes(sunGlow);
		}

		private static void normalizeKeyframes(@Nullable Keyframe[] keyframes) {
			if (keyframes == null || keyframes.length == 0)
				throw new IllegalStateException("Missing sky keyframes");
			float previousAltitude = Float.NEGATIVE_INFINITY;
			for (int i = 0; i < keyframes.length; i++) {
				Keyframe keyframe = keyframes[i];
				if (keyframe == null || keyframe.altitude <= previousAltitude)
					throw new IllegalStateException("Sky keyframes must be ordered by altitude");
				if (keyframe.color == null)
					throw new IllegalStateException("Expected a sky color keyframe");
				keyframe.color = HDUtils.ensureArrayLength(keyframe.color, 3);
				previousAltitude = keyframe.altitude;
			}
		}

		private static void interpolate(float[] out, float altitude, Keyframe[] keyframes) {
			int end = keyframes.length - 1;
			int i = 0;
			while (i < end && altitude > keyframes[i + 1].altitude)
				i++;
			Keyframe from = keyframes[i];
			if (i == end) {
				copyTo(out, from.color);
				return;
			}
			Keyframe to = keyframes[i + 1];
			mix(out, from.color, to.color, saturate((altitude - from.altitude) / (to.altitude - from.altitude)));
		}
	}

	/**
	 * Interpolate shader parameters. Lighting, disk color, gradients, and celestial state
	 * are evaluated separately before blending.
	 */
	public SkyConfiguration interpolateLightingParameters(SkyConfiguration from, SkyConfiguration to, float t) {
		horizonWidth = mix(from.horizonWidth, to.horizonWidth, t);
		// Sky fog defaults are resolved against the environment before interpolation by the renderer.
		starVisibility = mix(from.starVisibility, to.starVisibility, t);
		nebulaVisibility = mix(from.nebulaVisibility, to.nebulaVisibility, t);
		auroraVisibility = mix(from.auroraVisibility, to.auroraVisibility, t);
		moonSizeMult = mix(from.moonSizeMult, to.moonSizeMult, t);
		starHorizonHeight = mix(from.starHorizonHeight, to.starHorizonHeight, t);
		return this;
	}

	public void evaluateGradient(GradientSample out, float sunAltitudeDegrees, float[] fogColor) {
		float takeover = max(0, skyColorTakeoverAngle);
		SkyProfile.interpolate(out.zenith, sunAltitudeDegrees, profile.zenith);
		SkyProfile.interpolate(out.horizon, sunAltitudeDegrees, profile.horizon);
		SkyProfile.interpolate(out.sunGlow, sunAltitudeDegrees, profile.sunGlow);
		// Authored gradients bypass the automatic fog takeover and night-color replacement.
		if (customGradient)
			return;
		float[] nightColor = multiply(nightHorizonColor, nightHorizonStrength);
		if (fogColor != null && sunStrength < 1) {
			float window = smoothstep(-25, 0, sunAltitudeDegrees);
			float suppression = (1 - sunStrength) * window;
			if (suppression > 0) {
				float nightBlend = smoothstep(5, -5, sunAltitudeDegrees);
				for (int i = 0; i < 3; i++) {
					float target = mix(fogColor[i], nightColor[i], nightBlend);
					out.zenith[i] = mix(out.zenith[i], target, suppression);
					out.horizon[i] = mix(out.horizon[i], target, suppression);
				}
				multiply(out.sunGlow, out.sunGlow, 1 - suppression);
			}
		}
		if (fogColor != null && sunriseSunsetStrength < 1) {
			float window = sunAltitudeDegrees < 0 ?
				smoothstep(-15, 0, sunAltitudeDegrees) :
				takeover == 0 ? 0 : smoothstep(takeover, 0, sunAltitudeDegrees);
			float suppression = (1 - sunriseSunsetStrength) * window;
			if (suppression > 0) {
				blendSky(out.zenith, out.horizon, fogColor, suppression);
				multiply(out.sunGlow, out.sunGlow, 1 - suppression);
			}
		}
		if (fogColor != null) {
			float blend = sunAltitudeDegrees < 0 ? 0 : takeover == 0 ? 1 : smoothstep(0, takeover, sunAltitudeDegrees);
			if (blend > 0)
				blendSky(out.zenith, out.horizon, fogColor, blend);
		}
		// Preserve the twilight gradient through civil dusk, then fade to the night tint.
		float nightBlend = smoothstep(-6, -18, sunAltitudeDegrees);
		if (nightBlend > 0)
			blendSky(out.zenith, out.horizon, nightColor, nightBlend);
	}

	private static void blendSky(float[] zenith, float[] horizon, float[] color, float t) {
		mix(zenith, zenith, color, t);
		mix(horizon, horizon, color, t);
	}

	@Slf4j
	public static class Adapter implements TypeAdapterFactory {
		private final JsonParser JSON_ELEMENT_PARSER = new JsonParser();

		@Override
		@SuppressWarnings("unchecked")
		public <T> TypeAdapter<T> create(Gson gson, TypeToken<T> typeToken) {
			if (typeToken.getRawType() != SkyConfiguration.class)
				return null;

			TypeAdapter<SkyConfiguration> delegate = gson.getDelegateAdapter(this, TypeToken.get(SkyConfiguration.class));
			TypeAdapter<JsonElement> jsonElementAdapter = gson.getAdapter(JsonElement.class);
			return (TypeAdapter<T>) new TypeAdapter<SkyConfiguration>() {
				private JsonObject toDefinition(SkyConfiguration sky) {
					JsonObject json = delegate.toJsonTree(sky).getAsJsonObject();
					// Derived values must not become authored overrides through inheritance or serialization.
					if (sky.derivedMoonDirectionalColor)
						json.remove("moonDirectionalColor");
					if (sky.derivedMoonAmbientColor)
						json.remove("moonAmbientColor");
					if (sky.derivedMoonDirectionalStrength)
						json.remove("moonDirectionalStrength");
					if (sky.derivedMoonAmbientStrength)
						json.remove("moonAmbientStrength");
					return json;
				}

				@Nullable
				private SkyConfiguration resolveParent(String name, String location) {
					SkyConfiguration parent = SkyManager.PRESETS.get(name);
					if (parent == null)
						log.error("Unknown sky parent '{}' at {}; ignoring sky", name, location);
					return parent;
				}

				@Override
				public SkyConfiguration read(JsonReader in) throws IOException {
					JsonToken token = in.peek();
					if (token == JsonToken.NULL) {
						in.nextNull();
						return null;
					}

					String location = GsonUtils.location(in);
					if (token == JsonToken.STRING)
						return resolveParent(in.nextString(), location);

					if (token != JsonToken.BEGIN_OBJECT) {
						log.error("Expected a sky preset or object at {}; ignoring value", location);
						in.skipValue();
						return null;
					}

					JsonObject override = JSON_ELEMENT_PARSER.parse(in).getAsJsonObject();

					JsonElement parentElement = override.get("parent");
					SkyConfiguration parent = DEFAULT_PRESET;
					if (parentElement != null) {
						if (!parentElement.isJsonPrimitive() || !parentElement.getAsJsonPrimitive().isString()) {
							log.error("Sky parent must be a string at {}; ignoring sky", location);
							return null;
						}
						parent = resolveParent(parentElement.getAsString(), location);
						if (parent == null)
							return null;
						if (override.size() == 1)
							return parent;
					}

					if (parent == null) {
						log.error("No default sky preset at {}; ignoring sky", location);
						return null;
					}
					var parentJson = toDefinition(parent);
					GsonUtils.removeNulls(parentJson);
					parentJson.remove("name");
					parentJson.remove("parent");
					GsonUtils.deepInheritFrom(override, parentJson);
					try {
						return delegate.fromJsonTree(override);
					} catch (RuntimeException ex) {
						log.error("Invalid sky configuration at {}; ignoring sky: {}", location, ex.getMessage());
						return null;
					}
				}

				@Override
				public void write(JsonWriter out, SkyConfiguration sky) throws IOException {
					if (sky == null) {
						out.nullValue();
						return;
					}
					JsonObject json = toDefinition(sky);
					var base = DEFAULT_PRESET;
					if (sky.parent != null)
						base = SkyManager.PRESETS.getOrDefault(sky.parent, base);
					if (base == null) {
						jsonElementAdapter.write(out, json);
						return;
					}
					JsonObject baseJson = toDefinition(base);
					GsonUtils.removeMatching(json, baseJson);
					if (json.size() == 0) {
						if (sky.parent == null || base == DEFAULT_PRESET) {
							out.nullValue();
						} else {
							out.value(sky.parent);
						}
					} else {
						jsonElementAdapter.write(out, json);
					}
				}
			};
		}
	}
}

