@Slf4j
@Singleton
public final class StarField {
	private static final float[] UP_VECTOR = { 0, 1, 0 };
	private static final float[] LEFT_VECTOR = { 1, 0, 0 };

	private static final float[][] STAR_COLORS = {
		colorTemperatureToLinearRgb(4000),
		colorTemperatureToLinearRgb(5000),
		colorTemperatureToLinearRgb(6000),
		colorTemperatureToLinearRgb(7000),
		colorTemperatureToLinearRgb(9000),
		colorTemperatureToLinearRgb(12000),
	};

	static {
		// Temperature colors have unit luminance. Retain roughly the old palette's
		// mean luminance while keeping temperature independent of stellar brightness.
		for (float[] color : STAR_COLORS)
			multiply(color, color, 0.78f);
	}

	// VBO layout: direction.xyz, size, brightness, color.rgb, artistic rotation speed.
	private static final int FLOATS_PER_STAR = 9;

	// Match the old field's density independently of screen resolution.
	private static final int BRIGHT_STAR_COUNT = 350;   // layer 0: sparse/bright/large
	private static final int DIM_STAR_COUNT = 2200;     // layer 1: dense/dim/small
	private static final int CLUSTER_STAR_COUNT = 1600; // layer 2: clustered
	private static final int MAX_STAR_COUNT = BRIGHT_STAR_COUNT + DIM_STAR_COUNT + CLUSTER_STAR_COUNT;

	public static final int CLUSTER_COUNT = 12;
	private static final float CLUSTER_ANGULAR_SPREAD = 0.09f;

	private static final int NEBULA_CUBE_MAP_RESOLUTION = 512;

	@Inject
	private HdPlugin plugin;

	@Inject
	private HdPluginConfig config;

	@Inject
	private NebulaBakeShaderProgram nebulaBakeProgram;

	private final Random random = new Random(SEED);
	private final RenderState nebulaBakeRenderState = new RenderState();

	private int texNebulaCubemap;
	private int fboNebulaBake;

	@Getter
	private int vaoStars;
	@Getter
	private int vaoStarTriangles;

	public int starCount;

	private GLBuffer vboStars;

	private boolean starGeometryCurrent;
	private boolean nebulaMapCurrent;

	public void initialize() {
		resetStarfield();

		vaoStars = glGenVertexArrays();
		vaoStarTriangles = glGenVertexArrays();

		vboStars = new GLBuffer("Stars::VBO", GL_ARRAY_BUFFER, GL_STATIC_DRAW);
		vboStars.initialize(FLOATS_PER_STAR * MAX_STAR_COUNT);
		vboStars.bind();

		int stride = FLOATS_PER_STAR * Float.BYTES;
		for (int divisor = 0; divisor <= 1; divisor++) {
			glBindVertexArray(divisor == 0 ? vaoStars : vaoStarTriangles);
			// Each VAO owns its attribute layout; only the underlying buffer is shared.
			// direction.xyz, size, brightness, color.rgb, artistic rotation speed
			glVertexAttribPointer(0, 3, GL_FLOAT, false, stride, 0L);
			glVertexAttribPointer(1, 1, GL_FLOAT, false, stride, 3L * Float.BYTES);
			glVertexAttribPointer(2, 1, GL_FLOAT, false, stride, 4L * Float.BYTES);
			glVertexAttribPointer(3, 3, GL_FLOAT, false, stride, 5L * Float.BYTES);
			glVertexAttribPointer(4, 1, GL_FLOAT, false, stride, 8L * Float.BYTES);
			for (int i = 0; i < 5; i++) {
				glEnableVertexAttribArray(i);
				glVertexAttribDivisor(i, divisor);
			}
		}
		glBindVertexArray(0);
		glBindBuffer(GL_ARRAY_BUFFER, 0);

		fboNebulaBake = glGenFramebuffers();
		texNebulaCubemap = glGenTextures();

		glActiveTexture(TEXTURE_UNIT_NEBULA_MAP);
		glBindTexture(GL_TEXTURE_CUBE_MAP, texNebulaCubemap);

		for (int face = 0; face < 6; face++) {
			glTexImage2D(
				GL_TEXTURE_CUBE_MAP_POSITIVE_X + face,
				0,
				GL_RGBA16F,
				NEBULA_CUBE_MAP_RESOLUTION,
				NEBULA_CUBE_MAP_RESOLUTION,
				0,
				GL_RGBA,
				GL_FLOAT,
				0
			);
		}

		glTexParameteri(GL_TEXTURE_CUBE_MAP, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
		glTexParameteri(GL_TEXTURE_CUBE_MAP, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
		glTexParameteri(GL_TEXTURE_CUBE_MAP, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
		glTexParameteri(GL_TEXTURE_CUBE_MAP, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
		glTexParameteri(GL_TEXTURE_CUBE_MAP, GL_TEXTURE_WRAP_R, GL_CLAMP_TO_EDGE);

		glActiveTexture(TEXTURE_UNIT_UI);
		glBindTexture(GL_TEXTURE_CUBE_MAP, 0);
	}

	public void destroy() {
		if (vboStars != null)
			vboStars.destroy();
		vboStars = null;

		if (vaoStars != 0)
			glDeleteVertexArrays(vaoStars);
		vaoStars = 0;

		if (vaoStarTriangles != 0)
			glDeleteVertexArrays(vaoStarTriangles);
		vaoStarTriangles = 0;

		if (fboNebulaBake != 0)
			glDeleteFramebuffers(fboNebulaBake);
		fboNebulaBake = 0;

		if (texNebulaCubemap != 0)
			glDeleteTextures(texNebulaCubemap);
		texNebulaCubemap = 0;

		resetStarfield();
	}

	public void initializeShaders(ShaderIncludes includes) throws ShaderException, IOException {
		nebulaBakeProgram.compile(includes);
	}

	public void destroyShaders() {
		nebulaBakeProgram.destroy();
	}

	public void resetStarfield() {
		starGeometryCurrent = false;
		nebulaMapCurrent = false;
	}

	public boolean rebuildIfNeeded() {
		boolean rebuilt = false;
		if (!starGeometryCurrent) {
			random.setSeed(SEED);
			FloatBuffer vertexData = BufferUtils.createFloatBuffer(MAX_STAR_COUNT * FLOATS_PER_STAR);

			generateLayer(vertexData, BRIGHT_STAR_COUNT, 1.2f, 1.0f, 1);
			generateLayer(vertexData, DIM_STAR_COUNT, 0.4f, 0.8f, .7f);

			if (config.enableNebulae())
				generateClusteredLayer(vertexData, CLUSTER_STAR_COUNT, CLUSTER_COUNT, CLUSTER_ANGULAR_SPREAD, 0.5f, 0.5f, 1);

			starCount = vertexData.position() / FLOATS_PER_STAR;
			vboStars.upload(vertexData.flip());
			starGeometryCurrent = true;
			rebuilt = true;
		}

		if (!config.enableNebulae() || nebulaMapCurrent || fboNebulaBake == 0 || texNebulaCubemap == 0 || !nebulaBakeProgram.isValid())
			return rebuilt;

		nebulaBakeRenderState.framebuffer.set(GL_FRAMEBUFFER, fboNebulaBake);
		nebulaBakeRenderState.viewport.set(0, 0, NEBULA_CUBE_MAP_RESOLUTION, NEBULA_CUBE_MAP_RESOLUTION);
		nebulaBakeRenderState.vao.setVao(plugin.vaoTri);
		nebulaBakeRenderState.disable.set(GL_DEPTH_TEST);
		nebulaBakeRenderState.disable.set(GL_BLEND);
		nebulaBakeRenderState.disable.set(GL_CULL_FACE);
		nebulaBakeRenderState.apply();

		plugin.uboSky.upload();

		nebulaBakeProgram.use();
		for (int face = 0; face < 6; face++) {
			nebulaBakeProgram.uniCubeFace.set(face);
			glFramebufferTexture2D(
				GL_FRAMEBUFFER,
				GL_COLOR_ATTACHMENT0,
				GL_TEXTURE_CUBE_MAP_POSITIVE_X + face,
				texNebulaCubemap,
				0
			);
			glDrawArrays(GL_TRIANGLES, 0, 3);
		}

		glBindFramebuffer(GL_FRAMEBUFFER, 0);
		nebulaBakeRenderState.reset();
		nebulaMapCurrent = true;
		return true;
	}

	private void generateLayer(FloatBuffer vertexBuffer, int count, float maxBrightness, float sizeScale, float artisticRotationSpeed) {
		final float[] center = new float[3];
		for (int i = 0; i < count; i++) {
			randomPointOnSphere(center, random);
			writeStar(vertexBuffer, center, maxBrightness, sizeScale, artisticRotationSpeed, 1);
		}
	}

	private void generateClusteredLayer(
		FloatBuffer vertexBuffer,
		int count,
		int clusterCount,
		float angularSpread,
		float maxBrightness,
		float sizeScale,
		float artisticRotationSpeed
	) {
		final float[][] clusterCenters = new float[clusterCount][3];
		final float[][] clusterTangentU = new float[clusterCount][3];
		final float[][] clusterTangentV = new float[clusterCount][3];

		for (int c = 0; c < clusterCount; c++) {
			final float[] dir = clusterCenters[c];
			final float[] u = clusterTangentU[c];
			final float[] v = clusterTangentV[c];

			randomPointOnSphere(dir, random);

			cross(u, dir, (Math.abs(dir[1]) < 0.99f) ? UP_VECTOR : LEFT_VECTOR);
			normalize(u, u);
			cross(v, dir, u);

			plugin.uboSky.nebulaClusters[c].set(dir[0], dir[1], dir[2], CLUSTER_ANGULAR_SPREAD * 0.5f);
		}

		float[] pos = new float[3];

		for (int i = 0; i < count; i++) {
			final int c = random.nextInt(clusterCount);

			final float[] dir = clusterCenters[c];
			final float[] u = clusterTangentU[c];
			final float[] v = clusterTangentV[c];

			float radius = min(abs((float) random.nextGaussian()), 3) * angularSpread;
			float theta = (float) (random.nextFloat() * 2.0 * PI);
			float cosR = cos(radius);
			float sinR = sin(radius);
			float cosT = cos(theta);
			float sinT = sin(theta);
			for (int j = 0; j < 3; j++)
				pos[j] = cosR * dir[j] + sinR * (cosT * u[j] + sinT * v[j]);

			writeStar(vertexBuffer, pos, maxBrightness, sizeScale, artisticRotationSpeed, .5f);
		}
	}

	private void writeStar(
		FloatBuffer vertexBuffer,
		float[] position,
		float maxBrightness,
		float sizeScale,
		float artisticRotationSpeed,
		float brightnessScale
	) {
		// Power-law brightness: many dim, few bright (matches pow(seed, 2.5)).
		float brightnessSeed = random.nextFloat();
		float brightness = min(pow(brightnessSeed, 2.5f) * maxBrightness, .4f) * brightnessScale;

		// Per-star size variation, skewed toward the small end (squaring the
		// random factor biases most stars small with only a few larger ones),
		// scaled per layer. Range ~0.4x to 1.0x.
		float sizeSeed = random.nextFloat();
		float size = (0.4f + sizeSeed * sizeSeed * 0.6f) * sizeScale;

		// Representative stellar temperatures, rather than independent RGB tints.
		final float[] starColor = STAR_COLORS[random.nextInt(STAR_COLORS.length)];

		vertexBuffer
			.put(position)
			.put(size)
			.put(brightness)
			.put(starColor)
			.put(artisticRotationSpeed);
	}
}

package rs117.hd.scene.environments;

import com.google.gson.annotations.JsonAdapter;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import rs117.hd.scene.AreaManager;
import rs117.hd.scene.areas.Area;
import rs117.hd.scene.daylight_cycle.SkyConfiguration;
import rs117.hd.utils.ColorUtils;
import rs117.hd.utils.ExpressionParser;
import rs117.hd.utils.ExpressionPredicate;
import rs117.hd.utils.GsonUtils.DegreesToRadians;
import rs117.hd.utils.HDUtils;

import static rs117.hd.utils.ColorUtils.SrgbToLinearAdapter;
import static rs117.hd.utils.ColorUtils.rgb;
import static rs117.hd.utils.MathUtils.*;

@Slf4j
@Setter(value = AccessLevel.PRIVATE)
public class Environment {
	private static final float[] DEFAULT_SHADOW_ANGLES = HDUtils.sunAngles(52, 235);
	private static final float[] DEFAULT_FOG_COLOR = rgb("#000000");
	private static final float[] DEFAULT_WATER_COLOR = rgb("#66eaff");
	public static final Environment DEFAULT = new Environment()
		.setKey("DEFAULT")
		.setArea(Area.ALL)
		.setAmbientColor(rgb("#ffffff"))
		.setAmbientStrength(1)
		.setFogColor(DEFAULT_FOG_COLOR)
		.setWaterColor(DEFAULT_WATER_COLOR)
		.setShadowAngles(DEFAULT_SHADOW_ANGLES)
		.normalize();
	public static final Environment NONE = new Environment()
		.setKey("NONE")
		.setFogColor(rgb("#ff00ff"))
		.normalize();

	public static Environment OVERWORLD, AUTUMN, WINTER;

	public String key;
	@JsonAdapter(AreaManager.Adapter.class)
	public Area area = Area.NONE;
	public boolean isOverworld = false;
	public boolean isPohTheme = false;
	public boolean isLegacyTob = false;
	public boolean isUnderwater = false;
	public boolean force = false;
	public boolean allowSkyOverride = true;
	public boolean allowRoofShadows = true;
	public boolean lightningEffects = false;
	public boolean instantTransition = false;
	@JsonAdapter(ExpressionParser.PredicateAdapter.class)
	public ExpressionPredicate varbitCondition = ExpressionPredicate.TRUE;
	@JsonAdapter(ExpressionParser.PredicateAdapter.class)
	public ExpressionPredicate varpCondition = ExpressionPredicate.TRUE;
	@JsonAdapter(SrgbToLinearAdapter.class)
	@Getter
	private float[] ambientColor;
	public float ambientStrength = -1;
	@JsonAdapter(SrgbToLinearAdapter.class)
	@Getter
	private float[] directionalColor = rgb("#ffffff");
	public float directionalStrength = .25f;
	@JsonAdapter(SrgbToLinearAdapter.class)
	@Getter
	private float[] waterColor;
	@JsonAdapter(SrgbToLinearAdapter.class)
	@Getter
	private float[] waterCausticsColor;
	public float waterCausticsStrength = -1;
	@JsonAdapter(SrgbToLinearAdapter.class)
	@Getter
	private float[] underglowColor = rgb("#000000");
	public float underglowStrength = 0;
	@JsonAdapter(DegreesToRadians.class)
	@Getter
	private float[] shadowAngles; // horizontal coordinate system, in radians
	@JsonAdapter(SrgbToLinearAdapter.class)
	@Getter
	private float[] fogColor;
	public float fogDepth = 25;
	public float groundFogStart = -200;
	public float groundFogEnd = -500;
	public float groundFogOpacity = 0;
	@JsonAdapter(DegreesToRadians.class)
	public float windAngle = 0.0f;
	public float windSpeed = 15.0f;
	public float windStrength = 0.0f;
	public float windCeiling = 1280.0f;
	@JsonAdapter(SkyConfiguration.Adapter.class)
	@Nullable
	private SkyConfiguration sky;
	public boolean hideVanillaSkyboxes = false;
	public float nightExposure = 1;

	public transient boolean hasWaterColorOverride;
	public transient boolean hasFogColorOverride;
	private transient boolean normalized;

	public Environment normalize() {
		if (area == null)
			area = Area.NONE;
		if (varbitCondition == null)
			varbitCondition = ExpressionPredicate.TRUE;
		if (varpCondition == null)
			varpCondition = ExpressionPredicate.TRUE;
		if (directionalColor == null)
			directionalColor = rgb("#ffffff");
		directionalColor = HDUtils.ensureArrayLength(directionalColor, 3);
		if (underglowColor == null)
			underglowColor = rgb("#000000");

		if (!normalized) {
			hasFogColorOverride = fogColor != null;
			hasWaterColorOverride = waterColor != null;
		}
		if (fogColor == null)
			fogColor = DEFAULT_FOG_COLOR;
		if (waterColor == null)
			waterColor = DEFAULT_WATER_COLOR;

		if (area != Area.ALL && area != Area.NONE) {
			isOverworld = Area.OVERWORLD.intersects(area);
			if (!isOverworld) {
				if (!hasFogColorOverride) {
					fogColor = DEFAULT.fogColor;
					hasFogColorOverride = true;
				}
				if (!hasWaterColorOverride) {
					waterColor = DEFAULT.waterColor;
					hasWaterColorOverride = true;
				}
			}
		}

		if (ambientColor == null) {
			if (isOverworld) {
				ambientColor = new float[3];
				ColorUtils.deriveAmbientLight(ambientColor, directionalColor);
			} else {
				ambientColor = DEFAULT.ambientColor;
			}
		}
		ambientColor = HDUtils.ensureArrayLength(ambientColor, 3);
		if (ambientStrength < 0)
			ambientStrength = isOverworld ? directionalStrength : DEFAULT.ambientStrength;

		if (shadowAngles == null) {
			shadowAngles = DEFAULT_SHADOW_ANGLES;
		} else {
			shadowAngles = HDUtils.ensureArrayLength(shadowAngles, 2);
		}

		if (waterCausticsColor == null)
			waterCausticsColor = directionalColor;
		if (waterCausticsStrength == -1)
			waterCausticsStrength = directionalStrength;

		fogDepth = max(0, fogDepth);

		if (sky != null)
			sky.normalize();

		normalized = true;
		return this;
	}

	public SkyConfiguration getSky() {
		return sky != null ? sky : SkyConfiguration.DEFAULT_PRESET;
	}

	public Environment copy() {
		var env = new Environment();
		env.fogColor = new float[3];
		env.waterColor = new float[3];
		env.ambientColor = new float[3];
		env.directionalColor = new float[3];
		env.underglowColor = new float[3];
		env.shadowAngles = new float[3];
		env.waterCausticsColor = new float[3];
		this.copyTo(env);
		return env;
	}

	public void copyTo(Environment target) {
		target.interpolate(this, this, 0);
	}

	public Environment interpolate(Environment from, Environment to, float t) {
		mix(fogColor, from.fogColor, to.fogColor, t);
		mix(waterColor, from.waterColor, to.waterColor, t);
		mix(ambientColor, from.ambientColor, to.ambientColor, t);
		mix(directionalColor, from.directionalColor, to.directionalColor, t);
		mix(underglowColor, from.underglowColor, to.underglowColor, t);
		mix(shadowAngles, from.shadowAngles, to.shadowAngles, t);
		mix(waterCausticsColor, from.waterCausticsColor, to.waterCausticsColor, t);
		fogDepth = mix(from.fogDepth, to.fogDepth, t);
		nightExposure = mix(from.nightExposure, to.nightExposure, t);
		ambientStrength = mix(from.ambientStrength, to.ambientStrength, t);
		directionalStrength = mix(from.directionalStrength, to.directionalStrength, t);
		underglowStrength = mix(from.underglowStrength, to.underglowStrength, t);
		groundFogStart = mix(from.groundFogStart, to.groundFogStart, t);
		groundFogEnd = mix(from.groundFogEnd, to.groundFogEnd, t);
		groundFogOpacity = mix(from.groundFogOpacity, to.groundFogOpacity, t);
		waterCausticsStrength = mix(from.waterCausticsStrength, to.waterCausticsStrength, t);
		windAngle = mix(from.windAngle, to.windAngle, t);
		windSpeed = mix(from.windSpeed, to.windSpeed, t);
		windStrength = mix(from.windStrength, to.windStrength, t);
		windCeiling = mix(from.windCeiling, to.windCeiling, t);
		sky = t == 1 ? to.sky : from.sky;
		return this;
	}

	@Override
	public String toString() {
		return key != null ? key : area.name;
	}
}

package rs117.hd.scene.ground_materials;

import com.google.gson.TypeAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import rs117.hd.scene.GroundMaterialManager;
import rs117.hd.scene.materials.Material;
import rs117.hd.utils.GsonUtils;

@Getter
@Slf4j
public class GroundMaterial {
	public static final GroundMaterial NONE = new GroundMaterial("NONE", Material.NONE);

	public static GroundMaterial DIRT;
	public static GroundMaterial UNDERWATER_GENERIC;

	public final String name;
	private final Material[] materials;

	public GroundMaterial(String name, Material... materials) {
		this.name = name;
		this.materials = materials;
	}

	public void normalize() {
		for (int j = 0; j < materials.length; j++)
			if (materials[j] == null)
				materials[j] = Material.NONE;
	}

	public Material getRandomMaterial(int[] worldPos) {
		assert worldPos.length == 3;
		return getRandomMaterial(worldPos[0], worldPos[1], worldPos[2]);
	}

	/**
	 * Get a random material based on the given coordinates.
	 */
	public Material getRandomMaterial(int x, int y, int z) {
		long hash = x;
		hash = hash * 31 + y;
		hash = hash * 31 + z;
		long seed = (hash ^ 0x5DEECE66DL) & ((1L << 48) - 1);
		seed = (seed * 0x5DEECE66DL + 0xBL) & ((1L << 48) - 1);
		int r = (int) (seed >>> (48 - 31));
		return materials[r % materials.length];
	}

	@Override
	public String toString() {
		return name;
	}

	@Slf4j
	public static class Adapter extends TypeAdapter<GroundMaterial> {
		@Override
		public GroundMaterial read(JsonReader in) throws IOException {
			if (in.peek() == JsonToken.NULL)
				return null;

			if (in.peek() == JsonToken.STRING) {
				String name = in.nextString();
				for (var groundMaterial : GroundMaterialManager.GROUND_MATERIALS)
					if (name.equals(groundMaterial.name))
						return groundMaterial;

				log.warn("No ground material exists with the name '{}' at {}", name, GsonUtils.location(in), new Throwable());
			} else {
				log.warn("Unexpected type {} at {}", in.peek(), GsonUtils.location(in), new Throwable());
			}

			return null;
		}

		@Override
		public void write(JsonWriter out, GroundMaterial groundMaterial) throws IOException {
			if (groundMaterial == null) {
				out.nullValue();
			} else {
				out.value(groundMaterial.name);
			}
		}
	}
}

