package rs117.hd.utils.buffer;

import java.nio.ByteBuffer;
import java.nio.FloatBuffer;
import java.nio.IntBuffer;
import lombok.extern.slf4j.Slf4j;
import org.lwjgl.opengl.*;
import rs117.hd.utils.Destructible;
import rs117.hd.utils.DestructibleHandler;

import static org.lwjgl.opengl.GL33C.*;
import static org.lwjgl.opengl.GL44.GL_CLIENT_STORAGE_BIT;
import static org.lwjgl.opengl.GL44.GL_DYNAMIC_STORAGE_BIT;
import static org.lwjgl.opengl.GL44.GL_MAP_PERSISTENT_BIT;
import static org.lwjgl.opengl.GL44.glBufferStorage;
import static rs117.hd.HdPlugin.GL_CAPS;
import static rs117.hd.HdPlugin.SUPPORTS_STORAGE_BUFFERS;
import static rs117.hd.HdPlugin.checkGLErrors;
import static rs117.hd.utils.MathUtils.*;

@Slf4j
public class GLBuffer implements Destructible {
	private static ByteBuffer COPY_READ_BUFFER, COPY_WRITE_BUFFER;
	public static final boolean DEBUG_MAC_OS = false;

	public static final int STORAGE_NONE = 0;
	public static final int STORAGE_PERSISTENT = 1;
	public static final int STORAGE_IMMUTABLE = 2;
	public static final int STORAGE_CLIENT = 4;
	public static final int STORAGE_READ = 8;
	public static final int STORAGE_WRITE = 16;

	public static final int MAP_READ = 1;
	public static final int MAP_WRITE = 2;
	public static final int MAP_UNSYNCHRONIZED = 4;
	public static final int MAP_INVALIDATE = 8;

	public final int target;
	public final int usage;

	public String name;
	public int storageFlags;

	public int id;
	public long size;

	private GLMappedBuffer mappedBuffer;

	public GLBuffer(String name, int target, int usage, int storageFlags) {
		assert target != GL_ELEMENT_ARRAY_BUFFER || this instanceof EBO;
		this.name = name;
		this.target = target;
		this.usage = usage;
		this.storageFlags = storageFlags;
	}

	public GLBuffer(String name, int target, int usage) {
		this(name, target, usage, STORAGE_NONE);
	}

	private static void copyRangeTo(int src, int dst, long srcOffsetBytes, long dstOffsetBytes, long numBytes) {
		copyRangesTo(src, dst, new long[] { srcOffsetBytes }, new long[] { dstOffsetBytes }, new long[] { numBytes }, 1);
	}

	private static void copyRangeTo(GLBuffer src, GLBuffer dst, long srcOffsetBytes, long dstOffsetBytes, long numBytes) {
		copyRangesTo(src, dst, new long[] { srcOffsetBytes }, new long[] { dstOffsetBytes }, new long[] { numBytes }, 1);
	}

	private static void copyRangesTo(
		GLBuffer src,
		GLBuffer dst,
		long[] srcOffsetBytes,
		long[] dstOffsetBytes,
		long[] numBytes,
		int count
	) {
		assert !src.isMapped() || src.isStorageBuffer();
		assert !dst.isMapped() || dst.isStorageBuffer();
		copyRangesTo(src.id, dst.id, srcOffsetBytes, dstOffsetBytes, numBytes, count);
	}

	private static void copyRangesTo(
		int srcId,
		int dstId,
		long[] srcOffsetBytes,
		long[] dstOffsetBytes,
		long[] numBytes,
		int count
	) {
		assert count > 0;

		glBindBuffer(GL_COPY_READ_BUFFER, srcId);
		glBindBuffer(GL_COPY_WRITE_BUFFER, dstId);

		try {
			count = sortAndMergeRanges(srcOffsetBytes, dstOffsetBytes, numBytes, count);

			if (GL_CAPS.GL_ARB_copy_buffer && !DEBUG_MAC_OS) {
				copyWithCopyBuffer(srcOffsetBytes, dstOffsetBytes, numBytes, count);
			} else if (GL_CAPS.GL_ARB_map_buffer_range && !DEBUG_MAC_OS) {
				copyWithMapBufferRange(srcId, dstId, srcOffsetBytes, dstOffsetBytes, numBytes, count);
			} else {
				copyWithMapBuffer(srcId, dstId, srcOffsetBytes, dstOffsetBytes, numBytes, count);
			}

			if (checkGLErrors()) {
				long srcSizeBytes = glGetBufferParameteri64(GL_COPY_READ_BUFFER, GL_BUFFER_SIZE);
				long dstSizeBytes = glGetBufferParameteri64(GL_COPY_WRITE_BUFFER, GL_BUFFER_SIZE);
				log.error("Errors copying buffers src: {} dst: {} srcSize: {} dstSize: {}", srcId, dstId, srcSizeBytes, dstSizeBytes);
			}
		} finally {
			glBindBuffer(GL_COPY_READ_BUFFER, 0);
			glBindBuffer(GL_COPY_WRITE_BUFFER, 0);
		}
	}

	private static int sortAndMergeRanges(
		long[] src,
		long[] dst,
		long[] size,
		int count
	) {
		if (count <= 1)
			return count;

		// Sort by dst offset
		for (int i = 1; i < count; i++) {
			long dstKey = dst[i];
			long srcKey = src[i];
			long sizeKey = size[i];

			int j = i - 1;
			while (j >= 0 && dst[j] > dstKey) {
				dst[j + 1] = dst[j];
				src[j + 1] = src[j];
				size[j + 1] = size[j];
				j--;
			}

			dst[j + 1] = dstKey;
			src[j + 1] = srcKey;
			size[j + 1] = sizeKey;
		}

		// Merge adjacent ranges after sort
		int write = 0;
		for (int read = 1; read < count; read++) {
			long prevSrc = src[write];
			long prevDst = dst[write];
			long prevSize = size[write];

			long currSrc = src[read];
			long currDst = dst[read];
			long currSize = size[read];

			boolean adjacent =
				(prevDst + prevSize == currDst) &&
				(prevSrc + prevSize == currSrc);

			if (adjacent) {
				size[write] += currSize;
			} else {
				write++;
				src[write] = currSrc;
				dst[write] = currDst;
				size[write] = currSize;
			}
		}

		return write + 1;
	}

	private static void copyWithCopyBuffer(long[] src, long[] dst, long[] size, int count) {
		for (int i = 0; i < count; i++)
			glCopyBufferSubData(GL_COPY_READ_BUFFER, GL_COPY_WRITE_BUFFER, src[i], dst[i], size[i]);
	}

	private static void copyWithMapBufferRange(
		int srcId,
		int dstId,
		long[] srcOffsetBytes,
		long[] dstOffsetBytes,
		long[] numBytes,
		int count
	) {
		long srcMinOffset = Long.MAX_VALUE, dstMinOffset = Long.MAX_VALUE;
		long srcEnd = 0, dstEnd = 0;
		boolean contiguous = true;

		for (int i = 0; i < count; i++) {
			if (i > 0 && contiguous)
				contiguous = dstOffsetBytes[i - 1] + numBytes[i - 1] == dstOffsetBytes[i];

			srcMinOffset = min(srcMinOffset, srcOffsetBytes[i]);
			dstMinOffset = min(dstMinOffset, dstOffsetBytes[i]);
			srcEnd = max(srcEnd, srcOffsetBytes[i] + numBytes[i]);
			dstEnd = max(dstEnd, dstOffsetBytes[i] + numBytes[i]);
		}

		ByteBuffer src = null, dst = null;
		try {
			src = glMapBufferRange(GL_COPY_READ_BUFFER, srcMinOffset, srcEnd - srcMinOffset, GL_MAP_READ_BIT, COPY_READ_BUFFER);
			if (src == null)
				throw new IllegalStateException(String.format(
					"Failed to map copy source buffer %d, offset: %d, size: %d bytes",
					srcId, srcMinOffset, srcEnd - srcMinOffset));
			COPY_READ_BUFFER = src;

			dst = glMapBufferRange(
				GL_COPY_WRITE_BUFFER,
				dstMinOffset,
				dstEnd - dstMinOffset,
				GL_MAP_WRITE_BIT | (contiguous ? GL_MAP_INVALIDATE_RANGE_BIT : GL_MAP_FLUSH_EXPLICIT_BIT),
				COPY_WRITE_BUFFER
			);
			if (dst == null)
				throw new IllegalStateException(String.format(
					"Failed to map copy destination buffer %d, offset: %d, size: %d bytes",
					dstId, dstMinOffset, dstEnd - dstMinOffset));
			COPY_WRITE_BUFFER = dst;

			performCopies(
				src, dst,
				srcMinOffset, dstMinOffset,
				srcOffsetBytes, dstOffsetBytes, numBytes,
				count, !contiguous
			);
		} finally {
			unmapCopyBuffers(src, dst, srcId, dstId);
		}
	}

	private static void copyWithMapBuffer(
		int srcId,
		int dstId,
		long[] srcOffsetBytes,
		long[] dstOffsetBytes,
		long[] numBytes,
		int count
	) {
		ByteBuffer src = null, dst = null;
		try {
			src = glMapBuffer(GL_COPY_READ_BUFFER, GL_READ_ONLY, COPY_READ_BUFFER);
			if (src == null)
				throw new IllegalStateException(String.format(
					"Failed to map copy source buffer %d, offset: 0, size: %d bytes",
					srcId, glGetBufferParameteri64(GL_COPY_READ_BUFFER, GL_BUFFER_SIZE)));
			COPY_READ_BUFFER = src;

			dst = glMapBuffer(GL_COPY_WRITE_BUFFER, GL_WRITE_ONLY, COPY_WRITE_BUFFER);
			if (dst == null)
				throw new IllegalStateException(String.format(
					"Failed to map copy destination buffer %d, offset: 0, size: %d bytes",
					dstId, glGetBufferParameteri64(GL_COPY_WRITE_BUFFER, GL_BUFFER_SIZE)));
			COPY_WRITE_BUFFER = dst;

			performCopies(
				src, dst,
				0, 0,
				srcOffsetBytes, dstOffsetBytes, numBytes,
				count, false
			);
		} finally {
			unmapCopyBuffers(src, dst, srcId, dstId);
		}
	}

	private static void unmapCopyBuffers(ByteBuffer src, ByteBuffer dst, int srcId, int dstId) {
		boolean srcValid = src == null || glUnmapBuffer(GL_COPY_READ_BUFFER);
		boolean dstValid = dst == null || glUnmapBuffer(GL_COPY_WRITE_BUFFER);
		if (!srcValid || !dstValid)
			throw new IllegalStateException("Corrupted buffer contents while copying from " + srcId + " to " + dstId);
	}

	private static void performCopies(
		ByteBuffer src,
		ByteBuffer dst,
		long srcBase,
		long dstBase,
		long[] srcOffsets,
		long[] dstOffsets,
		long[] sizes,
		int count,
		boolean flush
	) {
		long flushStart = -1;
		long flushEnd = -1;

		for (int i = 0; i < count; i++) {
			int srcPos = (int) (srcOffsets[i] - srcBase);
			int dstPos = (int) (dstOffsets[i] - dstBase);
			int len = (int) sizes[i];

			// Update the limit before the position, to appease internal bounds checks
			src.limit(srcPos + len);
			src.position(srcPos);

			dst.limit(dstPos + len);
			dst.position(dstPos);

			dst.put(src);

			if (flush) {
				if (flushStart == -1) {
					flushStart = dstPos;
					flushEnd = dstPos + len;
				} else if (flushEnd == dstPos) {
					flushEnd += len;
				} else {
					glFlushMappedBufferRange(GL_COPY_WRITE_BUFFER, flushStart, flushEnd - flushStart);
					flushStart = dstPos;
					flushEnd = dstPos + len;
				}
			}
		}

		if (flushStart != -1)
			glFlushMappedBufferRange(GL_COPY_WRITE_BUFFER, flushStart, flushEnd - flushStart);
	}

	public static String storageFlagsToString(int mask) {
		if (mask == STORAGE_NONE) return "STORAGE_NONE";

		StringBuilder sb = new StringBuilder();
		if ((mask & STORAGE_PERSISTENT) != 0) sb.append("STORAGE_PERSISTENT | ");
		if ((mask & STORAGE_IMMUTABLE) != 0) sb.append("STORAGE_IMMUTABLE | ");
		if ((mask & STORAGE_CLIENT) != 0) sb.append("STORAGE_CLIENT | ");
		if ((mask & STORAGE_READ) != 0) sb.append("STORAGE_READ | ");
		if ((mask & STORAGE_WRITE) != 0) sb.append("STORAGE_WRITE | ");

		if (sb.length() > 3)
			sb.setLength(sb.length() - 3);

		return sb.toString();
	}

	public GLBuffer initialize() {
		return initialize(0);
	}

	public GLBuffer initialize(long initialCapacity) {
		id = glGenBuffers();
		// Initialize both GL and CL buffers to buffers of a single byte or more,
		// to ensure that valid buffers are given to compute dispatches.
		// This is particularly important on Apple M2 Max, where an uninitialized buffer leads to a crash
		ensureCapacity(max(1, initialCapacity));
		unbind();
		return this;
	}

	public void setName(String newName) {
		if (newName != null && !newName.equals(name)) {
			name = newName;
			if (id != 0 && log.isDebugEnabled() && GL_CAPS.OpenGL43)
				GL43C.glObjectLabel(GL43C.GL_BUFFER, id, name);
		}
	}

	@Override
	public void destroy() {
		if (mappedBuffer != null)
			mappedBuffer.destroy();
		mappedBuffer = null;

		if (id != 0) {
			glDeleteBuffers(id);
			id = 0;
		}

		size = 0;
	}

	@Override
	public String toString() {
		return String.format("Name: %s, Capacity: %d", name, size);
	}

	@Override
	@SuppressWarnings("deprecation")
	protected void finalize() {
		if (id != 0)
			DestructibleHandler.queueLeakedDestruction(this);
	}

	public void orphan() {
		if (isStorageBuffer())
			throw new IllegalStateException("Not implemented for storage buffers. Perhaps via glInvalidateBufferData?");

		bind();
		glBufferData(target, size, usage);
		unbind();
	}

	public void bind() {
		glBindBuffer(target, id);
	}

	public void unbind() {
		glBindBuffer(target, 0);
	}

	public boolean ensureCapacity(long numBytes) {
		return ensureCapacity(0, numBytes);
	}

	public boolean ensureCapacity(long byteOffset, long numBytes) {
		numBytes += byteOffset;
		if (numBytes <= size) {
			bind();
			return false;
		}

		numBytes = ceilPow2(numBytes);
		if (log.isTraceEnabled()) {
			log.trace(
				"{} buffer '{}'\t{}",
				size > 0 ? "Resizing" : "Creating",
				name,
				String.format("%.2f MB -> %.2f MB", size / 1e6, numBytes / 1e6)
			);
		}

		final int mappedFlags = mappedBuffer != null && mappedBuffer.isMapped() ? mappedBuffer.getMappedFlags() : 0;
		if (mappedFlags != 0)
			unmap();

		int oldBuffer = id;
		// Create a new buffer if we have to preserve existing data
		if (byteOffset > 0 || (storageFlags & STORAGE_IMMUTABLE) != 0)
			id = glGenBuffers();

		bind();

		if (isStorageBuffer()) {
			int glStorageFlags = GL_MAP_PERSISTENT_BIT;
			int glMapFlags = GL_MAP_PERSISTENT_BIT | GL_MAP_UNSYNCHRONIZED_BIT;
			if ((storageFlags & STORAGE_IMMUTABLE) == 0)
				glStorageFlags |= GL_DYNAMIC_STORAGE_BIT;
			if ((storageFlags & STORAGE_CLIENT) != 0)
				glStorageFlags |= GL_CLIENT_STORAGE_BIT;
			if ((storageFlags & STORAGE_READ) != 0) {
				glStorageFlags |= GL_MAP_READ_BIT;
				glMapFlags |= GL_MAP_READ_BIT;
			}
			if ((storageFlags & STORAGE_WRITE) != 0) {
				glStorageFlags |= GL_MAP_WRITE_BIT;
				glMapFlags |= GL_MAP_WRITE_BIT | GL_MAP_FLUSH_EXPLICIT_BIT;
			}

			glBufferStorage(target, numBytes, glStorageFlags);

			if ((storageFlags & (STORAGE_READ | STORAGE_WRITE)) != 0) {
				ByteBuffer buf = glMapBufferRange(target, 0, numBytes, glMapFlags);
				if (buf != null) {
					mappedBuffer = new GLMappedBuffer(this, buf);
				} else {
					log.warn(
						"Persistent buffer failed to map range {} offset: {} size: {} mapFlags: {}",
						name,
						byteOffset,
						numBytes,
						glMapFlags
					);

					// Recreate buffers to fall back to non-persistent
					glDeleteBuffers(id);
					id = glGenBuffers();
					storageFlags = STORAGE_NONE;
					// The previous mapping belongs to the old storage
					mappedBuffer = new GLMappedBuffer(this);
					bind();
				}
				checkGLErrors();
			}
		}

		if (!isStorageBuffer())
			glBufferData(target, numBytes, usage);

		if (log.isDebugEnabled() && GL_CAPS.OpenGL43) {
			checkGLErrors(() -> String.format(
				"Errors encountered on buffer %s offset: %dl size: %dl mapped: %s isStorage: %s",
				name,
				byteOffset,
				size,
				isMapped(),
				isStorageBuffer()
			));
			GL43C.glObjectLabel(GL43C.GL_BUFFER, id, name);
		}

		size = numBytes;

		unbind();

		if (id != oldBuffer && oldBuffer != 0) {
			// Neither buffer must be mapped before this, except for with the persistent bit
			if (byteOffset > 0)
				copyRangeTo(oldBuffer, id, 0, 0, byteOffset);
			glDeleteBuffers(oldBuffer);
		}

		// If was mapped, remap without GL_MAP_INVALIDATE_BUFFER_BIT, since we may have previously written data
		if (mappedFlags != 0 && !isStorageBuffer())
			mappedBuffer.map(mappedFlags);

		return true;
	}

	public boolean isStorageBuffer() {
		return storageFlags != STORAGE_NONE && SUPPORTS_STORAGE_BUFFERS;
	}

	public boolean isMapped() {
		return mappedBuffer != null && mappedBuffer.isMapped();
	}

	public void upload(ByteBuffer data) {
		upload(data, 0);
	}

	public void upload(ByteBuffer data, long byteOffset) {
		long numBytes = data.remaining();
		ensureCapacity(byteOffset, numBytes);
		if (isStorageBuffer()) {
			mappedBuffer
				.map(MAP_WRITE, byteOffset, numBytes)
				.byteView()
				.put(data);
			mappedBuffer.unmap();
		} else {
			bind();
			glBufferSubData(target, byteOffset, data);
		}
		checkGLErrors(() -> String.format(
			"Errors encountered on buffer %s upload (offset: %dl size: %dl) offset: %dl size: %dl mapped: %s isStorage: %s",
			name,
			data.position(),
			data.remaining(),
			byteOffset,
			size,
			isMapped(),
			isStorageBuffer()
		));
	}

	public void upload(IntBuffer data) {
		upload(data, 0);
	}

	public void upload(IntBuffer data, long byteOffset) {
		long numBytes = 4L * data.remaining();
		ensureCapacity(byteOffset, numBytes);
		if (isStorageBuffer()) {
			mappedBuffer
				.map(MAP_WRITE, byteOffset, numBytes)
				.intView()
				.put(data);
			mappedBuffer.unmap();
		} else {
			bind();
			glBufferSubData(target, byteOffset, data);
		}
		checkGLErrors(() -> String.format(
			"Errors encountered on buffer %s upload (offset: %dl size: %dl) offset: %dl size: %dl mapped: %s isStorage: %s",
			name,
			data.position(),
			data.remaining(),
			byteOffset,
			size,
			isMapped(),
			isStorageBuffer()
		));
	}

	public void upload(FloatBuffer data) {
		upload(data, 0);
	}

	public void upload(FloatBuffer data, long byteOffset) {
		long numBytes = 4L * data.remaining();
		ensureCapacity(byteOffset, numBytes);
		if (isStorageBuffer()) {
			mappedBuffer
				.map(MAP_WRITE, byteOffset, numBytes)
				.floatView()
				.put(data);
			mappedBuffer.unmap();
		} else {
			bind();
			glBufferSubData(target, byteOffset, data);
		}
		checkGLErrors(() -> String.format(
			"Errors encountered on buffer %s upload (offset: %dl size: %dl) offset: %dl size: %dl mapped: %s isStorage: %s",
			name,
			data.position(),
			data.remaining(),
			byteOffset,
			size,
			isMapped(),
			isStorageBuffer()
		));
	}

	public void upload(GpuIntBuffer data) {
		upload(data.getBuffer());
	}

	public void upload(GpuIntBuffer data, long byteOffset) {
		upload(data.getBuffer(), byteOffset);
	}

	public void upload(GpuFloatBuffer data) {
		upload(data.getBuffer());
	}

	public void upload(GpuFloatBuffer data, long byteOffset) {
		upload(data.getBuffer(), byteOffset);
	}

	public GLMappedBuffer map(int flags) {
		return map(flags, 0, size);
	}

	public GLMappedBuffer map(int flags, long byteOffset, long byteSize) {
		if (mappedBuffer == null)
			mappedBuffer = new GLMappedBuffer(this);
		ensureCapacity(byteOffset, byteSize);
		return mappedBuffer.map(flags, byteOffset, byteSize);
	}

	public GLMappedBuffer mapped() {
		return mappedBuffer;
	}

	public void unmap() {
		if (mappedBuffer != null)
			mappedBuffer.unmap();
	}

	public void copyTo(GLBuffer dst, long srcOffsetBytes, long dstOffsetBytes, long numBytes) {
		if (numBytes <= 0)
			return;

		dst.ensureCapacity(dstOffsetBytes + numBytes);
		copyRangeTo(this, dst, srcOffsetBytes, dstOffsetBytes, numBytes);
	}

	public void copyMultiTo(GLBuffer dst, long[] srcOffsetBytes, long[] dstOffsetBytes, long[] numBytes, int count) {
		long totalNumBytes = 0;
		for (int i = 0; i < count; i++)
			totalNumBytes = max(totalNumBytes, max(dstOffsetBytes[i] + numBytes[i], 0L));
		if (totalNumBytes <= 0)
			return;

		dst.ensureCapacity(totalNumBytes);
		copyRangesTo(this, dst, srcOffsetBytes, dstOffsetBytes, numBytes, count);
	}

	public static class EBO extends GLBuffer {
		public EBO(String name, int usage) {
			super(name, GL_ELEMENT_ARRAY_BUFFER, usage);
		}

		@Override
		public void bind() {
			glBindVertexArray(0);
			glBindBuffer(target, id);
		}

		@Override
		public void unbind() {
			glBindVertexArray(0);
			glBindBuffer(target, 0);
		}
	}
}

package rs117.hd.utils.buffer;

import java.nio.ByteBuffer;
import java.nio.FloatBuffer;
import java.nio.IntBuffer;
import lombok.Getter;
import lombok.experimental.Accessors;

import static org.lwjgl.opengl.GL33C.*;
import static rs117.hd.HdPlugin.GL_CAPS;
import static rs117.hd.HdPlugin.checkGLErrors;
import static rs117.hd.utils.MathUtils.*;
import static rs117.hd.utils.buffer.GLBuffer.MAP_INVALIDATE;
import static rs117.hd.utils.buffer.GLBuffer.MAP_READ;
import static rs117.hd.utils.buffer.GLBuffer.MAP_UNSYNCHRONIZED;
import static rs117.hd.utils.buffer.GLBuffer.MAP_WRITE;

public final class GLMappedBuffer {
	@Getter
	private final GLBuffer owner;

	@Getter
	@Accessors(fluent = true)
	private ByteBuffer byteView;

	@Getter
	@Accessors(fluent = true)
	private IntBuffer intView;

	@Getter
	@Accessors(fluent = true)
	private FloatBuffer floatView;

	@Getter
	private boolean mapped;

	@Getter
	private int mappedFlags;

	@Getter
	private long mappingOffset; // the currently mapped slice's offset into the backing GPU buffer
	private ByteBuffer mappingBuffer; // the currently mapped slice of the backing GPU buffer

	private long absoluteViewOffset; // the current offset for the view buffers, into the backing GPU buffer

	GLMappedBuffer(GLBuffer owner) {
		this.owner = owner;
	}

	GLMappedBuffer(GLBuffer owner, ByteBuffer mappedBuffer) {
		this.owner = owner;
		this.mapped = true;
		if ((owner.storageFlags & GLBuffer.STORAGE_WRITE) != 0) mappedFlags |= MAP_WRITE;
		if ((owner.storageFlags & GLBuffer.STORAGE_READ) != 0) mappedFlags |= MAP_READ;
		updateViews(mappedBuffer, 0, mappedBuffer.capacity());
	}

	public GLMappedBuffer map(int flags) {
		return map(flags, 0, owner.size);
	}

	public GLMappedBuffer map(int flags, long offsetBytes, long sizeBytes) {
		if (mapped || owner.isStorageBuffer()) {
			updateViews(mappingBuffer, offsetBytes, sizeBytes);
			return this;
		}

		owner.bind();

		final ByteBuffer buf;
		if (GL_CAPS.GL_ARB_map_buffer_range && !GLBuffer.DEBUG_MAC_OS) {
			// Map a part of the buffer or its entirety depending on the offset and size
			int glFlags = 0;
			if ((flags & MAP_WRITE) != 0) glFlags |= GL_MAP_WRITE_BIT | GL_MAP_FLUSH_EXPLICIT_BIT;
			if ((flags & MAP_READ) != 0) glFlags |= GL_MAP_READ_BIT;
			if ((flags & MAP_UNSYNCHRONIZED) != 0) glFlags |= GL_MAP_UNSYNCHRONIZED_BIT;

			long mapSize = clamp(owner.size - offsetBytes, 0, sizeBytes);
			if (mapSize <= 0)
				return this;

			if ((flags & MAP_INVALIDATE) != 0) {
				if (mapSize == owner.size) glFlags |= GL_MAP_INVALIDATE_BUFFER_BIT;
				else glFlags |= GL_MAP_INVALIDATE_RANGE_BIT;
			}
			buf = glMapBufferRange(
				owner.target,
				offsetBytes,
				mapSize,
				glFlags,
				mappingBuffer
			);
			this.mappingOffset = offsetBytes;
		} else {
			// Map the whole buffer due to lack of GL_ARB_map_buffer_range support
			int glAccess;
			if ((flags & (MAP_WRITE | MAP_READ)) == (MAP_WRITE | MAP_READ)) {
				glAccess = GL_READ_WRITE;
			} else if ((flags & MAP_WRITE) != 0) {
				glAccess = GL_WRITE_ONLY;
			} else {
				glAccess = GL_READ_ONLY;
			}

			buf = glMapBuffer(owner.target, glAccess, mappingBuffer);
			this.mappingOffset = 0;
		}

		if (buf == null)
			throw new RuntimeException("Failed to map buffer " + owner.id);

		updateViews(buf, offsetBytes, sizeBytes);

		this.mappedFlags = flags;
		mapped = true;

		owner.unbind();
		checkGLErrors(() -> "Mapping Buffer: " + owner.name + " Size: " + owner.size);
		return this;
	}

	private void updateViews(ByteBuffer buffer, long offsetBytes, long sizeBytes) {
		int size = Math.toIntExact(sizeBytes);
		if (mappingBuffer != buffer || absoluteViewOffset != offsetBytes || byteView.capacity() != size) {
			assert offsetBytes >= mappingOffset : "The view must be within the mapped slice of the backing buffer";
			absoluteViewOffset = offsetBytes;
			int mappedOffset = Math.toIntExact(absoluteViewOffset - mappingOffset);
			mappingBuffer = buffer
				.clear()
				.position(mappedOffset)
				.limit(Math.addExact(mappedOffset, size));
			byteView = mappingBuffer.slice().order(mappingBuffer.order());
			intView = byteView.asIntBuffer();
			floatView = byteView.asFloatBuffer();
		} else {
			byteView.clear();
			intView.clear();
			floatView.clear();
		}
	}

	public int getPositionBytes() {
		int bytesPos = byteView.position();
		if (intView.position() * 4 > bytesPos)
			bytesPos = intView.position() * 4;
		if (floatView.position() * 4 > bytesPos)
			bytesPos = floatView.position() * 4;
		return bytesPos;
	}

	public void setPositionBytes(int bytesPos) {
		if (byteView == null)
			return;
		byteView.position(bytesPos);
		intView.position(bytesPos / 4);
		floatView.position(bytesPos / 4);
	}

	public void syncViews() {
		int bytesPos = getPositionBytes();
		byteView.position(bytesPos);
		intView.position(bytesPos / 4);
		floatView.position(bytesPos / 4);
	}

	public void unmap() {
		if (!mapped)
			return;

		syncViews();

		owner.bind();

		// Explicitly flush both persistent buffers and buffers mapped with the explicit flush bit
		if ((mappedFlags & MAP_WRITE) != 0 &&
			byteView.position() > 0 &&
			(owner.isStorageBuffer() || GL_CAPS.GL_ARB_map_buffer_range && !GLBuffer.DEBUG_MAC_OS)
		) {
			glFlushMappedBufferRange(owner.target, absoluteViewOffset - mappingOffset, byteView.position());
		}

		boolean corrupted = false;
		// Unmap non-persistent buffers, and handle possible buffer corruption
		if (!owner.isStorageBuffer()) {
			corrupted = !glUnmapBuffer(owner.target);
			mapped = false;
		}
		owner.unbind();

		if (corrupted) {
			// We might technically be able to recover from this, but it requires careful handling
			throw new IllegalStateException(
				String.format(
					"Corrupted buffer contents while unmapping '%s', offset: %d",
					owner,
					mappingOffset
				));
		}
	}

	void destroy() {
		unmap();

		mappingBuffer = null;
		byteView = null;
		intView = null;
		floatView = null;
	}
}

package rs117.hd.utils.buffer;

import java.nio.ByteBuffer;
import java.nio.IntBuffer;
import java.util.ArrayDeque;
import java.util.ArrayList;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import org.lwjgl.BufferUtils;
import rs117.hd.utils.Destructible;
import rs117.hd.utils.DestructibleHandler;

import static rs117.hd.utils.buffer.GLBuffer.MAP_INVALIDATE;
import static rs117.hd.utils.buffer.GLBuffer.MAP_UNSYNCHRONIZED;
import static rs117.hd.utils.buffer.GLBuffer.MAP_WRITE;

@RequiredArgsConstructor
public class GLMappedBufferIntWriter implements Destructible {
	public static final boolean DEBUG_STAGING = false;

	private final GLBuffer buffer;
	private GLBuffer stagingBuffer;

	private final ArrayDeque<ReservedView> freeViews = new ArrayDeque<>();
	private final ArrayDeque<ReservedView> usedStagingViews = new ArrayDeque<>();
	private final ArrayList<ReservedView> usedMappedViews = new ArrayList<>();

	private GLMappedBuffer mappedBuffer;
	private int writeHead;
	private int stagingWriteHead;

	public int getWrittenInts() {
		return writeHead + stagingWriteHead;
	}

	public void map(boolean sync) {
		mappedBuffer = buffer.map(MAP_WRITE | MAP_INVALIDATE | (sync ? 0 : MAP_UNSYNCHRONIZED));
	}

	public synchronized ReservedView reserve(int sizeInts) {
		assert mappedBuffer.isMapped();

		// Need staging if we've already staged or mapped buffer has no space
		if (stagingWriteHead > 0 || mappedBuffer.intView().remaining() < sizeInts || DEBUG_STAGING) {
			ReservedView staging = new ReservedView();
			staging.buffer = BufferUtils.createIntBuffer(sizeInts);
			staging.offsetInts = writeHead + stagingWriteHead;
			stagingWriteHead += sizeInts;
			usedStagingViews.add(staging);
			return staging;
		}

		ReservedView view = freeViews.poll();
		if (view == null)
			view = new ReservedView();

		if (view.backing != mappedBuffer.byteView()) {
			view.backing = mappedBuffer.byteView();
			view.buffer = view.backing.asIntBuffer();
		}

		view.buffer.clear();
		view.buffer.position(writeHead);
		view.buffer.limit(writeHead + sizeInts);
		view.offsetInts = writeHead;

		writeHead += sizeInts;
		mappedBuffer.intView().position(writeHead);

		usedMappedViews.add(view);
		return view;
	}

	@Override
	@SuppressWarnings("deprecation")
	protected void finalize() {
		if (!usedStagingViews.isEmpty() || !usedMappedViews.isEmpty() || !freeViews.isEmpty())
			DestructibleHandler.queueLeakedDestruction(this);
	}

	@Override
	public void destroy() {
		if (mappedBuffer != null && mappedBuffer.isMapped())
			mappedBuffer.unmap();
		mappedBuffer = null;

		if (stagingBuffer != null)
			stagingBuffer.destroy();
		stagingBuffer = null;

		for (ReservedView view : freeViews) {
			view.backing = null;
			view.buffer = null;
		}
		freeViews.clear();

		for (ReservedView view : usedMappedViews) {
			view.backing = null;
			view.buffer = null;
		}
		usedMappedViews.clear();

		for (ReservedView view : usedStagingViews) {
			view.backing = null;
			view.buffer = null;
		}
		usedStagingViews.clear();
	}

	public synchronized long flush() {
		mappedBuffer.setPositionBytes(writeHead * Integer.BYTES);
		mappedBuffer.unmap();

		if (!usedStagingViews.isEmpty()) {
			final GLBuffer owner = mappedBuffer.getOwner();
			final long mappedSize = (long) writeHead * Integer.BYTES;
			final long stagingCapacity = (long) stagingWriteHead * Integer.BYTES;

			owner.ensureCapacity(mappedSize, stagingCapacity);
			mappedBuffer = owner.map(MAP_WRITE, mappedSize, stagingCapacity);

			final IntBuffer overflow = owner.mapped().intView().clear();
			ReservedView staging;
			while ((staging = usedStagingViews.poll()) != null) {
				staging.buffer.flip();
				// Ensure we write to the reserved offset, just in case
				// a previous staging view did not fill its reservation
				overflow.position(staging.offsetInts - writeHead);
				overflow.put(staging.buffer);
				staging.buffer = null;
			}

			mappedBuffer.syncViews();
			mappedBuffer.unmap();
		}

		freeViews.addAll(usedMappedViews);
		usedMappedViews.clear();

		long writtenBytes = (long) (writeHead + stagingWriteHead) * Integer.BYTES;
		writeHead = 0;
		stagingWriteHead = 0;
		return writtenBytes;
	}

	public static final class ReservedView {
		private ByteBuffer backing;
		@Getter
		private IntBuffer buffer;
		@Getter
		private int offsetInts;

		public int getEndOffsetInts() {
			return getPositionOffsetInts() + buffer.position();
		}

		public int getPositionOffsetInts() {
			return backing == null ? offsetInts : 0;
		}
	}
}

package rs117.hd.utils.buffer;

import lombok.Getter;

import static org.lwjgl.opengl.GL33C.*;

public class GLTextureBuffer extends GLBuffer {
	@Getter
	private int texId;

	public GLTextureBuffer(String name, int usage) {
		this(name, usage, 0);
	}

	public GLTextureBuffer(String name, int usage, int storageFlags) {
		super(name, GL_TEXTURE_BUFFER, usage, storageFlags);
	}

	@Override
	public GLTextureBuffer initialize(long initialCapacity) {
		super.initialize(initialCapacity);

		// Create texture
		texId = glGenTextures();
		glBindTexture(target, texId);

		// RGB32 signed integer texture buffer
		glTexBuffer(target, GL_RGB32I, id);

		glBindTexture(target, 0);
		return this;
	}

	@Override
	public boolean ensureCapacity(long byteOffset, long numBytes) {
		int oldId = id;
		boolean resized = super.ensureCapacity(byteOffset, numBytes);
		if (oldId != id) {
			glBindTexture(target, texId);
			glTexBuffer(target, GL_RGB32I, id);
			glBindTexture(target, 0);
		}
		return resized;
	}

	@Override
	public void destroy() {
		if (texId != 0) {
			glDeleteTextures(texId);
			texId = 0;
		}

		super.destroy();
	}
}

