package rs117.hd.utils.buffer;

import java.nio.IntBuffer;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import org.lwjgl.system.MemoryUtil;
import rs117.hd.HdPlugin;

@Slf4j
public class GpuIntBuffer {
	@Getter
	private IntBuffer buffer;
	private final boolean ownsBuffer;

	public GpuIntBuffer() {
		this(65536);
	}

	public GpuIntBuffer(int initialCapacity) {
		try {
			buffer = MemoryUtil.memAllocInt(initialCapacity);
		} catch (OutOfMemoryError oom) {
			// Force garbage collection and try again
			System.gc();
			buffer = MemoryUtil.memAllocInt(initialCapacity);
		}
		ownsBuffer = true;
	}

	public GpuIntBuffer(IntBuffer buffer) {
		this.buffer = buffer;
		ownsBuffer = false;
	}

	public GpuIntBuffer(boolean ownsBuffer) {
		this.ownsBuffer = ownsBuffer;
	}

	public void destroy() {
		if (buffer != null && ownsBuffer)
			MemoryUtil.memFree(buffer);
		buffer = null;
	}

	public GpuIntBuffer setBuffer(GLMappedBuffer buffer) {
		assert !ownsBuffer;
		this.buffer = buffer.intView();
		return this;
	}

	@Override
	@SuppressWarnings("deprecation")
	protected void finalize() {
		destroy();
	}

	@Override
	public String toString() {
		return String.format(
			"%s@%x(pos=%d, size=%d)",
			getClass().getSimpleName(),
			hashCode(),
			buffer.position(),
			buffer.capacity()
		);
	}

	public void put(int x, int y, int z) {
		buffer.put(x).put(y).put(z);
	}

	public void put(float x, float y, float z, int w) {
		buffer
			.put(Float.floatToIntBits(x))
			.put(Float.floatToIntBits(y))
			.put(Float.floatToIntBits(z))
			.put(w);
	}

	public void put(int[] ints) {
		buffer.put(ints);
	}

	public void put(IntBuffer buffer) {
		this.buffer.put(buffer);
	}

	public int position() {
		return buffer.position();
	}

	public void flip() {
		buffer.flip();
	}

	public GpuIntBuffer clear() {
		buffer.clear();
		return this;
	}

	public int capacity() {
		return buffer.capacity();
	}

	public GpuIntBuffer ensureCapacity(int size) {
		int capacity = buffer.capacity();
		final int position = buffer.position();
		if ((capacity - position) < size) {
			do {
				capacity = (int) (capacity * HdPlugin.BUFFER_GROWTH_MULTIPLIER);
			}
			while ((capacity - position) < size);

			IntBuffer newB = MemoryUtil.memAllocInt(capacity);
			buffer.flip();
			newB.put(buffer);
			MemoryUtil.memFree(buffer);
			buffer = newB;
		}

		return this;
	}
}

package rs117.hd.utils.buffer;

import java.nio.IntBuffer;
import rs117.hd.opengl.compute.OpenCLManager;

import static org.lwjgl.opencl.CL10.*;
import static org.lwjgl.opencl.CL10GL.clCreateFromGLBuffer;

public class SharedGLBuffer extends GLBuffer {
	public final int clUsage;

	public long clId;

	public SharedGLBuffer(String name, int target, int glUsage, int clUsage) {
		super(name, target, glUsage);
		this.clUsage = clUsage;
	}

	private void releaseCLBuffer() {
		if (clId != 0 && OpenCLManager.context != 0)
			clReleaseMemObject(clId);
		clId = 0;
	}

	@Override
	public void destroy() {
		releaseCLBuffer();
		super.destroy();
	}

	@Override
	public boolean ensureCapacity(long byteOffset, long numBytes) {
		boolean resized = super.ensureCapacity(byteOffset, numBytes);
		if (OpenCLManager.context != 0) {
			releaseCLBuffer();

			// OpenCL does not allow 0-size GL buffers, it will segfault on macOS
			if (size != 0)
				clId = clCreateFromGLBuffer(OpenCLManager.context, clUsage, id, (IntBuffer) null);
		}
		return resized;
	}
}

package rs117.hd.utils.collections;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.locks.LockSupport;
import java.util.function.Supplier;
import javax.annotation.Nonnull;
import rs117.hd.utils.Destructible;
import rs117.hd.utils.DestructibleHandler;
import rs117.hd.utils.Props;

public final class ConcurrentPool<T> {
	private static final List<ConcurrentPool<?>> ALL_POOLS = new ArrayList<>();

	private final ConcurrentLinkedQueue<Thread> parkedThreads;
	private final ArrayDeque<T> pool = new ArrayDeque<>();

	private final Supplier<T> supplier;
	private final int fixedSize;
	private int created;

	public ConcurrentPool(@Nonnull Supplier<T> supplier) {
		this(supplier, 0);
	}

	public ConcurrentPool(@Nonnull Supplier<T> supplier, int fixedSize) {
		this.supplier = supplier;
		this.fixedSize = fixedSize;
		parkedThreads = fixedSize > 0 ? new ConcurrentLinkedQueue<>() : null;
		ALL_POOLS.add(this);
	}

	private T poll() {
		synchronized (pool) {
			return pool.poll();
		}
	}

	private void offer(T obj) {
		synchronized (pool) {
			assert !Props.DEVELOPMENT || pool.isEmpty() || !pool.contains(obj) : "Object already in pool: " + obj;
			pool.offer(obj);
		}
	}

	public T acquire() {
		T obj = poll();
		if (obj == null && (fixedSize == 0 || created < fixedSize)) {
			obj = supplier.get();
			created++;
		}
		return obj;
	}

	public T acquireBlocking(int timeoutNanos) {
		T obj = acquire();
		if (obj == null && parkedThreads != null) {
			final Thread currentThread = Thread.currentThread();
			final long deadline = System.nanoTime() + timeoutNanos;
			while ((obj = poll()) == null) {
				if (!parkedThreads.contains(currentThread))
					parkedThreads.add(currentThread);
				LockSupport.parkNanos(1000);
				if (System.nanoTime() > deadline)
					return null;
			}
			parkedThreads.remove(currentThread);
		}
		return obj;
	}

	public void recycle(T obj) {
		if (obj == null)
			return;

		if (DestructibleHandler.isShuttingDown() && obj instanceof Destructible) {
			((Destructible) obj).destroy();
			return;
		}

		offer(obj);

		if (parkedThreads != null) {
			Thread parkedThread = parkedThreads.poll();
			if (parkedThread != null)
				LockSupport.unpark(parkedThread);
		}
	}

	public void destroy() {
		T obj;
		while ((obj = poll()) != null) {
			if (obj instanceof Destructible)
				((Destructible) obj).destroy();
		}
		ALL_POOLS.remove(this);
		created = 0;
	}

	public static void destroyAll() {
		ConcurrentPool<?> pool;
		while (!ALL_POOLS.isEmpty() && (pool = ALL_POOLS.remove(0)) != null)
			pool.destroy();
		ALL_POOLS.clear();
	}
}

package rs117.hd.utils.collections;

import java.util.Arrays;
import java.util.function.IntUnaryOperator;

import static rs117.hd.utils.MathUtils.*;
import static rs117.hd.utils.collections.Util.DEFAULT_CAPACITY;
import static rs117.hd.utils.collections.Util.DEFAULT_GROWTH;
import static rs117.hd.utils.collections.Util.EMPTY;
import static rs117.hd.utils.collections.Util.LOAD_FACTOR;
import static rs117.hd.utils.collections.Util.findIndex;
import static rs117.hd.utils.collections.Util.murmurHash3;

public final class Int2IntHashMap {
	private final float growthFactor;

	private int[] keys;
	private int[] values;
	private int[] distances;

	private int lowTide = Integer.MAX_VALUE;
	private int highTide;
	private int size;
	private int mask;

	public Int2IntHashMap() {
		this(DEFAULT_CAPACITY, DEFAULT_GROWTH);
	}

	public Int2IntHashMap(int initialCapacity) {
		this(initialCapacity, DEFAULT_GROWTH);
	}

	public Int2IntHashMap(int initialCapacity, float growthFactor) {
		assert growthFactor > 1;
		int cap = max(ceilPow2(initialCapacity), DEFAULT_CAPACITY);

		keys = new int[cap];
		values = new int[cap];
		distances = new int[cap];

		Arrays.fill(keys, EMPTY);

		this.growthFactor = growthFactor;
		this.mask = cap - 1;
		this.size = 0;
	}

	public void trimToSize() {
		resizeTo(max(size, DEFAULT_CAPACITY));
	}

	private void grow() {
		resizeTo((int) (keys.length * growthFactor));
	}

	private void resizeTo(int newCapacity) {
		assert size <= newCapacity;
		newCapacity = ceilPow2(newCapacity);
		if (newCapacity == keys.length)
			return;

		int[] oldKeys = keys;
		int[] oldValues = values;

		keys = new int[newCapacity];
		values = new int[newCapacity];
		distances = new int[newCapacity];

		Arrays.fill(keys, EMPTY);

		mask = newCapacity - 1;
		lowTide = Integer.MAX_VALUE;
		highTide = 0;

		// The size will remain the same after, but we make
		// it negative to avoid growth while repopulating
		int newSize = size;
		size = -newSize;

		for (int i = 0; i < oldKeys.length; i++)
			if (oldKeys[i] != EMPTY)
				put(oldKeys[i], oldValues[i]);

		size = newSize;
	}

	public boolean put(int key, int value) {
		return put(key, value, true);
	}

	public boolean putIfAbsent(int key, int value) {
		return put(key, value, false);
	}

	public int compute(int key, IntUnaryOperator op, int defaultValue) {
		int idx = findIndex(key, mask, keys, distances);
		if (idx >= 0)
			return values[idx] = op.applyAsInt(values[idx]);
		int newVal = op.applyAsInt(defaultValue);
		put(key, newVal);
		return newVal;
	}

	public int or(int key, int maskBits, int defaultValue) {
		int idx = findIndex(key, mask, keys, distances);
		if (idx >= 0)
			return values[idx] |= maskBits;
		int newVal = defaultValue | maskBits;
		put(key, newVal);
		return newVal;
	}

	public int and(int key, int maskBits, int defaultValue) {
		int idx = findIndex(key, mask, keys, distances);
		if (idx >= 0)
			return values[idx] &= maskBits;
		int newVal = defaultValue & maskBits;
		put(key, newVal);
		return newVal;
	}

	public int xor(int key, int maskBits, int defaultValue) {
		int idx = findIndex(key, mask, keys, distances);
		if (idx >= 0)
			return values[idx] ^= maskBits;
		int newVal = defaultValue ^ maskBits;
		put(key, newVal);
		return newVal;
	}

	public int setBits(int key, int valueBits, int maskBits, int defaultValue) {
		int idx = findIndex(key, mask, keys, distances);

		if (idx >= 0) {
			int v = values[idx];
			v = (v & ~maskBits) | (valueBits & maskBits);
			values[idx] = v;
			return v;
		}

		int newVal = (defaultValue & ~maskBits) | (valueBits & maskBits);
		put(key, newVal);
		return newVal;
	}

	public boolean test(int key, int maskBits) {
		int idx = findIndex(key, mask, keys, distances);
		return idx >= 0 && (values[idx] & maskBits) == maskBits;
	}

	public int getBits(int key, int maskBits, int shift, int defaultValue) {
		int idx = findIndex(key, mask, keys, distances);
		return idx >= 0 ? (values[idx] >>> shift) & maskBits : defaultValue;
	}

	private boolean put(int key, int value, boolean overwrite) {
		if (size >= (int) (keys.length * LOAD_FACTOR))
			grow();

		final int[] keys = this.keys;
		final int[] distances = this.distances;

		int idx = murmurHash3(key) & mask;
		int dist = 0;
		while (true) {
			final int k = keys[idx];

			if (k == EMPTY) {
				keys[idx] = key;
				values[idx] = value;
				distances[idx] = dist;
				size++;
				lowTide = min(idx, lowTide);
				highTide = max(idx, highTide);
				return true;
			}

			if (k == key) {
				if (overwrite)
					values[idx] = value;
				return false;
			}

			// Robin Hood swap: steal slot if we've probed farther
			if (distances[idx] < dist) {
				int tmpKey = keys[idx];
				int tmpVal = values[idx];
				int tmpDist = distances[idx];

				keys[idx] = key;
				values[idx] = value;
				distances[idx] = dist;

				key = tmpKey;
				value = tmpVal;
				dist = tmpDist;
			}

			idx = (idx + 1) & mask;
			dist++;
		}
	}

	public int find(int key) {
		return findIndex(key, mask, keys, distances);
	}

	public int getOrDefault(int key, int defaultValue) {
		int idx = findIndex(key, mask, keys, distances);
		return idx >= 0 ? values[idx] : defaultValue;
	}

	public boolean containsKey(int key) {
		return findIndex(key, mask, keys, distances) >= 0;
	}

	public int getValue(int idx) {
		return values[idx];
	}

	public void setValue(int idx, int value) {
		values[idx] = value;
	}

	public boolean remove(int key) {
		int idx = findIndex(key, mask, keys, distances);
		if (idx < 0)
			return false;

		removeIndex(idx);
		return true;
	}

	public void removeIndex(int idx) {
		keys[idx] = EMPTY;
		values[idx] = 0;
		distances[idx] = 0;
		size--;

		int last = idx;

		// Shift backward while probe distance allows
		while (true) {
			int next = (last + 1) & mask;
			if (keys[next] == EMPTY || distances[next] == 0)
				break;

			keys[last] = keys[next];
			values[last] = values[next];
			distances[last] = distances[next] - 1;

			keys[next] = EMPTY;
			values[next] = 0;
			distances[next] = 0;

			last = next;
		}
	}

	public void clear() {
		if (size == 0)
			return;
		Arrays.fill(keys, lowTide, highTide + 1, EMPTY);
		Arrays.fill(values, lowTide, highTide + 1, 0);
		Arrays.fill(distances, lowTide, highTide + 1, 0);
		lowTide = keys.length;
		highTide = 0;
		size = 0;
	}

	public boolean isEmpty() {
		return size == 0;
	}

	public int size() {
		return size;
	}

	public int capacity() {
		return keys.length;
	}
}

package rs117.hd.utils.collections;

import java.util.Arrays;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.function.UnaryOperator;
import lombok.Getter;
import lombok.NonNull;

import static rs117.hd.utils.MathUtils.*;
import static rs117.hd.utils.collections.Util.DEFAULT_CAPACITY;
import static rs117.hd.utils.collections.Util.DEFAULT_GROWTH;
import static rs117.hd.utils.collections.Util.EMPTY;
import static rs117.hd.utils.collections.Util.LOAD_FACTOR;
import static rs117.hd.utils.collections.Util.findIndex;
import static rs117.hd.utils.collections.Util.murmurHash3;

public final class Int2ObjectHashMap<T> implements Iterable<Int2ObjectHashMap.Entry<T>> {
	public interface Supplier<T> { T[] get(int capacity); }

	private final Supplier<T> defaultValueSupplier;
	private final float growthFactor;

	private int[] keys;
	private T[] values;
	private int[] distances;

	private int lowTide = Integer.MAX_VALUE;
	private int highTide;
	private int size;
	private int mask;

	public Int2ObjectHashMap() {
		this(DEFAULT_CAPACITY, DEFAULT_GROWTH, null);
	}

	public Int2ObjectHashMap(Supplier<T> defaultValueSupplier) {
		this(DEFAULT_CAPACITY, DEFAULT_GROWTH, defaultValueSupplier);
	}

	public Int2ObjectHashMap(int initialCapacity) {
		this(initialCapacity, DEFAULT_GROWTH, null);
	}

	public Int2ObjectHashMap(int initialCapacity, Supplier<T> defaultValueSupplier) {
		this(initialCapacity, DEFAULT_GROWTH, defaultValueSupplier);
	}

	@SuppressWarnings("unchecked")
	public Int2ObjectHashMap(int initialCapacity, float growthFactor, Supplier<T> defaultValueSupplier) {
		assert growthFactor > 1;
		this.defaultValueSupplier =
			defaultValueSupplier != null
				? defaultValueSupplier
				: (capacity) -> (T[]) new Object[capacity];

		this.growthFactor = growthFactor;

		int cap = max(ceilPow2(initialCapacity), DEFAULT_CAPACITY);

		keys = new int[cap];
		values = this.defaultValueSupplier.get(cap);
		distances = new int[cap];

		Arrays.fill(keys, EMPTY);

		this.size = 0;
		this.mask = cap - 1;
	}

	public void trimToSize() {
		resizeTo(max(size, DEFAULT_CAPACITY));
	}

	private void grow() {
		resizeTo((int) (keys.length * growthFactor));
	}

	private void resizeTo(int newCapacity) {
		assert size <= newCapacity;
		newCapacity = ceilPow2(newCapacity);
		if (newCapacity == keys.length)
			return;

		int[] oldKeys = keys;
		T[] oldValues = values;

		keys = new int[newCapacity];
		values = defaultValueSupplier.get(newCapacity);
		distances = new int[newCapacity];

		Arrays.fill(keys, EMPTY);

		mask = newCapacity - 1;
		lowTide = Integer.MAX_VALUE;
		highTide = 0;

		// The size will remain the same after, but we make
		// it negative to avoid growth while repopulating
		int newSize = size;
		size = -newSize;

		for (int i = 0; i < oldKeys.length; i++)
			if (oldKeys[i] != EMPTY)
				put(oldKeys[i], oldValues[i]);

		size = newSize;
	}

	public boolean put(int key, T value) {
		return put(key, value, true);
	}

	public boolean putIfAbsent(int key, T value) {
		return put(key, value, false);
	}

	public T compute(int key, UnaryOperator<T> op, T defaultValue) {
		int idx = findIndex(key, mask, keys, distances);
		if (idx >= 0)
			return values[idx] = op.apply(values[idx]);
		T newVal = op.apply(defaultValue);
		put(key, newVal);
		return newVal;
	}

	private boolean put(int key, T value, boolean overwrite) {
		if (size >= (int) (keys.length * LOAD_FACTOR))
			grow();

		final int[] keys = this.keys;
		final int[] distances = this.distances;

		int idx = murmurHash3(key) & mask;
		int dist = 0;
		while (true) {
			final int k = keys[idx];

			if (k == EMPTY) {
				keys[idx] = key;
				values[idx] = value;
				distances[idx] = dist;
				size++;
				lowTide = min(idx, lowTide);
				highTide = max(idx, highTide);
				return true;
			}

			if (k == key) {
				if (overwrite)
					values[idx] = value;
				return false;
			}

			// Robin Hood swap: steal slot if we probed farther
			if (distances[idx] < dist) {
				int tmpKey = keys[idx];
				T tmpVal = values[idx];
				int tmpDist = distances[idx];

				keys[idx] = key;
				values[idx] = value;
				distances[idx] = dist;

				key = tmpKey;
				value = tmpVal;
				dist = tmpDist;
			}

			idx = (idx + 1) & mask;
			dist++;
		}
	}

	public T getOrDefault(int key, T defaultValue) {
		int idx = findIndex(key, mask, keys, distances);
		return idx >= 0 ? values[idx] : defaultValue;
	}

	public T get(int key) {
		int idx = findIndex(key, mask, keys, distances);
		return idx >= 0 ? values[idx] : null;
	}

	public boolean containsKey(int key) {
		return findIndex(key, mask, keys, distances) >= 0;
	}

	public T getValue(int idx) {
		return values[idx];
	}

	public void setValue(int idx, T value) {
		values[idx] = value;
	}

	public boolean remove(int key) {
		int idx = findIndex(key, mask, keys, distances);
		if (idx < 0)
			return false;

		removeIndex(idx);
		return true;
	}

	public void removeIndex(int idx) {
		keys[idx] = EMPTY;
		values[idx] = null;
		distances[idx] = 0;
		size--;

		int last = idx;

		// Shift backward while probe distance allows
		while (true) {
			int next = (last + 1) & mask;
			if (keys[next] == EMPTY || distances[next] == 0)
				break;

			keys[last] = keys[next];
			values[last] = values[next];
			distances[last] = distances[next] - 1;

			keys[next] = EMPTY;
			values[next] = null;
			distances[next] = 0;

			last = next;
		}
	}

	public void clear() {
		if (size == 0)
			return;
		Arrays.fill(keys, lowTide, highTide + 1, EMPTY);
		Arrays.fill(values, lowTide, highTide + 1, null);
		Arrays.fill(distances, lowTide, highTide + 1, 0);
		lowTide = keys.length;
		highTide = 0;
		size = 0;
	}

	public boolean isEmpty() {
		return size == 0;
	}

	public int size() {
		return size;
	}

	public int capacity() { return keys.length; }

	@Override
	@NonNull
	public Iterator<Entry<T>> iterator() {
		return new Iter();
	}

	public static class Entry<T> {
		@Getter
		private int key;
		@Getter
		private T value;
	}

	private class Iter implements Iterator<Entry<T>> {
		private int index = -1;
		private int nextIndex = -1;

		private final Entry<T> entry = new Entry<>();

		Iter() {
			advance();
		}

		private void advance() {
			do {
				nextIndex++;
			} while (nextIndex < keys.length && keys[nextIndex] == EMPTY);
		}

		@Override
		public boolean hasNext() {
			return nextIndex < keys.length;
		}

		@Override
		public Entry<T> next() {
			if (!hasNext())
				throw new NoSuchElementException();

			index = nextIndex;
			advance();

			entry.key = keys[index];
			entry.value = values[index];
			return entry;
		}

		@Override
		public void remove() {
			if (index == -1)
				throw new IllegalStateException();

			removeIndex(index);
			nextIndex = index;
			index = -1;
		}
	}
}

package rs117.hd.utils.collections;

import java.util.Arrays;
import java.util.Iterator;
import java.util.NoSuchElementException;
import lombok.NonNull;

import static rs117.hd.utils.MathUtils.*;
import static rs117.hd.utils.collections.Util.DEFAULT_CAPACITY;
import static rs117.hd.utils.collections.Util.DEFAULT_GROWTH;
import static rs117.hd.utils.collections.Util.EMPTY;
import static rs117.hd.utils.collections.Util.LOAD_FACTOR;
import static rs117.hd.utils.collections.Util.findIndex;
import static rs117.hd.utils.collections.Util.murmurHash3;

public final class IntHashSet implements Iterable<Integer> {
	private final float growthFactor;

	private int[] keys;
	private int[] distances;

	private int lowTide = Integer.MAX_VALUE;
	private int highTide;
	private int size;
	private int mask;

	public IntHashSet() {
		this(DEFAULT_CAPACITY, DEFAULT_GROWTH);
	}

	public IntHashSet(int initialCapacity) {
		this(initialCapacity, DEFAULT_GROWTH);
	}

	public IntHashSet(int initialCapacity, float growthFactor) {
		assert growthFactor > 1;
		int cap = max(ceilPow2(initialCapacity), DEFAULT_CAPACITY);

		keys = new int[cap];
		distances = new int[cap];

		Arrays.fill(keys, EMPTY);

		this.growthFactor = growthFactor;
		this.size = 0;
		this.mask = cap - 1;
	}

	public void trimToSize() {
		resizeTo(max(size, DEFAULT_CAPACITY));
	}

	private void grow() {
		resizeTo((int) (keys.length * growthFactor));
	}

	private void resizeTo(int newCapacity) {
		assert size <= newCapacity;
		newCapacity = ceilPow2(newCapacity);
		if (newCapacity == keys.length)
			return;

		final int[] oldKeys = keys;
		keys = new int[newCapacity];
		distances = new int[newCapacity];
		Arrays.fill(keys, EMPTY);

		mask = newCapacity - 1;
		lowTide = Integer.MAX_VALUE;
		highTide = 0;

		// The size will remain the same after, but we make
		// it negative to avoid growth while repopulating
		int newSize = size;
		size = -newSize;

		for (int i = 0; i < oldKeys.length; i++)
			if (oldKeys[i] != EMPTY)
				add(oldKeys[i]);

		size = newSize;
	}

	public boolean addAll(IntHashSet other) {
		if (other == null || other.size == 0)
			return false;

		int originalSize = size;
		if (size + other.size >= keys.length * LOAD_FACTOR)
			resizeTo(ceilPow2((int) ((size + other.size) / LOAD_FACTOR)));

		// The size will remain the same after, but we make
		// it negative to avoid growth while repopulating
		int newSize = size;
		size = -newSize;

		boolean modified = false;
		for (int i = 0; i < other.keys.length; i++) {
			int k = other.keys[i];
			if (k != EMPTY && add(k))
				modified = true;
		}

		size += newSize + originalSize;
		return modified;
	}

	public boolean add(int key) {
		if (size >= (int) (keys.length * LOAD_FACTOR))
			grow();

		final int[] keys = this.keys;
		final int[] distances = this.distances;

		int idx = murmurHash3(key) & mask;
		int dist = 0;
		while (true) {
			final int k = keys[idx];

			if (k == EMPTY) {
				keys[idx] = key;
				distances[idx] = dist;
				size++;
				lowTide = min(idx, lowTide);
				highTide = max(idx, highTide);
				return true;
			}

			if (k == key)
				return false; // already present

			// Robin Hood swap
			if (distances[idx] < dist) {
				int tmpKey = keys[idx];
				int tmpDist = distances[idx];

				keys[idx] = key;
				distances[idx] = dist;

				key = tmpKey;
				dist = tmpDist;
			}

			idx = (idx + 1) & mask;
			dist++;
		}
	}

	public boolean contains(int key) {
		return findIndex(key, mask, keys, distances) >= 0;
	}

	public boolean remove(int key) {
		int idx = findIndex(key, mask, keys, distances);
		if (idx < 0)
			return false;

		removeIndex(idx);
		return true;
	}

	private void removeIndex(int idx) {
		keys[idx] = EMPTY;
		distances[idx] = 0;
		size--;

		int last = idx;

		// Shift backward while probe distance allows
		while (true) {
			int next = (last + 1) & mask;
			if (keys[next] == EMPTY || distances[next] == 0)
				break;

			keys[last] = keys[next];
			distances[last] = distances[next] - 1;

			keys[next] = EMPTY;
			distances[next] = 0;

			last = next;
		}
	}

	public void clear() {
		if (size == 0)
			return;
		Arrays.fill(keys, lowTide, highTide + 1, EMPTY);
		Arrays.fill(distances, lowTide, highTide + 1, 0);
		lowTide = keys.length;
		highTide = 0;
		size = 0;
	}

	public boolean isEmpty() {
		return size == 0;
	}

	public int size() { return size; }

	public int capacity() { return keys.length; }

	@Override
	@NonNull
	public Iterator<Integer> iterator() {
		return new Iter();
	}

	private class Iter implements Iterator<Integer> {
		private int index = -1;
		private int nextIndex = -1;

		Iter() {
			advance();
		}

		private void advance() {
			do {
				nextIndex++;
			} while (nextIndex < keys.length && keys[nextIndex] == EMPTY);
		}

		@Override
		public boolean hasNext() {
			return nextIndex < keys.length;
		}

		@Override
		public Integer next() {
			if (!hasNext())
				throw new NoSuchElementException();

			index = nextIndex;
			advance();

			return keys[index];
		}

		@Override
		public void remove() {
			if (index == -1)
				throw new IllegalStateException();

			removeIndex(index);
			nextIndex = index;
			index = -1;
		}
	}
}

package rs117.hd.utils.collections;

import java.lang.reflect.Array;
import java.util.ArrayDeque;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.StampedLock;
import javax.annotation.Nonnull;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import static java.lang.Integer.numberOfLeadingZeros;
import static rs117.hd.utils.MathUtils.*;

@Slf4j
public enum PooledArrayType {
	BOOL(boolean[]::new, 1),
	BYTE(byte[]::new, 1),
	CHAR(char[]::new, 2),
	SHORT(short[]::new, 2),
	INT(int[]::new, 4),
	FLOAT(float[]::new, 4),
	OBJECT(Object[]::new, 4);

	public static final boolean CHECK_FOR_DUPLICATES_IN_POOL = false;

	public static final PooledArrayType[] VALUES = values();

	private static final double MAX_HEAP_FRACTION = 0.05; // 768 MB * 0.05 = 38.4 MB
	private static final long MAX_POOL_BYTES = max((long) (Runtime.getRuntime().maxMemory() * MAX_HEAP_FRACTION), 10 * MB);

	private static final int MAX_BUCKET = 30;
	private static final int STRIPES = 8;
	private static final int STRIPES_MASK = STRIPES - 1;
	private static final int CLEANUP_INTERVAL = 64;
	private static final long SHRINK_DELAY_MS = 60_000;
	private static final double ALPHA = 0.1;

	private static final AtomicLong CURRENT_POOL_BYTES = new AtomicLong();

	public final ArraySupplier<?> supplier;
	public final int stride;

	private final Bucket[][] buckets = new Bucket[MAX_BUCKET + 1][STRIPES];

	PooledArrayType(ArraySupplier<?> supplier, int stride) {
		this.supplier = supplier;
		this.stride = stride;

		for (int i = 0; i < buckets.length; i++) {
			int size = 1 << i;
			for (int s = 0; s < STRIPES; s++)
				buckets[i][s] = new Bucket(size);
		}
	}

	private static int bucket(int size) {
		if (size <= 1) return 0;
		int b = 32 - numberOfLeadingZeros(size - 1);
		return min(b, MAX_BUCKET);
	}

	private static int stripeIndex() {
		final int hash = Thread.currentThread().hashCode();
		return (hash ^ (hash >>> 16)) & STRIPES_MASK;
	}

	private static boolean isPoolFull(long additionalBytes) {
		return CURRENT_POOL_BYTES.get() + additionalBytes > MAX_POOL_BYTES;
	}

	public static void forceCleanup(boolean full) {
		for (int v = 0; v < VALUES.length; v++) {
			final PooledArrayType type = VALUES[v];
			for (int b = 0; b < type.buckets.length; b++) {
				for (int s = 0; s < STRIPES; s++) {
					final Bucket bucket = type.buckets[b][s];
					final long stamp = bucket.lock.writeLock();
					try {
						bucket.opCounter = 0;
						if (full) {
							bucket.inUse = 0;
							bucket.isEmpty = true;
							bucket.stack.clear();
						} else {
							type.maybeCleanup(b, s, bucket, true);
						}
					} finally {
						bucket.lock.unlockWrite(stamp);
					}
				}
			}
		}
		if (full)
			CURRENT_POOL_BYTES.set(0);
	}

	public static void shutdown() {
		CURRENT_POOL_BYTES.set(0);

		for (int v = 0; v < VALUES.length; v++) {
			final PooledArrayType type = VALUES[v];
			for (int b = 0; b < VALUES[v].buckets.length; b++) {
				for (int s = 0; s < STRIPES; s++) {
					final Bucket bucket = type.buckets[b][s];
					bucket.stack.clear();
					bucket.isEmpty = true;

					bucket.inUse = 0;
					bucket.peakInUse = 0;
					bucket.avgDemand = 0;
					bucket.lastOverTargetTime = 0;

					// Recreate the bucket to clear the stack inner arrays
					type.buckets[b][s] = new Bucket(bucket.size);
				}
			}
		}
	}

	public static long getCurrentTotalCacheSize() {
		return CURRENT_POOL_BYTES.get();
	}

	private void maybeCleanup(int b, int s, Bucket bucket) {
		maybeCleanup(b, s, bucket, false);
	}

	private void maybeCleanup(int b, int s, Bucket bucket, boolean forced) {
		if (!forced && (++bucket.opCounter & (CLEANUP_INTERVAL - 1)) != 0)
			return;

		bucket.avgDemand = (float) (ALPHA * bucket.peakInUse + (1 - ALPHA) * bucket.avgDemand);
		bucket.peakInUse = bucket.inUse;

		if (bucket.stack.size() <= bucket.avgDemand) {
			bucket.lastOverTargetTime = 0;
			return;
		}

		final long now = System.currentTimeMillis();
		if (bucket.lastOverTargetTime == 0) {
			bucket.lastOverTargetTime = now;
			return;
		}

		if (!forced && now - bucket.lastOverTargetTime <= SHRINK_DELAY_MS)
			return;

		final int target = max((int) (bucket.avgDemand * 0.5f), 1);
		int excess = bucket.stack.size() - target;

		while (excess-- > 0) {
			Object arr = bucket.poll(bytesFor(bucket.size));
			if (arr == null)
				break;

			spill(b, s, arr);
		}

		bucket.lastOverTargetTime = now;
	}

	private boolean spill(int b, int fromStripe, Object array) {
		final Bucket[] stripes = buckets[b];

		final long bytes = bytesFor(Array.getLength(array));

		for (int i = 1; i < STRIPES; i++) {
			final int s = (fromStripe + i) & STRIPES_MASK;
			final Bucket other = stripes[s];

			if (other.stack.size() > other.avgDemand)
				continue;

			final long stamp = other.lock.tryWriteLock();
			if (stamp == 0)
				continue;

			try {
				if (other.stack.size() <= other.avgDemand) {
					other.add(array, bytes);
					return true;
				}
			} finally {
				other.lock.unlockWrite(stamp);
			}
		}

		return false;
	}

	private long bytesFor(int len) {
		return (long) len * stride;
	}

	@SuppressWarnings("unchecked")
	public <T> T create(int requestedSize) {
		return (T) supplier.get(ceilPow2(requestedSize));
	}

	@SuppressWarnings("unchecked")
	public <T> T ensureCapacity(Object array, int requestedSize) {
		final int len = array != null ? Array.getLength(array) : 0;
		if (len >= requestedSize)
			return (T) array;

		release(array);
		return borrow(requestedSize);
	}

	@SuppressWarnings("SuspiciousSystemArraycopy")
	public <T> T cache(@Nonnull Object array, int offset, int size) {
		final T cached = borrow(size);
		System.arraycopy(array, offset, cached, 0, size);
		return cached;
	}

	public <T> T borrow(int requestedSize) {
		return borrow(requestedSize, true);
	}

	@SuppressWarnings("unchecked")
	public <T> T borrow(int requestedSize, boolean createIfMissing) {
		final int roundedSize = ceilPow2(requestedSize);
		final int b = bucket(roundedSize);

		final long bytes = bytesFor(roundedSize);
		final Bucket[] bucketStripes = buckets[b];
		final int startStripe = stripeIndex();

		for (int i = 0; i < STRIPES * 2; i++) {
			final int s = (startStripe + i) & STRIPES_MASK;
			final Bucket bucket = bucketStripes[s];
			if (bucket.isEmpty)
				continue;

			final long stamp = i < STRIPES ? bucket.lock.tryWriteLock() : bucket.lock.writeLock();
			if (stamp == 0)
				continue;

			try {
				final T arr = (T) bucket.poll(bytes);
				if (arr != null) {
					bucket.inUse++;
					bucket.peakInUse = Math.max(bucket.peakInUse, bucket.inUse);
					maybeCleanup(b, s, bucket);
					return arr;
				}
			} finally {
				bucket.lock.unlockWrite(stamp);
			}
		}

		return createIfMissing ? (T) supplier.get(roundedSize) : null;
	}

	public void release(Object array) {
		if (array == null)
			return;

		final int len = Array.getLength(array);
		if (len != ceilPow2(len))
			return;

		final int b = bucket(len);

		final long bytes = bytesFor(len);
		if (isPoolFull(bytes))
			return;

		final int startStripe = stripeIndex();

		final Bucket[] bucketStripes = buckets[b];

		for (int i = 0; i < STRIPES * 2; i++) {
			final int s = (startStripe + i) & STRIPES_MASK;
			final Bucket bucket = bucketStripes[s];

			final long stamp = i < STRIPES
				? bucket.lock.tryWriteLock()
				: bucket.lock.writeLock();
			if (stamp == 0)
				continue;

			try {
				if (isPoolFull(bytes))
					return;

				bucket.inUse = max(0, bucket.inUse - 1);
				bucket.add(array, bytes);
				maybeCleanup(b, s, bucket);
				return;
			} finally {
				bucket.lock.unlockWrite(stamp);
			}
		}
	}

	@FunctionalInterface
	public interface ArraySupplier<T> {
		T get(int capacity);
	}

	@RequiredArgsConstructor
	private static final class Bucket {
		private final ArrayDeque<Object> stack = new ArrayDeque<>();
		private final StampedLock lock = new StampedLock();

		private final int size;
		private int opCounter;
		private int inUse;
		private int peakInUse;
		private float avgDemand;
		private long lastOverTargetTime;

		private volatile boolean isEmpty = true;

		public void add(Object array, long bytes) {
			if (CHECK_FOR_DUPLICATES_IN_POOL && !isEmpty && stack.contains(array))
				throw new IllegalStateException("Duplicate array: " + array);
			stack.add(array);
			CURRENT_POOL_BYTES.addAndGet(bytes);
			isEmpty = false;
		}

		public Object poll(long bytes) {
			Object arr = stack.poll();
			if (arr != null)
				CURRENT_POOL_BYTES.addAndGet(-bytes);
			isEmpty = stack.isEmpty();
			return arr;
		}
	}
}

package rs117.hd.utils.collections;

public final class PooledObjectArray<T> {
	public Object[] array;

	@SuppressWarnings("unchecked")
	public T get(int idx) {
		return (T) array[idx];
	}

	public void set(int idx, T value) {
		array[idx] = value;
	}

	public void ensureCapacity(int size) {
		array = PooledArrayType.OBJECT.ensureCapacity(array, size);
	}

	public void release() {
		if (array != null)
			PooledArrayType.OBJECT.release(array);
		array = null;
	}
}

package rs117.hd.utils.collections;

import java.util.Arrays;

import static java.lang.System.arraycopy;
import static rs117.hd.utils.MathUtils.*;

public final class PrimitiveCharArray {
	public char[] array = new char[16];
	public int length;

	public PrimitiveCharArray reset() {
		length = 0;
		return this;
	}

	public PrimitiveCharArray ensureCapacity(int count) {
		if (length + count > array.length)
			array = Arrays.copyOf(array, ceilPow2(length + count));
		return this;
	}

	public void put(char i) {
		if (length < array.length)
			array[length++] = i;
	}

	public void put(char[] ints, int offset, int count) {
		ensureCapacity(count);
		arraycopy(ints, offset, array, length, count);
		length += count;
	}

	public void removeAt(int idx) {
		if (idx < 0 || idx >= length)
			return;
		arraycopy(array, idx + 1, array, idx, length - idx - 1);
		length--;
	}

	public void removeAtSwap(int idx) {
		if (idx < 0 || idx >= length)
			return;
		array[idx] = array[--length];
	}
}

package rs117.hd.utils.collections;

import java.util.Arrays;

import static java.lang.System.arraycopy;
import static rs117.hd.utils.MathUtils.*;

public final class PrimitiveIntArray {
	public int[] array = new int[16];
	public int length;

	public PrimitiveIntArray reset() {
		length = 0;
		return this;
	}

	public PrimitiveIntArray ensureCapacity(int count) {
		if (length + count > array.length)
			array = Arrays.copyOf(array, ceilPow2(length + count));
		return this;
	}

	public void put(int v) {
		if (length < array.length)
			array[length++] = v;
	}

	public void putUnique(int v) {
		if (length < array.length) {
			for (int i = 0; i < length; i++)
				if (array[i] == v) return;
			array[length++] = v;
		}
	}

	public void put(int[] ints, int offset, int count) {
		ensureCapacity(count);
		arraycopy(ints, offset, array, length, count);
		length += count;
	}

	public void removeAt(int idx) {
		if (idx < 0 || idx >= length)
			return;
		arraycopy(array, idx + 1, array, idx, length - idx - 1);
		length--;
	}

	public void removeAtSwap(int idx) {
		if (idx < 0 || idx >= length)
			return;
		array[idx] = array[--length];
	}
}

package rs117.hd.utils.collections;

import java.util.Comparator;
import java.util.List;

public final class Util {
	public static final int DEFAULT_CAPACITY = 16;
	public static final int EMPTY = Integer.MIN_VALUE;
	public static final float LOAD_FACTOR = 0.7f;
	public static final float DEFAULT_GROWTH = 1.5f;

	static {
		// noinspection ConstantValue
		assert LOAD_FACTOR < 1 : "Must be less than 1 for to avoid infinite loops";
	}

	public static int murmurHash3(int x) {
		x ^= x >>> 16;
		x *= 0x85ebca6b;
		x ^= x >>> 13;
		x *= 0xc2b2ae35;
		x ^= x >>> 16;
		return x;
	}

	public static long murmurHash3(long x) {
		x ^= x >>> 33;
		x *= 0xff51afd7ed558ccdL;
		x ^= x >>> 33;
		x *= 0xc4ceb9fe1a85ec53L;
		x ^= x >>> 33;
		return x;
	}

	public static int findIndex(final int key, final int mask, final int[] keys, final int[] distances) {
		int idx = murmurHash3(key) & mask;
		for (int dist = 0; dist == 0 || distances[idx] >= dist; dist++) {
			final int k = keys[idx];

			if (k == EMPTY)
				break;

			if (k == key)
				return idx;

			idx = (idx + 1) & mask;
		}

		return -1;
	}

	/**
	 * Allocation-free quicksort for Object arrays and Lists.
	 * Algorithm based on the JDK 8 Dual-Pivot Quicksort by Yaroslavskiy, Bentley,
	 *   https://github.com/openjdk/jdk/blob/master/src/java.base/share/classes/java/util/DualPivotQuicksort.java
	 */

	private static final int INSERTION_SORT_THRESHOLD = 47;

	@SuppressWarnings("unchecked")
	public static <T> void quickSort(List<T> list, Comparator<T> comparator) {
		final int size = list.size();
		if (size <= 1) return;

		final Object[] buf = PooledArrayType.OBJECT.borrow(size);
		try {
			list.toArray(buf);
			quickSortInternal(buf, 0, size - 1, comparator);
			for (int i = 0; i < size; i++)
				list.set(i, (T) buf[i]);
		} finally {
			PooledArrayType.OBJECT.release(buf);
		}
	}

	public static <T> void quickSort(T[] a, Comparator<T> comparator) {
		if (a.length > 1)
			quickSortInternal(a, 0, a.length - 1, comparator);
	}

	public static <T> void quickSort(T[] a, int left, int right, Comparator<T> comparator) {
		if (a.length > 1)
			quickSortInternal(a, left, right, comparator);
	}

	@SuppressWarnings({"unchecked", "rawtypes"})
	private static void quickSortInternal(Object[] a, int left, int right, Comparator comparator) {
		if (right <= left) return;

		/*
		 * Stack layout: pairs of (lo, hi) indices.
		 * Worst-case depth with "always push larger, tail-loop smaller" is
		 * ceil(log2(n)), so 64 int slots (= 32 pairs) covers 2^32 elements.
		 * We borrow from the pool to keep the entire call heap-allocation-free.
		 */
		final int[] stack = PooledArrayType.INT.borrow(64);
		try {
			int top = 0;
			stack[top++] = left;
			stack[top++] = right;

			while (top > 0) {
				right = stack[--top];
				left  = stack[--top];

				// tail-call loop for the smaller partition
				while (left < right) {
					int length = right - left + 1;

					// insertion sort for tiny ranges (JDK 8)
					if (length <= INSERTION_SORT_THRESHOLD) {
						insertionSort(a, left, right, comparator);
						break;
					}

					// 5-sample pivot selection (mirrors JDK 8 sort)
					//
					// Divide the range into 6 equal-ish segments, take the
					// element at each interior boundary, sort those 5 candidates
					// in-place, then use the middle one (e3) as the pivot.
					// This keeps the pivot selection cost at O(1) while giving a
					// much better median estimate than median-of-three alone.
					int sixth = length / 6;
					int e1 = left  + sixth;
					int e5 = right - sixth;
					int e3 = left  + (length >>> 1); // midpoint
					int e2 = e3   - sixth;
					int e4 = e3   + sixth;

					// sort the 5 samples with a 5-element sort network (7 comparisons)
					if (comparator.compare(a[e1], a[e2]) > 0) swap(a, e1, e2);
					if (comparator.compare(a[e4], a[e5]) > 0) swap(a, e4, e5);
					if (comparator.compare(a[e1], a[e3]) > 0) swap(a, e1, e3);
					if (comparator.compare(a[e2], a[e3]) > 0) swap(a, e2, e3);
					if (comparator.compare(a[e1], a[e4]) > 0) swap(a, e1, e4);
					if (comparator.compare(a[e3], a[e4]) > 0) swap(a, e3, e4);
					if (comparator.compare(a[e2], a[e5]) > 0) swap(a, e2, e5);
					if (comparator.compare(a[e2], a[e3]) > 0) swap(a, e2, e3);
					if (comparator.compare(a[e4], a[e5]) > 0) swap(a, e4, e5);
					// invariant: a[e1] <= a[e2] <= a[e3] <= a[e4] <= a[e5]

					Object pivot = a[e3]; // true median of 5 samples

					// 3-way partition (Dutch-flag / Bentley-McIlroy)
					int lt = left;
					int gt = right;
					int i  = left;

					while (i <= gt) {
						int cmp = comparator.compare(a[i], pivot);
						if      (cmp < 0) swap(a, lt++, i++);
						else if (cmp > 0) swap(a, i, gt--);
						else              i++;
					}

					// push larger partition; tail-loop smaller
					//
					// This is the key invariant that keeps the pooled stack at
					int leftLen  = lt - 1 - left;
					int rightLen = right - (gt + 1);

					if (leftLen >= rightLen) {
						// left side larger -> push it, tail-recurse right
						if (left < lt - 1) {
							stack[top++] = left;
							stack[top++] = lt - 1;
						}
						left = gt + 1; // continue with right partition
					} else {
						// right side larger -> push it, tail-recurse left
						if (gt + 1 < right) {
							stack[top++] = gt + 1;
							stack[top++] = right;
						}
						right = lt - 1; // continue with left partition
					}
				}
			}
		} finally {
			PooledArrayType.INT.release(stack);
		}
	}

	/**
	 * Straight insertion sort for small ranges.
	 * JDK 8 uses the same algorithm for ranges below its INSERTION_SORT_THRESHOLD.
	 */
	@SuppressWarnings({"rawtypes", "unchecked"})
	private static void insertionSort(Object[] a, int left, int right, Comparator c) {
		for (int i = left + 1; i <= right; i++) {
			final Object key = a[i];
			int j = i - 1;
			while (j >= left && c.compare(a[j], key) > 0) {
				a[j + 1] = a[j];
				j--;
			}
			a[j + 1] = key;
		}
	}

	private static void swap(Object[] a, int i, int j) {
		final Object tmp = a[i];
		a[i] = a[j];
		a[j] = tmp;
	}
}

package rs117.hd.utils.jobs;

import java.util.concurrent.Semaphore;

public final class ClientCallbackJob {
	private static final ThreadLocal<ClientCallbackJob> POOL = ThreadLocal.withInitial(ClientCallbackJob::new);

	public static ClientCallbackJob current() {
		ClientCallbackJob callback = POOL.get();
		callback.semaphore.drainPermits();
		return callback;
	}

	final Semaphore semaphore = new Semaphore(0);
	public Runnable callback;
}

package rs117.hd.utils.jobs;

import rs117.hd.utils.collections.ConcurrentPool;

public final class GenericJob extends Job {
	private static final ConcurrentPool<GenericJob> POOL = new ConcurrentPool<>(GenericJob::new);

	@FunctionalInterface
	public interface TaskRunnable {
		void run(GenericJob Task) throws InterruptedException;
	}

	public static GenericJob build(String context, TaskRunnable runnable) {
		GenericJob newTask = POOL.acquire();
		newTask.context = context;
		newTask.runnable = runnable;
		newTask.resetReleased();

		return newTask;
	}

	private String context;
	private TaskRunnable runnable;

	@Override
	public void onRun() throws InterruptedException {
		runnable.run(this);
	}

	@Override
	protected void onCancel() {}

	@Override
	public void onReleased() {
		runnable = null;
		POOL.recycle(this);
	}

	@Override
	public String toString() {
		return super.toString() + " " + context;
	}
}

package rs117.hd.utils.jobs;

import com.google.inject.Injector;
import java.util.concurrent.atomic.AtomicBoolean;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@SuppressWarnings("unchecked")
public abstract class Job {
	static JobSystem JOB_SYSTEM;

	protected final AtomicBoolean done = new AtomicBoolean();
	protected final AtomicBoolean wasCancelled = new AtomicBoolean();
	protected final AtomicBoolean encounteredError = new AtomicBoolean();
	protected final AtomicBoolean ranToCompletion = new AtomicBoolean();
	protected final AtomicBoolean queued = new AtomicBoolean();
	protected JobGroup<Job> group;

	private final AtomicBoolean released = new AtomicBoolean();

	boolean executeAsync = true;
	JobHandle handle;

	public final void waitForCompletion() {
		waitForCompletion(false);
	}

	public final void waitForCompletion(boolean shouldRelease) {
		waitForCompletion(-1);
		if (shouldRelease)
			release();
	}

	public final boolean waitForCompletion(int timeoutNanos) {
		boolean completed = false;
		if (handle != null) {
			try {
				if (isDone()) {
					completed = true;
				} else {
					completed = handle.await(timeoutNanos);
				}
			} catch (InterruptedException e) {
				log.warn("Job {} was interrupted while waiting for completion", this);
				throw new RuntimeException(e);
			} finally {
				if (completed)
					handle.release();
			}
		} else {
			completed = true;
		}

		if (group != null && completed) {
			group.pending.remove(this);
			group = null;
		}
		return completed;
	}

	public final boolean isQueued() {
		return queued.get();
	}

	public final boolean encounteredError() {
		return encounteredError.get();
	}

	public final boolean wasCancelled() {
		return wasCancelled.get();
	}

	public final boolean ranToCompletion() {
		return ranToCompletion.get();
	}

	public final void cancel() {
		if (handle != null) {
			try {
				handle.cancel(true);
			} catch (InterruptedException e) {
				log.warn("Job {} was interrupted while waiting for it to be cancelled", this);
				throw new RuntimeException(e);
			} finally {
				handle.release();
			}
		}
	}

	public final void release() {
		// Only release once
		if (!released.compareAndSet(false, true))
			return;

		queued.set(false);
		waitForCompletion();
		onReleased();
	}

	public final boolean isReleased() {
		return released.get();
	}

	protected final void resetReleased() {
		// Only the new owner may reset this after acquiring the job from the pool
		released.set(false);
	}

	public final boolean isDone() {
		return done.get();
	}

	public final boolean isHighPriority() {
		return (group != null && group.highPriority) || (handle != null && handle.highPriority);
	}

	protected static Injector getInjector() { return JOB_SYSTEM.injector; }

	protected void invokeClientCallback(Runnable callback) throws InterruptedException {
		JOB_SYSTEM.invokeClientCallback(callback);
	}

	public final void workerHandleCancel() throws InterruptedException {
		if (handle == null)
			return;

		final Worker worker = handle.worker;
		if (handle.worker == null)
			return;

		worker.workerHandleCancel();
	}

	public final <T extends Job> T setExecuteAsync(boolean executeAsync) {
		this.executeAsync = executeAsync;
		return (T) this;
	}

	public final <T extends Job> T queue(JobGroup<T> group, Job... dependencies) {
		assert group != null;
		waitForCompletion();
		JOB_SYSTEM.queue(this, group.highPriority, dependencies);
		if (executeAsync) {
			this.group = (JobGroup<Job>) group;
			this.group.pending.add(this);
		}
		return (T) this;
	}

	public final <T extends Job> T queue(boolean highPriority, Job... dependencies) {
		waitForCompletion();
		JOB_SYSTEM.queue(this, highPriority, dependencies);
		return (T) this;
	}

	public final <T extends Job> T queue(Job... dependencies) {
		waitForCompletion();
		JOB_SYSTEM.queue(this, true, dependencies);
		return (T) this;
	}

	protected abstract void onRun() throws InterruptedException;

	protected boolean canStart() { return true; }

	protected void onCompletion() {}

	protected void onCancel() {}

	protected void onReleased() {}

	public String toString() {
		return "[" + hashCode() + "|" + getClass().getSimpleName() + "]";
	}
}

package rs117.hd.utils.jobs;

import java.util.concurrent.ConcurrentLinkedQueue;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@RequiredArgsConstructor
public final class JobGroup<T extends Job> {
	@Getter
	final ConcurrentLinkedQueue<T> pending = new ConcurrentLinkedQueue<>();

	@Getter
	final boolean highPriority;

	@Getter
	final boolean autoRelease;

	public int getPendingCount() { return pending.size(); }

	public void complete() {
		T work;
		while ((work = pending.poll()) != null) {
			work.waitForCompletion();
			if (autoRelease) work.release();
		}
	}

	public void cancel() {
		T work;
		while ((work = pending.poll()) != null) {
			work.cancel();
			if (autoRelease) work.release();
		}
		pending.clear();
	}
}

package rs117.hd.utils.jobs;

import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.AbstractQueuedSynchronizer;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import rs117.hd.utils.collections.ConcurrentPool;

import static rs117.hd.utils.HDUtils.getThreadStackTrace;
import static rs117.hd.utils.MathUtils.*;
import static rs117.hd.utils.jobs.JobSystem.VALIDATE;

@Slf4j
final class JobHandle extends AbstractQueuedSynchronizer {
	static JobSystem JOB_SYSTEM;

	public static final int STATE_NONE = 0;
	public static final int STATE_QUEUED = 1;
	public static final int STATE_RUNNING = 2;
	public static final int STATE_CANCELLED = 3;
	public static final int STATE_COMPLETED = 4;

	private static final String[] STATE_NAMES = { "NONE", "QUEUED", "RUNNING", "CANCELLED", "COMPLETED" };
	private static final long DEADLOCK_TIMEOUT_SECONDS = 10;
	private static final ConcurrentPool<JobHandle> POOL = new ConcurrentPool<>(JobHandle::new);

	private static final ThreadLocal<ArrayDeque<JobHandle>> CYCLE_STACK = ThreadLocal.withInitial(ArrayDeque::new);
	private static final ThreadLocal<HashSet<JobHandle>> VISITED = ThreadLocal.withInitial(HashSet::new);

	private final ConcurrentLinkedQueue<JobHandle> dependants = new ConcurrentLinkedQueue<>();
	private final AtomicInteger jobState = new AtomicInteger(STATE_NONE);
	private final AtomicInteger refCounter = new AtomicInteger();
	private final AtomicInteger depCount = new AtomicInteger();

	@Getter
	Job item;
	@Getter
	Worker worker;
	@Getter
	boolean highPriority;

	static JobHandle obtain() {
		JobHandle handle = POOL.acquire();
		if (handle.refCounter.get() > 0) {
			// Handle is still referenced by another thread (IE: ClientThread)
			// It needs to be released before it can be reused within the job system
			// Add to the end of the queue and create a new Handle for the time being
			POOL.recycle(handle);
			handle = new JobHandle();
		}
		handle.setJobState(STATE_NONE);
		handle.refCounter.set(1);
		handle.dependants.clear();

		// reset AQS state for completion
		handle.setStateAQS(0);

		handle.depCount.set(0);
		handle.highPriority = false;
		handle.item = null;
		handle.worker = null;

		return handle;
	}

	synchronized boolean addDependency(@Nullable JobHandle handle) {
		return handle != null && handle.addDependant(this);
	}

	synchronized boolean addDependant(@Nullable JobHandle handle) {
		if (handle == null)
			return false;

		if (isCompleted() || isReleased()) {
			if (VALIDATE)
				log.debug(
					"Handle [{}] Skipping dependant [{}] due to being in state: [{}]",
					this,
					handle,
					STATE_NAMES[jobState.get()]
				);
			return false;
		}

		if (wouldCreateCycle(handle, this))
			throw new IllegalStateException("Circular dependency detected: " + this + " depends on " + handle);

		if (VALIDATE)
			log.debug("Handle [{}] added dependant [{}]", this, handle);

		dependants.add(handle);
		handle.depCount.getAndIncrement();

		return true;
	}

	static boolean wouldCreateCycle(JobHandle start, JobHandle target) {
		if (start == target)
			return true;

		if (start.dependants.isEmpty())
			return false;

		ArrayDeque<JobHandle> stack = CYCLE_STACK.get();
		HashSet<JobHandle> visited = VISITED.get();
		try {
			stack.push(start);
			while (!stack.isEmpty()) {
				JobHandle h = stack.pop();
				if (!visited.add(h)) continue;
				if (h == target) return true;
				for (JobHandle dep : h.dependants) stack.push(dep);
			}
		} finally {
			stack.clear();
			visited.clear();
		}

		return false;
	}

	synchronized boolean setRunning(Worker worker) {
		if (isInQueue()) {
			setJobState(STATE_RUNNING);
			this.worker = worker;
			return true;
		}
		return false;
	}

	synchronized void setInQueue() {
		assert isIdle() : "State should be NONE but is " + STATE_NAMES[jobState.get()];
		setJobState(STATE_QUEUED);
	}

	synchronized void setCompleted() throws InterruptedException {
		if (isCompleted()) return;

		final boolean wasCancelled = isCancelled();
		setJobState(STATE_COMPLETED);

		if (item != null)
			item.done.set(true);

		// Signal completion via AQS
		releaseShared(0);

		if (item != null)
			item.onCompletion();

		if (VALIDATE)
			log.debug("Handle [{}] Completed", this);

		int queuedWork = 0;
		JobHandle dep;
		while ((dep = dependants.poll()) != null) {
			if (wasCancelled) {
				dep.cancel(false);
				continue;
			}

			if (dep.isIdle() && dep.depCount.decrementAndGet() == 0) {
				dep.setInQueue();
				if (VALIDATE)
					log.debug("Handle [{}] Adding: [{}] to queue", this, dep);

				if (dep.isHighPriority()) {
					worker.localWorkQueue.addFirst(dep);
				} else {
					worker.localWorkQueue.addLast(dep);
				}

				queuedWork++;
			}
		}

		if (queuedWork > 1)
			JOB_SYSTEM.signalWorkAvailable(queuedWork - 1);
	}

	private void setJobState(int newState) {
		final int currentState = jobState.get();
		if (currentState == newState) return;
		if (VALIDATE) log.trace("[{}] {} -> {}", hashCode(), STATE_NAMES[currentState], STATE_NAMES[newState]);
		jobState.set(newState);
	}

	private void setStateAQS(int value) {
		setState(value); // AQS state for completion: 0 = not done, 1 = done
	}

	synchronized void release() {
		if (isReleased()) return;

		if (refCounter.decrementAndGet() > 0)
			return;

		assert item != null : "Double Release, item is already null";
		assert isCompleted() : "Release before setCompleted() has been called?!";

		if (VALIDATE) log.debug("Releasing [{}] state: [{}]", this, STATE_NAMES[jobState.get()]);
		setJobState(STATE_NONE);
		item.handle = null;
		item = null;
		worker = null;

		POOL.recycle(this);
	}

	void cancel(boolean block) throws InterruptedException {
		if (item == null || isCancelled() || isCompleted())
			return;

		int prevState = jobState.get();
		setJobState(STATE_CANCELLED);

		if (item != null)
			item.wasCancelled.set(true);

		if (VALIDATE) log.debug("Cancelling [{}] state: [{}]", this, STATE_NAMES[prevState]);

		if (prevState == STATE_NONE || (prevState == STATE_QUEUED && JOB_SYSTEM.workQueue.remove(this))) {
			setCompleted();
			return;
		}

		if (prevState == STATE_RUNNING && worker != null && worker.thread != Thread.currentThread())
			worker.thread.interrupt();

		if (block)
			await();
	}

	boolean isReleased() { return isIdle() && refCounter.get() == 0; }
	boolean isIdle() { return jobState.get() == STATE_NONE; }
	boolean isInQueue() { return jobState.get() == STATE_QUEUED; }
	boolean isCancelled() { return jobState.get() == STATE_CANCELLED; }
	boolean isCompleted() { return jobState.get() == STATE_COMPLETED; }

	boolean await() throws InterruptedException {
		return await(-1);
	}

	boolean await(int timeoutNanos) throws InterruptedException {
		refCounter.incrementAndGet();

		final boolean isClientThread = JOB_SYSTEM.client != null && JOB_SYSTEM.client.isClientThread();
		try {
			if (!isDone()) {
				if (isClientThread) {
					long start = System.nanoTime();
					int seconds = 0;
					while (true) {
						long waitNanos = TimeUnit.MILLISECONDS.toNanos(1);
						if (timeoutNanos > 0)
							waitNanos = clamp(timeoutNanos - (System.nanoTime() - start), 0, waitNanos);
						if (tryAcquireSharedNanos(0, waitNanos))
							break;
						JOB_SYSTEM.processPendingClientCallbacks();
						// Check if the job has completed during callback processing
						if (isDone())
							return true;
						long elapsedNanos = System.nanoTime() - start;
						int newSeconds = (int) TimeUnit.NANOSECONDS.toSeconds(elapsedNanos);
						if (newSeconds > seconds) {
							if (VALIDATE) {
								log.debug(
									"Waiting on Handle: [{}] state [{}] elapsed: {} secs",
									this,
									STATE_NAMES[jobState.get()],
									newSeconds
								);
								JOB_SYSTEM.printWorkersState();
							}
							seconds = newSeconds;
						}
						if (timeoutNanos > 0) {
							if (elapsedNanos >= timeoutNanos)
								return false;
						} else if (elapsedNanos >= TimeUnit.SECONDS.toNanos(DEADLOCK_TIMEOUT_SECONDS)) {
							handleDeadlock();
							return false;
						}
						Thread.yield();
					}
				} else {
					if (timeoutNanos > 0) {
						if (!tryAcquireSharedNanos(0, timeoutNanos))
							return false;
					} else {
						if (!tryAcquireSharedNanos(0, TimeUnit.SECONDS.toNanos(DEADLOCK_TIMEOUT_SECONDS)))
							handleDeadlock();
					}
				}
			}
		} finally {
			refCounter.decrementAndGet();
		}
		return true;
	}

	private boolean isDone() {
		return getState() != 0;
	}

	@Override
	protected int tryAcquireShared(int ignored) {
		return isDone() ? 1 : -1;
	}

	@Override
	protected boolean tryReleaseShared(int ignored) {
		setStateAQS(1);
		return true;
	}

	private void handleDeadlock() throws InterruptedException {
		if (!JOB_SYSTEM.active) return;

		log.warn(
			"Deadlock detected on thread: {} whilst waiting {} seconds on handle {} {}, worker {}, shutting down...",
			Thread.currentThread().getName(),
			DEADLOCK_TIMEOUT_SECONDS,
			hashCode(),
			item,
			worker
		);
		log.warn("Thread {} stacktrace:\n{}", Thread.currentThread().getName(), getThreadStackTrace(Thread.currentThread()));
		if (worker != null)
			log.warn("Worker {} stacktrace:\n{}", worker.thread.getName(), getThreadStackTrace(worker.thread));

		JOB_SYSTEM.plugin.stopPlugin();
		if (JOB_SYSTEM.isWorker())
			throw new InterruptedException();
	}

	@Override
	public String toString() {
		return "[" + hashCode() + "] " + (item != null ? item.toString() : "null");
	}
}

package rs117.hd.utils.jobs;

import com.google.inject.Injector;
import java.util.HashMap;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.util.concurrent.Semaphore;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.client.callback.ClientThread;
import rs117.hd.HdPlugin;
import rs117.hd.config.CpuUsageLimit;
import rs117.hd.overlays.FrameTimer;

import static rs117.hd.HdPlugin.PROCESSOR_COUNT;
import static rs117.hd.utils.MathUtils.*;

@Slf4j
@Singleton
public final class JobSystem {
	public static final boolean VALIDATE = false;

	@Inject
	public Injector injector;

	@Inject
	public Client client;

	@Inject
	public ClientThread clientThread;

	@Inject
	public HdPlugin plugin;

	@Inject
	public FrameTimer frametimer;

	@Getter
	boolean active;

	private int workerCount;

	final ConcurrentLinkedDeque<JobHandle> workQueue = new ConcurrentLinkedDeque<>();
	private final ConcurrentLinkedDeque<ClientCallbackJob> clientCallbacks = new ConcurrentLinkedDeque<>();

	private final HashMap<Thread, Worker> threadToWorker = new HashMap<>();

	private boolean clientInvokeScheduled;

	Worker[] workers;
	Semaphore workerSemaphore;

	public void startUp(CpuUsageLimit cpuUsageLimit) {
		workerCount = max(1, ceil((PROCESSOR_COUNT - 1) * cpuUsageLimit.threadRatio));
		workers = new Worker[workerCount];
		workerSemaphore = new Semaphore(workerCount);
		active = true;

		for (int i = 0; i < workerCount; i++) {
			Worker worker = workers[i] = new Worker(this, i);
			worker.thread = new Thread(worker::run);
			worker.thread.setPriority(Thread.NORM_PRIORITY + 1);
			worker.thread.setName("117HD - Worker " + i);
			threadToWorker.put(worker.thread, worker);
		}

		Job.JOB_SYSTEM = this;
		JobHandle.JOB_SYSTEM = this;

		for (int i = 0; i < workerCount; i++)
			workers[i].thread.start();

		log.debug("Initialized JobSystem with {} workers", workerCount);
	}

	void signalWorkAvailable(int workCount) {
		int availPermits = workerSemaphore.availablePermits();
		if (availPermits >= workCount)
			return;
		workerSemaphore.release(min(workCount, workCount - availPermits));
	}

	public int getWorkQueueSize() {
		return workQueue.size();
	}

	private void cancelAllWork(ConcurrentLinkedDeque<JobHandle> queue) {
		JobHandle handle;
		while ((handle = queue.poll()) != null) {
			try {
				handle.cancel(false);
				handle.setCompleted();
			} catch (InterruptedException e) {
				log.warn("Interrupted while shutting down worker", e);
				throw new RuntimeException(e);
			}
		}
	}

	public void shutDown() {
		active = false;
		cancelAllWork(workQueue);

		for (Worker worker : workers) {
			cancelAllWork(worker.localWorkQueue);
			if (worker.handle != null) {
				try {
					worker.handle.cancel(true);
				} catch (InterruptedException e) {
					log.warn("Interrupted while shutting down worker", e);
					throw new RuntimeException(e);
				}
			}
			worker.thread.interrupt();
		}

		int workerShutdownCount = 0;
		for (Worker worker : workers) {
			if (!worker.thread.isAlive()) {
				workerShutdownCount++;
				continue;
			}

			try {
				worker.thread.join(1000);
			} catch (InterruptedException e) {
				log.warn("Interrupted while waiting for worker shutdown", e);
			}

			if (worker.thread.isAlive()) {
				log.warn("Worker {} didn't shutdown within a timely manner", worker.thread.getName());
				worker.printState();
			} else {
				workerShutdownCount++;
			}
		}

		if (workerShutdownCount == workerCount)
			log.debug("All workers shutdown successfully");

		threadToWorker.clear();
		workers = null;
	}

	public boolean isWorker() {
		return threadToWorker.containsKey(Thread.currentThread());
	}

	public boolean hasIdleWorkers() {
		for (Worker worker : workers) {
			if (!worker.inflight.get())
				return true;
		}
		return false;
	}

	public void printWorkersState() {
		log.debug("WorkQueue Size: {}", workQueue.size());
		for (Worker worker : workers)
			worker.printState();
	}

	void queue(Job item, boolean highPriority, Job... dependencies) {
		if (!item.executeAsync) {
			try {
				item.queued.set(true);
				item.onRun();
				item.ranToCompletion.set(true);
			} catch (Throwable ex) {
				if (item.wasCancelled()) {
					log.debug("Encountered an error whilst processing: {}", item.hashCode(), ex);
				} else {
					log.warn("Encountered an error whilst processing: {}", item.hashCode(), ex);
				}
			} finally {
				item.done.set(true);
			}
			return;
		}

		JobHandle newHandle = item.handle = JobHandle.obtain();
		newHandle.highPriority = highPriority;
		newHandle.item = item;

		boolean shouldQueue = true;
		for (Job dep : dependencies) {
			if (dep == null || dep.handle == null) continue;
			if (dep.handle.addDependant(newHandle)) {
				shouldQueue = false;
			}
		}

		item.queued.set(true);
		item.done.set(false);
		item.wasCancelled.set(false);
		item.encounteredError.set(false);
		item.ranToCompletion.set(false);

		if (shouldQueue) {
			newHandle.setInQueue();
			if (VALIDATE) log.debug("Handle [{}] Added to queue (Dep Count: {{}})", newHandle, dependencies);
			if (highPriority) {
				workQueue.addFirst(newHandle);
			} else {
				workQueue.addLast(newHandle);
			}
		}

		signalWorkAvailable(1);
	}

	void invokeClientCallback(Runnable callback) throws InterruptedException {
		if (client.isClientThread()) {
			callback.run();
			processPendingClientCallbacks();
			return;
		}

		final ClientCallbackJob clientCallback = ClientCallbackJob.current();
		clientCallback.callback = callback;

		clientCallbacks.add(clientCallback);

		if (!clientInvokeScheduled) {
			clientInvokeScheduled = true;
			clientThread.invoke(() -> {
				clientInvokeScheduled = false;
				processPendingClientCallbacks();
			});
		}

		try {
			clientCallback.semaphore.acquire();
		} catch (InterruptedException e) {
			clientCallbacks.remove(clientCallback);
			throw new InterruptedException();
		}
	}

	public void processPendingClientCallbacks() {
		int size = clientCallbacks.size();
		if (size == 0)
			return;

		ClientCallbackJob pair;
		while (size-- > 0 && (pair = clientCallbacks.poll()) != null) {
			try {
				pair.callback.run();
			} catch (Throwable ex) {
				log.warn("Encountered exception whilst processing client callback", ex);
			} finally {
				pair.semaphore.release();
			}
		}
	}
}

package rs117.hd.utils.jobs;

import java.util.ArrayDeque;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import static rs117.hd.utils.HDUtils.getThreadStackTrace;
import static rs117.hd.utils.MathUtils.*;
import static rs117.hd.utils.jobs.JobSystem.VALIDATE;

@Slf4j
@RequiredArgsConstructor
public final class Worker {
	private static final long SLEEP_TIME_NANOS = TimeUnit.MICROSECONDS.convert(1, TimeUnit.NANOSECONDS);

	String name, pausedName;
	Thread thread;
	JobHandle handle;
	int stealTargetIdx = -1;

	final JobSystem jobSystem;
	final int workerIdx;
	final ConcurrentLinkedDeque<JobHandle> localWorkQueue = new ConcurrentLinkedDeque<>();
	final ArrayDeque<JobHandle> localStalledWork = new ArrayDeque<>();
	final AtomicBoolean inflight = new AtomicBoolean();

	boolean findNextStealTarget() {
		// Find the best target to steal work from
		int nextVictimIdx = -1;
		int nextVictimWorkCount = -1;
		for (int i = 0; i < jobSystem.workers.length; i++) {
			if (i == workerIdx || !jobSystem.workers[i].inflight.get())
				continue; // Don't query ourselves or a worker that is idle
			int workCount = jobSystem.workers[i].localWorkQueue.size();
			if (workCount > nextVictimWorkCount) {
				nextVictimIdx = i;
				nextVictimWorkCount = workCount;
			}
		}
		stealTargetIdx = nextVictimIdx;
		return nextVictimWorkCount > 0;
	}

	@SuppressWarnings("ResultOfMethodCallIgnored")
	void run() {
		name = thread.getName();
		pausedName = name + " [Paused]";
		while (jobSystem.active) {
			// Check local work queue
			handle = (localStalledWork.isEmpty() ? localWorkQueue : localStalledWork).poll();

			long waitStart = handle == null ? System.nanoTime() : 0;
			while (handle == null) {
				if (stealTargetIdx >= 0) {
					final Worker victim = jobSystem.workers[stealTargetIdx];
					int stealCount = max(1, victim.localWorkQueue.size() / jobSystem.workers.length);

					JobHandle stolenHandle;
					while (stealCount-- > 0 && (stolenHandle = victim.localWorkQueue.poll()) != null) {
						if (handle == null) {
							handle = stolenHandle;
						} else {
							if (handle.highPriority)
								localWorkQueue.addFirst(stolenHandle);
							else
								localWorkQueue.addLast(stolenHandle);
						}
					}
				}

				if (handle == null) {
					// Check if any work is in the main queue before attempting to steal again
					handle = localStalledWork.isEmpty() ? jobSystem.workQueue.poll() : localStalledWork.poll();
				}

				if (handle == null && !findNextStealTarget() && System.nanoTime() - waitStart > SLEEP_TIME_NANOS) {
					// Wait for a signal that there is work to be had
					try {
						jobSystem.workerSemaphore.acquire();
					} catch (InterruptedException ignored) {
						// Interrupts are used to signal that the worker should shutdown, we'll pick this up and shutdown
						thread.isInterrupted(); // Consume the interrupt to prevent it from cancelling the next job
					}

					if (handle == null) {
						// We've been signaled that there is work to be had, try the main queue again
						handle = jobSystem.workQueue.poll();
					}
				}

				if (!jobSystem.active) {
					log.trace("Shutdown");
					return;
				}
			}

			try {
				processHandle();
			} catch (InterruptedException ignored) {
				thread.isInterrupted(); // Consume the interrupt to prevent it from cancelling the next job
			}
		}
		log.trace("Shutdown");
	}

	void processHandle() throws InterruptedException {
		boolean requeued = false;
		try {
			workerHandleCancel();

			if (handle.item != null) {
				if (handle.item.canStart()) {
					if (handle.setRunning(this)) {
						inflight.set(true);
						handle.item.onRun();
						handle.item.ranToCompletion.set(true);
					}
				} else {
					// Requeue into stalled work queue, since adding to ConcurrentLinkedDeque continuously is costly
					localStalledWork.addLast(handle);
					requeued = true;
				}
			}
		} catch (InterruptedException e) {
			log.debug("Interrupt Received whilst processing: {}", handle.hashCode());
		} catch (Throwable ex) {
			if (handle.item.wasCancelled()) {
				log.debug("Encountered an error whilst processing: {}", handle.hashCode(), ex);
			} else {
				log.warn("Encountered an error whilst processing: {}", handle.hashCode(), ex);
			}
			handle.item.encounteredError.set(true);
			handle.cancel(false);
		} finally {
			if (!requeued) {
				if (handle.item != null && handle.item.wasCancelled.get())
					handle.item.onCancel();
				handle.setCompleted();
				handle.worker = null;
			}
			handle = null;
		}
	}

	void workerHandleCancel() throws InterruptedException {
		if (handle.isCancelled()) {
			if (VALIDATE) log.debug("Handle {} has been cancelled, interrupting to exit execution", handle);
			throw new InterruptedException();
		}
	}

	void printState() {
		log.debug("Worker {} is {}", thread.getName(), handle == null ? "idle" : "running:\n" + getThreadStackTrace(thread));
	}
}

package rs117.hd;

import java.io.InputStream;
import java.util.Properties;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.externalplugins.ExternalPluginManager;
import rs117.hd.utils.Props;

@Slf4j
@SuppressWarnings("unchecked")
public class HdPluginTest
{
	public static void main(String[] args) throws Exception
	{
		log.warn(
			"If this is your first time using the HdPluginTest run configuration, " +
			"this window will filter on WARN-level logging by default"
		);

		Props.DEVELOPMENT = true;
		Props.set("rlhd.resource-path", "src/main/resources");
		ClassLoader.getSystemClassLoader().setDefaultAssertionStatus(true);
		useLatestPluginHub();
		ExternalPluginManager.loadBuiltin(HdPlugin.class);
		RuneLite.main(args);
	}

	private static void useLatestPluginHub()
	{
		if (System.getProperty("runelite.pluginhub.version") == null)
		{
			try
			{
				Properties props = new Properties();
				try (InputStream in = RuneLiteProperties.class.getResourceAsStream("runelite.properties"))
				{
					props.load(in);
				}

				String version = props.getProperty("runelite.pluginhub.version");
				String[] parts = version.split("[.-]");
				if (parts.length > 3 && parts[3].equals("SNAPSHOT"))
				{
					int patch = Integer.parseInt(parts[2]) - 1;
					version = parts[0] + "." + parts[1] + "." + patch;
					log.info("Detected SNAPSHOT version with no manually specified plugin-hub version. " +
							"Setting runelite.pluginhub.version to {}", version);
					System.setProperty("runelite.pluginhub.version", version);
				}
			}
			catch (Exception ex)
			{
				log.error("Failed to automatically use latest plugin-hub version", ex);
			}
		}
	}
}

